    ["01-2"] = {name="杜隆塔尔", nameA="杜隆塔尔 {a:367}／{a:362}", shortA="杜隆塔尔 {a:367} +", tips={{k="取捨", text="「新的背包」值得做。帆布脚料可和提拉加德城堡的其他任务一起收集。"}, {k="取捨", text="先交背信弃义的人类 ，才接得到海底沉船 。把沉船和沃纳尔大师 安排在同一趟。"}, {k="取捨", text="暗影裂口副本任务链可先保留。打算进怒焰裂谷的话，再向萨尔接隐藏的敌人 →→。 所需的军官徽章可在北边火刃区取得。"}, {k="提醒", text="不足 12 级可补做保卫商路、骷髅石或来自深海的威胁的前几段。", s={{"不足 12 级可补做保卫商路、骷髅石或来自深海的威胁的前几段"}}}}, danger={[1]="提拉加德城堡的楼梯和门框容易把楼上水手一起引下来。先清外墙和门口。", [2]="北岸的海巨人在纳迦区域活动。先清掉周围小怪再打，跑不动时从岸上撤退。"}, grind={[1]={mob="库尔提拉斯水兵", note="提拉加德城堡里普通怪密集，通道容易引到多只，先打外侧。顺手收集新背包所需的帆布脚料。"}, [2]={mob="钢鬃卫兵", note="剃刀岭西面普通怪集中，巡逻怪可能加入，先在营地边缘引怪。可与野猪人的进犯一起做。"}, [3]={mob="尘风雷巫", note="杜隆塔尔北部普通怪集中，有施法怪，贴着掩体把怪引到近处。做保卫商路，或进奥格瑞玛前练到 12 级。"}}, supply={[1]={npc="特莱耶克"}, [2]={npc="旅店老板格罗斯克"}, [3]={npc="沃克"}, [4]={npc="旅店老板格罗斯克"}, [5]={npc="格劳特"}, [6]={npc="多拉斯"}}, steps={[1]={npc="乌克尔", tgt="乌克尔", desc="在从试炼谷往森金村的路上找乌克尔。"}, [2]={hint="与森金村的加德林大师谈一谈。"}, [3]={npc="加德林大师", tgt="加德林大师"}, [4]={npc="拉尔·猎齿", tgt="拉尔·猎齿"}, [5]={npc="维尔林·长牙", tgt="维尔林·长牙"}, [6]={npc="沃纳尔大师", tgt="沃纳尔大师"}, [7]={npc="加德林大师", tgt="加德林大师"}, [8]={npc="加德林大师", tgt="加德林大师"}, [9]={npc="加德林大师", tgt="加德林大师"}, [10]={npc="维尔林·长牙", tgt="维尔林·长牙"}, [11]={npc="克萨尔迪", tgt="克萨尔迪"}, [12]={npc="沃纳尔大师", tgt="沃纳尔大师"}, [13]={npc="帕祖拉", tgt="帕祖拉", tag="可选", desc="能获得分解产物时才做。"}, [14]={text="先到剃刀岭报到"}, [15]={hint="在杜隆塔尔南部消灭6只脊影爬行者和6只脊影潜伏者，然后向剃刀岭的加索克报到。"}, [16]={hint="将日记交给剃刀岭附近的布拉克。", tag="可选"}, [17]={npc="布拉克", tgt="布拉克", tag="可选"}, [18]={npc="布拉克", tgt="布拉克", tag="可选"}, [19]={hint="在布拉克的基础营火旁坐下休息，直到获得\"强化休息\"增益。", tag="可选"}, [20]={npc="布拉克", tgt="布拉克", tag="可选"}, [21]={npc="布拉克", tgt="布拉克", tag="可选"}, [22]={npc="布拉克", tgt="布拉克", tag="可选", desc="学会剥皮后才做，在奥格瑞玛上交。"}, [23]={hint="和剃刀岭的奥戈尼尔·魂痕谈一谈。"}, [24]={hint="把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。"}, [25]={npc="奥戈尼尔·魂痕", tgt="奥戈尼尔·魂痕"}, [26]={npc="加索克", tgt="加索克"}, [27]={npc="旅店老板格罗斯克", tgt="旅店老板格罗斯克"}, [28]={text="到剃刀岭先找旅店老板格罗斯克绑定炉石（51.51, 41.64）。"}, [29]={npc="加索克", tgt="加索克"}, [30]={npc="奥戈尼尔·魂痕", tgt="奥戈尼尔·魂痕"}, [31]={npc="厨师托尔卡", tgt="厨师托尔卡"}, [32]={npc