    ["01-3"] = {name="纳拉其营地", tips={{k="交通", text="从其他种族起点来：先到血蹄村，再沿路向南上红云台地，前往纳拉其营地。完整转乘见开头。"}, {k="取捨", text="刺刃峡谷一趟同时做力量仪祭、刺鬃酋长、斗猪，有地图再接 纳拉其营地的危机。"}, {k="提醒", text="不足 6 级就沿刺刃峡谷外侧补斗猪或刺背野猪人，再往血蹄村。", s={{"不足 6 级就沿刺刃峡谷外侧补斗猪或刺背野猪人，再往血蹄村"}}}}, danger={[1]="刺刃峡谷的野猪人集中在狭窄坡口。打刺鬃酋长前先清坡口，撤退时回红云台地。"}, grind={[1]={mob="平原陆行鸟", note="纳拉其营地东南井旁，普通怪密集，多为中立，可逐只引怪。开始狩猎时顺手打。"}, [2]={mob="山狮", note="红云台地南坡，普通怪密集，多为中立，可逐只引怪。补继续狩猎所需的皮。"}, [3]={mob="刺背斗猪", note="刺刃峡谷，普通怪集中，与刺背野猪人混居，先清外侧。与斗猪及力量仪祭同行。"}}, supply={[1]={npc="布隆克·钢怒"}, [2]={npc="穆恩丹·秋谷"}, [3]={npc="卡文尼·柔风"}}, steps={[1]={npc="纳拉其营地礼品券", npcObj=true, tag="可选、需游戏内实测", desc="持有纳拉其营地礼品券才接。礼品券是原种族角色出生时背包里的起始物品，直接右键使用，地图上没有接取点。"}, [2]={hint="将纳拉其营地礼品券交给沃恩·星眼。", tag="可选", desc="持有纳拉其营地礼品券才接。"}, [3]={npc="沃恩·星眼", tgt="沃恩·星眼", tag="可选", desc="持有纳拉其营地礼品券才接。"}, [4]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [5]={npc="鹰风酋长", tgt="鹰风酋长"}, [6]={hint="纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。"}, [7]={hint="鹰风酋长要求你去纳拉其营地东南方的水井处寻找他的母亲。"}, [8]={npc="鹰风酋长的母亲", tgt="鹰风酋长的母亲"}, [9]={npc="鹰风酋长的母亲", tgt="鹰风酋长的母亲"}, [10]={hint="在井边拿一只水罐。", desc="在鹰风祖母身边的井里找水罐。"}, [11]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [12]={npc="鹰风酋长", tgt="鹰风酋长"}, [13]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [14]={npc="鹰风酋长", tgt="鹰风酋长"}, [15]={npc="卫兵维萨罗·风羽", tgt="卫兵维萨罗·风羽"}, [16]={hint="纳拉其营地的格鲁尔·鹰风要求你带给他10张山狮皮。"}, [17]={hint="找到居住在纳拉其营地正南方山中的灰舌先知。"}, [18]={npc="灰舌先知", tgt="灰舌先知"}, [19]={npc="灰舌先知", tgt="灰舌先知"}, [20]={npc="灰舌先知", tgt="灰舌先知", tag="可选", desc="领到闷燃熏香后十分钟内送到东南祭坛。", star={"烧焦的皮革包"}}, [21]={hint="在十分钟内，赶在阴燃熏香化为灰烬之前，将它带到东南方山丘里的安瑟与穆莎的神龛！", tag="可选", desc="领到闷燃熏香后十分钟内送到东南祭坛。"}, [22]={npc="仪式火焰", npcObj=true, tag="可选", desc="领到闷燃熏香后十分钟内送到东南祭坛。", star={"烧焦的皮革包"}}, [23]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [24]={npc="格鲁尔·鹰风", tgt="格鲁尔·鹰风"}, [25]={hint="杀掉刺刃峡谷的刺背野猪人并带回12条刺背腰带，把它们交给纳拉其营地的鹰风酋长。"}, [26]={hint="把刺鬃酋长的头颅交给红云台地的卫兵维萨罗·风羽。"}, [27]={hint="纳拉其营地的格鲁尔·鹰风要求你去干掉斗猪，并带给他4块斗猪头和4块斗猪肋排。"}, [28]={npc="沾满泥土的地图", npcObj=true, tag="可选", desc="刺背野猪人掉落沾满泥土的地图，拾取后右键点开。"}, [29]={npc="鹰风酋长", tgt="鹰风酋长"}, [30]={npc="卫兵维萨罗