    ["01-4"] = {name="莫高雷", nameA="莫高雷 {a:222}", tips={{k="取捨", text="值得做幻象仪祭 →→、智慧仪祭 和雷霆崖之旅 ，末段正好开飞行点。"}, {k="取捨", text="水井任务要先完成前一口才能接下一口。已到 12 级时可跳过蛮鬃之井支线。", s={{"水井任务要先完成前一口才能接下一口。已到 12 级时可跳过蛮鬃之井支线。", {race={"Tauren"}}}}}, {k="取捨", text="到了雷霆崖可接怒焰裂谷前置任务；打算进本时，再向拉哈罗接试探敌人 、寻找背包 。"}, {k="提醒", text="接近 12 级但经验不够，优先补莫高雷北边鹰身人、赤色石或菲兹普罗克矿坑；10 级职业解锁见文末。", s={{"接近 12 级但经验不够，优先补莫高雷北边鹰身人、赤色石或菲兹普罗克矿坑"}, {"10 级职业解锁见文末"}}}}, danger={[1]="菲兹普罗克矿坑会把巡逻怪与矿工一起引来。先清外侧，拿到笔记板就退出洞道。"}, grind={[1]={mob="草原捕食者", note="血蹄村北侧，普通怪分散，草地上可逐只引怪，留意游走怪。顺手收集马兹拉纳其材料。"}, [2]={mob="风险投资公司主官", note="菲兹普罗克矿坑周边，普通怪集中，混有工人与巡逻怪，先沿矿坑外侧引怪。可顺做矿坑任务。"}, [3]={mob="风怒女族长", note="莫高雷西北鹰身人营地，普通怪密集，混有施法型鹰身人，先拉营地外侧。接近 12 级时补经验。"}}, supply={[1]={npc="旅店老板考乌斯"}, [2]={npc="哈兰特·铁枝"}, [3]={npc="旅店老板考乌斯"}, [4]={npc="肯纳·鹰眼"}, [5]={npc="塔尔"}}, steps={[1]={hint="将补给包交给血蹄村附近的卡加·狂野之蹄。", tag="可选"}, [2]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [3]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [4]={hint="在卡加的基础营火旁坐下休息，直到获得\"强化休息\"增益。", tag="可选"}, [5]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [6]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选"}, [7]={npc="卡加·狂野之蹄", tgt="卡加·狂野之蹄", tag="可选", desc="已学会剥皮才接，熟练度达到任务要求再交。"}, [8]={hint="顺着离开纳拉其营地的路将鹰风图腾带给血蹄村的贝恩·血蹄。"}, [9]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [10]={hint="将一捆毛皮带给血蹄村的旅店老板考乌斯。", tag="可选"}, [11]={npc="旅店老板考乌斯", tgt="旅店老板考乌斯", tag="可选"}, [12]={text="到血蹄村先找旅店老板考乌斯绑定炉石（45.93, 64.16）。"}, [13]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [14]={hint="和血蹄村的扎尔曼·双月谈一谈。"}, [15]={npc="扎尔曼·双月", tgt="扎尔曼·双月"}, [16]={npc="扎尔曼·双月", tgt="扎尔曼·双月"}, [17]={npc="哈肯·风之图腾", tgt="哈肯·风之图腾"}, [18]={npc="茂尔·祈雨", tgt="茂尔·祈雨"}, [19]={npc="贝恩·血蹄", tgt="贝恩·血蹄"}, [20]={npc="卫兵萨拉莫尼·野蹄", tgt="卫兵萨拉莫尼·野蹄"}, [21]={npc="穆尔·雷角", tgt="穆尔·雷角"}, [22]={npc="克朗·石蹄", tgt="克朗·石蹄", tag="可选"}, [23]={hint="为塔恩·石蹄在决斗中击败3名玩家或新手战士。", tag="可选"}, [24]={npc="克朗·石蹄", tgt="克朗·石蹄", tag="可选"}, [25]={npc="阿哈布·麦蹄", tgt="阿哈布·麦蹄", tag="可选"}, [26]={hint="前往血蹄村与派尔·沉默行者交谈，学习烹饪手艺。", tag="可选"}, [27]={npc="派尔·沉默行者", tgt="派尔·沉默行者", tag="可选"}, [28]={hint="展示出你对专业技能的精通后，前往血蹄村寻找姚恩·