    ["01-5"] = {name="丧钟镇", tips={{k="交通", text="从其他种族起点来：在布瑞尔南侧飞艇塔下船，沿大道向西进入丧钟镇。完整转乘见开头。"}, {k="提醒", text="从墓穴内的 突然醒来 开始。抵达丧钟镇后，可在暗影牧师萨维斯（30.84, 66.20）处接 无脑的僵尸。若萨维斯没有显示任务，沿道路前往布瑞尔。", s={{"从墓穴内的 突然醒来 开始", {race={"Scourge"}}}, {"抵达丧钟镇后，可在暗影牧师萨维斯（30.84, 66.20）处接 无脑的僵尸"}, {"若萨维斯没有显示任务，沿道路前往布瑞尔"}}}, {k="提醒", text="未到 3 级就再打几只断骨骷髅，升到 3 级才接玛拉的遗愿 。到 6 级或做完这段就去布瑞尔。", s={{"未到 3 级就再打几只断骨骷髅，升到 3 级才接玛拉的遗愿"}, {"到 6 级或做完这段就去布瑞尔"}}}}, danger={[1]="夜行蜘蛛洞穴的窄道容易同时引到前后两群蜘蛛。入口先清一轮再进。"}, grind={[1]={mob="丑陋的僵尸", note="丧钟镇北侧，普通怪密集，多为中立，可逐只引怪。1-2 级顺做无脑的僵尸。"}, [2]={mob="夜行蜘蛛", note="夜行蜘蛛洞穴内普通怪密集，容易引到多只，从入口向内逐段清。顺做洞穴任务。"}, [3]={mob="血色新兵", note="东侧血色营地，普通怪与信徒混居，先打营地外围。与臂章任务一起清。"}}, supply={[1]={npc="铁匠兰德"}, [2]={npc="乔舒·基恩"}, [3]={npc="乔舒·基恩"}}, steps={[1]={npc="管理员摩尔多", tgt="管理员摩尔多"}, [2]={hint="和暗影牧师萨维斯谈一谈。"}, [3]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [4]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [5]={hint="暗影牧师萨维斯让你杀掉8个无脑的僵尸和8个丑陋的僵尸。"}, [6]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [7]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [8]={hint="新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。"}, [9]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [10]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [11]={npc="亡灵卫兵萨尔坦", tgt="亡灵卫兵萨尔坦"}, [12]={npc="执行官阿伦", tgt="执行官阿伦"}, [13]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [14]={npc="阿拉米斯·锤手", tgt="阿拉米斯·锤手"}, [15]={hint="杀掉12个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。"}, [16]={hint="在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。"}, [17]={hint="执行官阿伦要你去杀掉10只小夜行蜘蛛和8只夜行蜘蛛。"}, [18]={hint="将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。"}, [19]={hint="为丧钟镇的阿拉米斯·锤手解救夜行蜘蛛洞穴中的6名落网的受害者。"}, [20]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯"}, [21]={npc="亡灵卫兵萨尔坦", tgt="亡灵卫兵萨尔坦"}, [22]={npc="执行官阿伦", tgt="执行官阿伦"}, [23]={npc="新兵艾尔雷斯", tgt="新兵艾尔雷斯"}, [24]={npc="阿拉米斯·锤手", tgt="阿拉米斯·锤手"}, [25]={npc="执行官阿伦", tgt="执行官阿伦"}, [26]={hint="从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。"}, [27]={npc="执行官阿伦", tgt="执行官阿伦"}, [28]={npc="执行官阿伦", tgt="执行官阿伦"}, [29]={hint="到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。"}, [30]={npc="执行官阿伦", tgt="执行官阿伦"}, [31]={npc="执行官阿伦", tgt="执行官阿伦"}, [32]={npc="暗影牧师萨维斯", tgt="暗影牧师萨维斯", desc="先交提瑞斯法林地丧钟镇的无脑的僵尸。同任务也可找新兵艾尔雷斯（30.86, 66.05）。"},