    ["01-6"] = {name="提瑞斯法林地", nameA="提瑞斯法林地 {a:159}", tips={{k="提醒", text="若 重要情报 未接，直接从布瑞尔旅店和第一批可接任务开始。", s={{"若 重要情报 未接，直接从布瑞尔旅店和第一批可接任务开始"}}}, {k="取捨", text="血色、蜘蛛和墓穴杂草在东南同一趟做；北岸鱼人和阿加曼德可合成一趟。先就近交任务，12 级就转去十字路口。"}, {k="取捨", text="旅店旁的 死亡之寒 需要粗线，顺路向商人购买。被遗忘者的皮 若手上仍缺北岸鱼人皮，可等再去北岸时完成。"}, {k="取捨", text="可在银色黎明的两个原地任务后接班达里安堡 。堡垒的部分后续任务可接。赶往十字路口的话，可在银色黎明的两个原地任务后离开。", s={{"可在银色黎明的两个原地任务后接班达里安堡", {race={"Orc", "Troll", "Scourge"}}}, {"堡垒的部分后续任务可接", {race={"Scourge"}}}, {"赶往十字路口的话，可在银色黎明的两个原地任务后离开"}}}, {k="提醒", text="若未到 12 级，优先补 与血色十字军的战争、家族墓穴 或银色黎明 银色特使／诅咒神教／战争的残迹，视可接任务与所在位置而定。", s={{"若未到 12 级，优先补 与血色十字军的战争、家族墓穴 或银色黎明 银色特使／诅咒神教／战争的残迹，视可接任务与所在位置而定"}}}}, danger={[1]="东南墓地混有血僵尸与游荡的幽灵，容易被前后夹击。沿墓地边缘清，留住退路。"}, grind={[1]={mob="血色传教士", note="布瑞尔西南，普通怪分散，会施法，可从营地外侧逐只引怪。与第一轮血色十字军任务同行。"}, [2]={mob="游荡的幽灵", note="东南墓地，普通怪集中，与血僵尸混居，留意巡逻。巡查后方和墓穴杂草可一起做。"}, [3]={mob="黑暗新教徒", note="东南银色黎明支线附近，普通怪密集，与黑暗执法者混居，营地边缘较好单引。11 级后可补到 12 级。"}}, supply={[1]={npc="旅店老板瑞尼"}, [2]={npc="亚伯·温特斯"}, [3]={npc="旅店老板瑞尼"}, [4]={npc="温特斯夫人"}, [5]={npc="多拉斯"}}, steps={[1]={npc="亡灵卫兵希米尔", tgt="亡灵卫兵希米尔"}, [2]={npc="葛尔多", tgt="葛尔多"}, [3]={hint="从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。"}, [4]={hint="收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。"}, [5]={hint="把血色十字军文件交给布瑞尔的执行官塞加德。"}, [6]={npc="执行官塞加德", tgt="执行官塞加德"}, [7]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [8]={npc="初级药剂师霍兰德", tgt="初级药剂师霍兰德"}, [9]={text="到布瑞尔找旅店老板瑞尼绑定炉石（61.72, 52.05）。"}, [10]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [11]={hint="将斑纹南瓜带给被关在恐惧之末旅店地下室中的血色十字军俘虏。"}, [12]={npc="血色十字军俘虏", tgt="血色十字军俘虏"}, [13]={npc="亡灵卫兵迪林格尔", tgt="亡灵卫兵迪林格尔"}, [14]={npc="执政官塞弗伦", tgt="执政官塞弗伦"}, [15]={npc="药剂师乔汉", tgt="药剂师乔汉"}, [16]={npc="初级药剂师霍兰德", tgt="初级药剂师霍兰德"}, [17]={npc="执行官塞加德", tgt="执行官塞加德"}, [18]={npc="执行官塞加德", tgt="执行官塞加德"}, [19]={npc="执行官塞加德", tgt="执行官塞加德"}, [20]={npc="通缉！", npcObj=true}, [21]={text="布瑞尔外围与西侧血色十字军"}, [22]={hint="给布瑞尔的亡灵卫兵迪林格尔带回7只腐烂的爪子。"}, [23]={hint="杀死腐皮盗墓贼和混血腐皮豺狼人。"}, [24]={hint="布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。"}, [25]={hint="收集10株末日草，把它们交给初级药剂师霍兰德。"}, [26]={hint="布瑞尔的执行官塞加德要求你杀掉10名血色战士。