    ["01-7"] = {tips={{k="交通", text="从其他种族起点来：在莫高雷观天者台地南侧码头（34.30, 25.80）搭乘割天者号，在瓦拉纳尔西码头（57.90, 80.90）下船，再沿路北上森达尔林地。"}, {k="提醒", text="抵达瓦拉纳尔后沿大道北上森达尔林地。其他部落种族可做共用支线，种族限定与未解锁的前置步骤由插件过滤。1-3 级可先沿森达尔林地打飞狐幼崽与卷云蜂，再做可接的采集和村落支线。若已清完可接任务仍不足 12 级，回莫高雷接血蹄村支线补足。", s={{"抵达瓦拉纳尔后沿大道北上森达尔林地"}, {"其他部落种族可做共用支线，种族限定与未解锁的前置步骤由插件过滤"}, {"1-3 级可先沿森达尔林地打飞狐幼崽与卷云蜂，再做可接的采集和村落支线"}, {"若已清完可接任务仍不足 12 级，回莫高雷接血蹄村支线补足"}}}, {k="取捨", text="本岛主线依序走森达尔林地、申达尔村、瓦拉纳尔、阿基尔神殿。还没到 12 级可先做果园或影风森林支线，再搭飞艇。"}, {k="取捨", text="村旁学徒和强盗任务可一起接。也可同时接角鹰兽的袭扰 。傲爪的麻烦奖励简易皮革背袋。多管闲事的法师可选潮汐流转雕像。完成火之召唤可取得蓄能烈焰图腾。", s={{"村旁学徒和强盗任务可一起接"}, {"也可同时接角鹰兽的袭扰", {race={"天裔精靈"}}}, {"傲爪的麻烦奖励简易皮革背袋"}, {"多管闲事的法师可选潮汐流转雕像", {class={"DRUID"}}}, {"完成火之召唤可取得蓄能烈焰图腾", {class={"SHAMAN"}}}}}, {k="提醒", text="离岛两个衔接任务 下一步、大地之环 显示为 13 级，7 级就能接，主线跑完就接。", s={{"离岛两个衔接任务 下一步、大地之环 显示为 13 级，7 级就能接，主线跑完就接"}}}}, danger={[1]="森达尔林地瞭望塔的跳下路线需要空中行走。先把种族技能放上快捷栏，跳下后立即使用。", [2]="影风森林营地的奥拉凯斯追风者混在步行兵之间，别穿营地中央，沿外圈逐只引怪。"}, grind={[1]={mob="幼年瓦尔德伦", note="森达尔林地，普通怪密集，可逐只引怪，留意附近的蜂群。1-2 级可先在起点附近升级。"}, [2]={mob="高地强盗", note="申达尔高地，普通怪密集，强盗会成群，先清营地边缘。与法外之徒及被偷走的风石同行。"}, [3]={mob="奥拉凯斯逐暴者", note="影风森林，普通怪密集，混有步行兵，先从营地外侧引怪。顺做遭弃与不配，接近 12 级时补经验。"}}, supply={[1]={npc="费夫拉斯·天锤"}, [2]={npc="乌阿莉亚·日冠"}, [3]={npc="乌阿莉亚·日冠"}, [4]={npc="泽风岛平民"}, [5]={npc="艾迪·三铸"}, [6]={npc="泽风岛平民"}, [7]={npc="贝兰迪尔·远航"}, [8]={npc="多纳尔·微风"}, [9]={npc="塔莉亚·明空"}, [10]={npc="多纳尔·微风"}, [11]={npc="安特拉瑞娅·凝云"}, [12]={npc="塔尔"}}, steps={[1]={npc="收藏家达莉亚", tgt="艾莉·远心"}, [2]={hint="在森达尔林地与寻天者罗里安交谈。"}, [3]={npc="艾莉·远心", tgt="寻天者罗里安"}, [4]={npc="艾莉·远心", tgt="寻天者罗里安"}, [5]={npc="法罗恩·秋风", tgt="埃拉特雷尔·轻羽"}, [6]={npc="米莉亚尔·唤雾", tgt="米莉亚尔·唤雾"}, [7]={npc="哈兰·鹰眼", tgt="哈兰·鹰眼"}, [8]={hint="在森达尔林地消灭8只幼年瓦尔德伦。"}, [9]={hint="在森达尔林地消灭8只烦人的卷云蝇。"}, [10]={hint="从森达尔林地的瞭望塔顶跳下，使用你的踏空而行能力减缓下落速度。", desc="登上瞭望塔后才往下跳，落地前启动天裔精灵的空中行走。"}, [11]={hint="与哈兰·鹰眼交谈，借用他的天赋去观察远处的锚点水晶塔。"}, [12]={npc="艾莉·远心", tgt="寻天者罗里安"}, [13]={npc="法罗恩·秋风", tgt="埃拉特雷尔·轻羽"}, [14]={npc="艾莉·远心", tgt="寻天者罗里安"}, [15]={npc="哈兰·鹰眼", tgt="哈兰·鹰眼"}, [16]={npc="法罗恩·秋风", tgt="埃拉特雷