    ["05-d2"] = {name="Hall of Thanes", entrance="铁炉堡 27.63, 47.83", pickup="从贫瘠之地转往东部王国后，只有专程成就队才从幽暗城经银松、希尔斯布莱德、阿拉希南下湿地，经丹奥加兹到丹莫罗再进铁炉堡。部落前置接取点未查到。", pickupS={{"从贫瘠之地转往东部王国后，只有专程成就队才从幽暗城经银松、希尔斯布莱德、阿拉希南下湿地，经丹奥加兹到丹莫罗再进铁炉堡"}, {"部落前置接取点未查到"}}, tips={{k="動線", text="入口→安威玛休憩地打法德林→黑铁召唤师旁打玛格玛图斯→走廊清巡逻的掠夺者→诸王圣物库打杜尔根。"}, {k="說明", text="地下地图、旧铁炉堡入侵、永不安息的亡者、远古的宿怨、重要的传家宝、谅解条约 是联盟任务，部落接不到。", s={{"地下地图、旧铁炉堡入侵、永不安息的亡者、远古的宿怨、重要的传家宝、谅解条约 是联盟任务，部落接不到"}}}, {k="說明", text="可进本打法德林·安威玛、玛格玛图斯、掠夺者、杜尔根·丧钟锤等首领。这趟以掉落或成就为主。", s={{"可进本打法德林·安威玛、玛格玛图斯、掠夺者、杜尔根·丧钟锤等首领"}, {"这趟以掉落或成就为主"}}}, {k="說明", text="部落交件未查到。", s={{"部落交件未查到"}}}, {k="取捨", text="练级可略过。若要做传承成就，先约队再去，联盟首都守卫与 PvP 规则会增加进门难度。"}, {k="說明", text="城内由王座厅侧门进旧铁炉堡通道；穿到底才到副本门。暴雪确认部落可进，但需进联盟领地。", s={{"城内由王座厅侧门进旧铁炉堡通道"}, {"穿到底才到副本门"}, {"暴雪确认部落可进，但需进联盟领地"}}}}, steps={[1]={text="Hall of Thanes 入口"}}},
    ["05-d1"] = {name="怒焰裂谷", entrance="奥格瑞玛 52.60, 49.00", pickup="在贫瘠之地十字路口开飞行点后，飞雷霆崖找拉哈罗接 寻找背包／试探敌人，飞奥格瑞玛找萨尔先做 隐藏的敌人／隐藏的敌人，再去暗影裂口接 饥饿者塔拉加曼；若此轮已开幽暗城飞行点，可在飞艇跨海时先向瓦里玛萨斯领 毁灭之力。", pickupS={{"在贫瘠之地十字路口开飞行点后，飞雷霆崖找拉哈罗接 寻找背包／试探敌人，飞奥格瑞玛找萨尔先做 隐藏的敌人／隐藏的敌人，再去暗影裂口接 饥饿者塔拉加曼"}, {"若此轮已开幽暗城飞行点，可在飞艇跨海时先向瓦里玛萨斯领 毁灭之力"}}, tips={{k="動線", text="入口清穴居人→首厅岔路右上坡，打奥格弗林特并找玛尔→回主路过十字熔岩桥打塔拉加曼→沿路清火刃教徒→右坡打巴扎兰，尽头打耶戈什。"}, {k="取捨", text="进本前确认 隐藏的敌人 已解锁。只打怒焰一次，暗影裂口就近交 饥饿者塔拉加曼；雷霆崖、幽暗城的交件可分配到跨城主线。"}, {k="說明", text="正式门在奥格瑞玛暗影裂口底部；先进城内暗影裂口，再沿通道到蓝色门。", s={{"正式门在奥格瑞玛暗影裂口底部"}, {"先进城内暗影裂口，再沿通道到蓝色门"}}}}, steps={[1]={npc="拉哈罗", tgt="拉哈罗"}, [2]={npc="拉哈罗", tgt="拉哈罗"}, [3]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", tag="可选", desc="尚未去过幽暗城，可请已持有 毁灭之力 的队友分享；不能顺手开任务就先做其他四件。"}, [4]={npc="萨尔", tgt="萨尔"}, [5]={hint="将军官的徽章交给奥格瑞玛的萨尔。"}, [6]={npc="萨尔", tgt="萨尔"}, [7]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [8]={hint="将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。"}, [9]={npc="萨尔", tgt="萨尔"}, [10]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [11]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [12]={text="怒焰裂谷 入口"}, [13]={hint="在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。", desc="位置：进门沿坡到第一间穴居人大厅，清祭司与穴居人。", spot="进门沿坡到第一间穴居人大厅，清祭司与穴居人"}, [14]={hint="在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。", desc="位置：首间穴居人厅右岔上坡，找奥格弗林特后方遗体。", spot="首间穴居人厅右岔上坡，找奥格弗林特后方遗体"}, [15]={npc="玛尔·恐怖图腾", tgt="玛尔·恐怖图腾", tag="需游戏内实测", spot="首个穴居人大厅右岔上坡，奥格弗林特后方遗体"}, [16]={npc="玛尔·恐怖图腾", tgt="玛尔·恐怖图腾", tag="需游戏内实测", preText="寻找背包"}, [17]={hint="进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。", desc="位置：回主路至十字熔岩桥，找中央平台的塔拉加曼。", spot="回主路至十字熔岩桥，找中央平台的塔拉加曼"}, [18]={hint="将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。", tag="可选", desc="位置：过熔岩桥后清往双首领方向的火刃教徒。", spot="过熔岩桥后清往双首领方向的火刃教徒"}, [19]={hint="杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。", desc="位置：尾段岔路右坡找巴扎兰，再回主路到耶戈什厅。", spot="尾段岔路右坡找巴扎兰，再回主路到耶戈什厅"}, [20]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [21]={npc="萨尔", tgt="萨尔"}, [22]={npc="萨尔", tgt="萨尔", preText="隐藏的敌人"}, [23]={hint="与奥格瑞玛的尼尔鲁·火刃谈一谈。"}, [24]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [25]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃", preText="隐藏的敌人"}, [26]={hint="与