    ["02-9"] = {name="银松森林", tips={{k="交通", text="初次到瑟伯切尔先走地面；开点后才飞。回程优先用十字路口炉石，冷却时才搭奥格瑞玛飞艇。"}, {k="取捨", text="值得做：先解锁 调查安伯米尔 和永恒版 监视道路，同一趟扫荡安伯米尔；调查安伯米尔 交回后再杀 法师的头领 的法师。"}, {k="取捨", text="值得做：在焚木村一起做 99、致命的配方；交 99 后一次接 阿鲁高的愚行、阻止蔓延，到格雷迈恩之墙一起清。"}, {k="取捨", text="可跳过：走到 20 级便可以回贫瘠之地。优先跳过还没开始的护送 护送埃兰德、伏击 焚木村中的伏击 与影牙城堡支线。若已接 致命的配方、腐皮豺狼人的产生 等幽暗城交付，从瑟伯切尔飞回时顺便交。"}, {k="取捨", text="先别交：前往希尔斯布莱德丘陵 在 19 级接到后留给希尔斯布莱德丘陵 塔伦米尔。路线先回贫瘠之地，不另跑一趟塔伦米尔。"}, {k="提醒", text="若低于 20 级，先清格雷迈恩之墙（约 43, 81）或安伯米尔（约 63, 65）剩余的单人任务和普通怪。有队伍时可打影牙城堡；乌尔之书 最低 16 级，除掉阿鲁高、影牙城堡里的亡灵哨兵 最低 18 级。", s={{"若低于 20 级，先清格雷迈恩之墙（约 43, 81）或安伯米尔（约 63, 65）剩余的单人任务和普通怪"}, {"有队伍时可打影牙城堡"}, {"乌尔之书 最低 16 级，除掉阿鲁高、影牙城堡里的亡灵哨兵 最低 18 级"}}}}, danger={[1]="银松森林有 24-25 级精英阿鲁高之子巡逻。看到精英就绕开，别往林内逃。", [2]="焚木村通往格雷迈恩之墙的路上也会遇到阿鲁高之子。做完伏击就走，别沿墙追怪。"}, grind={[1]={mob="达拉然咒术师", note="安伯米尔外围，普通远程怪，密度中等；先清路边，用地形把怪拉离房屋门口，减少连带引怪。"}, [2]={mob="达拉然巫师", note="安伯米尔外圈，普通远程怪，密度中等；附近有卫兵，逐只打。离原本的达拉然任务近。"}, [3]={mob="病怏怏的难民", note="格雷迈恩之墙前，普通怪，密度高；近墙区域较拥挤，从路边逐只引怪，适合离站前补到 20 级。"}}, supply={[1]={npc="卡洛斯·拉佐克"}, [2]={npc="旅店老板拜特斯"}, [3]={npc="塞巴斯蒂安·米洛奇"}, [4]={npc="旅店老板拜特斯"}, [5]={npc="艾德温·哈里"}, [6]={npc="帕崔斯·杜耶尔"}, [7]={npc="旅店老板瑞尼"}, [8]={npc="旅店老板瑞尼"}, [9]={npc="迈克尔·加勒特"}, [10]={npc="托马斯·莫丹"}, [11]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="在杜隆塔尔城外飞艇塔，找弗雷萨（50.82, 13.54）确认去提瑞斯法林地的线路再登艇。到布瑞尔南方的飞艇塔后沿大道往幽暗城；保留十字路口炉石。"}, [2]={text="尚未开启幽暗城飞行点就进城找迈克尔·加勒特（63.25, 48.56）。若已开瑟伯切尔就飞去；首次到瑟伯切尔先出幽暗城，沿提瑞斯法林地西南的大路进入银松森林。"}, [3]={text="瑟伯切尔接任务 → 北面农场"}, [4]={text="首次到瑟伯切尔时找卡洛斯·拉佐克开启飞行点（45.62, 42.60）。本段不改旅店绑定。"}, [5]={hint="和瑟伯切尔的茉拉·符文图腾谈一谈。"}, [6]={npc="茉拉·符文图腾", tgt="茉拉·符文图腾"}, [7]={hint="将药剂师乔汉的研究成果带给银松森林的药剂师伦弗利尔。", tag="可选"}, [8]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔", tag="可选"}, [9]={hint="把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。", tag="可选"}, [10]={npc="尤瑞夫的墓碑", npcObj=true, tag="可选"}, [11]={npc="达拉尔·道恩维沃尔", tgt="达拉尔·道恩维沃尔"}, [12]={npc="高级执行官哈德瑞克", tgt="高级执行官哈德瑞克"}, [13]={npc="高级执行官哈德瑞克", tgt="高级执行官哈德瑞克"}, [14]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔"}, [15]={npc="暗影牧师奥利斯特", tgt="暗影牧师奥利斯特"}, [16]={hint="瑟伯切尔的达拉尔·道恩