    ["05-d3"] = {name="洛丹伦废墟", entrance="幽暗城 72.41, 11.37", pickup="先在提瑞斯法林地布瑞尔向林奈确认 巡查后方 的进度。林奈另有 巡查后方 版本。前往银松森林前，从布瑞尔下飞艇可顺路拜访林奈与克里斯托弗；瑟伯切尔先向塔比莎领 惊恐的求援，并完成 致命的配方→致命的配方→致命的配方；幽暗城炼金房找格雷夫与莫宾。这六类任务等副本阶段再交。", pickupS={{"先在提瑞斯法林地布瑞尔向林奈确认 巡查后方 的进度"}, {"林奈另有 巡查后方 版本", {race={"Orc", "Scourge"}}}, {"前往银松森林前，从布瑞尔下飞艇可顺路拜访林奈与克里斯托弗"}, {"瑟伯切尔先向塔比莎领 惊恐的求援，并完成 致命的配方→致命的配方→致命的配方"}, {"幽暗城炼金房找格雷夫与莫宾"}, {"这六类任务等副本阶段再交"}}, tips={{k="動線", text="入口→国王巷打枯牙→沿路清亡灵→击败男爵并取纹章→墓园打拉斯梅尔，顺路找西侧的爱德华。市集的被遗忘者与墓园西南烟囱的维克托可选。"}, {k="取捨", text="部落 16-20 级可优先排一场。没清过银松配方线的角色，可先做银松森林 瑟伯切尔，再组队进本，让枯牙一并计入。"}, {k="說明", text="入口在幽暗城上方、提瑞斯法地表的洛丹伦废墟。用幽暗城地图坐标，进入废墟后走左侧石阶；不要走到地下电梯。", s={{"入口在幽暗城上方、提瑞斯法地表的洛丹伦废墟"}, {"用幽暗城地图坐标，进入废墟后走左侧石阶"}, {"不要走到地下电梯"}}}}, steps={[1]={npc="亡灵卫兵林奈", tgt="亡灵卫兵林奈", desc="提瑞斯法林地布瑞尔已完成就略过。"}, [2]={hint="杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。", desc="提瑞斯法林地布瑞尔已完成就略过。"}, [3]={npc="亡灵卫兵林奈", tgt="亡灵卫兵林奈", desc="提瑞斯法林地布瑞尔已完成就略过。"}, [4]={npc="亡灵卫兵林奈", tgt="亡灵卫兵林奈", preText="巡查后方"}, [5]={hint="把撕裂者的心脏交给亡灵卫兵林奈。"}, [6]={npc="亡灵卫兵林奈", tgt="亡灵卫兵林奈"}, [7]={npc="亡灵卫兵克里斯托弗", tgt="亡灵卫兵克里斯托弗", desc="前置任务 巡查后方 有种族限制；其他种族看克里斯托夫身上有没有这个任务。", preText="巡查后方"}, [8]={npc="塔比莎·织心", tgt="塔比莎·织心"}, [9]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔", desc="银松森林瑟伯切尔已有此段则沿原进度交，不重做。"}, [10]={hint="收集6个灰熊的心脏和6份粘稠的血液样本，并将这些东西送给幽暗城的大药剂师法拉尼尔。", desc="银松森林瑟伯切尔已有此段则沿原进度交，不重做。"}, [11]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="银松森林瑟伯切尔已有此段则沿原进度交，不重做。"}, [12]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="伯纳德的日记在焚木村旅店。", preText="致命的配方"}, [13]={hint="从焚木村的旅店中找到伯纳德的日记，把它交给瑟伯切尔的药剂师伦弗利尔。", desc="伯纳德的日记在焚木村旅店。"}, [14]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔", desc="伯纳德的日记在焚木村旅店。"}, [15]={npc="药剂师伦弗利尔", tgt="药剂师伦弗利尔", preText="致命的配方"}, [16]={hint="收集6份湖岸爬行者苔藓的样本、6份湖岸潜藏者苔藓的样本和1块硬瘤，把它们交给幽暗城的大药剂师法拉尼尔。"}, [17]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔"}, [18]={npc="萨多雷·格雷夫", tgt="萨多雷·格雷夫", preText="致命的配方"}, [19]={npc="莫宾·圣光之灾", tgt="莫宾·圣光之灾"}, [20]={text="洛丹伦废墟 入口"}, [21]={hint="前往洛丹伦废墟，从枯牙身上提取剧毒的毒株，将其交给幽暗城的萨多雷·格雷夫。", desc="位置：入口过蛛魔区，到国王巷找巡逻的枯牙。", spot="入口过蛛魔区，到国王巷找巡逻的枯牙"}, [22]={hint="在洛丹伦废墟收集25个完好的肢体，交给幽暗城的莫宾·圣光之灾。", desc="位置：国王巷、眺望台与墓园沿主路拾亡灵战利品。", spot="国王巷、眺望台与墓园沿主路拾亡灵战利品"}, [23]={npc="憎恶头颅", npcObj=true, tag="需游戏内实测", desc="击杀男爵后拾可憎头颅，从物品接受。暴雪 11 月 6 日热修后，部落 15 级可接。"}, [24]={npc="洛丹伦纹章", npcObj=true, tag="需游戏内实测", desc="洛丹伦纹章有多个候选点，沿路查看蜘蛛庭院、楼塔及锁门房的可互动物件。"}, [25]={hint="前往洛丹伦废墟，调查爱德华·织心的失踪之谜。", desc="位置：到拉斯梅尔墓园西侧，靠近食尸鬼旁的爱德华。顺序：建议先打第 25 步再靠近遗体。", spot="到拉斯梅尔墓园西侧，靠近食尸鬼旁的爱德华"}, [26]={hint="在洛丹伦废墟击杀拉斯玛尔，向布瑞尔的亡灵卫兵克里斯托弗复命。", desc="位置：往洛丹伦墓园找拉斯梅尔，清出交战位置。", spot="往洛丹伦墓园找拉斯梅尔，清出交战位置"}, [27]={npc="萨多雷·格雷夫", tgt="萨多雷·格雷夫"}, [28]={npc="莫宾·圣光之灾", tgt="莫宾·圣光之灾"}, [29]={hint="将洛丹伦纹章交给幽暗城的奥兰·斯内克威瑟。", desc="洛丹伦纹章有多个候选点，沿路查看蜘蛛庭院、楼塔及锁门房的可互动物件。"}, [30]={npc="奥兰·斯内克威瑟", tgt="奥兰·斯内克威瑟"}, [31]={hint="把憎恶头颅带给幽暗城的大药剂师法拉尼尔。", desc="击杀男爵后拾可憎头颅，从物品接受。暴雪 11 月 6 日热修后，部落 15 级可接。"}, [32]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔"}, [33]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", preText="无尽的折磨"}, [34]={hint="将男爵的头颅带到幽暗城中奥斯玛尔的躯体旁。"}, [35]={npc="未完成的憎恶", tgt="未完成的憎恶"}, [36]={npc="未完成的憎恶", tgt="未完成的憎恶", preText="无尽的折磨"}, [37]={hint="将你的发现汇报给幽暗城的大药剂师法拉尼尔。"}, [38]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔"}, [39]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="剧毒颅帽到贸易区找塔文·格瑞斯特；灼蚀草在草药训练师旁；苦楚精华向盗贼区毒药商买。", preText="无尽的折磨"}, [40]={hint="为幽暗城的大药剂师法拉尼尔收集药材：去贸易区找塔文·格瑞斯特拿一顶剧毒骨帽，在草药学训练师附近采点水疱草，最后去潜行者区找毒药商人买些苦楚精华。", desc="剧毒颅帽到贸易区找塔文·格瑞斯特；灼蚀草在草药训练师旁；苦楚精华向盗贼区毒药商买。"}, [41]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="剧毒颅帽到贸易区找塔文·格瑞斯特；灼蚀草在草药训练师旁；苦楚精华向盗贼区毒药商买。"}, [42]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="向奥斯玛上方装置注入嘶嘶作响的血清。", preText="无尽的折磨"}, [43]={hint="替大药剂师法拉尼尔将嘶嘶血清注入奥斯玛尔躯体上方的仪器中。", desc="向奥斯玛上方装置注入嘶嘶作响的血清。"}, [44]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="向奥斯玛上方装置注入嘶嘶作响的血清。"}, [45]={npc="亡灵卫兵克里斯托弗", tgt="亡灵卫兵克里斯托弗"}, [46]={npc="塔比莎·织心", tgt="塔比莎·织心"}}},
    ["02-10"] = {name="贫瘠之地", nameA="贫瘠之地 {a:392}／{a:378}", shortA="贫瘠之地 {a:392} +", tips={{k="交通", text="北侧清完用炉石回十字路口，先交营地任务再飞棘齿城。初到陶拉祖营地补开飞行点。"}, {k="取捨", text="值得做 野猪人的内战、她的名字叫奥格拉、复仇的怒火 的重叠目标。复仇的怒火 需要 60 根獠牙，不够就留在背包，等级达标时可省去单刷。"}, {k="取捨", text="开往石爪山的 写给金吉尔的信、菲兹克斯 在下一站交，深苔蜘蛛的卵 先采蛋、下次顺路回棘齿城才交。灰谷狩猎 与选做的 战歌报告 留给灰谷。"}, {k="取捨", text="20 级精英 通缉：布鲁兹、半人马事件 人马无双！、边境 错怪无辜，罪有应得 组队再做；北方城堡护送容易引到沿路怪，也可略过。"}, {k="取捨", text="矿工的宝贝掉率偏低，打不出来就去做路线后段；四个稀有怪只在遇到并拾到物品时触发。"}, {k="提醒", text="未到 23 级可在肃清原野 肃清田野 的怪点（47.11, 77.38）续打蜥蜴、潜猎者，或南下接 加恩的报复。哀嚎洞穴入口约 47.70, 35.00，建议 18-23 级去。可带贫瘠之地十字路口已解锁的尖牙德鲁伊 、毒蛇花 ，棘齿城港口的麻烦 、智慧饮料 ，以及洞外岩台的变异皮革 、清除变异者 。", s={{"未到 23 级可在肃清原野 肃清田野 的怪点（47.11, 77.38）续打蜥蜴、潜猎者，或南下接 加恩的报复"}, {"哀嚎洞穴入口约 47.70, 35.00，建议 18-23 级去"}, {"可带贫瘠之地十字路口已解锁的尖牙德鲁伊 、毒蛇花 ，棘齿城港口的麻烦 、智慧饮料 ，以及洞外岩台的变异皮革 、清除变异者"}}}}, danger={[1]="肃清原野的精英掠夺者在普通怪之间巡逻。只打外圈蜥蜴，避免穿过战团。", [2]="通往尘泥沼泽的边境有成群联盟士兵。没有队伍可略过遭错怪，得平反（97250）。"}, grind={[1]={mob="雷鳞蜥蜴", note="肃清原野，普通怪，密度高；在草地轮巡，留意愤恨的掠夺者精英，避开战团中央。"}, [2]={mob="乱齿捕猎者", note="与雷鳞蜥蜴同一片草地，普通怪，密度高；有其他玩家在清同一区时，沿外圈补另一种怪，不必转营地。"}}, supply={[1]={npc="迪弗拉克"}, [2]={npc="布拉高克"}, [3]={npc="旅店老板维尔雷"}, [4]={npc="格拉利克斯"}, [5]={npc="旅店老板维尔雷"}, [6]={npc="加吉克"}, [7]={npc="欧姆萨·雷角"}, [8]={npc="旅店老板比鲁拉"}, [9]={npc="萨努耶·符文图腾"}}, steps={[1]={text="已从银松森林瑟伯切尔回到十字路口者，在营地接任务。中途加入且仍在东部王国，优先用炉石回十字路口；炉石不可用则搭布瑞尔南塔的奥格瑞玛线，再从奥格瑞玛飞十字路口。十字路口炉石先留到北线清完。"}, [2]={npc="曼科里克", tgt="曼科里克"}, [3]={npc="曼科里克", tgt="曼科里克"}, [4]={npc="科兰", tgt="科兰"}, [5]={npc="索克", tgt="索克"}, [6]={hint="把埃其亚基的皮交给十字路口的瑟格拉·黑棘。"}, [7]={npc="瑟格拉·黑棘", tgt="瑟格拉·黑棘", desc="贫瘠之地十字路口已交则略过。"}, [8]={npc="瑟格拉·黑棘", tgt="瑟格拉·黑棘"}, [9]={hint="从巫翼杀戮者那里收集6枚鹰身人首领之戒，把它们交给十字路口的达索克·快刀。", desc="贫瘠之地十字路口未完成才做。"}, [10]={npc="达索克·快刀", tgt="达索克·快刀", desc="贫瘠之地十字路口已交则略过。"}, [11]={npc="达索克·快刀", tgt="达索克·快刀"}, [12]={text="从十字路口飞棘齿城，先前两处飞行点已开就直接搭鸟；漏开棘齿城就沿东侧大道进城找布拉高克（63.08, 37.16）。贫瘠之地十字路口已拿 什么什么平衡器 可保留。"}, [13]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [14]={npc="沙罗萨斯船长", tgt="沙罗萨斯船长"}, [15]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [16]={npc="斯布特瓦夫", tgt="斯布特瓦夫"}, [17]={npc="码头管理员迪兹维格", tgt="码头管理员迪兹维格", tag="可选", desc="北边要顺路去矿洞才接。"}, [18]={npc="通缉", npcObj=true, tag="可选", desc="20 级精英，打算组队才接。"}, [19]={npc="起重机操作员比戈弗兹", tgt="起重机操作员比戈弗兹", tag="可选", desc="预定组队下哀嚎洞穴才接。"}, [20]={text="棘齿城沿城北通道往泥浆沼泽，顺便清北侧原野；第一趟未接 什么什么平衡器 者先回斯布特瓦夫补接。"}, [21]={hint="在风险投资公司研究基地里找到控制台。"}, [22]={npc="控制台", npcObj=true}, [23]={npc="控制台", npcObj=true}, [24]={hint="关闭燃油控制阀、调节阀和主控制阀，然后再使用控制台。"}, [25]={npc="控制台", npcObj=true}, [26]={npc="控制台", npcObj=true}, [27]={hint="从工匠斯尼格斯那里拿到能打开控制台的钥匙。"}, [28]={npc="控制台", npcObj=true}, [29]={npc="控制台", npcObj=true}, [30]={hint="从风险投资公司的某个监督或者执行者那里夺取猫眼翡翠，然后把它交给棘齿城的码头管理员迪兹维格。", tag="可选", desc="猫眼翡翠掉率偏低；经过才打，刷太久就走。"}, [31]={npc="维兹克兰克的伐木机", tgt="维兹克兰克的伐木机", desc="击倒工头取得打火钥匙后交给维兹克兰克。"}, [32]={hint="取得打火钥匙，把它交给维兹克兰克。", desc="击倒工头取得打火钥匙后交给维兹克兰克。"}, [33]={npc="维兹克兰克的伐木机", tgt="维兹克兰克的伐木机", desc="击倒工头取得打火钥匙后交给维兹克兰克。"}, [34]={npc="维兹克兰克的伐木机", tgt="维兹克兰克的伐木机", desc="接取即开始护送，先补血清近怪。"}, [35]={hint="保护维兹克兰克以及他偷来的地精伐木机返回棘齿城的斯布特瓦夫那里。", desc="护送离开泥浆沼泽，等对话跑完并确认任务完成。"}, [36]={hint="到贫瘠之地北部的卡德拉克那里报到。"}, [37]={npc="卡德拉克", tgt="卡德拉克"}, [38]={npc="卡德拉克", tgt="卡德拉克", tag="可选", desc="留到灰谷碎木岗哨顺路做；接到后先右键打开报告集，取得要交给三位使者的战歌报告，保留各人的最新回复。"}, [39]={npc="弗朗恩·凝血", tgt="弗朗恩·凝血"}, [40]={npc="弗朗恩·凝血", tgt="弗朗恩·凝血"}, [41]={hint="从贫瘠之地的草原狮后和草原狮王身上收集6张草原狮的皮。"}, [42]={hint="从贫瘠之地的爆炸陷阱中收集8份被困的猎物。"}, [43]={npc="弗朗恩·凝血", tgt="弗朗恩·凝血"}, [44]={npc="弗朗恩·凝血", tgt="弗朗恩·凝血"}, [45]={npc="弗朗恩·凝血", tgt="弗朗恩·凝血"}, [46]={hint="将一捆兽皮交给贫瘠之地无水岭上方山脊上的隐士。"}, [47]={npc="泰瑞·长饮", tgt="沃尔顿"}, [48]={npc="泰瑞·长饮", tgt="沃尔顿"}, [49]={hint="前往失事商队处，查明库尔提拉斯人出现在这里的原因。"}, [50]={npc="泰瑞·长饮", tgt="沃尔顿"}, [51]={npc="泰瑞·长饮", tgt="沃尔顿", tag="可选", desc="护卫遭围攻时先拉出落单海军，等事件到击杀泰瑞才交。"}, [52]={hint="帮助沃尔顿在遭遇泰瑞·长饮和库尔提拉斯水兵时活下来。", tag="可选", desc="护卫遭围攻时先拉出落单海军，等事件到击杀泰瑞才交。"}, [53]={npc="泰瑞·长饮", tgt="沃尔顿", tag="可选", desc="护卫遭围攻时先拉出落单海军，等事件到击杀泰瑞才交。"}, [54]={hint="杀掉塞瑞娜·血羽，把她的头颅交给十字路口的达索克·快刀。"}, [55]={text="北侧清完用炉石回十字路口；若炉石仍在冷却，沿大路南下。先交塞瑞娜并接金吉尔的信，再飞棘齿城。"}, [56]={npc="达索克·快刀", tgt="达索克·快刀"}, [57]={npc="达索克·快刀", tgt="达索克·快刀", desc="留到石爪山脉烈日石居，进石爪山入口洞穴找金吉尔。"}, [58]={text="十字路口的交接完成后，再飞棘齿城交平衡器与北线任务。"}, [59]={hint="把主动式负载平衡器交给棘齿城的斯布特瓦夫。"}, [60]={npc="斯布特瓦夫", tgt="斯布特瓦夫"}, [61]={npc="斯布特瓦夫", tgt="斯布特瓦夫"}, [62]={npc="码头管理员迪兹维格", tgt="码头管理员迪兹维格", tag="可选"}, [63]={hint="将布鲁兹的背鳍交给棘齿城的加兹鲁维。", tag="可选", desc="组队下水，或拉到守卫附近帮忙，务必打足可拾取的伤害。"}, [64]={npc="加兹鲁维", tgt="加兹鲁维", tag="可选"}, [65]={text="东南海岸，往陶拉祖营地收野猪人任务"}, [66]={hint="帮棘齿城的加兹鲁维取回一箱靴子以及一块望远镜片。", desc="与北方城堡同行，先在南海营地各开一个箱子。"}, [67]={hint="棘齿城中的沙罗萨斯船长要你收集10枚塞拉摩徽章并干掉法莫斯队长、炮兵维桑恩和炮兵斯密瑟。"}, [68]={npc="基尔萨瑞斯·火枝", tgt="基尔萨瑞斯·火枝", tag="可选", desc="准备好才开护送；先把塔内火炮和徽章处理完。"}, [69]={hint="护送基尔萨瑞斯·火枝安全地返回棘齿城的沙罗萨斯船长那里。", tag="可选", desc="随基尔萨里斯由北方城堡走回棘齿城，确定计入任务进度后再离队。"}, [70]={npc="加兹鲁维", tgt="加兹鲁维"}, [71]={npc="沙罗萨斯船长", tgt="沙罗萨斯船长"}, [72]={npc="沙罗萨斯船长", tgt="沙罗萨斯船长", tag="可选"}, [73]={text="从棘齿城向西南走到死水绿洲与迅猛龙巢穴，之后顺路往陶拉祖。"}, [74]={hint="把维罗戈的头颅交给十字路口的雷戈萨·死门。", desc="多人一起清怪比较快；看到喊话就去 53.06, 41.74 的帐篷。"}, [75]={hint="杀死赤鳞迅猛龙并收集它们的羽毛，把这些羽毛放在3个赤鳞镰爪龙的巢穴里，然后返回十字路口的瑟格拉·黑棘那里。"}, [76]={hint="从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。"}, [77]={hint="把被偷走的银币交给十字路口的加兹罗格。"}, [78]={hint="找到曼科里克的妻子，然后回到十字路口找他。"}, [79]={text="抵达陶拉祖营地后，尚未开点就找欧姆萨·雷角（44.45, 59.15）。保留十字路口炉石到石爪山脉烈日石居。"}, [80]={npc="碎牙", tgt="碎牙"}, [81]={npc="塔特纳克·钢炉", tgt="塔特纳克·钢炉", tag="可选", desc="要往南端打野猪人时才接。"}, [82]={npc="步兵劳格玛", tgt="步兵劳格玛", tag="可选", desc="永恒版组队线；人手不足可跳过。"}, [83]={text="飞回十字路口一趟交 狂暴的镰爪龙、在战斗中失踪 等，接到乔恩引导任务后，再走西南打半人马或飞回陶拉祖。"}, [84]={npc="瑟格拉·黑棘", tgt="瑟格拉·黑棘"}, [85]={npc="加兹罗格", tgt="加兹罗格"}, [86]={npc="曼科里克", tgt="曼科里克"}, [87]={npc="曼科里克", tgt="曼科里克", desc="先交 在战斗中失踪 才可接。"}, [88]={npc="瑟格拉·黑棘", tgt="瑟格拉·黑棘"}, [89]={npc="雷戈萨·死门", tgt="雷戈萨·死门"}, [90]={npc="雷戈萨·死门", tgt="雷戈萨·死门"}, [91]={hint="把赫兹鲁尔的头颅交给十字路口的雷戈萨·死门。"}, [92]={npc="雷戈萨·死门", tgt="雷戈萨·死门"}, [93]={npc="雷戈萨·死门", tgt="雷戈萨·死门", tag="可选", desc="组队再接，半人马增援会分波进攻。"}, [94]={hint="将克罗姆扎军旗的碎片交给十字路口西边的雷戈萨·死门。", tag="可选", desc="保护己方并击杀军阀克罗姆扎，拾取军旗碎片 ×1。"}, [95]={npc="雷戈萨·死门", tgt="雷戈萨·死门", tag="可选"}, [96]={hint="与陶拉祖营地的乔恩·星眼谈一谈。"}, [97]={npc="