    ["05-d5"] = {name="死亡矿井", entrance="西部荒野 38.20, 77.50", pickup="前往银松森林时，先在提瑞斯法林地 班达里安堡找丹妮莎接 外交风波，顺路做完银松、芬里斯岛前置。满 20 级在瑟伯切尔向卢米娜接 月吻之刃 并找特雷凡拿笔记。从贫瘠之地 棘齿城搭船去藏宝海湾，沿荆棘谷北上暮色森林，再向西到月溪镇。", pickupS={{"前往银松森林时，先在提瑞斯法林地 班达里安堡找丹妮莎接 外交风波，顺路做完银松、芬里斯岛前置", {race={"Scourge"}, class={"PALADIN"}}}, {"满 20 级在瑟伯切尔向卢米娜接 月吻之刃 并找特雷凡拿笔记", {race={"Scourge"}, class={"PALADIN"}}}, {"从贫瘠之地 棘齿城搭船去藏宝海湾，沿荆棘谷北上暮色森林，再向西到月溪镇"}}, tips={{k="動線", text="入口矿道→拉克佐→斯尼德伐木场顺捡木材→基尔尼格熔炉→炸门进船坞→重拳先生→绿皮队长→艾德温·范克里夫。曲奇在船下层。只需木材可在斯尼德房取完后退出。"}, {k="取捨", text="纯练级可略过这趟。做 月吻之刃 打到斯尼德房间收齐木料即可。队伍想拿尾王装备可继续打完。", s={{"纯练级可略过这趟"}, {"做 月吻之刃 打到斯尼德房间收齐木料即可", {race={"Scourge"}, class={"PALADIN"}}}, {"队伍想拿尾王装备可继续打完"}}}, {k="說明", text="月溪镇的矿井入口约 42.40, 70.40，先进建筑下楼，再循坑道到 38.20, 77.50 的正式门。联盟接的迪菲亚任务不列入部落。", s={{"月溪镇的矿井入口约 42.40, 70.40，先进建筑下楼，再循坑道到 38.20, 77.50 的正式门"}, {"联盟接的迪菲亚任务不列入部落"}}}}, steps={[1]={npc="丹妮莎·莫尔", tgt="丹妮莎·莫尔"}, [2]={hint="前往银松森林的瑟伯切尔，与特雷凡·罗尔谈谈失踪的大地之环旅客。"}, [3]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔"}, [4]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔", preText="外交风波"}, [5]={hint="与亡灵卫兵巴尔德伦交谈，询问最近经过瑟伯切尔的那两名神秘大地之环旅客。"}, [6]={npc="亡灵卫兵巴尔德伦", tgt="亡灵卫兵巴尔德伦"}, [7]={npc="亡灵卫兵巴尔德伦", tgt="亡灵卫兵巴尔德伦", preText="古怪的二人组"}, [8]={hint="调查东边的芬里斯岛，查明大地之环旅队的下落。"}, [9]={npc="被烧焦的残骸", npcObj=true}, [10]={npc="被烧焦的残骸", npcObj=true, preText="悲惨的命运"}, [11]={hint="前往北方的芬里斯城堡展开调查，设法寻找大地之环队伍中失踪的成员。"}, [12]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [13]={npc="卢米娜·风歌", tgt="卢米娜·风歌", preText="进入芬里斯城堡"}, [14]={hint="从腐皮豺狼人手中夺回芬里斯岛钥匙，解救卢米娜·风歌。"}, [15]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [16]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="依银松森林 瑟伯切尔职业栏处理塑风者。", preText="卢米娜·风歌"}, [17]={hint="陪同卢米娜·风歌，助她逃离芬里斯城堡。", desc="依银松森林 瑟伯切尔职业栏处理塑风者。"}, [18]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="依银松森林 瑟伯切尔职业栏处理塑风者。"}, [19]={npc="卢米娜·风歌", tgt="卢米娜·风歌", preText="塑风者之怒"}, [20]={hint="到瑟伯切尔与卢米娜·风歌交谈。"}, [21]={npc="卢米娜·风歌", tgt="卢米娜·风歌"}, [22]={npc="卢米娜·风歌", tgt="卢米娜·风歌", desc="接后和特雷凡·罗尔谈话取武器笔记 ×1，然后保留任务。", preText="血债"}, [23]={text="死亡矿井 入口"}, [24]={hint="到瑟伯切尔与特雷凡·罗尔交谈，并带回他所需的材料。", desc="掉率只计地精木匠掉落的白石橡木。位置：过拉克佐守门后进伐木工坊，打斯尼德旁的木匠。", spot="过拉克佐守门后进伐木工坊，打斯尼德旁的木匠"}, [25]={npc="特雷凡·罗尔", tgt="特雷凡·罗尔", desc="必须备妥武器笔记、白石橡木、影牙城堡的附魔银锭、寻找科尔宝石 的净化过的科尔宝石才交。"}}},
    ["05-d4"] = {name="哀嚎洞穴", entrance="贫瘠之地 46.00, 36.30", pickup="在贫瘠之地 十字路口找汤加完成 遗忘之池→死水绿洲→变异的生物，然后去雷霆崖找哈缪尔、纳拉与扎马；棘齿城先交 迅猛龙角 再接 智慧饮料 和 港口的麻烦。最后去洞口上方石台找纳尔帕克与厄布鲁。", pickupS={{"在贫瘠之地 十字路口找汤加完成 遗忘之池→死水绿洲→变异的生物，然后去雷霆崖找哈缪尔、纳拉与扎马"}, {"棘齿城先交 迅猛龙角 再接 智慧饮料 和 港口的麻烦"}, {"最后去洞口上方石台找纳尔帕克与厄布鲁"}}, tips={{k="動線", text="入口浅水找安娜科德拉→河西打考布莱恩→回水道往东打皮萨斯、斯卡姆、瑟芬迪斯、永生的沃尔丹→四牙王都倒后回入口护送信徒，打穆坦努斯。两翼沿路采毒蛇花、收变异皮革和哀嚎香精，并清变异怪。"}, {k="取捨", text="没交 迅猛龙角 就看不到 智慧饮料；少一条不必让全队在门口等。已先完成贫瘠之地 十字路口绿洲链，照既有进度从 哈缪尔·符文图腾 接续。"}, {k="說明", text="外洞洞口约 47.70, 35.00；由甜水绿洲进石洞穿过通道，门在更深处。纳尔帕克、厄布鲁在外洞上方的小洞，接完再下去。", s={{"外洞洞口约 47.70, 35.00"}, {"由甜水绿洲进石洞穿过通道，门在更深处"}, {"纳尔帕克、厄布鲁在外洞上方的小洞，接完再下去"}}}}, steps={[1]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [2]={hint="向图加·符文图腾报告你的发现。"}, [3]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [4]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="遗忘之池"}, [5]={hint="调查死水绿洲，然后返回十字路口向图加·符文图腾报告。"}, [6]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [7]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="死水绿洲"}, [8]={hint="收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。", tag="目标：绿洲钳嘴龟／绿洲钳嘴龟幼体"}, [9]={npc="图加·符文图腾", tgt="图加·符文图腾"}, [10]={npc="图加·符文图腾", tgt="图加·符文图腾", preText="变异的生物"}, [11]={hint="和哈缪尔·符文图腾谈一谈。"}, [12]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [13]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾", preText="哈缪尔·符文图腾"}, [14]={hint="和纳拉·蛮鬃谈一谈。"}, [15]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃"}, [16]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", preText="纳拉·蛮鬃"}, [17]={npc="药剂师扎玛", tgt="药剂师扎玛"}, [18]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [19]={hint="从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。"}, [20]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [21]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", preText="迅猛龙角"}, [22]={npc="起重机操作员比戈弗兹", tgt="起重机操作员比戈弗兹"}, [23]={npc="纳尔帕克", tgt="纳尔帕克"}, [24]={npc="厄布鲁", tgt="厄布鲁"}, [25]={hint="棘齿城的起重机操作员比戈弗兹让你从疯狂的马格利什那儿取回一瓶99年波尔多陈酿，疯狂的马格利什就藏在哀嚎洞穴里。"}, [26]={text="哀嚎洞穴 入口"}, [27]={hint="为雷霆崖的药剂师扎玛收集10朵毒蛇花。", desc="毒蛇花生长在副本门前的外洞。位置：进门沿浅水河道找毒蛇花，扫两岸可采植株。", spot="进门沿浅水河道找毒蛇花，扫两岸可采植株"}, [28]={hint="哀嚎洞穴的纳尔帕克想要20张变异皮革。", desc="变异杀戮者在副本门前的外洞。位置：浅水岔路与两翼清变异兽，边推首领边拾皮。", spot="浅水岔路与两翼清变异兽，边推首领边拾皮"}, [29]={hint="哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。", desc="位置：浅水岔路先清，河道西、东两翼补齐四种怪。", spot="浅水岔路先清，河道西、东两翼补齐四种怪"}, [30]={hint="收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。", desc="坐标指向门外的吞噬软浆怪，进本后仍可继续收集。可在副本门外击杀吞噬软浆怪。位置：在副本内沿水道找软泥怪，缺精华再补。", spot="在副本内沿水道找软泥怪，缺精华再补"}, [31]={hint="将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。", desc="位置：浅水找安娜科德拉，河西考布莱恩，河东另两王。", spot="浅水找安娜科德拉，河西考布莱恩，河东另两王"}, [32]={npc="发光的碎片", npcObj=true, tag="需游戏内实测", desc="四位德鲁伊清完后回入口找纳拉雷克斯的信徒，完成护送和仪式，再击杀吞噬者穆坦努斯拾碎片。"}, [33]={npc="纳尔帕克", tgt="纳尔帕克"}, [34]={npc="厄布鲁", tgt="厄布鲁"}, [35]={npc="起重机操作员比戈弗兹", tgt="起重机操作员比戈弗兹"}, [36]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [37]={hint="寻找更多有关这块噩梦碎片的信息。"}, [38]={npc="菲拉·古风", tgt="菲拉·古风"}, [39]={npc="菲拉·古风", tgt="菲拉·古风", preText="发光的碎片"}, [40]={hint="把噩梦碎片交给长者高地的哈缪尔·符文图腾。"}, [41]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [42]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃"}, [43]={npc="药剂师扎玛", tgt="药剂师扎玛"}}},
    ["02-11"] = {name="石爪山脉", tips={{k="交通", text="烈日石居首次开点和绑定炉石；留炉石给南侧山口交任务后回烈日石居，续飞棘齿城。"}, {k="取捨", text="值得做。暗色湖捡盖亚之种，石爪峰清塞纳留斯的遗产。交回种子后，烧焦谷四项同一趟做。千针石林乱风岗路过大升降梯再交 召回卫兵。"}, {k="取捨", text="之后顺路。 在灰谷碎木岗哨打奥达努斯；新的指示～格雷苏 只有日后会回狂风峭壁才续做，可少一趟棘齿城往返。"}, {k="取捨", text="可跳过。贝瑟莱斯、土灵的觉醒要打精英；金吉尔的森林魔法 要刷多种野兽且交任务在南端，已有足够材料才交。"}, {k="提醒", text="不到 25 级时在烧焦谷外围（约 32, 64）补血怒鹰身人或火元素，先打单只落单怪。", s={{"不到 25 级时在烧焦谷外围（约 32, 64）补血怒鹰身人或火元素，先打单只落单怪"}}}}, danger={[1]="蛛网山地有精英蜘蛛贝瑟莱斯。先清周围小蜘蛛，没有队伍可跳过。", [2]="滚岩峡谷洞里路窄，开桶召出高戈罗克前先清洞口到桶边的退路。"}, grind={[1]={mob="血怒鹰身人", note="烧焦谷东侧入口，普通怪，密度中等；外围先挑落单的，留意巡逻，23 级即可补经验。"}, [2]={mob="血怒唤风者", note="烧焦谷东侧，普通施法怪，密度高；利用山壁拉出营地，避免把巢群一起引来。可同时做烧焦谷任务。"}}, supply={[1]={npc="萨尔姆"}, [2]={npc="旅店老板杰卡"}, [3]={npc="波兰德"}, [4]={npc="旅店老板杰卡"}, [5]={npc="格劳纳尔"}, [6]={npc="基达"}}, steps={[1]={text="从十字路口沿西北大道往石爪山入口，先找贫瘠之地的希雷斯·碎石（35.26, 27.88）。"}, [2]={hint="找到石爪山的希雷斯·碎石并和她谈一谈。", tag="若贫瘠之地十字路口已接、可选"}, [3]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="若贫瘠之地十字路口已接、可选"}, [4]={npc="希雷斯·碎石", tgt="希雷斯·碎石"}, [5]={text="走石爪山南侧到玛拉卡金，再沿蜘蛛区上狂风峭壁。"}, [6]={hint="把达索克的亲笔信交给金吉尔，他住在石爪山的洞穴中。", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [7]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [8]={npc="辛吉拉", tgt="辛吉拉"}, [9]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="可选"}, [10]={npc="通缉：贝瑟莱斯", npcObj=true, tag="可选"}, [11]={hint="和狂风峭壁的菲兹克斯谈一谈。", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [12]={npc="菲兹克斯", tgt="菲兹克斯", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [13]={npc="菲兹克斯", tgt="菲兹克斯"}, [14]={hint="玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。"}, [15]={hint="收集15颗深苔蜘蛛的卵，把它们交给棘齿城的麦伯克·米希瑞克斯。", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [16]={hint="杀死15个风险投资公司樵夫，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。"}, [17]={hint="为石爪山的菲兹克斯偷来超级收割机6000型的设计图。", desc="设计图由风险投资公司操作员掉落。"}, [18]={npc="菲兹克斯", tgt="菲兹克斯"}, [19]={npc="菲兹克斯", tgt="菲兹克斯"}, [20]={hint="杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。", tag="可选", desc="贝瑟莱斯是精英，打不过先略过。"}, [21]={text="沿路上烈日石居，先找萨尔姆开启飞行点（45.12, 59.84），再向旅店老板杰卡（47.47, 62.13）绑定炉石，留到南侧山口交任务完成后再用。"}, [22]={npc="马格兰", tgt="马格兰", tag="可选"}, [23]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [24]={npc="布莱林·火拳", tgt="布莱林·火拳"}, [25]={npc="马格兰", tgt="马格兰"}, [26]={npc="苏纳曼", tgt="苏纳曼"}, [27]={npc="马格兰", tgt="马格兰"}, [28]={npc="马格兰", tgt="马格兰"}, [29]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [30]={text="往北绕暗色湖和石爪峰，按原路下山；在烈日石居交种子后再转西。"}, [31]={hint="烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。"}, [32]={hint="为石爪峰附近的布莱林·火拳杀死4名塞纳留斯的儿子，4名塞纳留斯的女儿以及4名塞纳里奥植物学家。"}, [33]={hint="玛拉卡金的巫医金吉尔需要5瓶石爪苔液、5根夜行虎须、30颗巨角鹿的眼球和1块灵龙的鳞片。", tag="可选", desc="角鹿之眼数量多，可在打塞纳留斯的遗产路过时顺手收，别专程刷完。"}, [34]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [35]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [36]={npc="布莱林·火拳", tgt="布莱林·火拳"}, [37]={npc="布莱林·火拳", tgt="布莱林·火拳", tag="可选"}, [38]={text="从烈日石居往西进入烧焦谷，将鹰身人、日光石、火元素和土堆安排在同一圈。"}, [39]={hint="烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。"}, [40]={hint="把15块闪光的太阳石带给摩罗加尔。"}, [41]={hint="将10块焚火余烬交给烈日石居的苏纳曼。"}, [42]={hint="将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。", desc="对有凸起的盖亚土堆使用任务种子。"}, [43]={text="完成烧焦谷一圈后，循东侧路回烈日石居集中交任务，炉石留给玛拉卡金与山口回程。"}, [44]={npc="马格兰", tgt="马格兰"}, [45]={npc="摩罗加尔", tgt="摩罗加尔"}, [46]={npc="苏纳曼", tgt="苏纳曼"}, [47]={npc="塔姆拉·荒原", tgt="塔姆拉·荒原"}, [48]={npc="马格兰", tgt="马格兰", tag="精英、可选"}, [49]={hint="烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。", tag="精英、可选", desc="血怒撕裂者是 26 级精英，有队友才做。"}, [50]={npc="马格兰", tgt="马格兰", tag="精英、可选"}, [51]={text="在烈日石居交完烧焦谷任务后，从东南路下山，做滚岩峡谷选做支线，或直往玛拉卡金与贫瘠之地山口。保留烈日石居炉石，等山口任务交完再用。"}, [52]={hint="深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。", tag="可选"}, [53]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [54]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [55]={hint="使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。", tag="可选", desc="此步会召出 20 级精英，想单刷可跳过。"}, [56]={npc="摩罗加尔", tgt="摩罗加尔", tag="可选"}, [57]={npc="辛吉拉", tgt="辛吉拉"}, [58]={npc="巫医金吉尔", tgt="巫医金吉尔", tag="可选"}, [59]={npc="希雷斯·碎石", tgt="希雷斯·碎石"}, [60]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="已有足够经验可不折返、可选"}, [61]={hint="杀死伐木机XT:4和XT:9，然后向石爪山与贫瘠之地交界处的希雷斯·碎石复命。", tag="已有足够经验可不折返、可选、目标：XT:4/XT:9"}, [62]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="已有足够经验可不折返、可选"}, [63]={npc="希雷斯·碎石", tgt="希雷斯·碎石", tag="雷霆崖前置、可选"}, [64]={text="在山口交完希雷斯的任务后，炉石回烈日石居，从萨尔姆搭鸟到棘齿城交蛋与密信。若炉石还在冷却，从山口沿路进贫瘠之地，到十字路口飞棘齿城。"}, [65]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", tag="若贫瘠之地棘齿城与陶拉祖营地已接"}, [66]={hint="将密封的信封交给贫瘠之地的斯布特瓦夫。"}, [67]={npc="斯布特瓦夫", tgt="斯布特瓦夫"}, [68]={npc="斯布特瓦夫", tgt="斯布特瓦夫", tag="之后顺路、可选"}, [69]={text="选做无辜者之血前置且有 长者 时，从棘齿城飞雷霆崖接续。未开雷霆崖飞行点又不打算顺路开启者，可略过这条支线，从棘齿城直接飞奥格瑞玛。"}, [70]={hint="与雷霆崖的玛加萨谈一谈。", tag="雷霆崖前置、可选"}, [71]={npc="玛加萨·野性图腾", tgt="玛加萨·野性图腾", tag="雷霆崖前置、可选"}, [72]={npc="玛加萨·野性图腾", tgt="玛加萨·野性图腾", tag="雷霆崖前置、可选"}, [73]={hint="和预见之池的药剂师扎玛谈一谈。", tag="雷霆崖前置、可选"}, [74]={npc="药剂师扎玛", tgt="药剂师扎玛", tag="雷霆崖前置、可选"}, [75]={npc="药剂师扎玛", tgt="药剂师扎玛", tag="雷霆崖前置、可选"}, [76]={npc="维尼克斯", tgt="维尼克斯", tag="可选", desc="先做这个准备，再到银松森林做 谢尔索斯号角；这是副本潜入的可选开门方法。"}, [77]={hint="掉落自：风险投资公司砍树工、风险投资公司操作员、风险投资公司樵夫", tag="可选", desc="先做这个准备，再到银松森林做 谢尔索斯号角；这是副本潜入的可选开门方法。"}, [78]={npc="维尼克斯", tgt="维尼克斯", tag="可选", desc="先做这个准备，再到银松森林做 谢尔索斯号角；这是副本潜入的可选开门方法。"}, [79]={npc="乌尔库", tgt="乌尔库"}, [80]={hint="完成任务目标。"}, [81]={npc="乌尔库", tgt="乌尔库"}, [82]={text="做完雷霆崖选做支线先从雷霆崖飞奥格瑞玛。从奥格瑞玛出城，到杜隆塔尔飞艇塔弗雷萨（50.82, 13.54）处确认去提瑞斯法林地的线路；搭到布瑞尔南塔，再走到幽暗城。接续往希尔斯布莱德丘陵塔伦米尔。"}}},
    ["02-12"] = {name="希尔斯布莱德丘陵", tips={{k="交通", text="初次前往先由瑟伯切尔步行至塔伦米尔；开启扎瑞斯飞行点、向沙恩绑定炉石。离站从幽暗城走到布瑞尔南塔搭去奥格瑞玛的飞艇。"}, {k="取捨", text="值得做：受难药剂、痛苦药剂 在西面同一趟收集，搭配希尔斯布莱德之战 。交 后才出现 死亡的纪念品，之后杀人类时一路收头骨。"}, {k="取捨", text="值得做：支援斥候、苦楚药剂 顺路完成玛索吉周围的两个任务；若接了 无辜者之血，再到敦霍尔德外围。永恒版 XP 走完才补满颅骨，此处从 希尔斯布莱德之战 起就顺手收。"}, {k="取捨", text="可跳过：若 危险！ 缺目标且需为此折返，直接前往下一站。丹加洛克 希尔斯布莱德之战 怪多，单人可留到等级更高；宝贵制高点 西侧山脊有高等山狮，赶路时略过整条支线。"}, {k="取捨", text="之后顺路：若石爪山脉 烈日石居已接 塔伦米尔之旅，趁敦霍尔德行程完成 无辜者之血，带 返回雷霆崖 给千针石林 乱风岗，途经雷霆崖时交。"}, {k="取捨", text="之后顺路：苦楚药剂 → 苦楚药剂 完成后，希尔斯布莱德丘陵 塔伦米尔可在幽暗城接 苦楚药剂，再回希尔斯布莱德海岸做。"}, {k="取捨", text="之后顺路：想现在救敦霍尔德城堡的两名囚犯，可顺做克鲁斯克的拯救行动（The Rescue，）；同地的通缉：辛迪加成员（WANTED: Syndicate Personnel，）可一起做。奥特兰克山脉收录两个任务的完整步骤。完成 后 29 级才接续秘密潜入（Infiltration，）。"}, {k="提醒", text="到 27 级即可转千针石林乱风岗短访，再进灰谷。仍低于 27 级时，先在西侧希尔斯布莱德农场（约 33, 42）打农夫，或清敦霍尔德城堡外围（约 77, 43）的普通辛迪加成员；有队伍可再挑战丹加洛克。", s={{"到 27 级即可转千针石林乱风岗短访，再进灰谷"}, {"仍低于 27 级时，先在西侧希尔斯布莱德农场（约 33, 42）打农夫，或清敦霍尔德城堡外围（约 77, 43）的普通辛迪加成员"}, {"有队伍可再挑战丹加洛克"}}}}, danger={[1]="丹加洛克的火枪手、牧师与巡山人会在阶梯口互相支援。队伍先清外圈，再进室内找上尉。", [2]="放西峰药剂瓶要经过雪怪洞上方。遇到高等山狮就沿坡绕开，避免直接上陡坡。"}, grind={[1]={mob="希尔斯布莱德农夫", note="希尔斯布莱德农场东侧，普通怪，密度中等；避开农舍门口的群怪，可同步收人类颅骨。"}, [2]={note="农场中段，普通怪，密度中等；沿田边找巡逻步卒，避开同时站着议员与农夫的屋内。"}, [3]={mob="老灰熊", note="敦霍尔德城堡北侧的野外林地，普通怪，密度较低；避开城堡人群，适合沿东侧主线回程时补几只。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="已从石爪山脉烈日石居进幽暗城者从城内出发。塔伦米尔飞行点已开可直飞；初次前往先飞瑟伯切尔，再沿南路到银松通往希尔斯布莱德的东侧道路，过丘陵沿北岔路到塔伦米尔。瑟伯切尔未开点则由幽暗城先走地面。若中途加入仍在卡利姆多，才先到奥格瑞玛城外搭飞艇。"}, [2]={text="初次前往找扎瑞斯开启塔伦米尔飞行点（60.14, 18.62），并向旅店老板沙恩绑定炉石（62.78, 19.03）。"}, [3]={hint="将伦弗利尔的研究成果交给希尔斯布莱德山脚下塔伦米尔的药剂师林度恩。"}, [4]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [5]={hint="把扎玛的信带给塔伦米尔的林度恩。", tag="可选"}, [6]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [7]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="需先完成 塔伦米尔之旅、可选"}, [8]={text="塔伦米尔接齐 → 西边熊、蜘蛛、山狮与农场"}, [9]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [10]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [11]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [12]={npc="危险！", npcObj=true, tag="可选"}, [13]={hint="塔伦米尔的药剂师林度恩要你去收集10个灰熊的舌头和一些食苔蛛的毒液。"}, [14]={hint="收集10瓶山地狮的血液，把它们交给塔伦米尔的药剂师林度恩。"}, [15]={hint="杀掉6个希尔斯布莱德雇农和6个希尔斯布莱德农夫，还有农夫雷恩和农夫盖兹，然后返回塔伦米尔向达萨利亚报告。"}, [16]={text="西面第一轮清完，炉石回塔伦米尔交任务；炉石仍在冷却时沿大路回镇。"}, [17]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [18]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [19]={npc="亡灵卫兵沙穆萨", tgt="亡灵卫兵沙穆萨"}, [20]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [21]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [22]={hint="把受难药剂交给乌比。"}, [23]={npc="乌比", tgt="乌比"}, [24]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [25]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [26]={text="第二轮农场 → 东面敦霍尔德与泥头花 → 西面铁匠铺"}, [27]={hint="把痛苦药剂喂给小狗斯坦雷。"}, [28]={npc="斯坦利", tgt="斯坦利"}, [29]={hint="杀死15个希尔斯布莱德农民，然后回到塔伦米尔向达萨利亚汇报。"}, [30]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [31]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [32]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [33]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [34]={hint="为塔伦米尔的药剂师林度恩收集5瓶无辜者之血。", tag="可选"}, [35]={hint="高级执行官达萨利亚要求你，将最新的命令送去交给驻扎在塔伦米尔以南、丹加洛克外围的亡灵哨兵玛索吉。"}, [36]={npc="亡灵哨兵玛索吉", tgt="亡灵哨兵玛索吉"}, [37]={npc="亡灵哨兵玛索吉", tgt="亡灵哨兵玛索吉", tag="先完成 支援斥候、可选"}, [38]={hint="收集6朵泥头花，把它们交给塔伦米尔的药剂师林度恩。"}, [39]={hint="杀掉铁匠维林坦和4个希尔斯布莱德见习铁匠，并从那里抢回一箱铁材，然后向塔伦米尔的达萨利亚汇报。"}, [40]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [41]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [42]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="可选"}, [43]={npc="药剂师林度恩", tgt="药剂师林度恩", tag="需先完成 无辜者之血；千针石林乱风岗交、可选"}, [44]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [45]={npc="药剂师林度恩", tgt="药剂师林度恩"}, [46]={text="市政厅 → 矿坑 → 塔伦米尔回交"}, [47]={hint="杀掉波恩塞德镇长和5个希尔斯布莱德议员，摧毁《希尔斯布莱德宣言》，偷取希尔斯布莱德城镇文档，然后回到塔伦米尔向达萨利亚汇报。"}, [48]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [49]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [50]={hint="杀死工头邦德斯和10个希尔斯布莱德矿工，然后回到塔伦米尔向达萨利亚汇报。"}, [51]={hint="塔伦米尔的高级执行官达萨利亚悬赏通缉书记员赫拉斯·怀特斯蒂德、平民维尔克斯、矿工哈克特和农夫卡拉巴。", tag="可选"}, [52]={hint="塔伦米尔的亡灵卫兵沙穆萨想要30个希尔斯布莱德人类颅骨。"}, [53]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [54]={npc="亡灵卫兵沙穆萨", tgt="亡灵卫兵沙穆萨"}, [55]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="可选"}, [56]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚", tag="组队、可选"}, [57]={hint="