    ["03-15"] = {name="希尔斯布莱德丘陵", tips={{k="取捨", text="未到 31 级可在丘陵洞穴打雪怪补差额。"}, {k="取捨", text="达拉然巡逻队与地缚护腕要交前一轮才开，集中跑西侧。城市钥匙可顺手接，达拉然城副本可跳过。"}, {k="取捨", text="秘密潜入 要先完成拯救行动 ，留到奥特兰克山脉再接。未做过药剂前段就跳过沿海分支。"}, {k="提醒", text="赫尔库拉的墓地靠近联盟南海镇，从城外接近。", s={{"赫尔库拉的墓地靠近联盟南海镇，从城外接近"}}}, {k="提醒", text="30-32 级路线可与阿拉希高地落锤镇合并累积。缺经验先打希尔斯布莱德西侧山脚的普通雪怪（约 45, 29），也可到落锤镇再补。", s={{"30-32 级路线可与阿拉希高地落锤镇合并累积"}, {"缺经验先打希尔斯布莱德西侧山脚的普通雪怪（约 45, 29），也可到落锤镇再补"}}}}, danger={[1]="南海镇有 55 级联盟卫兵。交赫尔库拉的复仇时从镇外到墓地，避免从镇中穿行。", [2]="雪人洞入口刷新集中。找赫尔库拉魔棒可先清外围，进洞前留一条撤退线。"}, grind={[1]={mob="洞穴雪人", note="西侧雪人洞外坡地，普通怪，密度高。先在洞外逐只打，避开洞口重叠怪点，30 级即可开始。"}, [2]={mob="凶恶的雪人", note="雪人洞口附近，普通怪，密度高。与洞穴雪人混在一起，先清外圈再补 31-32 级经验。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="已在碎木岗哨搭过飞艇者从布瑞尔南塔进幽暗城；由卡利姆多中途加入时才飞奥格瑞玛、补技能再搭飞艇。尚未开启幽暗城飞行点，找迈克尔·加勒特（63.25, 48.56）。"}, [2]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="幽暗城有前置才接、可选"}, [3]={text="从幽暗城飞往塔伦米尔。"}, [4]={text="开启塔伦米尔飞行点 60.14, 18.62，绑定炉石。"}, [5]={npc="学徒塞万德", tgt="学徒塞万德"}, [6]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [7]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [8]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [9]={npc="塔隆", tgt="塔隆"}, [10]={text="丘陵洞穴 → 达拉然营地"}, [11]={hint="从雪怪手上拿回赫尔库拉的魔棒，把它交给塔伦米尔的学徒塞万德。", desc="最后在南海镇外找墓碑，靠近前先避开联盟守卫。"}, [12]={npc="学徒塞万德", tgt="学徒塞万德"}, [13]={npc="学徒塞万德", tgt="学徒塞万德"}, [14]={hint="去找到那些叛徒，夺回神器，然后向我复命，<name>。"}, [15]={hint="收集10个用旧的石雕，把它们带给塔伦米尔的看守者贝尔杜加。"}, [16]={hint="为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。"}, [17]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [18]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [19]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [20]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [21]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [22]={hint="消灭6个达拉然召唤师和8个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}, [23]={hint="为塔伦米尔的看守者贝瓦里尔收集4个地缚护腕。", desc="打达拉然附近的奴役元素取得护腕。"}, [24]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [25]={npc="看守者贝瓦里尔", tgt="看守者贝瓦里尔"}, [26]={text="碧玉矿坑／南海镇外海岸"}, [27]={h