    ["05-d10"] = {name="达拉然城", entrance="奥特兰克山脉 8.46, 59.21", pickup="塔伦米尔可先接梅里萨拉的 墓穴骑士，经幽暗城时向马丁医生接 力量之源。希尔斯布莱德丘陵 塔伦米尔到 30 级向沃迪恩接 入室偷窃／城市大门钥匙，沿洛丹米尔湖东南到收容所，同一趟取血石和污秽钥匙；回塔伦米尔交后接 达拉然巡逻队，完成再接 喋血街头。绕湖岸向莫德拉的影像报到，接 动乱之源 后把下水道钥匙留在身上。", pickupS={{"塔伦米尔可先接梅里萨拉的 墓穴骑士，经幽暗城时向马丁医生接 力量之源"}, {"希尔斯布莱德丘陵 塔伦米尔到 30 级向沃迪恩接 入室偷窃／城市大门钥匙，沿洛丹米尔湖东南到收容所，同一趟取血石和污秽钥匙"}, {"回塔伦米尔交后接 达拉然巡逻队，完成再接 喋血街头"}, {"绕湖岸向莫德拉的影像报到，接 动乱之源 后把下水道钥匙留在身上"}}, tips={{k="動線", text="进本在下水道入口接地精任务→打阿崔希斯，想打林恩再进符文密室→从右路上街，沿途收构装体核心并到城堡左侧楼上书架找书→紫罗兰城堡会客室开传送门，击败大法师之影。离本前回下水道入口找瑞克希交书。"}, {k="取捨", text="部落前置从 30 级起，建议先做好开门任务再招募。队伍有钥匙可先确认谁能开门；有自己的钥匙便于再访。队伍想打隐藏首领 Lyn the Ignored，再带从影牙城堡起手制成的 Tome of Dalaran。"}, {k="說明", text="莫德拉影像与正式门在不同点；走洛丹米尔湖的下水道侧。户外达拉然城门与城内 NPC 通行受阵营规则限制。", s={{"莫德拉影像与正式门在不同点"}, {"走洛丹米尔湖的下水道侧"}, {"户外达拉然城门与城内 NPC 通行受阵营规则限制"}}}}, steps={[1]={npc="马丁·费尔本", tgt="马丁·费尔本"}, [2]={npc="梅里萨拉", tgt="梅里萨拉"}, [3]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [4]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [5]={hint="去找到那些叛徒，夺回神器，然后向我复命，<name>。"}, [6]={hint="为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。"}, [7]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [8]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [9]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", preText="入室偷窃、城市大门钥匙"}, [10]={hint="消灭6个达拉然召唤师和8个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。"}, [11]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [12]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", preText="达拉然巡逻队、城市大门钥匙"}, [13]={hint="沿着洛丹米尔湖，寻找潜入达拉然的路线。"}, [14]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像"}, [15]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像", desc="接取即获达拉然下水道钥匙（物品 277507）；污秽钥匙只是前置。", preText="喋血街头"}, [16]={text="达拉然城 入口"}, [17]={npc="Rexxie Copperclutch", tag="需游戏内实测", desc="进本后先看下水道右侧栅栏内的地精。"}, [18]={hint="在达拉然城击败墓穴骑士阿特雷克斯，向塔伦米尔的梅里萨拉复命。", desc="位置：自入口沿下水道主路深入，到开阔处打阿崔希斯。", spot="自入口沿下水道主路深入，到开阔处打阿崔希斯"}, [19]={hint="在达拉然城，为幽暗城的马丁·费尔本收集6个开裂的哨兵核心。", desc="位置：过墓穴骑士后从右路上街，沿街清破碎哨兵。", spot="过墓穴骑士后从右路上街，沿街清破碎哨兵"}, [20]={hint="在达拉然城，为下水道入口附近的雷克希·铜抓取回《达拉然的建立》。", desc="位置：城堡阶梯左侧建筑上楼，找雕像后方的书架。", spot="城堡阶梯左侧建筑上楼，找雕像后方的书架"}, [21]={npc="Rexxie Copperclutch", tag="需游戏内实测"}, [22]={hint="在达拉然城，为塔伦米尔的大法师沃迪恩·伍德格莱尔收集奥术微粒。", desc="位置：进紫罗兰城堡开传送门，到会客室打大法师之影。", spot="进紫罗兰城堡开传送门，到会客室打大法师之影"}, [23]={npc="梅里萨拉", tgt="梅里萨拉"}, [24]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔"}, [25]={npc="马丁·费尔本", tgt="马丁·费尔本"}, [26]={npc="大法师沃迪恩·伍德格莱尔", tgt="大法师沃迪恩·伍德格莱尔", desc="部落出本交给湖岸影像，按角色当下任务标记走。", preText="动乱之源"}, [27]={hint="与达拉然附近的<name>法师茉德拉的影像对话。", desc="部落出本交给湖岸影像，按角色当下任务标记走。"}, [28]={npc="大法师茉德拉的影像", tgt="大法师茉德拉的影像", desc="部落出本交给湖岸影像，按角色当下任务标记走。"}}},
    ["05-d9"] = {name="血色修道院 墓地", entrance="提瑞斯法林地 85.20, 32.10", pickup="经希尔斯布莱德丘陵 塔伦米尔时可先开飞行点；从幽暗城沿提瑞斯法林地北路到修道院。先完成剃刀沼泽 蝙蝠的粪便（若先跑千针石林才去剃刀沼泽，把 狂热之心 留到转往奥特兰克山脉途中接；墓地可先打沃雷尔），在幽暗城炼金区找法拉内尔；离开墓地之后要到奥特兰克湖岸与塔伦米尔。", pickupS={{"经希尔斯布莱德丘陵 塔伦米尔时可先开飞行点"}, {"从幽暗城沿提瑞斯法林地北路到修道院"}, {"先完成剃刀沼泽 蝙蝠的粪便（若先跑千针石林才去剃刀沼泽，把 狂热之心 留到转往奥特兰克山脉途中接"}, {"墓地可先打沃雷尔），在幽暗城炼金区找法拉内尔"}, {"离开墓地之后要到奥特兰克湖岸与塔伦米尔"}}, tips={{k="動線", text="入口走廊清十字军并收心脏→审讯室打维沙斯，找拷问架上的沃雷尔→穿过露天墓园，下墓穴阶梯打血法师萨尔诺斯。"}, {k="取捨", text="墓地早期好组；若没有 蝙蝠的粪便 前置也可先做沃雷尔。"}, {k="說明", text="看清最左入口；墓地不需要血色十字军钥匙。", s={{"看清最左入口"}, {"墓地不需要血色十字军钥匙"}}}}, steps={[1]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="只在打算先刷剃刀沼泽时接；千针石林 闪光平原可做。"}, [2]={hint="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。", tag="可选", desc="此步骤位于剃刀沼泽中。"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选"}, [4]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="前置 蝙蝠的粪便 完整路线见剃刀沼泽。四个分区的掉落可累计，留到四个分区同一趟时再接。", preText="蝙蝠的粪便"}, [5]={text="血色修道院 墓地 入口"}, [6]={npc="沃瑞尔·森加斯", tgt="沃瑞尔·森加斯", tag="需游戏内实测", desc="前段审讯区，在拷问架上找沃雷尔。"}, [7]={hint="幽暗城的大药剂师法拉尼尔需要20颗狂热之心。", tag="可选", desc="位置：优先清入口走廊到审讯室的活人血色十字军。", spot="优先清入口走廊到审讯室的活人血色十字军"}, [8]={hint="把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。", desc="房间里可能还有另一位精英。等她巡逻到码头。"}, [9]={npc="莫尼卡·森古特斯", tgt="莫尼卡·森古特斯"}, [10]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="可选", desc="收集全部 20 个，然后交到幽暗城。"}}},
    ["03-16"] = {name="阿拉希高地", nameA="阿拉希高地 {a:321}", tips={{k="取捨", text="先清落锤镇近郊迅猛龙、辛迪加与东南边枯木。已到 32 级时，进阶的 短兵相接、迅猛龙的狡诈 留到阿拉希高地落锤镇再做。"}, {k="取捨", text="病房重新补给与蛛丝缝线是永恒版新增。先交 丝滑缝合 才接 病房补给。已到 32 级可留到第二趟。"}, {k="提醒", text="前往千针石林前若未到 32 级，从落锤镇到枯木村外围（约 68, 69）打普通枯木巨魔，避免深入怪多的营地。", s={{"前往千针石林前若未到 32 级，从落锤镇到枯木村外围（约 68, 69）打普通枯木巨魔，避免深入怪多的营地"}}}}, danger={[1]="枯木村屋内的巫医会补血，屋前有较高等的猎头者。优先沿田地边缘清，留好打断。"}, grind={[1]={mob="枯木掷斧者", note="枯木村外围，普通远程怪，密度高。从坡缘拉出单只，靠近原任务区，适合补到 32 级。"}, [2]={mob="枯木巫医", note="枯木村东侧，普通施法怪，密度高。可打断治疗并沿屋外清，留意附近更高等的枯木猎头者。"}}, supply={[1]={npc="尤尔达"}, [2]={npc="旅店老板埃德瓦"}, [3]={npc="穆塔"}, [4]={npc="旅店老板埃德瓦"}, [5]={npc="格劳德"}}, steps={[1]={hint="杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。"}, [2]={text="抵达落锤镇后开启尤尔达飞行点 73.02, 32.70。"}, [3]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [4]={npc="戈穆尔", tgt="戈穆尔"}, [5]={hint="和落锤村的托尔甘交谈。"}, [6]={npc="托尔甘", tgt="托尔甘"}, [7]={npc="托尔甘", tgt="托尔甘"}, [8]={npc="托尔甘", tgt="托尔甘"}, [9]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [10]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [11]={hint="从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。"}, [12]={hint="帮落锤村的托尔甘找10枚血石护符。"}, [13]={npc="托尔甘", tgt="托尔甘"}, [14]={npc="托尔甘", tgt="托尔甘"}, [15]={npc="托尔甘", tgt="托尔甘"}, [16]={hint="把迅猛龙利爪护符交给戈穆尔。"}, [17]={npc="戈穆尔", tgt="戈穆尔"}, [18]={npc="戈穆尔", tgt="戈穆尔"}, [19]={hint="和托尔甘谈一谈。"}, [20]={npc="托尔甘", tgt="托尔甘"}, [21]={hint="杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。"}, [22]={hint="将12份外科蛛丝交给阿拉希高地落锤镇的格里高利·维克托医生。"}, [23]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [24]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [25]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生", desc="先在同一位医生处交 丝滑缝合，才会出现补给任务。"}, [26]={hint="去格沙克农场的乔雷尔的实验室拿一箱包装好的补剂，带给落锤镇的格里高利·维克托医生。"}, [27]={npc="格里高利·维克托医生", tgt="格里高利·维克托医生"}, [28]={text="飞幽暗城整理技能与背包，到布瑞尔南侧飞艇塔搭去奥格瑞玛的飞艇。到奥格瑞玛后，已开乱风岗就直接选该飞行点；未开则飞陶拉祖营地，沿南路搭大升降梯下谷底，再往东搭乱风岗升降梯。"}}},
    ["05-d13"] = {name="血色修道院 大教堂", entrance="提瑞斯法林地 85.20, 32.10", pickup="由阿拉希高地 落锤镇飞幽暗城，满 35 级可和图书馆、军械库一起打。前往希尔斯布莱德丘陵途中，经过幽暗城时可先看皇家区瓦里玛萨斯，33 级才接 深入血色修道院；若尚未满 35 级，可在回东部王国去奥特兰克山脉时一起打。带血色十字军钥匙与图书馆、军械库的击杀进度。", pickupS={{"由阿拉希高地 落锤镇飞幽暗城，满 35 级可和图书馆、军械库一起打"}, {"前往希尔斯布莱德丘陵途中，经过幽暗城时可先看皇家区瓦里玛萨斯，33 级才接 深入血色修道院"}, {"若尚未满 35 级，可在回东部王国去奥特兰克山脉时一起打"}, {"带血色十字军钥匙与图书馆、军械库的击杀进度"}}, tips={{k="動線", text="穿过喷泉庭院上阶梯→正殿打莫格莱尼→怀特迈恩复活莫格莱尼→击败两人。"}, {k="取捨", text="若尚缺洛克希或赫洛德，先回相应分区，再一起回城。"}, {k="說明", text="带血色十字军钥匙，或请队友中开锁技能达 仰望星空 点的盗贼开门。", s={{"带血色十字军钥匙，或请队友中开锁技能达 仰望星空 点的盗贼开门"}}}}, steps={[1]={text="前置：深入血色修道院"}, [2]={text="血色修道院 大教堂 入口"}, [3]={hint="杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。", desc="大教堂先清房间周围；怀特迈恩会复活莫格莱尼。位置：穿过喷泉庭院上阶梯，进正殿打双王。顺序：莫格莱尼→怀特迈恩复活→双王。", spot="穿过喷泉庭院上阶梯，进正殿打双王。"}, [4]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="四个首领都计入后回幽暗城皇家区。"}}},
    ["05-d12"] = {name="血色修道院 武器库", entrance="提瑞斯法林地 85.20, 32.10", pickup="由阿拉希高地 落锤镇飞幽暗城，可与图书馆同趟；在幽暗城皇家区瓦里玛萨斯处接 深入血色修道院，需 33 级；若在图书馆已接，保留任务并带上血色十字军钥匙。从幽暗城走提瑞斯法林地北路到修道院。", pickupS={{"由阿拉希高地 落锤镇飞幽暗城，可与图书馆同趟"}, {"在幽暗城皇家区瓦里玛萨斯处接 深入血色修道院，需 33 级"}, {"若在图书馆已接，保留任务并带上血色十字军钥匙"}, {"从幽暗城走提瑞斯法林地北路到修道院"}}, tips={{k="動線", text="开门进军械库→沿营房和长廊到底→在大厅打赫洛德→清后续进场的血色学员。"}, {k="取捨", text="已有钥匙的队伍可直接清军械库。"}, {k="說明", text="带血色十字军钥匙，或请队友中开锁技能达 仰望星空 点的盗贼开门。", s={{"带血色十字军钥匙，或请队友中开锁技能达 仰望星空 点的盗贼开门"}}}}, steps={[1]={text="前置：深入血色修道院"}, [2]={text="血色修道院 武器库 入口"}, [3]={text="击杀勇士赫洛德，记入深入血色修道院 ；旋风斩时近战拉开。"}, [4]={text="深入血色修道院先留着，接着打大教堂；四名首领都完成才回幽暗城交。", desc="军械库后保留，继续大教堂。"}}},
    ["05-d11"] = {name="血色修道院 图书馆", entrance="提瑞斯法林地 85.20, 32.10", pickup="阿拉希高地 落锤镇回幽暗城再去图书馆；千针石林 乱风岗先做多恩 信仰的试炼→耐力的试炼→力量的试炼。已走过石爪山脉 烈日石居时，可在灰谷南线由隧道去布劳格，再到幽暗城找帕科瓦。路过雷霆崖时可顺接 堕落者纲要。可在 千针石林 闪光平原、尘泥沼泽 蕨墙村跑塔贝萨和提尔斯的前置，书可之后回东部王国时补拿。", pickupS={{"阿拉希高地 落锤镇回幽暗城再去图书馆"}, {"千针石林 乱风岗先做多恩 信仰的试炼→耐力的试炼→力量的试炼"}, {"已走过石爪山脉 烈日石居时，可在灰谷南线由隧道去布劳格，再到幽暗城找帕科瓦"}, {"路过雷霆崖时可顺接 堕落者纲要", {race={"Orc", "Tauren", "Troll"}}}, {"可在 千针石林 闪光平原、尘泥沼泽 蕨墙村跑塔贝萨和提尔斯的前置，书可之后回东部王国时补拿", {class={"MAGE"}}}}, tips={{k="動線", text="穿过入口画廊到左手小室取书→经前庭打驯犬者洛克希→在长廊末段与杜安前的书架分别取书→击败奥法师杜安，开身后箱取血色十字军钥匙。"}, {k="取捨", text="先取血色十字军钥匙，可接着开军械库与大教堂；书类任务可一起拾。"}, {k="說明", text="深入血色修道院 横跨三翼，完整做／交列在大教堂。", s={{"深入血色修道院 横跨三翼，完整做／交列在大教堂"}}}}, steps={[1]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", desc="千针石林 乱风岗已做可略。"}, [2]={hint="如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。", tag="可选", desc="千针石林 乱风岗已做可略。"}, [3]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", desc="千针石林 乱风岗已做可略。"}, [4]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="信仰的试炼"}, [5]={hint="把格林卡的爪子交给千针石林的多恩·平原行者。", tag="可选"}, [6]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选"}, [7]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="耐力的试炼"}, [8]={hint="把罗卡里姆的碎片交给千针石林的多恩·平原行者。", tag="可选"}, [9]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选"}, [10]={npc="多恩·平原行者", tgt="多恩·平原行者", tag="可选", preText="力量的试炼"}, [11]={hint="找到连接石爪山和灰谷的石爪小径里的布劳格·幽魂。", tag="可选"}, [12]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选"}, [13]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。", preText="知识试炼"}, [14]={hint="找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。"}, [15]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", desc="在山洞里找到这本书，然后返回布劳格。"}, [16]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", preText="知识试炼"}, [17]={hint="成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。", tag="可选"}, [18]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选"}, [19]={npc="布劳格·幽魂", tgt="布劳格·幽魂", tag="可选", preText="知识试炼"}, [20]={hint="找到幽暗城的帕科瓦·芬塔拉斯。", tag="可选"}, [21]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选"}, [22]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选", preText="知识试炼"}, [23]={npc="圣者图希克", tgt="圣者图希克"}, [24]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="至少 33 级。若这次未达等级，之后补接并回头打洛克希。"}, [25]={npc="迪诺", tgt="迪诺", tag="可选", desc="同任务也可找奥松·格鲁尔（25.70, 14.19）、安娜斯塔西娅·哈特威尔（85.14, 10.03）。"}, [26]={hint="和塔贝萨谈一谈。", tag="可选"}, [27]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [28]={npc="塔贝萨", tgt="塔贝萨", tag="可选", preText="沼泽之旅"}, [29]={hint="和闪光平原的大法师提尔斯谈一谈。", tag="可选"}, [30]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [31]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", preText="隐藏的秘密"}, [32]={hint="找到提尔斯保险箱的解封咒语，然后向提尔斯复命。", tag="可选"}, [33]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [34]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", preText="解封咒语"}, [35]={text="血色修道院 图书馆 入口"}, [36]={hint="找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。", tag="可选", desc="位置：入口画廊前段左侧小房，桌上取亡灵的起源。", spot="入口画廊前段左侧小房，桌上取亡灵的起源"}, [37]={hint="从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。", desc="位置：过洛克希到最后转角，找杜安走廊起点的书架。", spot="过洛克希到最后转角，找杜安走廊起点的书架"}, [38]={hint="将《能量仪祭》交给尘泥沼泽的塔贝萨。", tag="可选", desc="位置：最后一条走廊起点，找左手书架露出的书。", spot="最后一条走廊起点，找左手书架露出的书"}, [39]={text="击杀驯犬者洛克希，记入深入血色修道院 。"}, [40]={text="击杀奥法师杜安后，开他身后的保险箱，拾血色十字军钥匙。"}, [41]={npc="帕科瓦·芬塔拉斯", tgt="帕科瓦·芬塔拉斯", tag="可选"}, [42]={npc="圣者图希克", tgt="圣者图希克"}, [43]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}}},
    ["03-17"] = {name="千针石林", nameA="千针石林 {a:484}／{a:439}", shortA="千针石林 {a:484} +", tips={{k="取捨", text="闪光平原六个接任务点相近，先接齐再绕一圈。车手送件 只在下一趟经棘齿城时做。交完可向码头管理员迪兹维格接给克拉维尔的零件，留给下次经千针石林闪光平原赛道时交。"}, {k="取捨", text="保留流放者马特克 到荒芜之地卡加斯，兄弟 到凄凉之地葬影村，奈辛瓦里 赫米特·奈辛瓦里 到荆棘谷格罗姆高与藏宝海湾。"}, {k="提醒", text="若 疯狂的虫群 尚未交，略过 疯狂的虫群。视频提醒虫洞内怪物等级高，打到洞口一带就回头。虫群的样本 若完成，留到尘泥沼泽蕨墙村途经十字路口时交。", s={{"若 疯狂的虫群 尚未交，略过 疯狂的虫群"}, {"视频提醒虫洞内怪物等级高，打到洞口一带就回头"}, {"虫群的样本 若完成，留到尘泥沼泽蕨墙村途经十字路口时交"}}}, {k="提醒", text="32-34 级路线可与凄凉之地葬影村合并累积。闪光平原未到 33 级可在赛道南侧（约 76, 85）打乌龟、秃鹫与蝎子，再去凄凉之地。", s={{"32-34 级路线可与凄凉之地葬影村合并累积"}, {"闪光平原未到 33 级可在赛道南侧（约 76, 85）打乌龟、秃鹫与蝎子，再去凄凉之地"}}}}, danger={[1]="闪光平原虫洞深处的异种蝎密集且等级较高。完成疯狂的虫群后从洞口原路退出。"}, grind={[1]={mob="盐石水晶蜥蜴", note="闪光平原赛道南侧，普通怪，密度高。地势开阔，可沿盐地逐只挑选，适合 32 级补经验。"}, [2]={mob="盐壳掘地龟", note="同一片盐地往东，普通怪，密度中等。与蜥蜴轮流打，可顺便收盐壳龟壳。"}, [3]={mob="恐蝎", note="赛道东南，普通怪，密度中等。沿地表轮打即可，留意近处其他盐地野兽；有蝎毒任务可一起收。"}}, supply={[1]={npc="奈瑟"}, [2]={npc="旅店老板埃比克瓦"}, [3]={npc="斯塔恩"}, [4]={npc="旅店老板埃比克瓦"}, [5]={npc="斯塔恩"}, [6]={npc="莫塔尔"}, [7]={npc="赛恩格"}, [8]={npc="瑞兹尼克"}, [9]={npc="赛恩格"}}, steps={[1]={text="先开乱风岗奈瑟飞行点 45.14, 49.11，再沿路向东南进入闪光平原。"}, [2]={npc="峭壁卫兵图林·长角", tgt="峭壁卫兵图林·长角"}, [3]={npc="摩克塔·克林", tgt="摩克塔·克林", tag="可选"}, [4]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [5]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [6]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [7]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [8]={npc="普兹克", tgt="普兹克"}, [9]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [10]={hint="为闪光平原的菲兹尔·铜栓带去6份含盐的蝎毒。"}, [11]={hint="收集9块硬化龟壳，把它们交给闪光平原的维兹尔·铜栓。"}, [12]={hint="收集30个火箭车零件，把它们交给闪光平原的克拉维尔·浓须。"}, [13]={hint="为闪光平原的赛道管理员泽尔林杀死10条盐石蜥蜴、10条盐石水晶蜥蜴和6条盐石凝视者。"}, [14]={hint="给闪光平原的普兹克找10根空心秃鹫骨。"}, [15]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [16]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓"}, [17]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须"}, [18]={npc="赛道管理员泽尔林", tgt="赛道管理员泽尔林"}, [19]={npc="普兹克", tgt="普兹克"}, [20]={npc="菲兹尔·铜栓", tgt="菲兹尔·铜栓"}, [21]={npc="普兹克", tgt="普兹克", tag="经棘齿城才做、可选"}, [22]={npc="克拉维尔·浓须", tgt="克拉维尔·浓须", tag="经棘齿城才做、可选"}, [23]={text="若已接车手送件，可绕棘齿城一趟。"}, [24]={hint="和棘齿城的加兹鲁维谈一谈。", tag="经棘齿城才做、可选"}, [25]={hint="把克拉维尔的零件订单交给棘齿城的码头管理员迪兹维格。", tag="经棘齿城才做、可选"}, [26]={npc="加兹鲁维", tgt="加兹鲁维", tag="经棘齿城才做、可选"}, [27]={npc="码头管理员迪兹维格", tgt="码头管理员迪兹维格", tag="经棘齿城才做、可选"}, [28]={npc="加兹鲁维", tgt="加兹鲁维", tag="可选"}, [29]={npc="破碎的异种蝎壳", npcObj=true, tag="疯狂的虫群 途中掉落才接、可选", desc="打 疯狂的虫群 时掉落破碎的异种蝎壳，捡到后要点物品才会接到任务。"}, [30]={hint="收集1颗异种蝎的心脏、5只异种蝎的爪子和3个完整的异种蝎壳，把它们和你手中的这个破碎的异种蝎壳一起交给十字路口的科兰。", tag="和 疯狂的虫群 同一趟打、可选"}, [31]={hint="杀掉5只异种搜寻者、5只异种筑巢蝎和5只异种侵略者，然后向千针石林的摩克塔·克林复命。", tag="可选"}, [32]={npc="摩克塔·克林", tgt="摩克塔·克林", tag="可选"}, [33]={hint="把水灵碎片交给贫瘠之地的水之先知伊斯伦。", desc="完成任务即可获得水之图腾。"}, [34]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", desc="完成任务即可获得水之图腾。"}, [35]={npc="希尔恩·火结", tgt="希尔恩·火结", desc="奥格瑞玛训练师可接 空气的召唤，雷霆崖可用同线替代引导 空气的召唤。"}, [36]={hint="到千针石林去找普拉特·白云。", desc="奥格瑞玛训练师可接 空气的召唤，雷霆崖可用同线替代引导 空气的召唤。"}, [37]={npc="普拉特·白云", tgt="普拉特·白云", desc="奥格瑞玛训练师可接 空气的召唤，雷霆崖可用同线替代引导 空气的召唤。"}, [38]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="剃刀沼泽尾王掉落便笺，保留到奥特兰克山脉交。同一任务也可找劳恩·峭壁行者（46.14, 51.71）。"}, [39]={hint="在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。", tag="可选", desc="剃刀沼泽尾王掉落便笺，保留到奥特兰克山脉交。"}, [40]={text="在闪光平原收完任务，沿谷底原路回乱风岗，搭升降梯上飞行点，再飞石爪山脉烈日石居。从烈日石居往西南穿过烧焦谷进入凄凉之地。"}}},
    ["05-d14"] = {name="剃刀沼泽", entrance="贫瘠之地（1413），荆棘通道的副本入口附近，约 42.30, 89.90。", pickup="前往千针石林时可顺路进本。在贫瘠之地 棘齿城可先接 蓝叶薯 并拿地鼠工具；前往希尔斯布莱德丘陵途中，经过幽暗城时找法拉内尔接 蝙蝠的粪便；进本前若经雷霆崖找奥尔德接 奥尔德的报复。可从千针石林 乱风岗出发，经大升降梯回贫瘠之地，走西侧荆棘路进本。", pickupS={{"前往千针石林时可顺路进本"}, {"在贫瘠之地 棘齿城可先接 蓝叶薯 并拿地鼠工具"}, {"前往希尔斯布莱德丘陵途中，经过幽暗城时找法拉内尔接 蝙蝠的粪便"}, {"进本前若经雷霆崖找奥尔德接 奥尔德的报复"}, {"可从千针石林 乱风岗出发，经大升降梯回贫瘠之地，走西侧荆棘路进本"}}, tips={{k="動線", text="入口荆棘道沿路用地鼠找蓝叶薯→走支路打鲁古格→贾格巴→拉姆塔斯→蝙蝠洞收粪便→卡尔加小屋打王、拾心脏与任务物品→路清完再回尾王旁营帐，护送威利克斯到入口。"}, {k="取捨", text="想接狂热之心与剃刀高地后续，尾王及前厅蝙蝠都要打；只有短时间可先做沿路地鼠或护送。"}, {k="說明", text="大升降梯西侧是剃刀沼泽；东侧是剃刀高地。42.30, 89.90 为永恒版客户端的门口标记。从大路沿西侧荆棘隧道找传送门。", s={{"大升降梯西侧是剃刀沼泽"}, {"东侧是剃刀高地"}, {"42.30, 89.90 为永恒版客户端的门口标记"}, {"从大路沿西侧荆棘隧道找传送门"}}}}, steps={[1]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯", desc="棘齿城同 NPC 旁拿箱、指挥棒及说明物件；进本要用。"}, [2]={npc="奥尔德·石塔", tgt="奥尔德·石塔"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="交后开血色修道院的 狂热之心。"}, [4]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选"}, [5]={hint="收集5根颤抖的触角，把它们带给贫瘠之地陶拉祖营地的鲁迦。", tag="可选"}, [6]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选"}, [7]={npc="鲁迦·狂暴图腾", tgt="鲁迦·狂暴图腾", tag="可选", preText="巨人旷野的试炼"}, [8]={hint="与贫瘠之地的索恩格瑞姆·火眼谈一谈。", tag="可选"}, [9]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选"}, [10]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选", desc="先准备烟雾铁锭 ×15、蓝铜粉 ×10、铁锭 ×10；剃刀沼泽拿最后材料。", preText="巨人旷野的试炼、和索恩格瑞姆交谈"}, [11]={npc="希尔恩·火结", tgt="希尔恩·火结", tag="副本前置链"}, [12]={npc="普拉特·白云", tgt="普拉特·白云", tag="副本前置链"}, [13]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="30 级图腾线；依角色在千针石林找能给任务的 NPC。同任务也可找劳恩·峭壁行者（46.14, 51.71）。"}, [14]={text="剃刀沼泽 入口"}, [15]={hint="找到一个开孔的箱子。", desc="位置：荆棘道沿途挖薯，威利克斯回程也可挖。", spot="荆棘道沿途挖薯，威利克斯回程也可挖。"}, [16]={hint="为索恩格瑞姆收集15根烟雾铁锭、10份蓝铜粉、10块铁锭和1瓶燃素。", tag="可选", desc="位置：入口前段找鲁古格支路，先清他身旁小怪。", spot="入口前段找鲁古格支路，先清他身旁小怪。"}, [17]={npc="进口商威利克斯", tgt="进口商威利克斯", tag="需游戏内实测", desc="从地下城内的NPC开始护送。"}, [18]={hint="护送进口商威利克斯逃出剃刀沼泽。", desc="从地下城内的NPC开始护送。位置：尾王旁营帐出发，跟威利克斯走回入口。顺序：清完第 17-20 步再接护送。", spot="尾王旁营帐出发，跟威利克斯走回入口。"}, [19]={npc="进口商威利克斯", tgt="进口商威利克斯", tag="需游戏内实测", desc="从地下城内的NPC开始护送。", spot="副本入口处，护送终点"}, [20]={hint="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。", desc="位置：前往尾王前的蝙蝠洞，打穴居蝙蝠。", spot="前往尾王前的蝙蝠洞，打穴居蝙蝠。"}, [21]={hint="把卡尔加·刺肋的心脏交给雷霆崖的奥尔德·石塔。", desc="位置：出蝙蝠洞上平台，到尾端小屋打卡尔加。", spot="出蝙蝠洞上平台，到尾端小屋打卡尔加。"}, [22]={hint="在剃刀沼泽击败卡尔加·刺肋，收集有关野猪人计划的情报。", tag="可选", desc="位置：跟第 18 步同打尾端小屋的卡尔加。顺序：与第 18 步一起拾取。", spot="跟第 18 步同打尾端小屋的卡尔加。"}, [23]={npc="小卷轴", npcObj=true, tag="可选、需游戏内实测", desc="卡尔加·刺肋掉小卷轴；右键接，留幽暗城。"}, [24]={npc="麦伯克·米希瑞克斯", tgt="麦伯克·米希瑞克斯"}, [25]={npc="奥尔德·石塔", tgt="奥尔德·石塔"}, [26]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", desc="在幽暗城交完就接狂热之心 。"}, [27]={hint="把小卷轴交给幽暗城的瓦里玛萨斯。", tag="可选"}, [28]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", tag="可选"}, [29]={npc="索恩格瑞姆·火眼", tgt="索恩格瑞姆·火眼", tag="可选"}, [30]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="奥特兰克山脉到奥特兰克时交件。若日志显示乱风岗，按提示交劳恩·峭壁行者（46.14, 51.71）。"}}},
    ["03-18"] = {name="凄凉之地", nameA="凄凉之地 {a:2408}", tips={{k="取捨", text="大道劫匪与集骨者一起跑，顺手点营火再去比布里的小屋。三段任务等级皆为 40、最低 30 级，亡命之徒留到荆棘谷藏宝海湾交。"}, {k="取捨", text="吉尔吉斯线 吉尔吉斯部族／偷取物资 顺南路。已选玛格拉姆或声望相反时，跳过这两步与凄凉之地葬影村的吉尔吉斯后续任务。"}, {k="取捨", text="葬影村去西岸时一起做两个水域任务与上古之书。雷斧堡垒先打圣光节杖与埃鲁索斯之手，若进度不足再到第二趟补交。"}, {k="取捨", text="没遇到车队就直接走，不原地等护送。保留荆棘谷狩猎 到下一站。"}, {k="提醒", text="前往荆棘谷前若未到 34 级，在科多坟地周围打普通半人马（约 56, 60-68），或在西岸打滑刃纳迦（35.91, 28.84）。", s={{"前往荆棘谷前若未到 34 级，在科多坟地周围打普通半人马（约 56, 60-68），或在西岸打滑刃纳迦（35.91, 28.84）"}}}}, danger={[1]="西岸纳迦点靠近水下玛库拉。先把施法怪拉到沙滩，避免水下同时进两群。"}, grind={[1]={note="科多坟地东侧外围，普通怪，密度较低。留意其他食腐鸟，离坟地任务近，适合顺手补少量经验。"}, [2]={mob="滑刃纳迦", note="西岸水边，普通怪，密度高。沿岸挑落单的，留意同区巫女，西岸任务可以一起清。"}, [3]={mob="滑刃巫师", note="西岸纳迦区南端，普通施法怪，密度中等。把怪拉向岸边再打，避免水下玛库拉连带入战。"}}, supply={[1]={npc="萨隆"}, [2]={npc="旅店老板希科瓦"}, [3]={npc="海维拉尼"}, [4]={npc="旅店老板希科瓦"}, [5]={npc="图克"}}, steps={[1]={npc="费古尔·双刃", tgt="费古尔·双刃"}, [2]={npc="古尔达·蛮鬃", tgt="古尔达·蛮鬃"}, [3]={npc="古尔达·蛮鬃", tgt="古尔达·蛮鬃"}, [4]={npc="纳塔卡·长角", tgt="纳塔卡·长角"}, [5]={hint="将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。"}, [6]={npc="纳塔卡·长角", tgt="纳塔卡·长角"}, [7]={npc="斯米德·瑟卡布斯库", tgt="斯米德·瑟卡布斯库"}, [8]={hint="将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。"}, [9]={npc="斯米德·瑟卡布斯库", tgt="斯米德·瑟卡布斯库"}, [10]={text="沿南路过吉尔吉斯村，到葬影村开启萨隆飞行点 21.60, 74.13，绑定炉石。"}, [11]={npc="鲁恩·蛮鬃", tgt="鲁恩·蛮鬃"}, [12]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [13]={npc="麦拉斯", tgt="麦拉斯"}, [14]={npc="杜泽加尔", tgt="杜泽加尔"}, [15]={npc="阿卡莱", tgt="阿卡莱"}, [16]={text="海岸 → 雷斧堡垒 → 东侧萨特"}, [17]={npc="拉克摩尔的日志", npcObj=true}, [18]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [19]={npc="恶魔之皮", npcObj=true, tag="有掉落才做、可选", desc="点怪物掉落的恶魔之皮才会开启连锁，没有掉就先继续走。"}, [20]={hint="把恶魔之皮拿给凄凉之地的玛乌林·碎骨看看。", tag="有掉落才做、可选"}, [21]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="有掉落才做、可选"}, [22]={hint="拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。"}, [23]={hint="在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。", desc="在雷斧堡垒对红色水晶使用恶魔之锄，打倒出现的恶魔之魂取得恶魔之盒。"}, [24]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [25]={npc="阿佐尔·奥达蒙特", tgt="阿佐尔·奥达蒙特"}, [26]={npc="玛乌林·碎骨", tgt="玛乌林·碎骨", tag="可选"}, [27]={hint="在凄凉之地的萨格隆击败各种怨怒萨特，然后返回