    ["03-19"] = {name="荆棘谷", tips={{k="取捨", text="藏宝海湾初次到访就交亡命之徒并买酒完成「你在想樱桃酒吗？」。之后会去阿拉希高地东南离岸岛，再接后续盗却无道。"}, {k="取捨", text="祖昆达找得到吉米克斯才跑钥匙与护送，钥匙与遭窃货物同区。已有人护送可直接继续主线。[台服任务记录](https://wowamobi.com/quests/钥匙在哪？)"}, {k="取捨", text="藏宝海湾第 1 次到访主要开飞行点并接任务；约 35 级只交第一批：血顶巨魔的耳朵、调查营地、供与求、歌唱水晶碎片、恶性竞争，及已做完的 搜刮财物／齐米克斯大逃亡。交 供与求 和 歌唱水晶碎片 才开 收集鳄鱼皮 和 风险投资公司。"}, {k="取捨", text="先别交 风险投资公司、 刨花皮靴，留到荆棘谷藏宝海湾并南谷回收。收集鳄鱼皮 完成后留到荆棘谷藏宝海湾先交，再接 。"}, {k="取捨", text="42 级回访才排血帆 血帆海盗→血帆海盗→血帆海盗→血帆海盗→血帆海盗，并 海盗的眼睛／鼻烟、赞吉尔的秘密、吓唬病鬼→向马克基雷回报→讨债行动。先别排 荆棘谷热疫／荆棘谷热疫 热疫、→ 瓶中信、 船长的箱子、威士忌斯利姆的酒 酒和 你自己的OOX OOX，见荆棘谷藏宝海湾的 45 级后清单。视频的分次交原则保留，具体 ID 为路线配置。"}, {k="取捨", text="先把猎龙解到 ，再和 格罗姆高保卫战 一起打鞭尾迅猛龙。歌唱水晶碎片 先打北边的晶脊蜥蜴，第一趟无须绕去南谷。"}, {k="取捨", text="若 34 级空白起步，先做三条猎线头两轮，并做格罗姆高与血顶巨魔群。深喉猎豹同时解 ／摩克萨尔丁的魔法，普通辛达尔 猎虎 同圈处理。奈兹里奥克 的三件战利品留到荆棘谷藏宝海湾和裂骨项链一起做。荆棘谷的青山 -荆棘谷的青山 - 第四章 有散页再交。"}, {k="提醒", text="35 级可组队打沉没之城（35-40）。先确认队伍与相关任务，从格罗姆高西边海底入场。", s={{"35 级可组队打沉没之城（35-40）"}, {"先确认队伍与相关任务，从格罗姆高西边海底入场"}}}, {k="提醒", text="约 34-35 级先在北谷打血顶巨魔（29.76, 21.62）；36 级后转格罗姆高东南的食人魔营地（35.55, 30.92），缺多少就在这里补到 37 级再搭飞艇。先交营地里已完成的任务。", s={{"约 34-35 级先在北谷打血顶巨魔（29.76, 21.62）"}, {"36 级后转格罗姆高东南的食人魔营地（35.55, 30.92），缺多少就在这里补到 37 级再搭飞艇"}, {"先交营地里已完成的任务"}}}}, danger={[1]="暗礁海遗迹有盐鳞精英。从海面下潜贴外墙找石板，留足呼吸时间折返。", [2]="祖昆达废墟的吉米克斯护送会走过巡逻路。接护送前先清营地外侧。"}, grind={[1]={mob="血顶战士", note="北谷血顶遗迹，普通怪，密度中等。沿外墙挑落单的，留意附近的血顶萨满，适合 34 级补经验。可同趟收旋风武器任务用的血顶獠牙。"}, [2]={mob="鞭尾迅猛龙", note="格罗姆高以北的林地，普通怪，密度高。沿路找单只，避开下水后的盐鳞精英，可顺做迅猛龙猎杀。"}, [3]={mob="莫什奥格蛮兵", note="格罗姆高东南食人魔营地外围，普通怪，密度中等。避开巫医与稀有怪罗洛克，36 级后可就近补到 37 级。"}}, supply={[1]={npc="塞斯塔"}, [2]={npc="旅店老板苏贝克"}, [3]={npc="克拉克"}, [4]={npc="纳加特"}, [5]={npc="尤索克"}, [6]={npc="格林戈"}, [7]={npc="旅店老板斯金德"}, [8]={npc="祖塔克"}, [9]={npc="尼克拉克斯·菲拉莫格"}, [10]={npc="哈伦·坎麦尔"}}, steps={[1]={text="在奥格瑞玛城外飞艇塔搭去格罗姆高的飞艇，抵达后开启塞斯塔飞行点 32.54, 29.35。已在荆棘谷者直接到营地。"}, [2]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什"}, [3]={npc="尼姆布亚", tgt="尼姆布亚", tag="怪多、可选"}, [4]={npc="肯维雷", tgt="肯维雷", tag="怪多、可选"}, [5]={npc="先知摩克萨尔丁", tgt="先知摩克萨尔丁"}, [6]={npc="尼姆布亚", tgt="尼姆布亚"}, [7]={npc="肯维雷", tgt="肯