    ["05-d16"] = {name="The Drowned City", entrance="荆棘谷 21.50, 27.70", pickup="荆棘谷第一次已排进主线：格罗姆高接 先做暗礁海、交后接 古老的古拉巴什传说；藏宝海湾找克拉兹克接 可疑的盐水先知、盐水先知船长；祖尔昆达拓印 古老的古拉巴什传说；回格罗姆高接 定位失落之城、水中的敌人 在西岸一起做完，交后接 沉没之城、唯一的好盐鳞……。若已开雷霆崖飞行点，进本前可飞雷霆崖，沿莫高雷道路去天空观测高台找马祖康。接齐后回格罗姆高，自西岸下水游到水下传送门。", pickupS={{"荆棘谷第一次已排进主线：格罗姆高接 先做暗礁海、交后接 古老的古拉巴什传说"}, {"藏宝海湾找克拉兹克接 可疑的盐水先知、盐水先知船长"}, {"祖尔昆达拓印 古老的古拉巴什传说"}, {"回格罗姆高接 定位失落之城、水中的敌人 在西岸一起做完，交后接 沉没之城、唯一的好盐鳞……"}, {"若已开雷霆崖飞行点，进本前可飞雷霆崖，沿莫高雷道路去天空观测高台找马祖康"}, {"接齐后回格罗姆高，自西岸下水游到水下传送门"}}, tips={{k="動線", text="祖尔阿莱→伐塔卡→惧涌船长→不灭之髓→圣蛇米洛斯。沿途在入口水池左侧、伐塔卡左侧、船区头骨嘴里和米洛斯身后拓印石板；船区同时清海盗并收神器。原初元素与基尔可选。"}, {k="取捨", text="格罗姆高的两条前置先做，避免游一趟只解船区；莫高雷单一交件太远时可略。"}, {k="說明", text="副本门在格罗姆高以西的水下洞窟。带水下呼吸药剂，或请有技能的队友施放。", s={{"副本门在格罗姆高以西的水下洞窟"}, {"带水下呼吸药剂，或请有技能的队友施放"}}}}, steps={[1]={npc="肯维雷", tgt="肯维雷", desc="荆棘谷 格罗姆高与藏宝海湾已做可略。"}, [2]={hint="给格罗姆高营地里的肯维雷带回一块石板碎片。", desc="荆棘谷 格罗姆高与藏宝海湾已做可略。"}, [3]={npc="肯维雷", tgt="肯维雷", desc="荆棘谷 格罗姆高与藏宝海湾已做可略。"}, [4]={npc="肯维雷", tgt="肯维雷", preText="暗礁海"}, [5]={hint="使用兽皮和木炭，拓印巨魔传说第三章石板。"}, [6]={npc="肯维雷", tgt="肯维雷"}, [7]={npc="肯维雷", tgt="肯维雷", preText="古老的古拉巴什传说"}, [8]={hint="探索暗礁海并找到洞穴入口。"}, [9]={npc="肯维雷", tgt="肯维雷"}, [10]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", desc="荆棘谷 格罗姆高与藏宝海湾已有此步。先交 暗礁海 后向指挥官确认；若任务已出现，可在肯维雷往返时顺手做。", preText="暗礁海、古老的古拉巴什传说"}, [11]={hint="从盐鳞游击者那里收集10把盐鳞三叉戟。", tag="目标：海鳞争斗者", desc="荆棘谷 格罗姆高与藏宝海湾已有此步。先交 暗礁海 后向指挥官确认；若任务已出现，可在肯维雷往返时顺手做。"}, [12]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", desc="荆棘谷 格罗姆高与藏宝海湾已有此步。先交 暗礁海 后向指挥官确认；若任务已出现，可在肯维雷往返时顺手做。"}, [13]={npc="肯维雷", tgt="肯维雷", preText="定位失落之城"}, [14]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什", preText="水中的敌人、定位失落之城"}, [15]={npc="克拉兹克", tgt="克拉兹克"}, [16]={npc="克拉兹克", tgt="克拉兹克"}, [17]={npc="马祖康", tgt="马祖康", tag="可选", desc="马祖康位于莫高雷天空观测高台。已有该地交通点再绕。"}, [18]={text="The Drowned City 入口"}, [19]={hint="使用兽皮和木炭，拓印在沉没之城找到的石板。", desc="位置：水池左→伐塔卡左→船长旁骷髅嘴→尾王后。顺序：依四个地标沿途拓印。", spot="水池左→伐塔卡左→船长旁骷髅嘴→尾王后。"}, [20]={hint="在沉没之城消灭瓦尔塔卡。", desc="先处理身旁的祭司，留意水下呼吸。位置：过祖尔阿莱进水下档案区，找两名祭司旁的王。", spot="过祖尔阿莱进水下档案区，找两名祭司旁的王。"}, [21]={hint="从沉没之城的盐水先知海盗手中收集10个注入巫毒的神器。", desc="收不齐就继续清船区的海盗。位置：进盐占海盗船区，沿路清海盗收神器。顺序：和第 21 步同区清理。", spot="进盐占海盗船区，沿路清海盗收神器。"}, [22]={hint="在沉没之城消灭3个盐水先知验尸官和德雷德莱斯船长。", desc="位置：清理船长附近通道沿线的验尸官。顺序：杀死船长后点击发光珍珠。", spot="清理船长附近通道沿线的验尸官。"}, [23]={hint="从沉没之城找回一个远古古拉巴什神像。", tag="可选", desc="位置：过船长和珍珠屏障，进后段打不灭之髓。", spot="过船长和珍珠屏障，进后段打不灭之髓。"}, [24]={npc="肯维雷", tgt="肯维雷"}, [25]={npc="指挥官阿格罗戈什", tgt="指挥官阿格罗戈什"}, [26]={npc="克拉兹克", tgt="克拉兹克"}, [27]={npc="克拉兹克", tgt="克拉兹克"}, [28]={npc="马祖康", tgt="马祖康", tag="可选"}, [29]={npc="肯维雷", tgt="肯维雷", tag="可选", desc="如果还要飞回奥格瑞玛，顺手回报；不影响这次下本。", preText="沉没之城"}, [30]={hint="把石板拓片交给杜隆塔尔森金村的加德林大师。", tag="可选", desc="如果还要飞回奥格瑞玛，顺手回报；不影响这次下本。"}, [31]={npc="加德林大师", tgt="加德林大师", tag="可选", desc="如果还要飞回奥格瑞玛，顺手回报；不影响这次下本。"}}},
    ["05-d15"] = {name="诺莫瑞根", entrance="荆棘谷 27.60, 77.48", pickup="前往荆棘谷 藏宝海湾前，在奥格瑞玛 荣誉谷先找索维克和诺格。从棘齿城坐船到藏宝海湾，或格罗姆高飞藏宝海湾；斯库提完成 主工程师斯库提→出发！诺莫瑞根！ 后，保留地精转发器进入。", pickupS={{"前往荆棘谷 藏宝海湾前，在奥格瑞玛 荣誉谷先找索维克和诺格"}, {"从棘齿城坐船到藏宝海湾，或格罗姆高飞藏宝海湾"}, {"斯库提完成 主工程师斯库提→出发！"}, {"诺莫瑞根！"}, {"后，保留地精转发器进入"}}, tips={{k="動線", text="入本左转下坡到清洁区→右侧宿舍护送克努比→电刑器6000型→群体打击者9-60→瑟玛普拉格，拾密码开保险箱。打到脏兮兮的戒指后回清洁区用超级清洁器。"}, {k="取捨", text="装备或任务经验值得时再打；和藏宝海湾任务一起交最省路。"}, {k="說明", text="传送到丹莫罗的设施后，循地下走道到副本门；不走铁炉堡。若未解斯库提，先完成传送链。", s={{"传送到丹莫罗的设施后，循地下走道到副本门"}, {"不走铁炉堡"}, {"若未解斯库提，先完成传送链"}}}}, steps={[1]={npc="诺格", tgt="诺格"}, [2]={npc="索维克", tgt="索维克", preText="设备之战"}, [3]={hint="和藏宝海湾的斯库提谈一谈。"}, [4]={npc="斯库提", tgt="斯库提"}, [5]={npc="斯库提", tgt="斯库提", preText="主工程师斯库提"}, [6]={hint="等斯库提调整好地精传送器。"}, [7]={npc="斯库提", tgt="斯库提"}, [8]={text="诺莫瑞根 入口"}, [9]={hint="从诺莫瑞根拿到钻探设备蓝图和瑟玛普拉格的保险箱密码，把它们交给奥格瑞玛的诺格。", desc="战斗时让人去按掩体旁的按钮控制炸弹。位置：沿工坊深处通道进尾王圆厅，杀王后开箱。", spot="沿工坊深处通道进尾王圆厅，杀王后开箱。"}, [10]={npc="克努比", tgt="克努比", tag="需游戏内实测", desc="在清洁区附近找到克努比；先清护送路线。"}, [11]={hint="将克努比护送到出口，然后向藏宝海湾的斯库提汇报。", desc="位置：清洁区旁宿舍接人，沿发条小径回正门。顺序：可先做第 9-10 步再深入尾王。", spot="清洁区旁宿舍接人，沿发条小径回正门。"}, [12]={npc="脏兮兮的戒指", npcObj=true, tag="可选、需游戏内实测", desc="带 3 银币，依机器对话操作。"}, [13]={hint="想方法把脏兮兮的戒指弄干净。", tag="可选", desc="带 3 银币，依机器对话操作。位置：入门左转下坡，到清洁区墙边找清洁器。顺序：先从黑铁特工取得戒指。", spot="入门左转下坡，到清洁区墙边找清洁器。"}, [14]={npc="超级清洁器5200型", npcObj=true, tag="可选、需游戏内实测", desc="带 3 银币，依机器对话操作。", spot="入门左转下坡，清洁区墙边的清洁器"}, [15]={npc="超级清洁器5200型", npcObj=true, tag="可选、需游戏内实测", preText="脏兮兮的戒指"}, [16]={npc="斯库提", tgt="斯库提"}, [17]={npc="诺格", tgt="诺格"}, [18]={hint="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。", tag="可选"}, [19]={npc="诺格", tgt="诺格", tag="可选"}}},
    ["03-20"] = {name="尘泥沼泽", nameA="尘泥沼泽 {a:496}", tips={{k="取捨", text="黑色盾牌 、可疑的蹄印 、雷瑟上尉 帕瓦尔·雷瑟上尉 三件在同一座烧毁旅店。先接齐再进村。"}, {k="取捨", text="舒心草带 3 份再出城。月钢宽剑已有就交，特地买或锻造会增加折返。伊格纳兹的逃亡 在棘齿城交，当趟不路过就保留或略过。"}, {k="提醒", text="蕨墙村和凄凉之地葬影村共用 37→38 的经验带。若凄凉之地回访的任务已交过，可在尘泥北边打普通蜘蛛怪和迅猛龙，靠尘泥沼泽蕨墙村的北沼泽任务怪点补到 38 级。", s={{"蕨墙村和凄凉之地葬影村共用 37→38 的经验带"}, {"若凄凉之地回访的任务已交过，可在尘泥北边打普通蜘蛛怪和迅猛龙，靠尘泥沼泽蕨墙村的北沼泽任务怪点补到 38 级"}}}}, danger={[1]="北沼泽的毒蜘蛛与迅猛龙巡逻路重叠。沿外侧挑单只，避开草丛内的交会点。"}, grind={[1]={mob="枯藤沼泽兽", note="北沼泽枯藤地，普通怪，密度高。与其他枯藤怪混杂，沿陆地逐只清，等级贴近离站门槛。"}, [2]={mob="暗牙毒蜘蛛", note="北沼泽东侧，普通怪，密度中等。留意毒伤和迅猛龙巡逻，枯藤区有人清怪时可换点。"}, [3]={mob="血沼尖啸龙", note="北沼泽林缘，普通怪，密度高。旁边有鳄鱼与其他迅猛龙，沿岸挑单只，打到 38 级即可离站。"}}, supply={[1]={npc="沙尔迪"}, [2]={npc="克伦卡"}, [3]={npc="奥克玛尔"}, [4]={npc="萨纳拉"}, [5]={npc="巴莱·洛克维"}}, steps={[1]={npc="科兰", tgt="科兰", tag="可选"}, [2]={text="从陶拉祖营地往东进尘泥沼泽，先停在路边烧毁的旅店。"}, [3]={npc="黑色盾牌", npcObj=true}, [4]={npc="蹄印", npcObj=true}, [5]={npc="塞拉摩卫兵徽章", npcObj=true}, [6]={nodeA="{a:496}", desc="向沙尔迪开启飞行点。"}, [7]={text="保留先前绑在凄凉之地葬影村的炉石，留给下一站回程。"}, [8]={hint="把被熏黑的铁盾牌带给蕨墙村的克罗格。"}, [9]={hint="把树荫旅店的可疑蹄印报告给蕨墙村的克罗格。"}, [10]={hint="把雷瑟的徽章带给蕨墙村的克罗格。"}, [11]={npc="克罗格", tgt="克罗格"}, [12]={npc="克罗格", tgt="克罗格"}, [13]={npc="克罗格", tgt="克罗格"}, [14]={npc="克罗格", tgt="克罗格"}, [15]={hint="把被熏黑的铁盾牌拿给蕨墙村的杜高尔看一看。"}, [16]={npc="杜高尔", tgt="杜高尔"}, [17]={npc="杜高尔", tgt="杜高尔"}, [18]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [19]={npc="马德克拉什", tgt="马德克拉什"}, [20]={npc="奥格隆", tgt="奥格隆"}, [21]={hint="和奥格隆一起去和雷瑟谈一谈，然后回到蕨墙村见克罗格。"}, [22]={npc="克罗格", tgt="克罗格"}, [23]={hint="杀掉9个塞拉摩间谍，然后回到蕨墙村去见纳泽尔·血矛。"}, [24]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [25]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [26]={text="北路护送 → 水光庄园 → 海边"}, [27]={npc="伊格纳兹", tgt="伊格纳兹", tag="顺路到棘齿城才交、可选"}, [28]={hint="护送伊格纳兹，然后和棘齿城的麦伯克·米希瑞克斯谈一谈。", tag="可选"}, [29]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [30]={hint="为尘泥沼泽的\"沼泽之眼\"加尔收集3棵舒心草。"}, [31]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [32]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [33]={npc="松软的泥土", npcObj=true}, [34]={hint="收集40颗黑雾蜘蛛的眼球，把它们交给水光庄园的\"沼泽之眼\"加尔。"}, [35]={hint="把间谍的报告交给蕨墙村的纳泽尔·血矛。"}, [36]={hint="为蕨墙村的杜高尔收集6个酸性毒囊。"}, [37]={hint="把指挥官的文件交给蕨墙村的纳泽尔·血矛。"}, [38]={hint="尘泥沼泽北部的马德克拉什要你去抓12条泥鳍小鱼。"}, [39]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔"}, [40]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [41]={npc="杜高尔", tgt="杜高尔"}, [42]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [43]={npc="马德克拉什", tgt="马德克拉什"}, [44]={npc="杜高尔", tgt="杜高尔"}, [45]={hint="和蕨墙村的克罗格谈一谈。"}, [46]={npc="克罗格", tgt="克罗格"}, [47]={npc="克罗格", tgt="克罗格", tag="可选"}, [48]={text="可选回程与跨区线"}, [49]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔", tag="已备月钢宽剑、可选"}, [50]={hint="给尘泥沼泽的加尔找一把月光剑。", tag="已备月钢宽剑、可选", desc="需要一把月钢宽剑，有成品再去交。"}, [51]={npc="沼泽之眼加尔", tgt="沼泽之眼加尔", tag="已备月钢宽剑、可选"}, [52]={npc="松软的泥土", npcObj=true, tag="可选"}, [53]={hint="把兽人的头颅交给蕨墙村的纳泽尔·血矛。", tag="可选"}, [54]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", tag="可选"}, [55]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", tag="可选"}, [56]={npc="迪诺", tgt="迪诺", tag="可选", desc="本路线经奥格瑞玛。已在雷霆崖可找奥松·格鲁尔（25.70, 14.19），在幽暗城可找安娜斯塔西娅·哈特威尔（85.14, 10.03）。"}, [57]={hint="和塔贝萨谈一谈。", tag="可选"}, [58]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [59]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先保留 10 根图腾束，到外禁锢法阵再互动合成。"}, [60]={hint="将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。", tag="可选", desc="先保留 10 根图腾束，到外禁锢法阵再互动合成。"}, [61]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先保留 10 根图腾束，到外禁锢法阵再互动合成。"}, [62]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [63]={hint="和闪光平原的大法师提尔斯谈一谈。", tag="可选"}, [64]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选"}, [65]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="选取小鸡输入 /beckon，等它变成人后交谈。"}, [66]={hint="找到提尔斯保险箱的解封咒语，然后向提尔斯复命。", tag="可选", desc="选取小鸡输入 /beckon，等它变成人后交谈。"}, [67]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="选取小鸡输入 /beckon，等它变成人后交谈。"}, [68]={npc="大法师提尔斯", tgt="大法师提尔斯", tag="可选", desc="组队进图书馆，在书架上找书。"}, [69]={hint="将《能量仪祭》交给尘泥沼泽的塔贝萨。", tag="可选", desc="组队进图书馆，在书架上找书。进入血色修道院后走图书馆区。"}, [70]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="组队进图书馆，在书架上找书。"}, [71]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="两条魔杖材料线都完成才回报。", star={"冰怒魔杖 / 虚空灵力魔杖 / 怒火魔杖"}}, [72]={hint="等塔贝萨的仪式完成后，和她谈一谈。", tag="可选", desc="两条魔杖材料线都完成才回报。"}, [73]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="两条魔杖材料线都完成才回报。", star={"冰怒魔杖 / 虚空灵力魔杖 / 怒火魔杖"}}, [74]={text="回蕨墙村，在飞行地图选葬影村。若未显示可达航线，就先飞十字路口转乘。保留炉石给凄凉之地葬影村集会所回程。"}}},
    ["03-21"] = {name="凄凉之地", nameA="凄凉之地 {a:2408}", tips={{k="取捨", text="视频有这趟回访。37 级缺经验时，补做东南侧半人马和附近的燃烧军团传送门；凄凉之地葬影村交过埃鲁索斯之手才接得到 燃烧军团的传送门。幽灵电浆可用箱子引出怪物后逐只处理。"}, {k="取捨", text="盎格库尔 的目标在悲伤沼泽。先接，留到悲伤沼泽斯通纳德顺路做。杰恩可汗 在回村交 后才接得到，留往后补。"}, {k="提醒", text="还未到 38 级，就在玛诺洛克集会所外圈（约 50.40, 70.40）打普通恶魔；若杀得慢，可回科多坟地东南的半人马区。", s={{"还未到 38 级，就在玛诺洛克集会所外圈（约 50.40, 70.40）打普通恶魔"}, {"若杀得慢，可回科多坟地东南的半人马区"}}}}, danger={[1]="玛诺洛克集会所南侧有精英领主。若只要补经验或材料，在东侧打法师猎手即可。"}, grind={[1]={mob="次级地狱火", note="玛诺洛克集会所北外圈，普通怪，密度高。留意周边其他恶魔。可顺便拿魔化金线血袍任务需要的次级地狱火石。"}, [2]={note="集会所同一片外圈，普通施法怪，密度中等。用地形拉出群怪，可与次级地狱火轮打。"}, [3]={mob="法师猎手", note="集会所东侧，普通怪，密度中等。沿外缘找单只，避开南面的精英领主；若外圈人多，可换到这里补经验。"}}, supply={[1]={npc="萨隆"}, [2]={npc="旅店老板希科瓦"}, [3]={npc="海维拉尼"}, [4]={npc="旅店老板希科瓦"}, [5]={npc="图克"}}, steps={[1]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [2]={text="从葬影村出发，先走幽灵岗哨，再沿南路往玛诺洛克集会所。"}, [3]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [4]={npc="智者乌泰克", tgt="智者乌泰克", tag="吉尔吉斯线、有前置、可选"}, [5]={hint="放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。", desc="对集会所的传送门使用泰迦给的埃鲁索斯之手，完成六次放逐。"}, [6]={hint="把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。", desc="在白骨之谷放磁铁箱，先退开再逐只击杀靠过来的幽灵。"}, [7]={npc="霍恩尼兹", tgt="霍恩尼兹"}, [8]={npc="泰迦·慧鬃", tgt="泰迦·慧鬃"}, [9]={npc="迪诺", tgt="迪诺", tag="可选", desc="本路线经奥格瑞玛。已在雷霆崖可找奥松·格鲁尔（25.70, 14.19），在幽暗城可找安娜斯塔西娅·哈特威尔（85.14, 10.03）。"}, [10]={hint="和塔贝萨谈一谈。", tag="可选"}, [11]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [12]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [13]={hint="将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。", tag="可选"}, [14]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [15]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先补满生命值及法力，再请塔贝萨开始驱除。"}, [16]={hint="杀死宝珠之魔，然后与塔贝萨谈一谈。", tag="可选", desc="先补满生命值及法力，再请塔贝萨开始驱除。"}, [17]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先补满生命值及法力，再请塔贝萨开始驱除。"}, [18]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先跟队伍确认会走有黑曜石哨兵的入口。"}, [19]={hint="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。", tag="可选", desc="先跟队伍确认会走有黑曜石哨兵的入口。从奥达曼后门进入，找黑曜石哨兵。"}, [20]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="先跟队伍确认会走有黑曜石哨兵的入口。"}, [21]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="接下后有时限，满法力再开始。"}, [22]={hint="在限定时间内杀死12只法力怒灵。", tag="可选", desc="接下后有时限，满法力再开始。"}, [23]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="接下后有时限，满法力再开始。"}, [24]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [25]={hint="完成任务目标。", tag="可选"}, [26]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}, [27]={text="仍绑在葬影村时用炉石回村；从其他站加入且绑在别处就沿路步行回飞行点。再飞奥格瑞玛补技能。"}}},
    ["03-22"] = {name="奥特兰克山脉", tips={{k="取捨", text="塔伦米尔先确认 拯救行动／通缉：辛迪加成员，两个前置可在敦霍尔德城堡同一趟做。进山后交 秘密潜入 才接 ，高迪尔和瓦杜斯的辛迪加营地目标一起找。"}, {k="提醒", text="与阿拉希高地落锤镇合计练到 40 级；到阿拉希高地落锤镇再看等级差额。若缺少量经验，可先打辛迪加营地的普通成员（58.44, 70.00），再往落锤镇。", s={{"与阿拉希高地落锤镇合计练到 40 级"}, {"到阿拉希高地落锤镇再看等级差额"}, {"若缺少量经验，可先打辛迪加营地的普通成员（58.44, 70.00），再往落锤镇"}}}}, danger={[1]="碎岭废墟城内有精英食人魔。清普通蛮卒时留在外侧山路，等队伍到了再进。"}, grind={[1]={mob="辛迪加间谍", note="辛迪加营地外围，普通怪，密度高。留意隐匿及巫师，沿营地边缘找单只，只补少量就往落锤镇。"}, [2]={note="碎岭外侧山路，普通怪，密度高。城内另有精英，留在外围可少绕路，适合单人补怪。"}}, supply={[1]={npc="扎瑞斯"}, [2]={npc="旅店老板沙恩"}, [3]={npc="旅店老板沙恩"}, [4]={npc="凯伦·苏萨隆"}, [5]={npc="高顿·温德哈姆"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="在奥格瑞玛城外飞艇塔搭去提瑞斯法林地的飞艇。从布瑞尔南塔下船后到幽暗城，飞塔伦米尔并绑定炉石。"}, [2]={npc="梅里萨拉", tgt="梅里萨拉", tag="有队伍再做、可选"}, [3]={npc="克鲁斯克", tgt="克鲁斯克"}, [4]={npc="通缉", npcObj=true, desc="同任务也可找物件通缉海报（62.57, 20.66）。"}, [5]={hint="塔伦米尔的克鲁斯克要你把德鲁尔和托格萨从敦霍尔德城堡救出来。", desc="两名囚犯各有一把钥匙，从敦霍尔德城堡的守卫取得后再开脚镣。"}, [6]={hint="杀死10个辛迪加潜行者和10个辛迪加哨兵，然后回到塔伦米尔向高级执行官达萨利亚报告。"}, [7]={npc="克鲁斯克", tgt="克鲁斯克"}, [8]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [9]={npc="克鲁斯克", tgt="克鲁斯克"}, [10]={npc="通缉", npcObj=true, desc="同任务也可找物件通缉海报（62.57, 20.66）。"}, [11]={hint="把关于高迪尔下落的消息带回来给塔伦米尔的克鲁斯克。"}, [12]={hint="塔伦米尔的梅里萨拉要你去杀掉14个破碎岭虐待者。", tag="有队伍再做、可选", desc="碎岭虐待者为精英，先找队伍再进奥特兰克废墟。"}, [13]={npc="克鲁斯克", tgt="克鲁斯克"}, [14]={npc="梅里萨拉", tgt="梅里萨拉", tag="有队伍再做、可选"}, [15]={npc="梅里萨拉", tgt="梅里萨拉", tag="可选"}, [16]={npc="克鲁斯克", tgt="克鲁斯克"}, [17]={hint="救出高迪尔，然后回到塔伦米尔去见克鲁斯克。"}, [18]={hint="杀了瓦杜斯男爵，把他的头带给塔伦米尔的高级执行官达萨利亚。", desc="瓦杜斯可能出现在不同辛迪加营地；先从高迪尔附近找，再查北边的营地。"}, [19]={npc="高迪尔", tgt="高迪尔"}, [20]={npc="高迪尔", tgt="高迪尔"}, [21]={hint="把高迪尔收集的消息带给塔伦米尔的克鲁斯克。"}, [22]={npc="克鲁斯克", tgt="克鲁斯克"}, [23]={npc="高级执行官达萨利亚", tgt="高级执行官达萨利亚"}, [24]={hint="干掉塔尔格、玛克拉克和戈洛姆斯，把他们的头带给塔伦米尔的梅里萨拉。", tag="可选"}, [25]={npc="梅里萨拉", tgt="梅里萨拉", tag="可选"}, [26]={npc="梅里萨拉", tgt="梅里萨拉", tag="有队伍再做、可选"}, [27]={hint="杀了玛格索尔，带着他的脑袋和意志之冠去塔伦米尔见梅里萨拉。", tag="有队伍再做、可选"}, [28]={npc="梅里萨拉", tgt="梅里萨拉", tag="有队伍再做、可选"}, [29]={npc="梅里萨拉", tgt="梅里萨拉", tag="有队伍再做、可选"}, [30]={hint="把意志之冠交给幽暗城的沙琳德拉。", tag="有队伍再做、可选"}, [31]={npc="沙琳德拉", tgt="沙琳德拉", tag="有队伍再做、可选"}, [32]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="最低可接 24 级，任务等级 36；趁本次到奥特兰克山脉处理。"}, [33]={hint="从巴顿身上偷走巴顿的侦察报告，然后把它交给拉文霍德庄园的麦洛克斯。", tag="可选、目标：巴尔顿", desc="最低可接 24 级，任务等级 36；趁本次到奥特兰克山脉处理。"}, [34]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="最低可接 24 级，任务等级 36；趁本次到奥特兰克山脉处理。"}, [35]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="先从储物箱取得制服；下一段在激流堡保持伪装。"}, [36]={hint="从诺斯弗德农场弄一套辛迪加制服，用来潜入激流堡。", tag="可选", desc="先从储物箱取得制服；下一段在激流堡保持伪装。"}, [37]={npc="辛迪加储物箱", npcObj=true, tag="可选", desc="先从储物箱取得制服；下一段在激流堡保持伪装。"}, [38]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="带上剃刀沼泽的便笺；若日志仍指向乱风岗，才向劳恩·峭壁行者（46.14, 51.71）交。"}, [39]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="交 元素救兵 后先看巴斯拉；若在乱风岗交上一段，可直接向劳恩接。"}, [40]={hint="与千针石林的普拉特·白云交谈。", tag="可选", desc="接在 元素救兵 后。"}, [41]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="接在 元素救兵 后。"}, [42]={npc="普拉特·白云", tgt="普拉特·白云", tag="可选", desc="若巴斯拉已提供此任务可先接起来；火与土在第 25 及 27 站可顺路收，凄凉之地与尘泥沼泽的图腾需要回访。"}, [43]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选、需游戏内实测", desc="若巴斯拉提供此支线才接；与主线练级可分开。"}, [44]={hint="Return to Rau Cliffrunner in Thousand Needles at Freewind Post.", tag="可选、需游戏内实测", desc="若巴斯拉提供此支线才接；与主线练级可分开。"}, [45]={npc="劳恩·峭壁行者", tgt="劳恩·峭壁行者", tag="可选、需游戏内实测", desc="若巴斯拉提供此支线才接；与主线练级可分开。"}, [46]={text="去完辛迪加营地后向东过索拉丁之墙，重返阿拉希高地。"}}},
    ["03-23"] = {name="阿拉希高地", nameA="阿拉希高地 {a:321}", tips={{k="取捨", text="石拳、迅猛龙与辛迪加进阶任务可在回访时一起清。低阶版没做过就跳过同名后续。禁锢之石 顺环线摸完，打开钥匙之石 弗兹鲁克适合有队伍才追。"}, {k="取捨", text="法迪尔海湾一次接打捞、水下宝藏和船长的复仇。先完成 解锁 ，接 领寻宝护目镜，并顺手做水下的 深海打捞／。 留到荆棘谷藏宝海湾， 回海湾的交任务另候顺路。"}, {k="取捨", text="视频建议激流堡有余力再做。要省跑图，先做水晶和落锤近郊，激流堡后段 阿拉索符印-托卡拉尔 可跳。"}, {k="提醒", text="途经斯通纳德先开飞行点。悲伤沼泽任务留到悲伤沼泽斯通纳德。", s={{"途经斯通纳德先开飞行点"}, {"悲伤沼泽任务留到悲伤沼泽斯通纳德"}}}, {k="提醒", text="前往大河林地前若未到 40 级，先清落锤镇东侧枯须峡谷的普通狗头人（约 84, 31）。怪物开始变灰时，改打枯木村外围的普通枯木巨魔（约 68, 69）。", s={{"前往大河林地前若未到 40 级，先清落锤镇东侧枯须峡谷的普通狗头人（约 84, 31）"}, {"怪物开始变灰时，改打枯木村外围的普通枯木巨魔（约 68, 69）"}}}}, danger={[1]="激流堡的守卫会在门洞集结。交符印链前先分开拉守卫，别从屋内同时开两群。", [2]="法迪尔海湾沉船有水下怪，进船前先戴寻宝潜水镜并注意氧气。"}, grind={[1]={mob="枯须勘探员", note="落锤镇东侧枯须峡谷深处，普通怪，密度中等。洞道狭窄且可能碰到稀有怪地卜师弗林塔格，从入口逐段推进。"}, [2]={mob="枯须掘地工", note="枯须峡谷洞道，普通怪，密度高。与勘探员混合，可和水晶任务同一趟，留意洞内回头时的重生。"}, [3]={mob="水浪流放者", note="落锤镇西北水元素区，普通怪，密度高。比狗头人稍高等，可打到 40 级。可同趟收集旋风武器任务的元素符咒。"}}, supply={[1]={npc="尤尔达"}, [2]={npc="旅店老板埃德瓦"}, [3]={npc="穆塔"}, [4]={npc="旅店老板埃德瓦"}, [5]={npc="格劳德"}}, steps={[1]={npc="密斯莱尔水晶碎块", npcObj=true}, [2]={npc="托尔甘", tgt="托尔甘"}, [3]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [4]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [5]={hint="前往阿拉希高地的落锤镇，与森谷谈一谈。"}, [6]={npc="森古", tgt="森古"}, [7]={npc="森古", tgt="森古", tag="可选"}, [8]={hint="收集密斯莱尔之尘。"}, [9]={npc="虹光水晶碎块", npcObj=true}, [10]={npc="虹光水晶碎块", npcObj=true}, [11]={hint="从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。"}, [12]={hint="杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。"}, [13]={hint="取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。", tag="可选"}, [14]={npc="托尔甘", tgt="托尔甘"}, [15]={npc="杜拉姆法尔", tgt="杜拉姆法尔"}, [16]={npc="托尔甘", tgt="托尔甘", tag="可选"}, [17]={npc="托尔甘", tgt="托尔甘"}, [18]={hint="把托尔甘的宝珠交给戈穆尔。"}, [19]={npc="戈穆尔", tgt="戈穆尔"}, [20]={npc="戈穆尔", tgt="戈穆尔"}, [21]={hint="和托尔甘谈一谈。"}, [22]={npc="托尔甘", tgt="托尔甘"}, [23]={npc="杜拉姆法尔", tgt="杜拉姆法尔", tag="可选"}, [24]={npc="科林法尔", tgt="科林法尔", tag="可选"}, [25]={hint="杀死15个石拳萨满祭司和10个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。", tag="可选"}, [26]={hint="杀死奥卡拉尔，将他的头颅带给落锤村哨所的科林法尔。", tag="可选"}, [27]={npc="杜拉姆法尔", tgt="杜拉姆法尔", tag="可选"}, [2