c="任务等级 40 且是精英，先组队再触发。"}, [72]={hint="将旋风之心带给捕风者巴斯拉。", tag="可选", desc="任务等级 40 且是精英，先组队再触发。"}, [73]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="任务等级 40 且是精英，先组队再触发。"}, [74]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", star={"旋风之斧 / 旋风之剑 / 旋风之锤"}}, [75]={hint="完成任务目标。", tag="可选"}, [76]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", star={"旋风之斧 / 旋风之剑 / 旋风之锤"}}, [77]={npc="辛迪加储物箱", npcObj=true, tag="可选", desc="进入前先使用制服，避免攻击会破坏伪装。"}, [78]={hint="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.", tag="可选", desc="进入前先使用制服，避免攻击会破坏伪装。"}, [79]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选", desc="进入前先使用制服，避免攻击会破坏伪装。"}, [80]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选"}, [81]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.", tag="可选", desc="到激流堡旁的房屋二楼找安娜斯塔西娅的藏品。"}, [82]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选"}, [83]={npc="安娜斯塔西娅·米勒", tgt="安娜斯塔西娅·米勒", tag="可选", desc="货物由两名守卫看管。"}, [84]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor.", tag="可选", desc="货物由两名守卫看管。"}, [85]={npc="麦洛克斯", tgt="麦洛克斯", tag="可选", desc="货物由两名守卫看管。"}, [86]={text="回落锤镇。已开洛格玛飞行点且斯通纳德飞行点也已开，可直接飞洛格玛。首次去洛格玛而斯通纳德飞行点已开，先选斯通纳德。尚未开斯通纳德则飞格罗姆高，沿荆棘谷大道北上暮色森林，绕开夜色镇守卫，从东口经逆风小径进入悲伤沼泽。格罗姆高飞行点未开时，可经幽暗城到布瑞尔南方飞艇塔转格罗姆高线。", tag="还没开这个飞行点，第一次要用跑的"}}},
    ["05-d17"] = {name="剃刀高地", entrance="贫瘠之地（1413），荆棘隧道深处的传送门，约49.10, 93.40。", pickup="离开阿拉希高地 落锤镇时先飞幽暗城。千针石林 闪光平原可先打剃刀沼泽并拾 邪恶的盟友。奥特兰克山脉至阿拉希高地 落锤镇经幽暗城时先交瓦里玛萨斯，再同城找安德鲁接 寒冰之王。由提瑞斯法坐飞艇回奥格瑞玛、飞雷霆崖，往莫高雷西北找苏塔菈接 凛风之眼；飞陶拉祖往南，门外找麦雷姆。若从东部王国的火线港转场，可搭船到热砂港后北上千针石林。", pickupS={{"离开阿拉希高地 落锤镇时先飞幽暗城"}, {"千针石林 闪光平原可先打剃刀沼泽并拾 邪恶的盟友"}, {"奥特兰克山脉至阿拉希高地 落锤镇经幽暗城时先交瓦里玛萨斯，再同城找安德鲁接 寒冰之王"}, {"由提瑞斯法坐飞艇回奥格瑞玛、飞雷霆崖，往莫高雷西北找苏塔菈接 凛风之眼"}, {"飞陶拉祖往南，门外找麦雷姆"}, {"若从东部王国的火线港转场，可搭船到热砂港后北上千针石林"}}, tips={{k="動線", text="入口清到火眼莫德雷斯附近牢房→和奔尼斯特拉兹交换誓言石，再护送他封印神像，途中可能遇见腐烂的普雷莫→沿螺旋坡打亚门纳尔，同区找凛风之眼。"}, {k="取捨", text="40 级后有队伍才跑完整本，凛风之眼 与 寒冰之王 同打尾王；34 级现在只适合先接眼球，有顺路可做门外 邪恶之地。"}, {k="說明", text="五人队，无钥匙。门口在大升降梯北侧的东路，与西侧剃刀沼泽不同。若已转入大河林地，可在火线港搭船到热砂港后再北上。", s={{"五人队，无钥匙"}, {"门口在大升降梯北侧的东路，与西侧剃刀沼泽不同"}, {"若已转入大河林地，可在火线港搭船到热砂港后再北上"}}}, {k="提醒", text="五人队，无钥匙。门口在大升降梯北侧的东路，与西侧剃刀沼泽不同。若已转入大河林地，可在火线港搭船到热砂港后再北上。", s={{"五人队，无钥匙"}, {"门口在大升降梯北侧的东路，与西侧剃刀沼泽不同"}, {"若已转入大河林地，可在火线港搭船到热砂港后再北上"}}}}, steps={[1]={npc="小卷轴", npcObj=true, tag="需游戏内实测", desc="前一趟剃刀沼泽从卡尔加拾小卷轴，已做可略。"}, [2]={hint="把小卷轴交给幽暗城的瓦里玛萨斯。"}, [3]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯"}, [4]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯", desc="交 邪恶的盟友 后同 NPC 接；目标在剃刀高地入口外的荆棘通道。", preText="邪恶的盟友"}, [5]={npc="安德鲁·布隆奈尔", tgt="安德鲁·布隆奈尔", desc="37 级可先在幽暗城魔法区接。"}, [6]={npc="苏塔拉·平原行者", tgt="苏塔拉·平原行者", desc="永恒版新增任务。"}, [7]={npc="麦雷姆·月歌", tgt="麦雷姆·月歌", desc="麦雷姆在贫瘠之地南端门外（49.01, 94.94）；进门前先接并清外围。"}, [8]={hint="把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。"}, [9]={hint="杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。"}, [10]={npc="麦雷姆·月歌", tgt="麦雷姆·月歌"}, [11]={text="剃刀高地 入口"}, [12]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需游戏内实测", desc="牢笼区找奔尼斯特拉兹，全队先完成誓言对话再开护送。"}, [13]={hint="如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。", desc="位置：走到火眼莫德雷斯附近牢房，找奔尼斯特拉兹。顺序：全队先交誓言石再接护送。", spot="走到火眼莫德雷斯附近牢房，找奔尼斯特拉兹。"}, [14]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需游戏内实测", spot="火眼莫德雷斯附近的牢房，奔尼斯特拉兹"}, [15]={npc="奔尼斯特拉兹", tgt="奔尼斯特拉兹", tag="需游戏内实测", desc="开始后跟紧 NPC，全队准备完才启动。", preText="剃刀高地的亡灵天灾"}, [16]={hint="保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。", desc="位置：从牢房跟到神像旁，护住奔尼斯特拉兹。", spot="从牢房跟到神像旁，护住奔尼斯特拉兹。"}, [17]={npc="奔尼斯特拉兹的火盆", npcObj=true, tag="需游戏内实测", spot="神像旁，奔尼斯特拉兹的火盆"}, [18]={hint="安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。", desc="位置：离开牢房区，沿螺旋高坡上到亚门纳尔。", spot="离开牢房区，沿螺旋高坡上到亚门纳尔。"}, [19]={hint="从剃刀高地夺回凛风之眼。", desc="位置：进亚门纳尔巢穴，找凛风之眼。顺序：与第 17 步同一区。", spot="进亚门纳尔巢穴，找凛风之眼。"}, [20]={npc="苏塔拉·平原行者", tgt="苏塔拉·平原行者"}, [21]={npc="安德鲁·布隆奈尔", tgt="安德鲁·布隆奈尔"}, [22]={npc="瓦里玛萨斯", tgt="瓦里玛萨斯"}}},
    ["03-24"] = {tips={{k="取捨", text="初次先清农场、豺狼人、河岸及洛格玛周边野兽。乔格扎克 再也没有暮光！ 和后续送头线留到有队伍再做，博德罗克的野猪和采石任务可直接接。42 级以上的暮光和海岸任务留给大河林地博德罗克与爆破引线港，按视频分两次跑。"}, {k="取捨", text="在这站先开洛格玛飞行点，往返卡加斯或斯通纳德可少跑地面。补给可找托卡。"}, {k="提醒", text="交完本站任务若未到 41 级，在纳佐克农场南侧（70.62, 33.08）刷普通野猪，或在洛格玛南侧野兽区（约 61, 50）继续打。博德罗克的进阶暮光任务留给大河林地博德罗克与爆破引线港。", s={{"交完本站任务若未到 41 级，在纳佐克农场南侧（70.62, 33.08）刷普通野猪，或在洛格玛南侧野兽区（约 61, 50）继续打"}, {"博德罗克的进阶暮光任务留给大河林地博德罗克与爆破引线港"}}}}, danger={[1]="洛格玛以南有远境堡斥候和牧师。先拉落单的斥候，避免牧师一起入战。", [2]="阳光林地的暮光仪式洞道狭窄。先清洞口再破坏仪式圈，别让暗影法师在背后重生。"}, grind={[1]={mob="低地秃鹰", note="洛格玛南侧草地，数据库刷新点密集，普通怪。附近有 41-42 级精英野兽，沿路单拉；可顺带收集 制作箭羽的羽毛 的羽毛。"}, [2]={mob="法霍德斥候", note="洛格玛以南的远境堡斥候区，密度高，普通怪。小心牧师与其他斥候一起入战，沿河外围清理并顺手做 教教他们规矩。"}, [3]={mob="法霍德牧师", note="南岸偏西，密度中等，普通施法怪。先打断治疗，别同时拉到斥候；已走过 教教他们规矩 西段时可顺手补。"}}, supply={[1]={npc="格拉克纳"}, [2]={npc="旅店老板托卡"}, [3]={npc="古尔多克"}, [4]={npc="纳鲁克"}, [5]={npc="玛卡"}, [6]={npc="布雷依克"}, [7]={npc="苏塔佐尔"}}, steps={[1]={nodeA="{a:75}", desc="由悲伤沼泽地面路线抵达时，向布雷依克开点；已直达洛格玛的角色略过。"}, [2]={text="从斯通纳德出发，已开洛格玛可直飞。首次依视频 26:56-27:13 由悲伤沼泽进大河林地，沿南侧道路经泰拉尔之望（约 60, 64）北上洛格玛。已由落锤镇直达洛格玛可直接找飞行管理员。", tag="还没开这个飞行点，第一次要用跑的"}, [3]={node="洛格玛", desc="向格拉克纳开启飞行点。"}, [4]={text="将炉石绑定在旅店老板托卡处（57.58, 45.47）。"}, [5]={hint="向河林洛格玛哨所的克罗姆罗什复命。"}, [6]={hint="在河林的洛格玛找到塔恩加尼。"}, [7]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [8]={npc="塔恩加尼", tgt="塔恩加尼"}, [9]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [10]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [11]={npc="古尔多克", tgt="克雷扎·暗棘"}, [12]={npc="塔恩加尼", tgt="塔恩加尼"}, [13]={text="南部农场和西南豺狼人"}, [14]={hint="消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。", tag="目标：草甸溪农场雇农"}, [15]={hint="从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。"}, [16]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [17]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [18]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [19]={hint="将偷来的饲料交给洛格玛的戈尔格。"}, [20]={npc="戈尔格", tgt="戈尔格"}, [21]={npc="戈尔格", tgt="戈尔格"}, [22]={hint="在训练场喂饱8名洛格玛受训者。", tag="目标：洛格玛受训者"}, [23]={npc="戈尔格", tgt="戈尔格"}, [24]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [25]={hint="在河流以南消灭8个法霍德牧师和12个法霍德斥候。", tag="目标：远境堡牧师／远境堡斥候"}, [26]={npc="克罗姆罗什", tgt="克罗姆罗什"}, [27]={npc="特兰古尔", tgt="特兰古尔"}, [28]={npc="特兰古尔", tgt="特兰古尔"}, [29]={text="沿河伐木营地与阳光林地"}, [30]={hint="从特纳的伐木场的伐木工那里，为洛格玛的克雷扎·暗棘夺回10把木匠的斧头。", tag="目标：特纳磨坊伐木工"}, [31]={hint="从特纳的伐木场的农夫木柴堆中收集一捆木材，然后把它们削成20把简易穿刺长矛。"}, [32]={npc="古尔多克", tgt="克雷扎·暗棘"}, [33]={npc="古尔多克", tgt="克雷扎·暗棘", desc="交完借刀杀人后接；剑先留到大河林地爆破引线港，再交给弗里兹。"}, [34]={npc="塔恩加尼", tgt="塔恩加尼"}, [35]={npc="塔恩加尼", tgt="塔恩加尼"}, [36]={hint="刺穿10只淡水鳄，然后回到洛格玛的特兰古尔那里。", tag="目标：淡水鳄"}, [37]={npc="塔恩加尼", tgt="塔恩加尼"}, [38]={hint="为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。", tag="目标：暮光袭击者/暮光暗影法师/暮光新教徒"}, [39]={hint="为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。", tag="目标：暮光暗影法师"}, [40]={npc="特兰古尔", tgt="特兰古尔"}, [41]={npc="特兰古尔", tgt="特兰古尔"}, [42]={npc="特兰古尔", tgt="特兰古尔"}, [43]={hint="说服阳光林地的一名暮光之锤矿工，让他泄露秘密。"}, [44]={npc="棍趾", tgt="棍趾"}, [45]={npc="棍趾", tgt="棍趾"}, [46]={hint="为棍趾在阳光林地下方的洞穴中寻找失踪的食人魔。"}, [47]={npc="强化蛮兵", tgt="暮光蛮兵"}, [48]={npc="强化蛮兵", tgt="暮光蛮兵"}, [49]={npc="棍趾", tgt="棍趾"}, [50]={hint="消灭5名强化蛮兵和10名暮光仪式师，然后回到阳光林地的棍趾那里。", tag="目标：强化蛮兵/暮光仪式师"}, [51]={hint="摧毁在阳光林地下方洞穴中发现的5个暮光仪式法阵。"}, [52]={npc="棍趾", tgt="棍趾"}, [53]={npc="棍趾", tgt="棍趾"}, [54]={npc="棍趾", tgt="棍趾", tag="有队伍再做、可选"}, [55]={hint="在阳光林地的洞穴中消灭乔格扎克，并为棍趾收集他们的头颅。", tag="有队伍再做、可选、目标：乔格扎克", desc="乔格扎克在晴林地洞穴内，是 41 级精英。"}, [56]={npc="棍趾", tgt="棍趾", tag="有队伍再做、可选"}, [57]={npc="棍趾", tgt="棍趾", tag="有队伍再做、可选"}, [58]={hint="将乔格的徽记交给洛格玛的特兰古尔。", tag="有队伍再做、可选"}, [59]={npc="特兰古尔", tgt="特兰古尔", tag="有队伍再做、可选"}, [60]={npc="特兰古尔", tgt="特兰古尔", tag="有队伍再做、可选"}, [61]={text="在洛格玛周围狩猎"}, [62]={npc="被剔骨的残骸", tgt="被剔骨的残骸", desc="南边野兽区的地面上有被啃过的尸体，找到后互动接任务。"}, [63]={hint="将啃过的颅骨交给洛格玛的涅扎·血吻。"}, [64]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [65]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [66]={hint="将完整的陆行鸟喙交给洛格玛的涅扎·血吻。", tag="目标：游荡的陆行鸟"}, [67]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [68]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [69]={hint="将6根平原秃鹰羽毛交给洛格玛的涅扎·血吻。", tag="目标：低地秃鹰"}, [70]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [71]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [72]={hint="将4份林地毒蛇毒液样本交给洛格玛的涅扎·血吻。", tag="目标：林地毒蛇"}, [73]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [74]={npc="涅扎·血吻", tgt="涅扎·血吻"}, [75]={hint="收集6张珍贵的狮皮，