"斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", tag="可选"}, [113]={npc="卡尔·噬灵", tgt="卡尔·噬灵", tag="可选"}, [114]={hint="与棘齿城的斯坦哈德·法尔杉谈一谈。", tag="可选"}, [115]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", tag="可选"}, [116]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="先交所在地的引导，再向斯坦哈德接取。"}, [117]={hint="与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。", desc="先交所在地的引导，再向斯坦哈德接取。"}, [118]={npc="斯坦哈德·法尔杉", tgt="斯坦哈德·法尔杉", desc="先交所在地的引导，再向斯坦哈德接取。"}, [119]={text="已开启卡加斯飞行点就从洛格玛直飞。初访沿视频 27:55-28:03 所示路线，从暮光营地北面的西侧山口进入荒芜之地，向西北走到卡加斯飞行点。炉石仍绑定洛格玛，供之后回访。", tag="还没开这个飞行点，第一次要用跑的"}}},
    ["03-25"] = {name="荒芜之地", nameA="荒芜之地 {a:340}", tips={{k="取捨", text="石元素与荒芜之地试剂 荒芜之地的试剂 共用部分怪点，先接齐再打。郊狼下颚要 30 个，边走边清，够数就走。"}, {k="取捨", text="冰霜之油、发条式同步协调陀螺仪和药水都备好才做 至关重要的冷却剂-卢希恩的药水。破碎的联盟 留给更高等级或有队伍时。"}, {k="提醒", text="视频把 40 级学骑术放在这次主城转场。已满 40 级且有金币，可以路过本族训练师时先学。参见文末「职业任务」及「40 级各族骑术」。", s={{"视频把 40 级学骑术放在这次主城转场"}, {"已满 40 级且有金币，可以路过本族训练师时先学"}, {"参见文末「职业任务」及「40 级各族骑术」"}}}, {k="提醒", text="离开卡加斯前若未到 42 级，在荒芜之地西南打普通巨型石元素（约 6.65, 73.85）。石元素点拥挤时，沿卡加斯东南山脊打郊狼和秃鹰。", s={{"离开卡加斯前若未到 42 级，在荒芜之地西南打普通巨型石元素（约 6.65, 73.85）"}, {"石元素点拥挤时，沿卡加斯东南山脊打郊狼和秃鹰"}}}}, danger={[1]="荒芜之地东侧有 39-40 级精英石窟先知与石窟猛击者。经过奥达曼外圈时保持距离。"}, grind={[1]={mob="巨型石元素", note="卡加斯南方山壁，密度高，普通怪。附近有火烟食人魔，沿岩壁清外侧；42 级前觉得吃力就改打山脊。"}, [2]={note="卡加斯东南山脊，密度中等，普通怪。避开精英与稀有巡逻怪，适合 41 级单练，或石元素区拥挤时换点。"}, [3]={mob="巨型秃鹫", note="卡加斯东南坡地，密度中等，普通怪。可与山脊巡行者轮打；有秃鹰翅膀或胃囊任务时一并收集。"}}, supply={[1]={npc="格里克"}, [2]={npc="旅店老板舒尔卡"}, [3]={npc="斯兰达"}, [4]={npc="旅店老板舒尔卡"}, [5]={npc="格劳尔"}}, steps={[1]={nodeA="{a:340}", desc="向格里克开启飞行点。"}, [2]={text="需要学技能和骑术时再离开，回来可飞卡加斯。"}, [3]={npc="加卡尔", tgt="加卡尔"}, [4]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [5]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [6]={npc="高恩", tgt="高恩", tag="可选"}, [7]={text="石元素与中央野怪环线"}, [8]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [9]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="材料齐了才做、可选"}, [10]={hint="找到冰霜之油，把它交给荒芜之地的鲁特维尔·沃拉图斯。", tag="材料齐了才做、可选", desc="先取得冰霜之油，再交给鲁特维尔。在这里交付。冰霜之油可由炼金术士制作。"}, [11]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="材料齐了才做、可选"}, [12]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="材料齐了才做、可选"}, [13]={hint="给荒芜之地的鲁特维尔·沃拉图斯带去一个发条式同步协调陀螺仪。", tag="材料齐了才做、可选", desc="先准备发条式同步协调陀螺仪，工程师可制作。"}, [14]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="材料齐了才做、可选"}, [15]={npc="卢希恩·枪穗", tgt="卢希恩·枪穗", tag="材料齐了才做、可选"}, [16]={hint="为荒芜之地的卢希恩·枪穗找到一瓶次级隐形药水和一瓶治疗药水。", tag="材料齐了才做、可选"}, [17]={npc="卢希恩·枪穗", tgt="卢希恩·枪穗", tag="材料齐了才做、可选"}, [18]={hint="收集10块小石头碎块，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}, [19]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [20]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [21]={hint="把菲兹尔·铜栓的信带给荒芜之地的流放者马特克。"}, [22]={npc="流放者马特克", tgt="流放者马特克"}, [23]={npc="流放者马特克", tgt="流放者马特克"}, [24]={npc="里格弗兹", tgt="里格弗兹"}, [25]={hint="找到迷失者塞尔杜林。", tag="可选"}, [26]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [27]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [28]={hint="收集3块大石片，把它们交给荒芜之地的鲁特维尔·沃拉图斯。"}, [29]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [30]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [31]={hint="收集5个石缚护腕，把它们交给荒芜之地的鲁特维尔·沃拉图斯。", desc="巨型石元素是普通怪，在西南侧刷石缚护腕。"}, [32]={hint="收集10块精铁碎片，把它们交给荒芜之地的流放者马特克。"}, [33]={hint="给里格弗兹带去4只秃鹫的翅膀。"}, [34]={hint="把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。", tag="可选"}, [35]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯"}, [36]={npc="流放者马特克", tgt="流放者马特克"}, [37]={npc="里格弗兹", tgt="里格弗兹"}, [38]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", tag="可选"}, [39]={hint="前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"}, [40]={hint="带30块山狗的颚骨去见卡加斯的尼卡·血痕。"}, [41]={hint="杀掉索格伦，把大地印章交给卡加斯的高恩。", tag="有队伍再做、可选"}, [42]={npc="加卡尔", tgt="加卡尔"}, [43]={npc="尼卡·血痕", tgt="尼卡·血痕"}, [44]={npc="高恩", tgt="高恩", tag="有队伍再做、可选"}, [45]={npc="加卡尔", tgt="加卡尔", tag="下奥达曼才接、可选"}, [46]={text="已学骑术就由卡加斯直飞格罗姆高；再从格罗姆高飞藏宝海湾。尚未学骑术时，按种族前往骑术训练师；若人在奥格瑞玛或幽暗城附近，才乘飞艇去格罗姆高。"}}},
    ["05-d18"] = {name="奥达曼", entrance="荒芜之地 约 42.60, 10.80（正门定位，沿挖掘场入地下）；后门实际门点?", pickup="荒芜之地 卡加斯走奥达曼；奥特兰克山脉、阿拉希高地 落锤镇到幽暗城先接派翠克的 寻找宝物。由落锤镇或格罗姆高飞荒芜之地 卡加斯，接加卡尔 荒芜之地的试剂→奥达曼的蘑菇，再找里格弗兹与塞尔杜林。满 35 级可在尘泥沼泽先做塔贝萨的前置。想做项链时，第一趟先打到破碎项链，可趁往返奥格瑞玛时交德兰，第二趟再从卡加斯进副本。", pickupS={{"荒芜之地 卡加斯走奥达曼"}, {"奥特兰克山脉、阿拉希高地 落锤镇到幽暗城先接派翠克的 寻找宝物"}, {"由落锤镇或格罗姆高飞荒芜之地 卡加斯，接加卡尔 荒芜之地的试剂→奥达曼的蘑菇，再找里格弗兹与塞尔杜林"}, {"满 35 级可在尘泥沼泽先做塔贝萨的前置", {class={"MAGE"}}}, {"想做项链时，第一趟先打到破碎项链，可趁往返奥格瑞玛时交德兰，第二趟再从卡加斯进副本"}}, tips={{k="動線", text="正门→雷夫洛什→找遗体取日记，先回卡加斯翻译再回本。可从后门直接去黑曜石哨兵。第二挖掘场→加加恩→格瑞姆洛克→阿扎达斯→诺甘农圆盘。"}, {k="取捨", text="优先顺手接 奥达曼的蘑菇、寻找宝物、能量石，达 40 级可取圆盘并拿背包。项链要来回两趟以上，想快速练级时可略。"}, {k="說明", text="五人队。34 级先接幽暗城 寻找宝物，荒芜之地顺路再做外洞；清尾王建议 42 级。正门适合全清与项链，后门适合只打后半。要做法师任务可从后门走。部分资料只标地面洞口，找门时沿洞内主道。", s={{"五人队"}, {"34 级先接幽暗城 寻找宝物，荒芜之地顺路再做外洞"}, {"清尾王建议 42 级"}, {"正门适合全清与项链，后门适合只打后半"}, {"要做法师任务可从后门走", {class={"MAGE"}}}, {"部分资料只标地面洞口，找门时沿洞内主道"}}}, {k="提醒", text="五人队。34 级先接幽暗城 寻找宝物，荒芜之地顺路再做外洞；清尾王建议 42 级。正门适合全清与项链，后门适合只打后半。要做法师任务可从后门走。部分资料只标地面洞口，找门时沿洞内主道。", s={{"五人队"}, {"34 级先接幽暗城 寻找宝物，荒芜之地顺路再做外洞"}, {"清尾王建议 42 级"}, {"正门适合全清与项链，后门适合只打后半"}, {"要做法师任务可从后门走", {class={"MAGE"}}}, {"部分资料只标地面洞口，找门时沿洞内主道"}}}}, steps={[1]={npc="帕特里克·加瑞特", tgt="帕特里克·加瑞特", desc="33 级可提前在幽暗城中环接，宝箱在副本门外。"}, [2]={npc="里格弗兹", tgt="里格弗兹", desc="能量石由门外暗炉矮人掉落，可一趟清。"}, [3]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林", desc="塞尔杜林在荒芜之地南边；已顺路经过才接。"}, [4]={npc="加卡尔", tgt="加卡尔", desc="荒芜之地 卡加斯已有这段，交过直接接 奥达曼的蘑菇。"}, [5]={hint="前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。"}, [6]={npc="加卡尔", tgt="加卡尔"}, [7]={npc="加卡尔", tgt="加卡尔", desc="加卡尔在卡加斯，交 荒芜之地的试剂 后直接接。", preText="荒芜之地的试剂"}, [8]={npc="迪诺", tgt="迪诺", desc="尘泥沼泽 蕨墙村至凄凉之地 葬影村满 35 级可先跑；已交略过。"}, [9]={hint="和塔贝萨谈一谈。"}, [10]={npc="塔贝萨", tgt="塔贝萨"}, [11]={npc="塔贝萨", tgt="塔贝萨"}, [12]={hint="将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。"}, [13]={npc="塔贝萨", tgt="塔贝萨"}, [14]={npc="塔贝萨", tgt="塔贝萨", preText="地狱火宝珠"}, [15]={hint="杀死宝珠之魔，然后与塔贝萨谈一谈。"}, [16]={npc="塔贝萨", tgt="塔贝萨"}, [17]={npc="塔贝萨", tgt="塔贝萨", desc="塔贝萨驱魔后接；和队伍先说要清后门一侧的黑曜石哨兵。", preText="驱除魔鬼"}, [18]={hint="从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。"}, [19]={hint="给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。"}, [20]={hint="把雷乌纳石板带给迷失者塞尔杜林。"}, [21]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", desc="选做项链。挖掘场或本内暗炉矮人掉破碎的项链；捡到后确认部落版 搜寻项链。"}, [22]={hint="在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。"}, [23]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯"}, [24]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", desc="若只打一趟奥达曼，可放弃这条多趟链。交 搜寻项链 后由德兰接。", preText="搜寻项链"}, [25]={text="奥达曼 入口"}, [26]={hint="收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。", desc="紫色蘑菇生长在副本门外。位置：正门外洞先采紫菇，进本再沿挖掘通道补齐。", spot="正门外洞先采紫菇，进本再沿挖掘通道补齐。"}, [27]={hint="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。", desc="位置：从后门进本，黑曜石哨兵就在附近。", spot="从后门进本，黑曜石哨兵就在附近。"}, [28]={hint="在奥达曼里找寻宝石的线索。", desc="位置：从正门打过雷夫洛什，到他身后房间查遗体。顺序：完成后出本做第 30、33 步。", spot="从正门打过雷夫洛什，到他身后房间查遗体。"}, [29]={npc="圣骑士的遗体", tgt="圣骑士的遗体", tag="需游戏内实测", spot="雷弗洛什身后房间的圣骑士遗体"}, [30]={npc="圣骑士的遗体", tgt="圣骑士的遗体", tag="需游戏内实测", desc="在遗体处接日记，先回卡加斯解锁下一趟。", preText="搜寻项链，再来一次"}, [31]={hint="在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"}, [32]={npc="加卡尔", tgt="加卡尔"}, [33]={npc="加卡尔", tgt="加卡尔", preText="翻译日记"}, [34]={hint="将项链借给加卡尔。作为交换，他将帮你翻译日记。"}, [35]={npc="加卡尔", tgt="加卡尔"}, [36]={npc="加卡尔", tgt="加卡尔", desc="卡加斯拿到翻译后接；第二趟再全清。", preText="翻译日记"}, [37]={hint="从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。", desc="位置：二号挖掘场瓮→加加恩房→格瑞姆洛克→尾王。顺序：先取黄宝石，再红、蓝宝石，最后取能量源。", spot="二号挖掘场瓮→加加恩房→格瑞姆洛克→尾王。"}, [38]={npc="诺甘农圆盘", npcObj=true, tag="需游戏内实测", desc="40 级以上，杀阿扎达斯后在终点房点诺甘农圆盘。"}, [39]={hint="和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。", desc="位置：击败阿扎达斯，进后方宝库点诺甘农圆盘。顺序：先听石头看守者，再点圆盘。", spot="击败阿扎达斯，进后方宝库点诺甘农圆盘。"}, [40]={npc="诺甘农圆盘", npcObj=true, tag="需游戏内实测", spot="阿扎达斯后方宝库的诺甘农圆盘"}, [41]={npc="诺甘农圆盘", npcObj=true, tag="需游戏内实测", desc="在同一圆盘接部落送件，回雷霆崖。", preText="白金圆盘"}, [42]={npc="加卡尔", tgt="加卡尔"}, [43]={npc="里格弗兹", tgt="里格弗兹"}, [44]={npc="迷失者塞尔杜林", tgt="迷失者塞尔杜林"}, [45]={npc="帕特里克·加瑞特", tgt="帕特里克·加瑞特"}, [46]={npc="塔贝萨", tgt="塔贝萨"}, [47]={hint="把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。"}, [48]={npc="圣者图希克", tgt="圣者图希克"}, [49]={npc="加卡尔", tgt="加卡尔"}, [50]={npc="加卡尔", tgt="加卡尔", preText="寻找宝贝"}, [51]={hint="把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。"}, [52]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯"}, [53]={npc="德兰·杜佛斯", tgt="德兰·杜佛斯", preText="交付宝石"}, [54]={hint="去卡加斯看看加卡尔是否成功了。"}, [55]={npc="加卡尔", tgt="加卡尔"}}},
    ["03-26"] = {name="荆棘谷", tips={{k="取捨", text="藏宝海湾第 2 趟先交 水下宝藏／风险投资公司／刨花皮靴 等已完成任务。血帆 血帆海盗→血帆海盗→血帆海盗 先跑近岸短段，开 血帆海盗 同做 海盗的眼睛／鼻烟；交 血帆海盗 才接 血帆海盗 打三船首领。讨债 讨债行动 需先交 吓唬病鬼→向马克基雷回报。视频要求逐环回港，这几个解锁点照走。"}, {k="取捨", text="可在血帆船上先接 科泰罗的谜题，到悲伤沼泽斯通纳德时顺路解第一段。刨花皮靴 和 风险投资公司 没做完就顺路补，避免为单件再飞一次。先处理岸上的 讨债行动 再上船。"}, {k="提醒", text="荆棘谷藏宝海湾至大河林地博德罗克与爆破引线港合计练到 45 级。若此站想先补少量经验，收完血帆三船后打岸边的普通血帆海盗（约 32, 79）。", s={{"荆棘谷藏宝海湾至大河林地博德罗克与爆破引线港合计练到 45 级"}, {"若此站想先补少量经验，收完血帆三船后打岸边的普通血帆海盗（约 32, 79）"}}}}, danger={[1]="莫什奥格丘陵的食人魔种类多，且有精英。打格罗姆高的攻势时从山脚拉，避免一次进营地。", [2]="血帆船上楼梯窄、出口少。登船前清岸边，逐层打完再下船。"}, grind={[1]={mob="血帆流氓", note="藏宝海湾外海滩，密度高，普通怪。先清岸上，留意其他玩家也在做血帆任务；船线做完可就近补经验。"}, [2]={mob="血帆术士", note="血帆南侧岸边，密度高，普通施法怪。先清同群近战，再拉术士；岸上循环可省上船时间。"}}, supply={[1]={npc="格林戈"}, [2]={npc="旅店老板斯金德"}, [3]={npc="祖塔克"}, [4]={npc="尼克拉克斯·菲拉莫格"}, [5]={npc="哈伦·坎麦尔"}, [6]={npc="塞斯塔"}, [7]={npc="旅店老板苏贝克"}, [8]={npc="克拉克"}, [9]={npc="纳加特"}}, steps={[1]={text="到格罗姆高后，先飞往藏宝海湾接下一批任务；若上一站出发点离格罗姆高近，可先接营地的任务。"}, [2]={hint="把精灵宝石样本交给藏宝海湾的舰队指挥官海角。"}, [3]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [4]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角", tag="之后顺路、可选"}, [5]={npc="大副克拉兹", tgt="大副克拉兹"}, [6]={npc="海狼马克基雷", tgt="海狼马克基雷"}, [7]={npc="海盗布劳兹", tgt="海盗布劳兹"}, [8]={npc="克兰克·菲兹巴布", tgt="克兰克·菲兹巴布"}, [9]={npc="科博克", tgt="科博克"}, [10]={npc="崔斯里克", tgt="崔斯里克"}, [11]={npc="崔斯里克", tgt="崔斯里克"}, [12]={npc="码头管理员罗兹基尔", tgt="码头管理员罗兹基尔", tag="完成祖尔昆达护送后才接、可选"}, [13]={npc="克拉兹克", tgt="克拉兹克", tag="悲伤沼泽斯通纳德再做、可选", desc="前置任务从棘齿城的给克拉维尔的零件开始，经闪光平原的侏儒的货物，再到藏宝海湾交车手的传闻。"}, [14]={text="北海滩踩点，再回港解锁血帆任务群"}, [15]={hint="大副克拉兹要求你去侦察一下藏宝海湾北边的海滩。"}, [16]={npc="血帆海盗的信件", npcObj=true}, [17]={npc="血帆海盗的信件", npcObj=true}, [18]={hint="将你的发现报告给藏宝海湾的大副克拉兹。"}, [19]={npc="大副克拉兹", tgt="大副克拉兹"}, [20]={npc="大副克拉兹", tgt="大副克拉兹"}, [21]={hint="把血帆海盗的计划报告给舰队指挥官海角。"}, [22]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [23]={npc="舰队指挥官卡拉·海角", tgt="舰队指挥官卡拉·海角"}, [24]={npc="独眼迪兹", tgt="独眼迪兹"}, [25]={npc="迪格", tgt="迪格"}, [26]={text="若要补收营地任务，从藏宝海湾飞格罗姆高，一路向南清怪回港。"}, [27]={hint="把兽人的头颅带到荆棘谷的格罗姆高营地里，交给肯维雷。", t