    ["03-27"] = {name="悲伤沼泽", nameA="悲伤沼泽 {a:75}", tips={{k="取捨", text="盖伦的逃亡 加林的逃亡 是视频提到的护送，沿路清怪再开笼。交付点在保险箱，无需回笼边。"}, {k="取捨", text="缺乏补给 →、海中的威胁 →→1427→、 新鲜的螃蟹腿留到 47 级后回访东南海岸，视频在约 30:50 才走这一带。"}, {k="提醒", text="西侧交完科泰罗的卷轴再去避难营地，和水晶任务一起收两条迷失者支线。若要补少量经验，可打泪水之池外圈的普通沼泽怪（约 60, 55），或下一站到东风海岸再补。", s={{"西侧交完科泰罗的卷轴再去避难营地，和水晶任务一起收两条迷失者支线"}, {"若要补少量经验，可打泪水之池外圈的普通沼泽怪（约 60, 55），或下一站到东风海岸再补"}}}}, danger={[1]="找盖伦之前先清笼旁和营地出口。打开笼子后再拉怪，容易同时顾不到护送对象和自己的血量。"}, grind={[1]={note="泪水之池北侧外圈，密度中等，普通怪。从陆地一侧拉，避免引到同区绿色龙人；靠近原路线，适合短暂补怪。"}, [2]={mob="沼泽喷墨鱼人", note="斯通纳德东南鱼人区，密度中等，普通怪。先挑营地外落单的鱼人，避免追进同群怪，适合 42-43 级。"}, [3]={mob="沼泽食腐鱼人", note="同一片鱼人区南缘，密度中等，普通怪。留意同区更高等级的神谕者，44 级前可与喷墨鱼人轮打。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="在斯通纳德确认已开启布雷依克飞行点（46.07, 54.83）。"}, [2]={hint="把尼卡的报告带给斯通纳德的赫格拉姆。"}, [3]={npc="赫格拉姆", tgt="赫格拉姆"}, [4]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [5]={text="西边桥下与避难营地"}, [6]={hint="解开这道迷题！"}, [7]={npc="浸水的卷轴", npcObj=true}, [8]={npc="浸水的卷轴", npcObj=true, tag="之后顺路"}, [9]={npc="玛格图尔", tgt="玛格图尔"}, [10]={npc="卡拉纳", tgt="卡拉纳"}, [11]={npc="佩卢克", tgt="佩卢克"}, [12]={hint="为藏宝海湾的克拉兹克收集10份梦境之尘。", tag="可选"}, [13]={hint="继续和吉尔吉斯部族保持良好的关系，并把德莱尼水晶碎片交给凄凉之地吉尔吉斯村的智者乌泰克。", tag="可选"}, [14]={hint="在农田避难所消灭10名失落者。"}, [15]={hint="找到偷走佩卢克鱼饵的失落者渔夫，并将鱼饵夺回来。"}, [16]={hint="给悲伤沼泽避难营地里的玛格图尔带去6块德莱尼水晶。"}, [17]={npc="诺博鲁的木棒", npcObj=true, tag="有掉落才做、可选", desc="击杀巡逻的诺博鲁后，点击掉落的木棒接任务。"}, [18]={hint="把诺博鲁的木棒交到悲伤沼泽中的避难营领导人手中。", tag="有掉落才做、可选"}, [19]={npc="玛格图尔", tgt="玛格图尔", tag="有掉落才做、可选"}, [20]={text="东北护送与泪水之池"}, [21]={npc="加林·古瓦德", tgt="加林·古瓦德"}, [22]={hint="护送加林逃出困境，然后打开他放在悲伤沼泽营地里的保险箱。", desc="先清笼边与出口的怪，开笼后跟盖伦走，交付点在路线末段的保险箱。"}, [23]={npc="加林的保险箱", npcObj=true}, [24]={npc="玛格图尔", tgt="玛格图尔"}, [25]={npc="卡拉纳", tgt="卡拉纳"}, [26]={npc="佩卢克", tgt="佩卢克"}, [27]={hint="斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。"}, [28]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [29]={npc="费泽鲁尔", tgt="费泽鲁尔", tag="下沉没的神庙再做、可选"}, [30]={npc="欧文·萨德", tgt="欧文·萨德", tag="可选", desc="跨区与副本材料齐全时再回图书馆。"}, [31]={hint="找到并收集图书管理员所要求的法术书材料。", tag="可选", desc="跨区与副本材料齐全时再回图书馆。"}, [32]={npc="欧文·萨德", tgt="欧文·萨德", tag="可选", desc="跨区与副本材料齐全时再回图书馆。"}, [33]={text="从斯通纳德直飞大河林地洛格玛。若从本段中途加入且未开洛格玛飞行点，沿大河林地通往洛格玛的地面路线前往，抵达后先开飞行点。"}}},
    ["03-28"] = {tips={{k="取捨", text="北线与暮光之罩整条选做。已做暮光不再的角色可先回博德罗克，交克鲁格菲斯特的法令后在洛格玛接任性的战士。爆破引线港第一次清海盗顺手拿走私货物，第二次收火药桶、杀投弹手并送走私快递，交完再出海炸船。海怪线要绕洞穴，经验不足且 NPC 有提供任务时再做。"}, {k="提醒", text="不足 45 级就在东风海岸（约 84, 35-43）沿岸打东海海盗与火枪手，港口附近可以补给。40-45 级有队伍可下 Krol'dok Stronghold，先接洛格玛的 莫格之眼／暮光宝典。", s={{"不足 45 级就在东风海岸（约 84, 35-43）沿岸打东海海盗与火枪手，港口附近可以补给"}, {"40-45 级有队伍可下 Krol'dok Stronghold，先接洛格玛的 莫格之眼／暮光宝典"}}}, {k="交通", text="到 45 级后在爆破引线港码头（80.60, 54.60）搭中立船到塔纳利斯热砂港（68.60, 23.00），再往加基森。若要留在东部王国，可沿路回洛格玛飞行点。从塔纳利斯抵港的部落角色同样要由陆路去洛格玛开飞行点。"}}, danger={[1]="斥候长瓦加斯是精英。组到队伍再靠近，先把周围巡逻怪分开。", [2]="东风水滨的火枪手容易在远处加入战斗。清海盗时沿沙滩拉开，炸船前清出上船的路。"}, grind={[1]={mob="东海冒险家", note="爆破引线港北侧东风海岸，数据库刷新点密集，普通怪。与火枪手混在一起，沿沙滩逐只拉；可同步完成 恶性竞争。"}, [2]={mob="东海火枪手", note="东风海岸中段，数据库刷新点密集，普通远程怪。与海盗交错，近战可利用地形拉到岸侧；适合补到 45 级。"}}, supply={[1]={npc="格拉克纳"}, [2]={npc="旅店老板吉兹普林克"}, [3]={npc="米卡·达比"}, [4]={npc="旅店老板吉兹普林克"}, [5]={npc="格里泽克"}, [6]={npc="克里克香克"}}, steps={[1]={text="已交暮光不再并带着巨人之地，才往北线找克鲁格菲斯特。做完北线先回洛格玛交克鲁格菲斯特的法令，再往西去暮光之罩。跳过这条任务链时，从洛格玛直接往东到爆破引线港。", tag="可选"}, [2]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="有北边前置才做、可选"}, [3]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="有北边前置才做、可选"}, [4]={hint="为博尔德罗克的克鲁格菲斯特消灭7名暮光虐待者和7名暮光唤火者。", tag="有北边前置才做、可选、目标：暮光虐待者/暮光唤火者"}, [5]={hint="从克朗克那里为博尔德罗克的克鲁格菲斯特收回颅骨重锤。", tag="有北边前置才做、可选、目标：克朗克"}, [6]={npc="乔姆-乔姆", tgt="乔姆-乔姆", tag="路过才做、可选"}, [7]={hint="护送乔姆-乔姆前往博尔德罗克，将其交给克鲁格菲斯特。", tag="路过才做、可选"}, [8]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="路过才做、可选"}, [9]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="有北边前置才做、可选"}, [10]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="有北边前置才做、可选"}, [11]={npc="克鲁格菲斯特", tgt="克鲁格菲斯特", tag="有北边前置才做、可选"}, [12]={hint="向洛格玛的克罗姆罗什复命。", tag="有北边前置才做、可选"}, [13]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="有北边前置才做、可选"}, [14]={text="洛格玛西侧暮光营地"}, [15]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="可选"}, [16]={hint="在洛格玛以西的丘陵地带找到达格罗什。", tag="可选"}, [17]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [18]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [19]={npc="达格罗什", tgt="达格罗什", tag="可选"}, [20]={hint="为达格罗什击败暮光之帷内的8名暮光狂热者、8名暮光腐蚀者和8名暮光勇士。", tag="目标：暮光狂热者/暮光腐蚀者/暮光勇士、可选"}, [21]={h