    ["05-d19"] = {name="Krol'dok Stronghold", nameA="{a:17780}", entrance="大河林地 48.60, 26.30", pickup="到大河林地 洛格玛先做特兰古尔的 Sunnyglade 与棍趾链，跑博尔德罗克的克鲁格菲斯特前置；之后从洛格玛往西进暮光营地找达格罗什和 Crag'rog，回洛格玛交书信再接眼与宝典。飞洛格玛或从卡加斯步行进大河林地，往 Sunnyglade 正北的高地找门。厚皮 ×4、铁锭 ×12 可先备给铸模后续。", pickupS={{"到大河林地 洛格玛先做特兰古尔的 Sunnyglade 与棍趾链，跑博尔德罗克的克鲁格菲斯特前置"}, {"之后从洛格玛往西进暮光营地找达格罗什和 Crag'rog，回洛格玛交书信再接眼与宝典"}, {"飞洛格玛或从卡加斯步行进大河林地，往 Sunnyglade 正北的高地找门"}, {"厚皮 ×4、铁锭 ×12 可先备给铸模后续"}}, tips={{k="動線", text="矿道打葛罗克斯→暮光指挥官扎尔莫克→阿什卡旁铁匠铺找铸模→纳古克取暮光宝典→桥头图夫→霸主马戈取莫格之眼。全程沿途收暮光教徒耳朵。"}, {k="取捨", text="先完成 大河林地洛格玛、大河林地博尔德罗克与火线港前置再组队，可同趟完成三项。铸模材料可预备，有打到再交。"}, {k="說明", text="入口在阳光林地正北，城门旁另有要塞传送门。", s={{"入口在阳光林地正北，城门旁另有要塞传送门"}}}}, steps={[1]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [2]={hint="消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。", tag="副本前置链"}, [3]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [4]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [5]={hint="从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。", tag="副本前置链"}, [6]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [7]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [8]={hint="在河流以南消灭8个法霍德牧师和12个法霍德斥候。", tag="副本前置链"}, [9]={npc="克罗姆罗什", tgt="克罗姆罗什", tag="副本前置链"}, [10]={npc="特兰古尔", tgt="特兰古尔"}, [11]={npc="特兰古尔", tgt="特兰古尔"}, [12]={hint="为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。", tag="目标：暮光袭击者/暮光暗影法师/暮光新教徒"}, [13]={hint="为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。", tag="目标：暮光暗影法师"}, [14]={npc="特兰古尔", tgt="特兰古尔"}, [15]={npc="特兰古尔", tgt="特兰古尔"}, [16]={npc="特兰古尔", tgt="特兰古尔", preText="暮光逼近、暮光信件"}, [17]={hint="说服阳光林地的一名暮光之锤矿工，让他泄露秘密。"}, [18]={npc="棍趾", tgt="棍趾"}, [19]={npc="棍趾", tgt="棍趾", preText="挖掘答案"}, [20]={hint="为棍趾在阳光林地下方的洞穴中寻找失踪的食人魔。"}, [21]={npc="强化蛮兵", tgt="暮光蛮兵"}, [22]={npc="强化蛮兵", tgt="暮光蛮兵", preText="紫色的家伙"}, [23]={npc="棍趾", tgt="棍趾", preText="紫色的家伙"}, [24]={hint="消灭5名强化蛮兵和10名暮光仪式师，然后回到阳光林地的棍趾那里。", tag="目标：强化蛮兵/暮光仪式师"}, [25]={hint="摧毁在阳光林地下方洞穴中发现的5个暮光仪式法阵。", desc="沿洞穴寻找。"}, [26]={npc="棍趾", tgt="棍趾"}, [27]={npc="棍趾", tgt="棍趾"}, [28]={npc="棍趾", tgt="棍趾", desc="精英，先请队友一同完成。", preText="紫色的家伙、令人作呕的光"}, [29]={hint="在阳光林地的洞穴中消灭乔格扎克，并为棍趾收集他们的头颅。",