    ["04-29"] = {name="塔纳利斯", nameA="塔纳利斯 {a:977}／{a:976}", shortA="塔纳利斯 {a:977} +", tips={{k="取捨", text="第一次到热砂港，把海盗帽、击杀、通缉与货箱一起清。TUGs 先排菲拉斯再回头清港口海盗；本路线从爆破引线港乘船到热砂港，可先清海岸并保留同样的视频站序。"}, {k="取捨", text="尖啸者的灵魂 留菲拉斯莫沙彻营地做；砂槌欠款 留砂槌营地；给马克基雷的货物 留到前往悲伤沼泽时在荆棘谷藏宝海湾交。"}, {k="提醒", text="未到下一站所需等级，废土营地 59.40,24.71、落帆海湾入口 70.90,42.48 的普通怪可循环打。已组祖尔法拉克可带 圣甲虫的壳、探水棒、巨魔调和剂，塔纳利斯加基森与砂槌营地交。", s={{"未到下一站所需等级，废土营地 59.40,24.71、落帆海湾入口 70.90,42.48 的普通怪可循环打"}, {"已组祖尔法拉克可带 圣甲虫的壳、探水棒、巨魔调和剂，塔纳利斯加基森与砂槌营地交"}}}}, danger={[1]="卡利夫会巡逻，身边可能带护卫。先清沿途废土强盗，等他走到开阔处再打。"}, grind={[1]={mob="南海海盗", note="落帆海湾入口，普通怪密集，海盗任务容易撞队。沿外侧往海滩清，可同步收海盗任务掉落。"}, [2]={mob="南海流氓", note="码头外沿的普通怪，海盗入口被抢怪时换点。从外缘拉，避免同时引到码头守怪。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}, [6]={npc="吉科希斯"}}, steps={[1]={text="在大河林地爆破引线港 80.60, 54.60 搭热砂港线，在塔纳利斯 68.60, 23.00 下船。从奥格瑞玛出发且已开加基森飞行点可搭鸟；初访可由乱风岗经闪光平原南坡步行到加基森。"}, [2]={text="港口先接，再入城整备"}, [3]={npc="傲慢的店主", tgt="傲慢的店主"}, [4]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹"}, [5]={npc="通缉：卡利夫·斯科比斯汀", npcObj=true}, [6]={npc="通缉：卡利夫·斯科比斯汀", npcObj=true}, [7]={npc="斯杜雷", tgt="斯杜雷"}, [8]={npc="叶基亚", tgt="叶基亚", desc="菲拉斯莫沙彻营地在菲拉斯做，塔纳利斯加基森与砂槌营地回热砂港交。"}, [9]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹", tag="可选", desc="砂槌营地顺路做，届时回热砂港交。"}, [10]={text="热砂港沿大道往西到加基森。找部落飞行管理员布科雷克·怒拳（51.60, 25.44）开飞行点，向旅店老板菲兹格瑞博（52.51, 27.91）暂绑炉石。到菲拉斯莫沙彻营地再改绑。"}, [11]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [12]={npc="操作员鲁格伦克", tgt="操作员鲁格伦克"}, [13]={npc="特兰雷克", tgt="特兰雷克", tag="可选", desc="打算下祖尔法拉克才接。"}, [14]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹", tag="可选", desc="祖尔法拉克阶梯事件掉落。", star={"石工兄弟会之戒", {"ROGUE", "HUNTER", "DRUID"}}}, [15]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤", tag="可选", desc="打算下祖尔法拉克才接。"}, [16]={text="废土营地和落帆海湾"}, [17]={hint="去加基森的东面杀掉10个废土窃贼和10个废土强盗，然后向总工程师比格维兹复命。"}, [18]={hint="收集5只废土水袋，把它们交给加基森的鲁格伦克。"}, [19]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [20]={npc="操作员鲁格伦克", tgt="操作员鲁格伦克"}, [21]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [22]={hint