    ["04-30"] = {name="菲拉斯", nameA="菲拉斯 {a:1099}", tips={{k="取捨", text="木爪豺狼人前置一路做到 作战计划，开启菲拉斯莫沙彻营地与怒痕堡东南祖卡什两个可一起做的任务。"}, {k="取捨", text="有捡到 OOX-22/FE 定位器可留在背包；护送与海岸巨人／水元素留待回访菲拉斯莫沙彻营地。"}, {k="提醒", text="未到 47 级可补深痕谷雪人 55.29,53.76，或营地北侧戈杜尼食人魔 75.13,34.86；打完拉回营地交件。", s={{"未到 47 级可补深痕谷雪人 55.29,53.76，或营地北侧戈杜尼食人魔 75.13,34.86"}, {"打完拉回营地交件"}}}}, danger={[1]="莫沙彻北边的戈杜尼营地混有法师和蛮兵。挖钴矿前先清撤退路，不要一路往营地深处跑。"}, grind={[1]={mob="深痕雪人", note="深痕谷外坡，普通雪人较集中，可连打并收雪人皮。洞口有同任务玩家，沿坡轮替。"}, [2]={mob="暴怒的巨型深痕雪人", note="深痕谷西南，普通雪人等级稍高。从外侧拉近战怪，避开密集洞口。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="已有莫沙彻飞行点可从加基森直接飞。初访照视频从加基森北行上闪光平原，经千针石林沿西路入菲拉斯。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={nodeA="{a:1099}", desc="向夏恩开启飞行点。"}, [3]={text="将炉石绑定在旅店老板格鲁尔处（74.80, 45.18）。"}, [4]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [5]={npc="奥尔文·吉兹米克", tgt="奥尔文·吉兹米克"}, [6]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [7]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [8]={npc="巫医尤克里", tgt="巫医尤克里"}, [9]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [10]={text="营地周边与北面戈杜尼前半段"}, [11]={hint="将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。"}, [12]={hint="莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。"}, [13]={hint="莫沙彻营地的奥尔文·吉兹米克需要12块戈杜尼钴矿石的样本。", desc="在戈杜尼营地的蓝色土丘旁使用任务铲子。"}, [14]={npc="戈杜尼卷轴", npcObj=true, desc="点击北侧地面的戈杜尼卷轴。"}, [15]={hint="将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。"}, [16]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [17]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [18]={npc="奥尔文·吉兹米克", tgt="奥尔文·吉兹米克"}, [19]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [20]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [21]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [22]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [23]={hint="在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。", desc="计时一小时。先去南边木爪岭，打完五只立即回交。"}, [24]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [25]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [26]={hint="在莫沙彻营地以南的豺狼人营地中寻找豺狼人的战斗计划。"}, [27]={npc="木爪作战地图", npcObj=true}, [28]={npc="木爪作战地图", npcObj=true}, [29]={hint="把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。"}, [30]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [31]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [32]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [33]={text="中央精灵龙，向西到深痕谷"}, [34]={hint="给莫沙彻营地的克鲁伊格·碎颅带去10个闪光的小精灵翅膀。"}, [35]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。", desc="塔纳利斯加基森与砂槌营地，回热砂港再交。"}, [36]={hint="给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。", desc="深痕谷洞内外的雪人掉厚重的雪人皮。"}, [37]={text="打完深痕谷，炉石回莫沙彻营地集中交。"}, [38]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [39]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [40]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [41]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [42]={hint="收集20支恐怖图腾之角，把它们交给千针石林的克鲁伊格·碎颅。", desc="到营地西北的恐怖图腾聚落，打到号角后回营。"}, [43]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [44]={npc="克鲁伊格·碎颅", tgt="克鲁伊格·碎颅"}, [45]={text="往悲伤沼泽途中，先在奥格瑞玛开菲拉斯后续"}, [46]={text="从莫沙彻飞奥格瑞玛（通常经陶拉祖等已开飞行点）。炉石维持绑定莫沙彻，清完悲伤沼泽东岸后可用来直接回菲拉斯。"}, [47]={hint="将皱缩的头颅交给奥格瑞玛的尼尔鲁·火刃。"}, [48]={hint="将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。"}, [49]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃"}, [50]={npc="贝尔戈洛姆·石槌", tgt="贝尔戈洛姆·石槌"}, [51]={npc="尼尔鲁·火刃", tgt="尼尔鲁·火刃", desc="留菲拉斯莫沙彻营地与怒痕堡，回莫沙彻交。"}}},
    ["04-31"] = {name="悲伤沼泽", nameA="悲伤沼泽 {a:75}", tips={{k="取捨", text="悲伤沼泽斯通纳德已做北侧的迷失者与护送。这趟只补海岸；先交 缺乏补给／缺乏补给 才开鱼人链，螃蟹在去程收、回程交。"}, {k="提醒", text="队伍要进沉没的神庙，可以先处理悲伤沼泽斯通纳德接的 阿塔莱流放者；交点实际在辛特兰，该线留辛特兰恶齿村与辛萨罗以后。若未满 47 级，东风海岸一般巨型海蟹可在 91.00,70.80 附近补；接近 49 级时补等优先打下一站较高等级的怒痕雪人。", s={{"队伍要进沉没的神庙，可以先处理悲伤沼泽斯通纳德接的 阿塔莱流放者"}, {"交点实际在辛特兰，该线留辛特兰恶齿村与辛萨罗以后"}, {"若未满 47 级，东风海岸一般巨型海蟹可在 91.00,70.80 附近补"}, {"接近 49 级时补等优先打下一站较高等级的怒痕雪人"}}}}, danger={[1]="东风海岸的鱼人常并排站，喷墨者与神谕者会从后方加怪。由岸上单拉，别追进水中。"}, grind={[1]={mob="巨型淤泥蟹", note="悲伤沼泽东岸的普通螃蟹，分布很密、可剥皮。只适合刚进站或差一小截，与海岸任务玩家共用。"}, [2]={mob="老年怒痕雪人", note="若接近 49 级，等下一站飞菲拉斯再打。怒痕堡普通雪人等级较合适，外坡能分开拉，洞口容易碰到任务队。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="从奥格瑞玛飞棘齿城，搭船到藏宝海湾。炉石留莫沙彻。"}, [2]={text="藏宝海湾顺手交件"}, [3]={hint="将斯杜雷的瓶子交给藏宝海湾的\"海狼\"马克基雷。"}, [4]={npc="海狼马克基雷", tgt="海狼马克基雷"}, [5]={npc="克拉兹克", tgt="克拉兹克", tag="可选", desc="悲伤沼泽斯通纳德若已收齐梦境之尘才交。"}, [6]={npc="威士忌斯利姆", tgt="威士忌斯利姆", desc="留辛特兰恶齿村与辛萨罗在辛特兰海岸拾酒，荆棘谷藏宝海湾经藏宝海湾再交。"}, [7]={text="斯通纳德到东南海岸"}, [8]={text="由藏宝海湾飞悲伤沼泽斯通纳德。若未开该点，沿荆棘谷北路经暮色森林东缘和逆风小径到斯通纳德，找布雷依克（46.07, 54.83）开飞行点。"}, [9]={npc="达尔", tgt="达尔"}, [10]={npc="达尔", tgt="达尔"}, [11]={hint="给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。", desc="先在泪水之池西南沼泽打盐齿鳄鱼，不够可沿岸找。"}, [12]={hint="给悲伤沼泽的达尔带去10条巨大的螃蟹腿。", desc="沿东风海岸北段打巨型海蟹，南下前先收十条腿。"}, [13]={npc="托克卡尔", tgt="托克卡尔"}, [14]={npc="托克卡尔", tgt="托克卡尔"}, [15]={hint="给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。"}, [16]={npc="托克卡尔", tgt="托克卡尔"}, [17]={npc="托克卡尔", tgt="托克卡尔"}, [18]={hint="与悲伤沼泽的卡塔尔谈一谈。"}, [19]={npc="卡塔尔", tgt="卡塔尔"}, [20]={npc="卡塔尔", tgt="卡塔尔", desc="沿东南海滩打沼泽鱼人三种各十只，再回卡塔尔。"}, [21]={hint="杀掉10个沼泽鱼人、10个沼泽喷墨鱼人和10个沼泽食腐鱼人，然后向悲伤沼泽的卡塔尔回报。", desc="沿东南海滩打沼泽鱼人三种各十只，再回卡塔尔。"}, [22]={npc="卡塔尔", tgt="卡塔尔", desc="沿东南海滩打沼泽鱼人三种各十只，再回卡塔尔。"}, [23]={npc="卡塔尔", tgt="卡塔尔"}, [24]={hint="与悲伤沼泽的托克卡尔谈一谈。"}, [25]={npc="托克卡尔", tgt="托克卡尔"}, [26]={npc="卡塔尔", tgt="卡塔尔", desc="交完 1427 要走回卡塔尔接下一段。顺着海岸往北补鱼人神谕者，交前确认三种各十只。"}, [27]={hint="杀掉10名沼泽喷墨鱼人、10名沼泽食腐鱼人和10名沼泽鱼人智者，然后向悲伤沼泽的卡塔尔回报。", desc="交完 1427 要走回卡塔尔接下一段。顺着海岸往北补鱼人神谕者，交前确认三种各十只。"}, [28]={npc="卡塔尔", tgt="卡塔尔", desc="交完 1427 要走回卡塔尔接下一段。顺着海岸往北补鱼人神谕者，交前确认三种各十只。"}, [29]={text="沿同路西返斯通纳德，向达尔交螃蟹腿。"}, [30]={npc="达尔", tgt="达尔"}, [31]={text="交完后用炉石回莫沙彻营地。炉石未绑莫沙彻时飞藏宝海湾，搭棘齿城船再飞莫沙彻。"}}},
    ["04-32"] = {name="菲拉斯 厄运之槌", nameA="菲拉斯 {a:1099}／厄运之槌", shortA="菲拉斯 {a:1099} +", tips={{k="取捨", text="怒痕雪人与深痕谷雪人是两批；先在菲拉斯莫沙彻营地交 质量的保证，再清这次的 更高的品质。完美的雪人毛皮 只在掉落时交。"}, {k="取捨", text="鱼人链后由炉石回来可省一次跨海。辛特兰恶齿村与辛萨罗再取 测试容器 枭兽精华，后续 角鹰兽灵魂精华-灵魂武器 留菲拉斯莫沙彻营地。"}, {k="提醒", text="视频回菲拉斯时接近 49 级；需要补等时，可在怒痕堡 55.73,33.05 至 54.39,33.10 外圈循环打怒痕雪人，优先单拉。", s={{"视频回菲拉斯时接近 49 级"}, {"需要补等时，可在怒痕堡 55.73,33.05 至 54.39,33.10 外圈循环打怒痕雪人，优先单拉"}}}}, danger={[1]="怒痕雪人洞门窄，老年怒痕雪人会和门口怪同时进战。先打外围再进洞。"}, grind={[1]={mob="狂暴的怒痕雪人", note="怒痕堡外坡的普通雪人。沿坡转一圈并收雪人皮，洞内有人抢时留外圈。"}, [2]={mob="老年怒痕雪人", note="同一营地的高等普通雪人，可混打补到 49 级。窄洞容易同时拉到两只，先清门边。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={hint="将尼尔鲁的草药包送给菲拉斯的巫医尤克里。"}, [2]={npc="巫医尤克里", tgt="巫医尤克里"}, [3]={npc="巫医尤克里", tgt="巫医尤克里", desc="留辛特兰。打枭兽后对尸体使用任务容器，留菲拉斯莫沙彻营地回莫沙彻交。"}, [4]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="沿路保留天然材料，完整收集与交件留菲拉斯莫沙彻营地。"}, [5]={npc="巫医尤克里", tgt="巫医尤克里", desc="塔纳利斯加基森与破碎石柱在塔纳利斯断柱交玛尔冯。"}, [6]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", desc="先留着，到费伍德森林击杀灰熊及掠夺者，菲拉斯莫沙彻营地回莫沙彻交。"}, [7]={hint="把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}, [8]={hint="击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}, [9]={hint="莫沙彻营地的洛卡·奥赫要你去杀掉十个戈杜尼萨满祭司、10个戈杜尼术士和5个戈杜尼虐待者。"}, [10]={hint="莫沙彻营地的洛卡·奥赫希望你找到一颗戈杜尼之宝珠。"}, [11]={text="顺着大路回莫沙彻，交菲拉斯的食人魔和祖卡什的入侵，下一趟再去北方雪人。"}, [12]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [13]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄"}, [14]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [15]={npc="洛卡·奥赫", tgt="洛卡·奥赫"}, [16]={npc="哈杜肯·迅蹄", tgt="哈杜肯·迅蹄", desc="留塔纳利斯加基森与砂槌营地经奥格瑞玛一并交。"}, [17]={npc="洛卡·奥赫", tgt="洛卡·奥赫", desc="留塔纳利斯加基森与砂槌营地经奥格瑞玛交。"}, [18]={text="怒痕雪人与回程"}, [19]={hint="把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。", desc="沿主路往西，绕到怒痕堡 55.73,33.05 取十张毛皮。"}, [20]={npc="完美的雪人毛皮", npcObj=true, tag="可选", desc="怒痕雪人掉完美毛皮才接。"}, [21]={hint="把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。", tag="可选"}, [22]={text="雪人任务完成后炉石回莫沙彻营地；炉石仍在冷却就沿大路步行回去。交完再飞加基森。"}, [23]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄"}, [24]={npc="杉多尔·迅蹄", tgt="杉多尔·迅蹄", tag="可选"}}},
    ["05-d20"] = {name="玛拉顿", entrance="凄凉之地 29.10, 62.50", pickup="前往凄凉之地 葬影村前，可从奥格瑞玛尤塞尔奈接暗影残片，但最低 39 级。离开菲拉斯 莫沙彻营地后往凄凉之地 葬影村，先找瓦克与瑟琳德拉，再绕维洛、半人马贱民。想做永恒版水瓶支线先到东南辛德拉，完成水晶塔与魔导师引导后到遗忘花园接 林中传言→腐朽与懊悔。辛德拉任务最低 35 级。进玛拉顿橙门之前接凯雯德拉。", pickupS={{"前往凄凉之地 葬影村前，可从奥格瑞玛尤塞尔奈接暗影残片，但最低 39 级"}, {"离开菲拉斯 莫沙彻营地后往凄凉之地 葬影村，先找瓦克与瑟琳德拉，再绕维洛、半人马贱民"}, {"想做永恒版水瓶支线先到东南辛德拉，完成水晶塔与魔导师引导后到遗忘花园接 林中传言→腐朽与懊悔"}, {"辛德拉任务最低 35 级"}, {"进玛拉顿橙门之前接凯雯德拉"}}, tips={{k="動線", text="橙线打诺克赛恩、锐刺鞭笞者，紫线打维利塔恩；沿路收塑像、可汗宝石和任务材料→两线掉落齐了到汇合点找塞雷布拉斯，跟完节杖仪式→地歌瀑布→公主→洛特格里普水池（选做）。"}, {k="取捨", text="首次想拿节杖就走橙、紫两线，若只打公主与鳄鱼，队友有节杖可直接进内区。任务若需门外暗影怪或不同分支，不要从捷径跳过。"}, {k="說明", text="29.10, 62.50 是荒野洞口，橙与紫两道实例门要沿对应颜色洞道寻找。紫线与橙线在毒水瀑布附近会合。", s={{"29.10, 62.50 是荒野洞口，橙与紫两道实例门要沿对应颜色洞道寻找"}, {"紫线与橙线在毒水瀑布附近会合"}}}}, steps={[1]={npc="尤塞尔奈", tgt="尤塞尔奈"}, [2]={npc="瓦克·战痕", tgt="瓦克·战痕"}, [3]={npc="瑟琳德拉", tgt="瑟琳德拉"}, [4]={npc="维洛", tgt="维洛"}, [5]={npc="半人马贱民", tgt="半人马贱民", desc="半人马贱民在凄凉之地南部巡逻。"}, [6]={npc="辛德拉水晶塔", npcObj=true, tag="可选"}, [7]={hint="探索辛德拉，设法寻找与你所见相似的其他水晶塔。", tag="可选"}, [8]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选"}, [9]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", preText="奇怪的水晶塔"}, [10]={hint="取回那些在玛格拉姆村和吉尔吉斯村受到严密看守的水晶塔碎片与残片。将它们交给莫丹特·永影。", tag="可选", desc="坐标依序为玛格拉姆与吉尔吉斯半人马村的两件物品。"}, [11]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选"}, [12]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", desc="法力数量依任务日志。", preText="水晶塔碎片"}, [13]={hint="从辛德拉神殿内取得法力过滤网，并用它来收集远古魔力水晶。收集到足够的法力后，即刻为水晶塔充能，然后向莫丹特·永影复命。", tag="可选、需游戏内实测", desc="法力数量依任务日志。到上层神殿最高一层取筛子，共收集 8 份法力，每塔 4 份。西塔与东塔可在潜行状态下互动。"}, [14]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选", desc="法力数量依任务日志。"}, [15]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需游戏内实测", preText="为晶塔供能"}, [16]={hint="与辛德拉的莫丹特·永影交谈，了解关于你修复的那些水晶的信息。", tag="可选、需游戏内实测"}, [17]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需游戏内实测"}, [18]={npc="莫丹特·永影", tgt="莫丹特·永影", tag="可选、需游戏内实测", preText="简短的历史课"}, [19]={hint="在辛德拉神殿内找到魔导师基兰迪斯。", tag="可选、需游戏内实测"}, [20]={npc="魔导师基兰迪斯", tgt="魔导师基兰迪斯", tag="可选、需游戏内实测"}, [21]={npc="米瑟拉", tgt="米瑟拉", tag="副本前置链"}, [22]={npc="米瑟拉", tgt="米瑟拉", tag="副本前置链"}, [23]={npc="米瑟拉", tgt="米瑟拉", tag="可选、需游戏内实测", preText="会见魔导师"}, [24]={hint="在凄凉之地辛德拉的荒弃花园找到林地怪。", tag="可选、需游戏内实测"}, [25]={npc="林地怪", tgt="林地怪", tag="可选、需游戏内实测"}, [26]={npc="林地怪", tgt="林地怪", tag="可选、需游戏内实测", desc="先交 林中传言；带进玛拉顿内区。", preText="林中传言"}, [27]={npc="凯雯德拉", tgt="凯雯德拉", desc="凯雯德拉站在橙门外。两边首领各掉一件。"}, [28]={hint="从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。"}, [29]={text="玛拉顿 入口"}, [30]={text="橙线（Foulspore Cavern，45-53）。进洞深处看橙色水晶和池塘，先装水再穿橙色传送门。"}, [31]={hint="在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。", desc="位置：橙门外水池装水，进门后沿路找藤蔓。", spot="橙门外水池装水，进门后沿路找藤蔓。"}, [32]={text="紫线（Wicked Grotto，45-53）。由三岔处走紫色水晶通道；取得维利塔恩掉落的钻石。"}, [33]={hint="为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。", desc="数量以任务日志为准。位置：橙紫外洞先打半人马，进门后一路拾雕像。", spot="橙紫外洞先打半人马，进门后一路拾雕像。"}, [34]={hint="阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。", desc="第一位在橙紫两线之间；第二与第三位分别在门外通道；第四、第五位在橙、紫门内，各巡逻。位置：橙紫分岔与两外洞找前三人，两门内各一人。", spot="橙紫分岔与两外洞找前三人，两门内各一人。"}, [35]={hint="找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。", desc="位置：橙线拿魔棒、紫线拿钻石，汇合处打塞雷布拉斯。顺序：橙紫线皆须到；材料齐才交。", spot="橙线拿魔棒、紫线拿钻石，汇合处打塞雷布拉斯。"}, [36]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需游戏内实测", desc="击败首领后与赎罪的塞雷布拉斯交谈。击败后向房内的赎罪者交付。", spot="塞雷布拉斯首领房内，赎罪者"}, [37]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需游戏内实测", desc="赎罪者在首领房内；仪式中跟随他。", preText="玛拉顿的传说"}, [38]={hint="帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。", desc="赎罪者在首领房内；仪式中跟随他。位置：塞雷布拉斯首领房，跟赎罪者走完仪式。", spot="塞雷布拉斯首领房，跟赎罪者走完仪式。"}, [39]={npc="赎罪的塞雷布拉斯", tgt="赎罪的塞雷布拉斯", tag="需游戏内实测", desc="赎罪者在首领房内；仪式中跟随他。", spot="塞雷布拉斯首领房内，赎罪者"}, [40]={text="内区地歌瀑布（Earth Song Falls，48-57）。队伍可从橙／紫路线的交会处往下，或由已持节杖的玩家开捷径。"}, [41]={hint="深入玛拉顿，取回一瓶大地之歌水。将其带回凄凉之地，交给荒弃花园的林地怪。", tag="可选、需游戏内实测", desc="洛特格里普在水池巡游；小喷泉在同一水池的水面上。位置：公主洞下方跳入洛特格里普水池，找水面喷泉。顺序：可先做第 39 步，再下水。", spot="公主洞下方跳入洛特格里普水池，找水面喷泉。"}, [42]={hint="杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。", desc="位置：沿地歌瀑布深入扎尔塔洞穴，到公主平台。", spot="沿地歌瀑布深入扎尔塔洞穴，到公主平台。"}, [43]={npc="扎尔塔的灵魂", tgt="扎尔塔的灵魂", tag="需游戏内实测", desc="瑟莱德丝公主死后，扎尔塔的灵魂出现。先接，出本再交。"}, [44]={npc="瑟琳德拉", tgt="瑟琳德拉"}, [45]={npc="瓦克·战痕", tgt="瓦克·战痕"}, [46]={npc="维洛", tgt="维洛"}, [47]={npc="半人马贱民", tgt="半人马贱民"}, [48]={npc="尤塞尔奈", tgt="尤塞尔奈"}, [49]={hint="深入玛拉顿，取回一瓶大地之歌水。将其带回凄凉之地，交给荒弃花园的林地怪。", tag="可选、需游戏内实测"}, [50]={npc="林地怪", tgt="林地怪", tag="可选、需游戏内实测"}, [51]={hint="到月光林地去找到雷姆洛斯，将生命之种交给他。", desc="可等 月光林地 顺路再做。"}, [52]={npc="守护者雷姆洛斯", tgt="守护者雷姆洛斯", desc="可等 月光林地。"}}},
    ["04-33"] = {name="塔纳利斯 沙怒营地", nameA="塔纳利斯 {a:976}／沙怒营地", shortA="塔纳利斯 {a:976} +", tips={{k="取捨", text="北方水池交完先开 82；交 82 开 10 再一起跑砂槌、灌木谷与南方虫巢。"}, {k="取捨", text="有队伍可下祖尔法拉克，四项副本任务可同场做。无队伍直接略过四项及 远古之卵。"}, {k="取捨", text="先交 32 与 祖卡什报告；异种蝎的远征 需 50 级，若已到门槛可在暗影裂口确认，完整后续留塔纳利斯加基森与破碎石柱。"}, {k="提醒", text="未满 50 级，砂槌营地 40.75,50.67 的普通食人魔集中且掉布；想在灼热峡谷升级就先保留这一小段经验缺口。", s={{"未满 50 级，砂槌营地 40.75,50.67 的普通食人魔集中且掉布"}, {"想在灼热峡谷升级就先保留这一小段经验缺口"}}}}, danger={[1]="森提帕尔虫巢入口容易连拉。只在巢口外沿空地打，不要为了一只追进窄道。"}, grind={[1]={mob="砂槌蛮兵", note="砂槌营地外侧，普通近战怪多，掉布并与食人魔任务重叠。有人抢怪可沿外围移动。"}, [2]={mob="森提帕尔群居蝎", note="西侧异种蝎巢外的普通怪密集且等级较高。只沿巢口单拉，窄道容易引到一群。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}}, steps={[1]={text="从莫沙彻飞加基森，在加基森暂绑炉石。"}, [2]={text="加基森接齐，西侧先完成水样与腐化之巢"}, [3]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [4]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [5]={npc="安迪·利恩", tgt="安迪·利恩"}, [6]={npc="特兰雷克", tgt="特兰雷克"}, [7]={npc="奎因", tgt="奎因", tag="可选", desc="顺路遇到沙漠废料才捡。"}, [8]={hint="用未使用的寻水器在流沙岗哨旁边的池中采集水样。一旦你收集到水样，就尽快将其交给加基森的高级勘探员菲兹杜瑟。", desc="在流沙岗哨水池使用未使用的寻水器，准备好水样立即回城。"}, [9]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [10]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [11]={hint="从腐化之巢找5个森提帕尔昆虫肢体，把它们交给加基森的炼金师匹斯特苏格。"}, [12]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [13]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [14]={text="南面砂槌与灌木谷，沿山脚扫到异种蝎巢"}, [15]={hint="加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。"}, [16]={hint="塔纳利斯热砂港的保安主管图拉·比尔吉维兹要你找回一只格外闪亮的手镯，它遗失在砂槌食人魔营地附近。", tag="可选", desc="塔纳利斯热砂港与加基森有接才做。"}, [17]={hint="找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。", desc="在灌木谷打露水收集者，拾取饱满的露水腺 ×1。"}, [18]={hint="加基森的特兰雷克要你杀掉8只长瘤的灌木兽和8只灌木塑根者。"}, [19]={hint="寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。", desc="在南方裂隙下到地下，找到谢申克的勘探设备。"}, [20]={hint="奎因要你找回7块沙漠废料，并在加基森交还给她。", tag="可选", desc="标记为物件实测出现点。废料可由联盟任务丢出，没看到就沿加基森外围找。"}, [21]={text="回加基森交任务。若有炉石可直接用；顺路再取好味道和昆虫研究。"}, [22]={npc="安迪·利恩", tgt="安迪·利恩"}, [23]={npc="特兰雷克", tgt="特兰雷克"}, [24]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [25]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [26]={npc="奎因", tgt="奎因", tag="可选"}, [27]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [28]={hint="马林·诺格弗格让你与加基森的斯普琳科谈一谈。"}, [29]={npc="斯普琳科", tgt="斯普琳科"}, [30]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [31]={hint="到加基森的炼金师匹斯特苏格那里去了解关于昆虫的研究有没有新的进展。"}, [32]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [33]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格"}, [34]={hint="把这份报告带给加基森的高级勘探员菲兹杜瑟，让他按照炼金师匹斯特苏格的要求为你复制一份报告。"}, [35]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟"}, [36]={npc="斯普琳科", tgt="斯普琳科", desc="辛特兰瓦罗温湖采紫色水生菇，塔纳利斯加基森与破碎石柱回加基森交。"}, [37]={npc="高级勘探员菲兹杜瑟", tgt="高级勘探员菲兹杜瑟", desc="路过奥格瑞玛暗巷区交，与 祖卡什报告 一起完成前置。"}, [38]={text="热砂港与祖尔法拉克选做"}, [39]={npc="叶基亚", tgt="叶基亚", desc="菲拉斯莫沙彻营地已完成三个尖啸者灵魂。"}, [40]={npc="安全主管吉罗姆·比格维兹", tgt="安全主管吉罗姆·比格维兹", tag="可选"}, [41]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="前置 尖啸者的灵魂 已交，有祖尔法拉克队伍才接。"}, [42]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", tag="可选"}, [43]={hint="给加基森的特兰雷克带去5个完整的圣甲虫壳。", tag="可选", desc="清除祖尔法拉克墓地中的圣甲虫。"}, [44]={hint="把探水棒交给加基森的首席工程师沙克斯·比格维兹。", tag="可选", desc="完成百人阶梯事件，从布莱中士取棒。"}, [45]={hint="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", tag="可选"}, [46]={npc="叶基亚", tgt="叶基亚", tag="可选"}, [47]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="只有已交 摩沙鲁的预言 才接。辛特兰可拿远古之卵，塔纳利斯加基森与破碎石柱回港交。"}, [48]={npc="特兰雷克", tgt="特兰雷克", tag="可选"}, [49]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹", tag="可选", star={"石工兄弟会之戒", {"ROGUE", "HUNTER", "DRUID"}}}, [50]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤", tag="可选"}, [51]={text="加基森飞奥格瑞玛。先到暗影裂口找基尔兹宾，再去暗木小屋交戈杜尼宝珠。"}, [52]={hint="把报告带给奥格瑞玛的基尔兹宾·鼓眼。"}, [53]={hint="把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。"}, [54]={hint="将戈杜尼宝珠交给奥格瑞玛暗木小屋里的尤塞尔奈。"}, [55]={npc="基尔兹宾·鼓眼", tgt="基尔兹宾·鼓眼"}, [56]={npc="基尔兹宾·鼓眼", tgt="基尔兹宾·鼓眼"}, [57]={npc="尤塞尔奈", tgt="尤塞尔奈"}}},
    ["05-d21"] = {name="祖尔法拉克", entrance="塔纳利斯 38.70, 20.00", pickup="先到塔纳利斯 加基森接三个本地任务，再到热砂港接叶基亚 尖啸者的灵魂；在菲拉斯捉灵魂，回塔纳利斯先到热砂港交 尖啸者的灵魂、接 摩沙鲁的预言，再和队伍于加基森会合。走过千针石林的闪光平原时可接 加兹瑞拉，前往悲伤沼泽前可绕尘泥沼泽解塔贝萨支线。", pickupS={{"先到塔纳利斯 加基森接三个本地任务，再到热砂港接叶基亚 尖啸者的灵魂"}, {"在菲拉斯捉灵魂，回塔纳利斯先到热砂港交 尖啸者的灵魂、接 摩沙鲁的预言，再和队伍于加基森会合"}, {"走过千针石林的闪光平原时可接 加兹瑞拉，前往悲伤沼泽前可绕尘泥沼泽解塔贝萨支线", {class={"MAGE"}}}}, tips={{k="動線", text="安图苏尔支路→塞卡甲虫房顺取第一块摩沙鲁石板→祖穆拉恩墓地→金字塔阶梯事件→水占师维蕾萨取第二块摩沙鲁石板和探水棒（水池可选召加兹瑞拉）→乌克兹。沿路收圣甲虫壳和巨魔调和剂。"}, {k="取捨", text="优先加基森三任与摩沙鲁石板；已有木槌再打加兹瑞拉；塔贝萨留给会经尘泥沼泽的角色。"}, {k="說明", text="可在塔纳利斯 热砂港与加基森先刷一次；走完整叶基亚前置才建议塔纳利斯 加基森与砂槌营地刷。摩沙鲁石板亦为哈卡链前置。", s={{"可在塔纳利斯 热砂港与加基森先刷一次"}, {"走完整叶基亚前置才建议塔纳利斯 加基森与砂槌营地刷"}, {"摩沙鲁石板亦为哈卡链前置"}}}}, steps={[1]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [2]={npc="特兰雷克", tgt="特兰雷克"}, [3]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤"}, [4]={npc="叶基亚", tgt="叶基亚", desc="先在热砂港接，再跑菲拉斯；回热砂港交后立即接 摩沙鲁的预言。"}, [5]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}, [6]={npc="叶基亚", tgt="叶基亚"}, [7]={npc="叶基亚", tgt="叶基亚", preText="尖啸者的灵魂"}, [8]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓", tag="可选", desc="队伍至少一人带祖尔法拉克之槌可确保能敲锣。若先顺跑辛特兰，可在祖尔祭坛取圣槌，再到辛萨罗祭坛转化。"}, [9]={npc="塔贝萨", tgt="塔贝萨", tag="可选", desc="塔贝萨直接提供；40 级幽暗城 塔贝萨的任务 是可略过的导引。"}, [10]={text="祖尔法拉克 入口"}, [11]={hint="给加基森的特兰雷克带去5个完整的圣甲虫壳。", desc="位置：到殉教者塞卡房，清附近的圣甲虫。顺序：同时做第 15 步第一块石板。", spot="到殉教者塞卡房，清附近的圣甲虫。"}, [12]={hint="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", desc="队伍先约定分配，掉落可能一趟不够。位置：从入口起沿主路清各区沙怒巨魔。", spot="从入口起沿主路清各区沙怒巨魔。"}, [13]={hint="将深渊皇冠交给尘泥沼泽的塔贝萨。", tag="可选", desc="位置：过金字塔事件区，沿路到水池旁找维蕾萨。顺序：同时做第 15 步第二块石板。", spot="过金字塔事件区，沿路到水池旁找维蕾萨。"}, [14]={hint="把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。", tag="可选", desc="位置：在维蕾萨旁水池岸边敲锣，等加兹瑞拉出现。顺序：同区先清维蕾萨再敲锣。", spot="在维蕾萨旁水池岸边敲锣，等加兹瑞拉出现。"}, [15]={hint="把探水棒交给加基森的首席工程师沙克斯·比格维兹。", desc="先开牢笼完成阶梯事件，清完下方波次再翻脸。位置：沿主路到金字塔顶开牢笼，下阶梯守波次。顺序：守完波次再挑战布莱中士。", spot="沿主路到金字塔顶开牢笼，下阶梯守波次。"}, [16]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", desc="位置：塞卡在甲虫房；维蕾萨在水池旁，分别拾取。顺序：甲虫房与第 10 步，水池与第 12-13 步。", spot="塞卡在甲虫房；维蕾萨在水池旁，分别拾取。"}, [17]={npc="特兰雷克", tgt="特兰雷克"}, [18]={npc="特伦顿·轻锤", tgt="特伦顿·轻锤"}, [19]={npc="首席工程师沙克斯·比格维兹", tgt="首席工程师沙克斯·比格维兹"}, [20]={npc="叶基亚", tgt="叶基亚"}, [21]={npc="叶基亚", tgt="叶基亚", desc="这次只接并保留；辛萨罗取蛋，之后进阿塔哈卡神庙。", preText="摩沙鲁的预言"}, [22]={npc="维兹尔·铜栓", tgt="维兹尔·铜栓", tag="可选"}, [23]={npc="塔贝萨", tgt="塔贝萨", tag="可选"}}},
    ["04-34"] = {name="灼热峡谷", nameA="灼热峡谷 {a:1446}", tips={{k="交通", text="先在瑟银哨塔开部落飞行点，完成后可飞幽暗城或落锤镇，再接辛特兰。"}, {k="取捨", text="四组杀怪可沿同一圈完成，被盗：鼓风机和望远镜 掉落不足先交别组；悬赏：工头玛托留斯 与 绝密配方！ 在同一洞内，能组队再顺路清。"}, {k="取捨", text="瑟银哨塔交完已达 50 级可以离站。火炬后半与东南木制厕所各需额外折返，缺经验再做。"}, {k="提醒", text="尚差少量经验，在大熔炉东侧外圈 44.76,38.72 打重型作战傀儡，或回北坡 41.21,23.33 打普通黑铁工头。", s={{"尚差少量经验，在大熔炉东侧外圈 44.76,38.72 打重型作战傀儡，或回北坡 41.21,23.33 打普通黑铁工头"}}}}, danger={[1]="工头玛托留斯在熔渣之池一带的黑铁矿洞深处。用队伍逐段清通道，独行可跳过悬赏。"}, grind={[1]={mob="重型作战傀儡", note="大熔炉东缘的普通傀儡，沿高处外圈打，可同步完成击杀任务。任务玩家多时别下熔炉底。"}, [2]={mob="黑铁工头", note="瑟银哨塔南侧的普通黑铁怪，回飞行点前可连打并补任务掉落。营地内可能连拉。"}}, supply={[1]={npc="格瑞沙"}, [2]={npc="大铁匠博恩奈特"}, [3]={npc="大铁匠博恩奈特"}, [4]={npc="大铁匠博恩奈特"}}, steps={[1]={text="从奥格瑞玛飞棘齿城，跨海前到棘齿城码头接安戈洛环形山引导；再坐船到藏宝海湾并飞荒芜之地卡加斯。"}, [2]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", desc="最低 49 级；安戈洛环形山马绍尔营地安戈洛火羽山打，贫瘠之地棘齿城回棘齿城交。"}, [3]={text="由卡加斯向西南沿道路进灼热峡谷，走北侧大道到瑟银哨塔。"}, [4]={nodeA="{a:1446}", desc="向部落飞行管理员格瑞沙开启飞行点。"}, [5]={text="瑟银哨塔接满，绕大熔炉和熔渣之池"}, [6]={npc="通缉/寻物/招领", npcObj=true}, [7]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [8]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [9]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [10]={npc="通缉/寻物/招领", npcObj=true, tag="可选", desc="两个掉落可随击杀顺路收。"}, [11]={npc="通缉/寻物/招领", npcObj=true, tag="可选", desc="玛托留斯是精英，组队才接。"}, [12]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特", tag="可选", desc="可与玛托留斯组队线同趟拿。"}, [13]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [14]={hint="听威拉罗克·温布雷讲述他的故事。"}, [15]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [16]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [17]={hint="汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。"}, [18]={hint="杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。"}, [19]={hint="汉瑟尔·重拳让你杀掉20个重型作战傀儡。"}, [20]={hint="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。", desc="大熔炉周围的傀儡和火元素顺手打。"}, [21]={hint="找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。", tag="可选"}, [22]={hint="汉瑟尔·重拳让你去杀掉20个熏火龙。", desc="进熔渣之池矿坑打熏火龙；与洞内黑铁一起清。"}, [23]={hint="在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。", tag="可选", desc="熔渣之池深处玛托留斯附近的图纸。等安全时再拾取。"}, [24]={hint="那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。", tag="可选"}, [25]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷"}, [26]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="若经验不足、愿意再进一次大熔炉再接。"}, [27]={hint="给威拉罗克·温布雷带去8把瑟银匕首。", tag="可选", desc="熔渣之池的黑铁工头与奴隶贩子可掉。"}, [28]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [29]={text="返回瑟银哨塔，把大熔炉任务一次交完。"}, [30]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [31]={npc="监工斯克兰格", tgt="监工斯克兰格"}, [32]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [33]={npc="汉瑟尔·重拳", tgt="汉瑟尔·重拳"}, [34]={npc="监工斯克兰格", tgt="监工斯克兰格", tag="可选"}, [35]={npc="大铁匠博恩奈特", tgt="大铁匠博恩奈特", tag="可选"}, [36]={npc="侦查队长洛洛尔", tgt="侦查队长洛洛尔", tag="可选"}, [37]={text="少量补等或仍需完成火炬"}, [38]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="完成 铸造火炬杆 才接，去西侧洞窟打暮光怪取拉格纳罗斯符记。"}, [39]={hint="找到一个拉格纳罗斯符记，把它交给威拉罗克·温布雷。", tag="可选", desc="完成 铸造火炬杆 才接，去西侧洞窟打暮光怪取拉格纳罗斯符记。"}, [40]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选", desc="完成 铸造火炬杆 才接，去西侧洞窟打暮光怪取拉格纳罗斯符记。"}, [41]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [42]={hint="等待威拉罗克·温布雷完成惩戒火炬。", tag="可选"}, [43]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [44]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [45]={hint="拿起惩戒火炬。", tag="可选"}, [46]={npc="惩戒火炬", npcObj=true, tag="可选"}, [47]={npc="卡拉然·温布雷", tgt="卡拉然·温布雷", tag="可选"}, [48]={hint="与侍卫玛特拉克谈一谈。", tag="可选"}, [49]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选"}, [50]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选", desc="分别在四座哨塔点火，先把塔上守卫拉开。"}, [51]={hint="使用惩戒火炬点燃北部、南部、东部和西部的哨塔。", tag="可选", desc="分别在四座哨塔点火，先把塔上守卫拉开。"}, [52]={npc="侍卫玛特拉克", tgt="侍卫玛特拉克", tag="可选", desc="分别在四座哨塔点火，先把塔上守卫拉开。"}, [53]={npc="黑龙的财宝", npcObj=true, tag="可选"}, [54]={hint="打开箱子。", tag="可选"}, [55]={npc="黑龙的财宝", npcObj=true, tag="可选"}, [56]={npc="木制厕所", npcObj=true, tag="可选", desc="只有要往东南或尚缺较多经验才绕去木制厕所；先备丝绸 ×15。"}, [57]={hint="杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。", tag="可选", desc="只有要往东南或尚缺较多经验才绕去木制厕所；先备丝绸 ×15。"}, [58]={npc="木制厕所", npcObj=true, tag="可选", desc="只有要往东南或尚缺较多经验才绕去木制厕所；先备丝绸 ×15。"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="尘泥沼泽 75.30, 14.10", pickup="前往悲伤沼泽时，未到 48 级可先开尘泥沼泽 蕨墙村飞行点。前往灼热峡谷前，在奥格瑞玛智慧谷萨尔的大厅向伊崔格接 库卡隆失联（34.28, 39.35），再飞蕨墙村找纳泽尔·血矛。沿东北海岸游往奥卡兹岛，在岛侧军士处依序交 精锐中的精锐、阴差阳错，拿 一个兽人都不能少 再进岛塔地下。留下 大酋长必须知情 至下次奥格瑞玛。", pickupS={{"前往悲伤沼泽时，未到 48 级可先开尘泥沼泽 蕨墙村飞行点"}, {"前往灼热峡谷前，在奥格瑞玛智慧谷萨尔的大厅向伊崔格接 库卡隆失联（34.28, 39.35），再飞蕨墙村找纳泽尔·血矛"}, {"沿东北海岸游往奥卡兹岛，在岛侧军士处依序交 精锐中的精锐、阴差阳错，拿 一个兽人都不能少 再进岛塔地下"}, {"留下 大酋长必须知情 至下次奥格瑞玛"}}, tips={{k="動線", text="入口上层牢房找福尔卡→打典狱长监督者瑞克斯取钥匙→清审问者和海潮主母并收头巾→开下层牢门打『清洁者』卡特莉娜与燃吼→在尾王身后密室查看纸条，再回上层牢房找福尔卡。"}, {k="取捨", text="优先走 库卡隆失联 到 大酋长必须知情 的库卡隆救援链；头巾若一趟未凑满，交件延后。"}, {k="說明", text="部落可避开塞拉摩；由蕨墙村到东北海岸后游泳。军士在岛侧，副本门位于岛塔地下走廊。", s={{"部落可避开塞拉摩"}, {"由蕨墙村到东北海岸后游泳"}, {"军士在岛侧，副本门位于岛塔地下走廊"}}}}, steps={[1]={npc="伊崔格", tgt="伊崔格", desc="48 级起在智慧谷萨尔的大厅找伊崔格。"}, [2]={hint="与蕨墙村的纳泽尔·血矛谈一谈。"}, [3]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛"}, [4]={npc="纳泽尔·血矛", tgt="纳泽尔·血矛", preText="库卡隆失联"}, [5]={hint="搜寻失踪的库卡隆精锐。"}, [6]={npc="乌尔卡中士", tgt="乌尔卡中士"}, [7]={npc="乌尔卡中士", tgt="乌尔卡中士", preText="精锐中的精锐"}, [8]={hint="与乌尔卡军士交谈，了解奥卡兹岛上的严峻局势。"}, [9]={npc="乌尔卡中士", tgt="乌尔卡中士"}, [10]={npc="乌尔卡中士", tgt="乌尔卡中士", preText="阴差阳错"}, [11]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选", desc="顺路先完成奥格瑞玛至岛侧的 库卡隆失联-阴差阳错，再检查军士的任务清单。"}, [12]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选", desc="游戏记录显示可向军士接；开放条件未确认。先走 库卡隆失联-阴差阳错。"}, [13]={text="Alcaz Prison 入口"}, [14]={hint="进入奥卡兹监狱，寻找指挥官福尔卡。", desc="位置：入本沿上层走廊找牢房内的指挥官。", spot="入本沿上层走廊找牢房内的指挥官。"}, [15]={npc="Commander Folkar", tag="需游戏内实测", spot="上层走廊的牢房，指挥官 Folkar"}, [16]={npc="Commander Folkar", tag="需游戏内实测", preText="一个兽人都不能少"}, [17]={hint="进入奥卡兹监狱，消灭15名斯塔莎兹士兵与8名斯塔莎兹女巫，并将海潮主母卡扎斯的徽记带给乌尔卡中士。", tag="可选", desc="位置：上层近牢房找海潮主母，沿走廊清纳迦。", spot="上层近牢房找海潮主母，沿走廊清纳迦。"}, [18]={hint="进入奥卡兹监狱，从人类守卫的尸体上收集8条血红头巾。", tag="可选", desc="可能要多刷一趟，出本前核对数量。位置：上层监牢走廊先打人类守卫，沿途补齐。", spot="上层监牢走廊先打人类守卫，沿途补齐。"}, [19]={hint="深入奥卡兹监狱，寻找国王瓦里安·乌瑞恩的下落。", desc="位置：开下层门打尾王，进后方密室找地板纸条。顺序：先从典狱长拿钥匙。", spot="开下层门打尾王，进后方密室找地板纸条。"}, [20]={npc="任务物件", npcObj=true, tag="需游戏内实测", spot="尾王后方密室的地板纸条"}, [21]={npc="任务物件", npcObj=true, tag="需游戏内实测", preText="库卡隆的荣耀"}, [22]={hint="向指挥官福尔卡复命。", desc="位置：从尾王密室折返上层，回原牢房交指挥官。顺序：先读第 18 步纸条。", spot="从尾王密室折返上层，回原牢房交指挥官。"}, [23]={npc="Commander Folkar", tag="需游戏内实测", spot="上层走廊的牢房，指挥官 Folkar"}, [24]={npc="Commander Folkar", tag="需游戏内实测", preText="给福尔卡的坏消息"}, [25]={npc="乌尔卡中士", tgt="乌尔卡中士", tag="可选"}, [26]={hint="前往奥格瑞玛，将瓦里安·乌瑞恩的死讯呈报给萨尔。"}, [27]={npc="萨尔", tgt="萨尔"}, [28]={npc="伊崔格", tgt="伊崔格", tag="可选"}}},
    ["04-35"] = {name="辛特兰", nameA="辛特兰 {a:3317}／{a:354}", shortA="辛特兰 {a:3317} +", tips={{k="取捨", text="值得做：威士忌斯利姆的酒 和海龟任务在同一段海滩完成；枭兽 野蛮的枭兽 与 测试容器 同打。"}, {k="取捨", text="可跳过：职位空缺：恶齿村卫兵队长 要打 80 只精英，没有现成队伍便略过。辛萨罗难以单刷时，先做沿岸与内陆任务。"}, {k="取捨", text="先别交：威士忌斯利姆的酒 到藏宝海湾交；测试容器 到莫沙彻营地交；斯普琳科的秘密佐料、远古之卵 留塔纳利斯 加基森与破碎石柱。"}, {k="提醒", text="未到 52 级可在辛特兰沿岸补海龟、枭兽，或与队伍清辛萨罗。", s={{"未到 52 级可在辛特兰沿岸补海龟、枭兽，或与队伍清辛萨罗"}}}}, danger={[1]="辛萨罗上层有成群邪枝精英与治疗怪。组队沿阶梯逐层清，未组队留在海岸。", [2]="加莫里塔是沿岸巡逻的精英海龟。补普通海龟时留意它，没有队伍就让开。"}, grind={[1]={mob="海水钳嘴龟", note="恶齿村北侧海滩的普通龟，可沿岸直线轮打和剥皮。和采龟肉的玩家共用，无需闯辛萨罗精英区。"}}, supply={[1]={npc="格卡斯"}, [2]={npc="拉尔德"}, [3]={npc="铁匠斯拉提"}, [4]={npc="拉尔德"}, [5]={npc="雷艾"}, [6]={npc="秘法师雅尔金"}}, steps={[1]={text="从灼热峡谷飞恶齿村。未开点先飞塔伦米尔，从敦霍尔德城堡北侧山口进辛特兰，沿大道往东，下海岸往南到恶齿村。", tag="还没开这个飞行点，第一次要用跑的"}, [2]={nodeA="{a:3317}", desc="向格卡斯开启飞行点。"}, [3]={text="任务期间可绑恶齿村炉石。"}, [4]={text="恶齿村接任务 → 海岸"}, [5]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [6]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [7]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [8]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [9]={npc="拉尔德", tgt="拉尔德"}, [10]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [11]={npc="断齿族长", tgt="断齿族长"}, [12]={npc="断齿族长", tgt="断齿族长"}, [13]={npc="猎户马克霍尔", tgt="猎户马克霍尔", tag="可选", desc="路上看到稀有的刀喙狮鹫才做。"}, [14]={npc="铁匠斯拉提", tgt="铁匠斯拉提", tag="可选", desc="需要绕到东北神庙。"}, [15]={npc="作战公告！", npcObj=true, tag="可选", desc="辛萨罗高处精英。已有队伍时接。"}, [16]={npc="作战公告！", npcObj=true, tag="可选", desc="共 80 只精英，打算在辛萨罗多刷才接。", star={"卫兵队长符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [17]={hint="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉15只海水钳嘴龟。完成任务之后回到他那里去复命。"}, [18]={hint="辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。", desc="与 钳嘴龟！、威士忌斯利姆的酒 同线；看到再打。"}, [19]={hint="藏宝海湾的威士忌斯利姆想要你帮他找回弄丢的紫葡萄酒。", desc="悲伤沼泽斯通纳德与东风海岸先接。从村外往北沿沙滩找瓶子。"}, [20]={hint="辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。"}, [21]={hint="解开这道迷题！", tag="可选", desc="限已交 科泰罗的谜题 并持有 科泰罗的谜题；科泰罗的谜题 在尘泥沼泽木桥下的发霉的卷轴交。"}, [22]={npc="科泰罗的宝藏", npcObj=true, tag="可选", desc="未持有 科泰罗的谜题 略过。"}, [23]={text="内陆枭兽与银鬃狼 → 辛萨罗祭坛"}, [24]={hint="辛特兰恶齿村的猎户马克霍尔要求你去杀掉15头银鬃捕猎者和15头银鬃嗥狼。完成任务之后就回到他那里复命。"}, [25]={hint="辛特兰恶齿村的猎户马克霍尔要求你去杀掉20头野蛮的枭兽。完成任务之后就回到他那里复命。"}, [26]={hint="到辛特兰去杀掉10头枭兽，然后使用灵魂精华容器捕获它们的灵魂。", desc="菲拉斯莫沙彻营地与怒痕堡接，留到菲拉斯交。"}, [27]={hint="辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。", tag="可选", desc="有遇到再打。"}, [28]={hint="辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。", tag="可选"}, [29]={hint="加基森的斯普琳科要你去给她找到一颗紫色水生菇。", desc="塔纳利斯加基森与砂槌营地先接，留到加基森交。"}, [30]={hint="辛特兰恶齿村的断齿族长要你在辛萨罗找到10瓶腐化之血。任务完成之后就回到断齿族长那里。", desc="与断齿长者任务同走，注意阶梯巡逻。"}, [31]={hint="辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的头颅和猎户莫克霍尔的骨头交给猎户马克霍尔。", desc="目标分两处，两件都拿。"}, [32]={hint="辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。"}, [33]={npc="断齿长者", tgt="断齿长者"}, [34]={npc="断齿长者", tgt="断齿长者"}, [35]={hint="辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。"}, [36]={npc="断齿长者", tgt="断齿长者"}, [37]={npc="断齿长者", tgt="断齿长者"}, [38]={hint="将远古之卵交给塔纳利斯的叶基亚。", tag="可选", desc="塔纳利斯加基森与砂槌营地已接才做；塔纳利斯加基森与破碎石柱热砂港交。"}, [39]={hint="你必须杀掉邪恶祭司海克斯和20名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。", tag="可选"}, [40]={hint="你必须消灭20个邪枝狂战士、20个邪枝暗影猎手、20个邪枝饮血者和20个邪枝噬魂者。", tag="可选"}, [41]={text="若炉石已绑恶齿村，回城一次交完。"}, [42]={hint="辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。"}, [43]={npc="断齿族长", tgt="断齿族长"}, [44]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [45]={npc="断齿族长", tgt="断齿族长"}, [46]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [47]={npc="钓鱼者卡图姆", tgt="钓鱼者卡图姆"}, [48]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [49]={npc="猎户马克霍尔", tgt="猎户马克霍尔"}, [50]={npc="拉尔德", tgt="拉尔德"}, [51]={npc="猎户马克霍尔", tgt="猎户马克霍尔", tag="可选"}, [52]={npc="铁匠斯拉提", tgt="铁匠斯拉提", tag="可选"}, [53]={npc="断齿族长", tgt="断齿族长", tag="可选"}, [54]={npc="断齿族长", tgt="断齿族长", tag="可选", star={"卫兵队长符文", {"PALADIN", "WARRIOR", "ROGUE", "HUNTER"}}}, [55]={npc="克里斯托弗·沃克", tgt="克里斯托弗·沃克", tag="可选", desc="幽暗城战士训练师克里斯托弗·沃克；诅咒之地血法师营地往诅咒之地时交。可在前往辛特兰前接。"}, [56]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="由塔伦米尔沿河往北到巴斯拉，四样可先在拍卖行备妥；已接训练师版 元素掌握 就用同一批材料交 元素掌握。"}, [57]={hint="将土元素、空气元素、火元素和水元素交给捕风者巴斯拉。", tag="可选", desc="由塔伦米尔沿河往北到巴斯拉，四样可先在拍卖行备妥；已接训练师版 元素掌握 就用同一批材料交 元素掌握。"}, [58]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="由塔伦米尔沿河往北到巴斯拉，四样可先在拍卖行备妥；已接训练师版 元素掌握 就用同一批材料交 元素掌握。"}, [59]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="元素掌握 或 控制元素 二选一完成；留到西瘟疫打材料。"}, [60]={npc="迈尔斯·迪克斯特", tgt="迈尔斯·迪克斯特", tag="可选", desc="幽暗城盗贼区先接；可在辛特兰恶齿村与辛萨罗初访辛特兰的转场顺路。"}, [61]={hint="前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。", tag="可选", desc="幽暗城盗贼区先接；可在辛特兰恶齿村与辛萨罗初访辛特兰的转场顺路。"}, [62]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="幽暗城盗贼区先接；可在辛特兰恶齿村与辛萨罗初访辛特兰的转场顺路。"}, [63]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="从拉文霍德庄园接，留艾萨拉。"}}},
    ["04-36"] = {name="诅咒之地", tips={{k="取捨", text="值得做：五个采集一起打。全交共需下颚 ×5、野猪肺 ×6、蝎螯 ×6、蜥蜴脑 ×11、秃鹫砂囊 ×14。每次交任务会扣材料。"}, {k="取捨", text="可跳过：先交掉落较快的任务。秃鹫或蜥蜴竞争激烈时，留下未完成的 石化蜥蜴的大脑 或 秃鹫的活力，继续荆棘谷 藏宝海湾。"}, {k="提醒", text="想补经验可留在北部 46-53, 15-27 沿山坡打野兽。南面有较高等级的敌人。", s={{"想补经验可留在北部 46-53, 15-27 沿山坡打野兽"}, {"南面有较高等级的敌人"}}}}, danger={[1]="血法师营地以南的怪群等级比北坡高。只做北部收集时留在山坡外圈。"}, grind={[1]={mob="厚甲毒刺蝎", note="血法师营地东侧有一整片普通蝎，顺收蝎钳并可剥皮。怪多时由路边往外打，避开精英巡逻。"}}, supply={[1]={npc="布雷依克"}, [2]={npc="旅店老板卡拉库尔"}, [3]={npc="卡尔拉什"}, [4]={npc="索尔塔什"}, [5]={npc="苏塔佐尔"}}, steps={[1]={text="从恶齿村飞悲伤沼泽斯通纳德，沿南方道路进诅咒之地。到北部两名血法师（50.55, 14.20／50.64, 14.30）。"}, [2]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [3]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [4]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [5]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [6]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [7]={hint="收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}, [8]={hint="收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}, [9]={hint="收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}, [10]={hint="收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}, [11]={hint="收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。"}, [12]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [13]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [14]={npc="血法师德拉吉亚", tgt="血法师德拉吉亚"}, [15]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [16]={npc="血法师莱诺雷", tgt="血法师莱诺雷"}, [17]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="没掉就略过。"}, [18]={hint="在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。", tag="可选", desc="没掉就略过。"}, [19]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="没掉就略过。"}, [20]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="没掉就略过。"}, [21]={hint="将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。", tag="可选", desc="没掉就略过。"}, [22]={npc="收藏家库米沙", tgt="收藏家库米沙", tag="可选", desc="没掉就略过。"}, [23]={hint="到诅咒之地的入口去，与部落英雄的灵魂谈一谈。", tag="可选"}, [24]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选"}, [25]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="与血法师的野猪肺任务顺路；可提前在北部同打。"}, [26]={hint="杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。", tag="可选", desc="与血法师的野猪肺任务顺路；可提前在北部同打。"}, [27]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="与血法师的野猪肺任务顺路；可提前在北部同打。"}, [28]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="敌人密集，靠营地外圈单拉。"}, [29]={hint="杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。", tag="可选", desc="敌人密集，靠营地外圈单拉。"}, [30]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="敌人密集，靠营地外圈单拉。"}, [31]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="已能组队时可在同一趟做完；也可留东瘟疫之地圣光之愿礼拜堂东部王国转场。", star={"钻石水瓶", {"WARRIOR"}}}, [32]={text="沿原路回斯通纳德，飞藏宝海湾。"}}},
    ["04-37"] = {name="荆棘谷（回访）", nameA="荆棘谷 {a:35}（回访）", tips={{k="取捨", text="值得做：本趟优先交 50 级的 威士忌斯利姆的酒。荆棘谷 格罗姆高与藏宝海湾、荆棘谷 藏宝海湾的低等任务已分次处理；仍在日志而且已完成的，也可在同一趟港口回交。"}, {k="取捨", text="可跳过：若没有辛特兰的酒或待交任务，这站只搭船转场。船长的箱子 与荆棘谷热疫 要出城再回，缺经验或有队伍时再做。"}, {k="提醒", text="藏宝海湾为中立港口，从客船前往棘齿城，避免误上其他渡船。", s={{"藏宝海湾为中立港口，从客船前往棘齿城，避免误上其他渡船"}}}}, grind={[1]={mob="血精灵搜寻者", note="藏宝海湾这一站以交件和搭船为主。缺 53 级可沿原路到下一站艾萨拉再打普通血精灵，任务点易撞队，可在营地外圈补。"}}, supply={[1]={npc="格林戈"}, [2]={npc="旅店老板斯金德"}, [3]={npc="祖塔克"}, [4]={npc="尼克拉克斯·菲拉莫格"}, [5]={npc="哈伦·坎麦尔"}}, steps={[1]={npc="威士忌斯利姆", tgt="威士忌斯利姆", desc="悲伤沼泽斯通纳德与东风海岸接、辛特兰恶齿村与辛萨罗在辛特兰捡酒。"}, [2]={npc="海克拜瑞·斯莫特船长", tgt="海克拜瑞·斯莫特船长", tag="可选", desc="47 级任务，想补经验且未做才接。"}, [3]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选", desc="连打数波猩猩，建议有队伍再接。"}, [4]={hint="将斯莫特的箱子交给藏宝海湾的海克拜瑞·斯莫特。", tag="可选"}, [5]={npc="巫医安巴格瓦", tgt="巫医安巴格瓦", tag="可选", desc="先接 荆棘谷热疫，再完成这个交牙事件。"}, [6]={hint="掉落自：迷雾谷猩猩、丛林大猩猩、暴怒的银背猩猩", tag="可选", desc="先接 荆棘谷热疫，再完成这个交牙事件。"}, [7]={npc="巫医安巴格瓦", tgt="巫医安巴格瓦", tag="可选", desc="先接 荆棘谷热疫，再完成这个交牙事件。"}, [8]={hint="找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。", tag="可选", desc="由 荆棘谷热疫 的交牙事件召出。"}, [9]={npc="海克拜瑞·斯莫特船长", tgt="海克拜瑞·斯莫特船长", tag="可选"}, [10]={npc="芬·菲兹拉克", tgt="芬·菲兹拉克", tag="可选"}, [11]={text="从藏宝海湾搭船到棘齿城，再飞奥格瑞玛。前往艾萨拉瓦罗莫克前，可在奥格瑞玛找贝尔戈洛姆接 叛徒。"}}},
    ["04-38"] = {name="艾萨拉 阿克科兰神殿", nameA="艾萨拉 {a:1237}／阿克科兰神殿", shortA="艾萨拉 {a:1237} +", tips={{k="取捨", text="值得做：萨拉斯营地、三枚印记和雷姆托里放在一趟；埃达拉斯废墟同步拾四块石板与纳迦符石。"}, {k="取捨", text="可跳过：视频跳过两个组队任务。永恒版可确认为精英的候选有 Ley of the Land与 Deadliest Catch，本站两个都略过。"}, {k="取捨", text="之后顺路：安德隆·甘特的石版 交幽暗城的安德隆·甘特（54.81, 76.33），可留东瘟疫之地 圣光之愿礼拜堂转场。城市寄回任务要重返艾萨拉，本路线可省掉。"}, {k="提醒", text="未满 53 级时可补埃达拉斯废墟纳迦或萨拉斯营地血精灵，打怪时顺手找任务掉落。", s={{"未满 53 级时可补埃达拉斯废墟纳迦或萨拉斯营地血精灵，打怪时顺手找任务掉落"}}}}, danger={[1]="埃达拉斯废墟内侧的纳迦法系怪密集。捡石板时沿外墙进出，打断后把怪拖出房间。"}, grind={[1]={mob="血精灵搜寻者", note="萨拉斯营地普通血精灵等级正合适，顺收血精灵任务掉落。营地内可能连拉法系，从外缘打。"}, [2]={mob="恶鞭侍从", note="埃达拉斯废墟的普通纳迦，路过可顺收纳迦任务。贴废墟外墙单拉，避开内侧密集法系。"}}, supply={[1]={npc="克隆姆"}, [2]={npc="格鲁尔·黑刃"}, [3]={npc="库尔"}, [4]={npc="旅店老板格雷什卡"}, [5]={npc="卡加"}, [6]={npc="霍苏斯"}}, steps={[1]={npc="贝尔戈洛姆·石槌", tgt="贝尔戈洛姆·石槌", desc="奥格瑞玛荣誉谷接。新版背叛线的引导。"}, [2]={npc="杰斯雷蒙", tgt="杰斯雷蒙", tag="可选", desc="可选；先接，留待安戈洛环形山马绍尔营地安戈洛打暴掠龙。"}, [3]={text="已有艾萨拉飞行点，从奥格瑞玛飞瓦罗莫克。初访从灰谷碎木岗哨往东，先到罗哈图，再走瓦罗莫克。", tag="还没开这个飞行点，第一次要用跑的"}, [4]={text="西面罗哈图 → 瓦罗莫克接齐"}, [5]={npc="罗哈图", tgt="罗哈图"}, [6]={npc="罗哈图", tgt="罗哈图"}, [7]={hint="杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。"}, [8]={hint="杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。"}, [9]={npc="罗哈图", tgt="罗哈图"}, [10]={npc="罗哈图", tgt="罗哈图"}, [11]={nodeA="{a:1237}", desc="向克隆姆开启飞行点。"}, [12]={hint="把这封给阿格图的密信交给艾萨拉的阿格图·血拳。"}, [13]={npc="阿格图·血拳", tgt="阿格图·血拳"}, [14]={npc="阿格图·血拳", tgt="阿格图·血拳"}, [15]={npc="杰迪加", tgt="杰迪加"}, [16]={text="萨拉斯营地 → 神殿与埃达拉斯废墟 → 瓦罗莫克"}, [17]={npc="基姆加尔", tgt="基姆加尔"}, [18]={hint="搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。"}, [19]={npc="基姆加尔", tgt="基姆加尔"}, [20]={npc="基姆加尔", tgt="基姆加尔"}, [21]={hint="杀死10个血精灵搜寻者和10个血精灵勘测员，并找到大法师雷姆托里的营地。一旦你发现了营地，就去找到某个对她极为重要的东西，以用于激怒她，让她与你战斗。", desc="数量以任务日志为准。"}, [22]={npc="卡多雷召唤宝典", npcObj=true, tag="需游戏内实测"}, [23]={npc="Sin'dorei Tome of Summoning", tgt="Sin'dorei Tome of Summoning", tag="需游戏内实测", desc="永恒版背叛线。三种各一，先完成 叛徒。"}, [24]={hint="掉落自：Lieutenant Suncrest、玛济斯·鹰盔、Ranger Lydrea", tag="目标：光冠中尉 / 玛济斯·鹰盔 / 游侠莉德里亚 / Sky