    ["04-39"] = {name="菲拉斯（回访）", nameA="菲拉斯 {a:1099}（回访）", tips={{k="取捨", text="值得做：测试容器 在莫沙彻营地交，接续 角鹰兽灵魂精华-山岭巨人灵魂精华；每个阶段都要先交，下一种容器才拿得到。"}, {k="取捨", text="可跳过：天然材料 材料缺太多就跳；北泉支线与较远的西部巨人同一趟，有时间再做。"}, {k="提醒", text="若差少量经验可在 69.45, 44.95 打精灵龙，或去西北鹰身人营地。", s={{"若差少量经验可在 69.45, 44.95 打精灵龙，或去西北鹰身人营地"}}}}, grind={[1]={mob="北泉杀戮者", note="北泉鹰身人营地外围的普通怪，若正在做北泉任务可顺收掉落。单为经验不必从营地折返，留到下站。"}, [2]={mob="格罗多克大猩猩", note="若鹰身人点被占，可改打东南侧普通猩猩；空地好退，沿外侧避开多只连拉。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="使用初访已开的莫沙彻营地飞行点。若由这一站开始且未开点，可先飞千针石林乱风岗，沿谷底大路向西进菲拉斯，再找夏恩开点。"}, [2]={npc="巫医尤克里", tgt="巫医尤克里", desc="菲拉斯莫沙彻营地与怒痕堡接，辛特兰用容器收枭兽灵魂。"}, [3]={npc="巫医尤克里", tgt="巫医尤克里", desc="完成再回巫医接下一种。"}, [4]={hint="杀掉10只任意种类的乱羽角鹰兽，然后用灵魂精华容器捕获它们的灵魂。", desc="完成再回巫医接下一种。"}, [5]={npc="巫医尤克里", tgt="巫医尤克里", desc="完成再回巫医接下一种。"}, [6]={npc="巫医尤克里", tgt="巫医尤克里"}, [7]={hint="杀掉8只精龙或小精龙，然后用灵魂精华容器捕获它们的灵魂。"}, [8]={npc="巫医尤克里", tgt="巫医尤克里"}, [9]={npc="巫医尤克里", tgt="巫医尤克里"}, [10]={hint="杀掉3个森林漫游者，然后用灵魂精华容器捕获它们的灵魂。"}, [11]={npc="巫医尤克里", tgt="巫医尤克里"}, [12]={npc="巫医尤克里", tgt="巫医尤克里"}, [13]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选", desc="要到北泉鹰身人区且有能力打精英时接。"}, [14]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [15]={hint="杀掉7个大地行者或者峭壁巨人，然后用灵魂精华容器捕获它们的灵魂。"}, [16]={hint="塔罗·刺蹄让你杀掉4个北泉鹰身人、4个北泉游荡者、4个北泉唤风者和4个北泉杀戮者。", tag="可选"}, [17]={hint="莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。", tag="可选", desc="召唤点在北泉祭坛。"}, [18]={hint="为莫沙彻营地的巫医尤克里收集2根断裂的原木、6颗包壳矿石、20片有弹性的肌腱和40块金属碎片。", tag="可选", desc="菲拉斯莫沙彻营地与怒痕堡先接。前三轮顺路收，差太多不必回头刷。"}, [19]={npc="巫医尤克里", tgt="巫医尤克里"}, [20]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选"}, [21]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [22]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="可选"}, [23]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="完成 山岭巨人灵魂精华、天然材料 后接。"}, [24]={hint="巫医尤克里希望你在他准备武器的时候稍等一会儿。", tag="可选", desc="完成 山岭巨人灵魂精华、天然材料 后接。"}, [25]={npc="巫医尤克里", tgt="巫医尤克里", tag="可选", desc="完成 山岭巨人灵魂精华、天然材料 后接。"}, [26]={text="从莫沙彻营地飞塔纳利斯加基森。"}}},
    ["04-40"] = {name="塔纳利斯", nameA="塔纳利斯 {a:976}／{a:1938}", shortA="塔纳利斯 {a:976} +", tips={{k="取捨", text="值得做：加基森先把 斯普琳科的秘密佐料→诺格弗格药剂 三段交完，接安戈洛任务后再去破碎石柱。"}, {k="取捨", text="可跳过： 要折返棘齿城；此站可只做 沉没的神庙 和 加兹瑞迪安。若为副本链而接 ，可在贫瘠之地 棘齿城取石环后另约一趟回交。"}, {k="取捨", text="之后顺路：极度粘稠的沥青 和有前置的 擒虫先擒王 都在安戈洛环形山 马绍尔营地做。尤卡·斯库比格特 在燃烧平原 烈焰峰与黑石山交。"}, {k="提醒", text="还差经验可在断柱附近解 加兹瑞迪安 并打砂槌食人魔；塔纳利斯也可组队打祖尔法拉克。", s={{"还差经验可在断柱附近解 加兹瑞迪安 并打砂槌食人魔"}, {"塔纳利斯也可组队打祖尔法拉克"}}}}, grind={[1]={mob="哈扎里群居蝎", note="哈札里巢外的普通蝎，等级较接近本段，密度足。留在地表，洞口附近容易连拉。"}, [2]={mob="晶鳞石化蜥蜴", note="去断柱或安戈洛前，沿南路打普通蜥蜴。刷新分散，较不会被砂槌营地任务队分走。"}}, supply={[1]={npc="布科雷克·怒拳"}, [2]={npc="旅店老板菲兹格瑞博"}, [3]={npc="乌林克·古德斯迪尔"}, [4]={npc="旅店老板菲兹格瑞博"}, [5]={npc="布雷兹里克·巴克舒特"}}, steps={[1]={npc="斯普琳科", tgt="斯普琳科", desc="塔纳利斯加基森与砂槌营地接，辛特兰恶齿村与辛萨罗采菇。回加基森后先交。"}, [2]={npc="斯普琳科", tgt="斯普琳科", desc="先上交斯普琳科的秘密佐料。"}, [3]={hint="斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。", desc="先上交斯普琳科的秘密佐料。"}, [4]={npc="马林·诺格弗格", tgt="马林·诺格弗格", desc="先上交斯普琳科的秘密佐料。"}, [5]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [6]={hint="马林·诺格弗格让你在他制成药剂之后再去找他。"}, [7]={npc="马林·诺格弗格", tgt="马林·诺格弗格"}, [8]={hint="与加基森的炼金师匹斯特苏格谈一谈。", tag="可选", desc="在艾萨拉瓦罗莫克离开奥格瑞玛前，若已完成 32 或 祖卡什报告，从基尔兹宾接。"}, [9]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [10]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选", desc="先交部落的 异种蝎的远征 才接。留给安戈洛环形山马绍尔营地安戈洛。"}, [11]={npc="特兰雷克", tgt="特兰雷克", desc="在安戈洛环形山（马绍尔营地一带）打焦油怪。"}, [12]={text="若有远古之卵，先往东去热砂港交。其余玩家可直接南下破碎石柱。"}, [13]={npc="叶基亚", tgt="叶基亚", tag="可选", desc="塔纳利斯加基森与砂槌营地接，辛萨罗拾卵。叶基亚在热砂港。"}, [14]={npc="尤尔巴·斯库比格特", tgt="尤尔巴·斯库比格特", tag="可选", desc="热砂港顺手接；烈焰峰交，适合会打黑石深渊的玩家。"}, [15]={hint="到塔纳利斯找到玛尔冯·瑞文斯克。", desc="菲拉斯莫沙彻营地与怒痕堡在莫沙彻营地先接。"}, [16]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [17]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [18]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选", desc="先交 。石环在棘齿城，想打沉没的神庙或解任务再接。"}, [19]={hint="塔纳利斯的玛尔冯·瑞文斯克要你收集30件加兹瑞迪安饰物。", desc="破碎石柱周围先找，沿外圈扫。"}, [20]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [21]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。", tag="可选", desc="之后有多次棘齿城路线，也可等贫瘠之地棘齿城顺手拿。"}, [22]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选"}, [23]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", tag="可选", desc="只在打沉没的神庙时接。"}, [24]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="进安戈洛东南入口时找托尔瓦·寻路者，下一站沿途采集。"}, [25]={text="从破碎石柱往南沿塔纳利斯道路，再转西进安戈洛环形山。"}}},
    ["05-d23"] = {name="阿塔哈卡神庙", entrance="悲伤沼泽 69.50, 52.50（神庙建筑外部路标）", pickup="到悲伤沼泽 斯通纳德完成 1424 并保留 阿塔莱流放者；从辛特兰 恶齿村飞行点走到辛特兰南侧流放者交 阿塔莱流放者、接 1444 与 1446，若完成祖尔法拉克石板链再去辛萨罗拿卵。菲拉斯先接 沉没的神庙；塔纳利斯 加基森与砂槌营地先到玛尔冯开石环任务，飞棘齿城取物，再回玛尔冯接两个神庙任务。在塔纳利斯 热砂港交卵后，可从加基森飞棘齿城，再搭船到藏宝海湾，飞斯通纳德交 1444、接 1445 并赴神庙。", pickupS={{"到悲伤沼泽 斯通纳德完成 1424 并保留 阿塔莱流放者"}, {"从辛特兰 恶齿村飞行点走到辛特兰南侧流放者交 阿塔莱流放者、接 1444 与 1446，若完成祖尔法拉克石板链再去辛萨罗拿卵"}, {"菲拉斯先接 沉没的神庙"}, {"塔纳利斯 加基森与砂槌营地先到玛尔冯开石环任务，飞棘齿城取物，再回玛尔冯接两个神庙任务"}, {"在塔纳利斯 热砂港交卵后，可从加基森飞棘齿城，再搭船到藏宝海湾，飞斯通纳德交 1444、接 1445 并赴神庙"}}, tips={{k="動線", text="入口右侧平路→下层环廊查祭坛并点雕像→阿塔拉利恩→上层六座阳台清守卫→献祭之穴东廊打迦玛兰→西廊可选召哈卡→四龙兽→伊兰尼库斯与精华之泉。沿途打阿塔莱巨魔收神像。"}, {k="取捨", text="斯通纳德与辛特兰本地链优先；摩沙鲁链适合已刷祖尔法拉克并到辛萨罗的人；石环在塔纳利斯 加基森与砂槌营地安排棘齿城一趟。"}, {k="說明", text="坐标指向泪水之池建筑外。沿南侧阶梯进神庙，经面具之厅及仪式之厅到骸骨之厅中层的副本门。", s={{"坐标指向泪水之池建筑外"}, {"沿南侧阶梯进神庙，经面具之厅及仪式之厅到骸骨之厅中层的副本门"}}}}, steps={[1]={npc="费泽鲁尔", tgt="费泽鲁尔", desc="若已在主路线完成，直接从 阿塔莱流放者 继续。"}, [2]={hint="斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。"}, [3]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [4]={npc="费泽鲁尔", tgt="费泽鲁尔", preText="泪水之池"}, [5]={hint="将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。"}, [6]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [7]={npc="阿塔莱流放者", tgt="阿塔莱流放者", preText="阿塔莱流放者"}, [8]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [9]={hint="向斯通纳德的费泽鲁尔回报。"}, [10]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [11]={npc="费泽鲁尔", tgt="费泽鲁尔", preText="向费泽鲁尔复命"}, [12]={npc="巫医尤克里", tgt="巫医尤克里"}, [13]={hint="到塔纳利斯找到玛尔冯·瑞文斯克。"}, [14]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [15]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="沉没的神庙"}, [16]={hint="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。"}, [17]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克"}, [18]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [19]={npc="玛尔冯·瑞文斯克", tgt="玛尔冯·瑞文斯克", preText="石环"}, [20]={npc="叶基亚", tgt="叶基亚", desc="先在热砂港接，再跑菲拉斯；回热砂港交后立即接 摩沙鲁的预言。"}, [21]={hint="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}, [22]={npc="叶基亚", tgt="叶基亚"}, [23]={npc="叶基亚", tgt="叶基亚", preText="尖啸者的灵魂"}, [24]={hint="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。", desc="为神庙任务 神灵哈卡 留下后续 远古之卵。"}, [25]={npc="叶基亚", tgt="叶基亚"}, [26]={npc="叶基亚", tgt="叶基亚", desc="辛萨罗有成群精英；主路线辛特兰 恶齿村与辛萨罗同步做。", preText="摩沙鲁的预言"}, [27]={hint="将远古之卵交给塔纳利斯的叶基亚。"}, [28]={npc="叶基亚", tgt="叶基亚"}, [29]={npc="叶基亚", tgt="叶基亚", preText="远古之卵"}, [30]={text="阿塔哈卡神庙 入口"}, [31]={hint="在悲伤沼泽沉没的神庙中找到哈卡祭坛。", desc="位置：进门走右侧平路下层，在环廊找哈卡祭坛。顺序：先交祭坛再接第 32 步。", spot="进门走右侧平路下层，在环廊找哈卡祭坛。"}, [32]={npc="哈卡祭坛", npcObj=true, tag="需游戏内实测", spot="环廊下层的哈卡祭坛"}, [33]={hint="到沉没的神庙去，揭开雕像群中隐藏的秘密。", desc="顺序有误会触发陷阱。位置：在下层环廊依序点六像，再到中央打王。顺序：南→北→西南→东南→西北→东北。", spot="在下层环廊依序点六像，再到中央打王。"}, [34]={npc="哈卡神像", npcObj=true, tag="需游戏内实测", spot="下层中央的哈卡塑像"}, [35]={hint="收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。", desc="位置：下层环廊及上层阳台沿途打阿塔莱巨魔。", spot="下层环廊及上层阳台沿途打阿塔莱巨魔。"}, [36]={hint="辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。", desc="位置：清上层六阳台，回献祭之穴走东廊找迦玛兰。顺序：先杀六名阳台守卫解除屏障。", spot="清上层六阳台，回献祭之穴走东廊找迦玛兰。"}, [37]={hint="将装满的哈卡之卵交给塔纳利斯的叶基亚。", desc="先全队进房再开事件；从西侧通道去哈卡房。位置：从献祭之穴走西廊进哈卡房，集合后用卵。顺序：西廊通哈卡，东廊通迦玛兰。", spot="从献祭之穴走西廊进哈卡房，集合后用卵。"}, [38]={npc="伊兰尼库斯精华", npcObj=true, tag="需游戏内实测", desc="击杀伊兰尼库斯之影后，右键其掉落物接受。"}, [39]={hint="把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。", desc="位置：打过四条龙兽首领，进梦者房尾王旁点泉。顺序：尾王掉精华，接后在同房交。", spot="打过四条龙兽首领，进梦者房尾王旁点泉。"}, [40]={npc="精华之泉", npcObj=true, tag="需游戏内实测", spot="伊兰尼库斯房，尾王旁的精华之泉"}, [41]={npc="费泽鲁尔", tgt="费泽鲁尔"}, [42]={npc="阿塔莱流放者", tgt="阿塔莱流放者"}, [43]={npc="叶基亚", tgt="叶基亚"}}},
    ["04-41"] = {name="安戈洛环形山", nameA="安戈洛环形山 {a:541}", tips={{k="取捨", text="值得做：能量水晶、恐龙材料、焦油和血瓣花一路并行。走近中部前留意巡逻魔暴龙。"}, {k="取捨", text="先别交：无人知晓的秘密 留冬泉谷；火山的活动、玛尔冯的车间 留棘齿城。拉克维的诱饵、三座水晶塔、猩猩、火羽山救援与究根问底留安戈洛环形山 马绍尔营地。"}, {k="取捨", text="之后顺路：骨刃武器 若已打齐爪子，下次经奥格瑞玛找杰斯雷蒙（55.52, 34.08）交。捕捉皇后 需在南边孵化并打王，可跳过。"}, {k="提醒", text="若差一点到 54 级，可在北部焦油怪（51.77, 25.14）或马绍尔营地东边双帆龙（50.78, 19.90）补经验。", s={{"若差一点到 54 级，可在北部焦油怪（51.77, 25.14）或马绍尔营地东边双帆龙（50.78, 19.90）补经验"}}}}, danger={[1]="安戈洛平原有 54-55 级精英魔暴龙巡逻。北上营地走东缘，看到它先让路。"}, grind={[1]={mob="焦油潜伏者", note="营地南侧的普通焦油怪，可顺收黏稠焦油。刷新靠水边，沿岸单拉并留意魔暴龙巡逻。"}, [2]={mob="安戈洛大猩猩", note="东北猩猩洞口的普通猩猩。与猩猩任务重叠，洞内易连拉，外圈有人就回焦油池。"}}, supply={[1]={npc="格莱菲"}, [2]={npc="吉波尔特"}, [3]={npc="奈尔加"}, [4]={npc="奈尔加"}}, steps={[1]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [2]={hint="找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。"}, [3]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [4]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [5]={hint="将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。"}, [6]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [7]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", desc="留给安戈洛环形山马绍尔营地安戈洛回访。"}, [8]={hint="将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。", tag="可选", desc="艾萨拉瓦罗莫克奥格瑞玛先接才做。"}, [9]={npc="破碎的木筏", npcObj=true}, [10]={hint="在池塘附近查找与搁浅的小艇有关的线索。"}, [11]={npc="小背包", npcObj=true}, [12]={npc="小背包", npcObj=true}, [13]={hint="查看袋子里的东西，然后将它们交给物主。", desc="包内物品保留。"}, [14]={text="沿东侧地带北上马绍尔营地，避开中部魔暴龙。"}, [15]={nodeA="{a:541}", desc="向葛莱夫开启飞行点。"}, [16]={npc="林克", tgt="林克"}, [17]={npc="林克", tgt="林克", desc="留到冬泉谷交多诺瓦。"}, [18]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [19]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [20]={npc="希兹尔", tgt="希兹尔"}, [21]={npc="拉瑞安", tgt="拉瑞安"}, [22]={npc="科琳", tgt="科琳"}, [23]={text="北面焦油怪 → 营地外环 → 回营地"}, [24]={hint="帮加基森的特兰雷克收集12块极度粘稠的沥青。", desc="塔纳利斯加基森与破碎石柱接。"}, [25]={hint="将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。"}, [26]={hint="为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}, [27]={hint="为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。"}, [28]={hint="将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。"}, [29]={hint="到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。", desc="灼热峡谷瑟银哨塔棘齿城接才做；贫瘠之地棘齿城交。"}, [30]={npc="被撕破的日记", npcObj=true, tag="可选", desc="掉落物触发，没掉不用专程刷。"}, [31]={hint="将日记还给安戈洛环形山中的威利德·马绍尔。", tag="可选", desc="掉落物触发，没掉不用专程刷。"}, [32]={npc="威利德·马绍尔", tgt="威利德·马绍尔", tag="可选", desc="掉落物触发，没掉不用专程刷。"}, [33]={hint="把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。", tag="可选", desc="塔纳利斯加基森与破碎石柱已接才做；要离区前走一次南线。"}, [34]={hint="收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。"}, [35]={npc="威利德·马绍尔", tgt="威利德·马绍尔"}, [36]={npc="斯巴克·尼米尔", tgt="斯巴克·尼米尔"}, [37]={npc="希兹尔", tgt="希兹尔"}, [38]={npc="拉瑞安", tgt="拉瑞安"}, [39]={npc="科琳", tgt="科琳"}, [40]={npc="科琳", tgt="科琳"}, [41]={npc="科琳", tgt="科琳"}, [42]={npc="科琳", tgt="科琳"}, [43]={npc="拉瑞安", tgt="拉瑞安", desc="棘齿城交。"}, [44]={text="从马绍尔营地飞加基森，顺手交跨区采集。"}, [45]={npc="特兰雷克", tgt="特兰雷克"}, [46]={npc="炼金师匹斯特苏格", tgt="炼金师匹斯特苏格", tag="可选"}, [47]={hint="收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。", tag="可选", desc="可和南区虫巢与采花的主线一起做。"}, [48]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选"}, [49]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="只须使用任务物品；完成立即脱离，无须击杀精英。"}, [50]={hint="将魔暴龙之刺扎入一只魔暴龙的体内。", tag="可选", desc="只须使用任务物品；完成立即脱离，无须击杀精英。"}, [51]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="只须使用任务物品；完成立即脱离，无须击杀精英。"}, [52]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="东瘟疫之地圣光之愿礼拜堂回东部王国时组神庙。", star={"斑白毛皮", {"DRUID"}}}, [53]={text="从加基森飞棘齿城，搭船到藏宝海湾，再飞荒芜之地卡加斯。暴掠龙爪留在幽暗城转回奥格瑞玛时顺路交。"}}},
    ["04-42"] = {name="燃烧平原 黑石山", nameA="燃烧平原 {a:251}／黑石山", shortA="燃烧平原 {a:251} +", tips={{k="取捨", text="值得做：卡加斯先接 、机器的崛起，烈焰峰开点后集中跑巨槌石与索瑞森废墟。"}, {k="取捨", text="先别交：菲诺克 先接，留冬泉谷永望镇交。"}, {k="取捨", text="可跳过：不和谐的烈焰、机器的崛起 要去黑石山或多一趟荒芜之地，单练缺时间可略。想打黑石深渊可另外接后续。"}, {k="提醒", text="差经验就打索瑞森废墟周围的黑铁矮人和傀儡；黑石深渊可组队，先在卡加斯与烈焰峰把地城任务接齐。", s={{"差经验就打索瑞森废墟周围的黑铁矮人和傀儡"}, {"黑石深渊可组队，先在卡加斯与烈焰峰把地城任务接齐"}}}}, danger={[1]="通往黑石深渊的矿场走道狭窄，征服者派隆会在路上巡逻。先清入口的普通怪再动手。", [2]="索瑞森废墟施法怪和巡逻会一起进战。从断墙外拉，别站在两条巡逻路交叉处。"}, grind={[1]={mob="战争掠夺者", note="索瑞森废墟外侧的普通傀儡，沿外墙可连打并补废墟击杀。留意混在废墟间的施法怪。"}, [2]={mob="索瑞森驭火者", note="同一片废墟的普通矮人，可顺路补布料及击杀。施法怪与巡逻可能一起进战，从断墙外拉。"}}, supply={[1]={npc="瓦格鲁克"}, [2]={npc="尤卡·斯库比格特"}, [3]={npc="格鲁纳"}, [4]={npc="旅店老板舒尔卡"}, [5]={npc="斯兰达"}, [6]={npc="格劳尔"}}, steps={[1]={npc="萨特拉克", tgt="萨特拉克", desc="在卡加斯接，东部巨槌石交。"}, [2]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼", desc="在卡加斯接，燃烧平原打傀儡与元素。"}, [3]={npc="桑德哈特", tgt="桑德哈特", tag="可选", desc="在卡加斯接。想去黑石山才做。"}, [4]={text="若已开烈焰峰飞行点，可从卡加斯直接飞过去。初访则经灼热峡谷黑石山穿到燃烧平原，再沿北侧往东到烈焰峰。", tag="还没开这个飞行点，第一次要用跑的"}, [5]={hint="到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。", tag="可选", desc="在副本入口外，注意周围巡逻。"}, [6]={nodeA="{a:251}", desc="向瓦格鲁克开启飞行点。"}, [7]={hint="与燃烧平原的尤卡·斯库比格特谈一谈。", tag="可选", desc="塔纳利斯加基森与破碎石柱热砂港接才交。"}, [8]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特", tag="可选"}, [9]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [10]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [11]={text="东面巨槌石 → 索瑞森废墟 → 卡加斯"}, [12]={hint="到燃烧平原去找到沙妮·长齿。"}, [13]={npc="沙妮·长齿", tgt="沙妮·长齿"}, [14]={npc="沙妮·长齿", tgt="沙妮·长齿"}, [15]={hint="从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。"}, [16]={hint="将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。", desc="要先使用道具，杀掉之后拾取留下的精华。"}, [17]={hint="把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。"}, [18]={hint="到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。", desc="可与石板路线同打。"}, [19]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林"}, [20]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔"}, [21]={npc="丁奇·斯迪波尔", tgt="丁奇·斯迪波尔", desc="留冬泉谷永望镇交菲诺克。"}, [22]={text="从烈焰峰飞卡加斯，交鼻环、碎片与做完的派隆。"}, [23]={npc="萨特拉克", tgt="萨特拉克"}, [24]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼"}, [25]={npc="塞朵拉·穆瓦丹尼", tgt="塞朵拉·穆瓦丹尼", tag="可选", desc="想接后续黑石深渊支线再往东去。"}, [26]={hint="将元素碎片样本交给鲁特维尔·沃拉图斯。", tag="可选", desc="想接后续黑石深渊支线再往东去。"}, [27]={npc="鲁特维尔·沃拉图斯", tgt="鲁特维尔·沃拉图斯", tag="可选", desc="想接后续黑石深渊支线再往东去。"}, [28]={npc="桑德哈特", tgt="桑德哈特", tag="可选"}, [29]={text="从卡加斯飞幽暗城，准备经西瘟疫之地进东瘟疫之地。"}}},
    ["05-d24"] = {name="黑石深渊", entrance="灼热峡谷 34.80, 85.30（黑石山外部路标）", pickup="在灼热峡谷 瑟银哨塔开点，去燃烧平原 烈焰峰时先找尤卡与麦克斯沃特。飞卡加斯接桑德哈特、通缉板与薇薇安，进黑石山杀门外派隆后回卡加斯交 不和谐的烈焰，接 不和谐的火焰、最后的元素；再由瑟银哨塔或烈焰峰进山。", pickupS={{"在灼热峡谷 瑟银哨塔开点，去燃烧平原 烈焰峰时先找尤卡与麦克斯沃特"}, {"飞卡加斯接桑德哈特、通缉板与薇薇安，进黑石山杀门外派隆后回卡加斯交 不和谐的烈焰，接 不和谐的火焰、最后的元素"}, {"再由瑟银哨塔或烈焰峰进山"}}, tips={{k="動線", text="入口外可先打征服者派隆→监狱与竞技场外廊清铁怒矮人→黑铁砧打伊森迪奥斯→工艺大厅打弗诺斯、到纪念碑换暗炉钥匙→宝库取山脉之心、黑铁酒吧打雷布里和取秘方，顺路可互换→过七贤与熔岩桥，到熔火之心门旁拾核心碎片。沿途打元素怪与魔像。"}, {k="取捨", text="首趟优先卡加斯与烈焰峰任务；时间足够再做宝库或熔火之心门。"}, {k="說明", text="北侧入口通往黑石山，内部沿中央锁链下行，穿过磨石场及派隆后找到实际副本门。也可由燃烧平原 29.40, 38.30 进山。", s={{"北侧入口通往黑石山，内部沿中央锁链下行，穿过磨石场及派隆后找到实际副本门"}, {"也可由燃烧平原 29.40, 38.30 进山"}}}}, steps={[1]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特"}, [2]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林", tag="可选", desc="需要搜齐 12 把遗物宝箱钥匙，打算跑宝库才接。"}, [3]={npc="通缉", npcObj=true}, [4]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [5]={npc="桑德哈特", tgt="桑德哈特", desc="坐标投影落在东部王国地图；从北侧黑石山入口进山，派隆在磨石场内、传送门前。"}, [6]={hint="到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。"}, [7]={npc="桑德哈特", tgt="桑德哈特"}, [8]={npc="桑德哈特", tgt="桑德哈特", preText="不和谐的烈焰"}, [9]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", preText="不和谐的烈焰"}, [10]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁", desc="以灵魂状态到黑石山中央悬吊墓室找铸铁，附近的黑石山外部坐标仅供导航。"}, [11]={hint="如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。", desc="坐标指黑石山墓室的弗兰克罗恩；以灵魂状态才能看到。"}, [12]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁"}, [13]={npc="弗兰克罗恩·铸铁", tgt="弗兰克罗恩·铸铁", preText="黑铁的遗产"}, [14]={npc="洛索斯·天痕", tgt="洛索斯·天痕", tag="可选", desc="满 55 级才接；走七贤和熔火之心门路线再做。"}, [15]={text="黑石深渊 入口"}, [16]={hint="到黑石深渊去消灭那些邪恶的侵略者！", desc="位置：入口入禁闭室，沿监牢至秩序竞技场清守卫。", spot="入口入禁闭室，沿监牢至秩序竞技场清守卫"}, [17]={hint="进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。", desc="位置：沿黑铁大道下坡，到黑铁砧打伊森迪奥斯。", spot="沿黑铁大道下坡，到黑铁砧打伊森迪奥斯"}, [18]={hint="杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。", desc="位置：工艺大厅拿锤，再到索瑞森神殿的纪念碑。顺序：先打弗诺斯，再点纪念碑。", spot="工艺大厅拿锤，再到索瑞森神殿的纪念碑"}, [19]={npc="弗兰克罗恩·铸铁的雕像", npcObj=true, tag="需游戏内实测", spot="索瑞森神殿里的铸铁纪念碑"}, [20]={hint="前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。", desc="位置：入口沿黑铁大道打元素魔像，派隆可在门外打。", spot="入口沿黑铁大道打元素魔像，派隆可在门外打"}, [21]={hint="把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。", desc="与酒桌旁的雷布里·斯库比格特交谈开始战斗。位置：穿暗炉城至黑铁酒吧，找酒桌旁的雷布里。", spot="穿暗炉城至黑铁酒吧，找酒桌旁的雷布里"}, [22]={hint="把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。", desc="与队友一起清掉酒吧附近敌人再动手。两个阵营都由同一敌人掉落秘方。位置：到酒吧后房敲碎三桶酒，等赫尔利出现。", spot="到酒吧后房敲碎三桶酒，等赫尔利出现"}, [23]={hint="把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。", tag="可选", desc="位置：进黑铁宝库开十二遗物箱，进暗室取山脉之心。", spot="进黑铁宝库开十二遗物箱，进暗室取山脉之心"}, [24]={hint="进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。", tag="可选", desc="位置：过七贤及熔岩桥，碎片在熔火之心门旁。", spot="过七贤及熔岩桥，碎片在熔火之心门旁"}, [25]={npc="桑德哈特", tgt="桑德哈特"}, [26]={npc="军官高图斯", tgt="军官高图斯"}, [27]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [28]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}, [29]={npc="尤卡·斯库比格特", tgt="尤卡·斯库比格特"}, [30]={npc="麦克斯沃特·尤博格林", tgt="麦克斯沃特·尤博格林", tag="可选"}, [31]={npc="洛索斯·天痕", tgt="洛索斯·天痕", tag="可选"}}},
    ["04-43"] = {name="东瘟疫之地 圣光之愿礼拜堂", tips={{k="取捨", text="值得做：首次到东瘟疫先开圣光之愿飞行点，礼拜堂书在同一处。提里奥、纳萨诺斯和达隆郡主要任务留到后段。"}, {k="取捨", text="可跳过：奥古斯图斯的收据册 要绕到恐惧谷，纯转场可略过。若视频拾的是礼拜堂里的书，对应永恒版 A Study of the Light。"}, {k="提醒", text="未满 54 级可在圣光之愿外沿道路打普通瘟疫怪，或到下一站清费尔斯通农场（约 38, 56）的普通亡灵。", s={{"未满 54 级可在圣光之愿外沿道路打普通瘟疫怪，或到下一站清费尔斯通农场（约 38, 56）的普通亡灵"}}}}, danger={[1]="走恐惧谷找收据册时，屋内和楼梯上的亡灵可能同时拉到。先清楼下再上楼。"}, grind={[1]={mob="腐肉虫", note="圣光之愿西南的普通腐肉虫，沿路能单拉，也可顺收弗丁任务需要的腐肉虫肉。避开北边高等亡灵群。"}, [2]={mob="毒性瘟疫蝙蝠", note="礼拜堂西侧空地的普通蝙蝠，补经验后可快速回补给。与瘟疫蝙蝠任务重叠，遇到玩家时往南转。"}}, supply={[1]={npc="乔吉亚"}, [2]={npc="杰希卡·查伯斯"}, [3]={npc="工匠威尔海姆"}, [4]={npc="杰希卡·查伯斯"}, [5]={npc="护理者奥林"}}, steps={[1]={hint="将玛科里石板交给幽暗城的安德隆·甘特。", tag="可选"}, [2]={npc="安德隆·甘特", tgt="安德隆·甘特", tag="可选"}, [3]={text="从幽暗城城外往东走到亡灵壁垒，再穿过西瘟疫之地进东瘟疫之地。沿南侧主路往东，不进斯坦索姆。"}, [4]={npc="被感动的奥古斯图斯", tgt="被感动的奥古斯图斯", tag="可选", desc="离主路较远。若只想开圣光之愿飞行点可略。"}, [5]={hint="把奥古斯图斯的收据册交给恶蛛隧道中的被感动的奥古斯图斯。", tag="可选", desc="离主路较远。若只想开圣光之愿飞行点可略。"}, [6]={npc="被感动的奥古斯图斯", tgt="被感动的奥古斯图斯", tag="可选", desc="离主路较远。若只想开圣光之愿飞行点可略。"}, [7]={node="圣光之愿礼拜堂", desc="向乔吉亚开启部落飞行点。"}, [8]={npc="书籍", tgt="詹妮亚·坎农", npcObj=true, desc="永恒版书籍。礼拜堂内靠后左侧，取书后在幽暗城交。"}, [9]={hint="使用／收集：书籍"}, [10]={text="由礼拜堂飞幽暗城，若手上有图书馆任务可顺路交。"}, [11]={npc="奥兰·斯内克威瑟", tgt="奥兰·斯内克威瑟", desc="奥兰与欧文·萨德（73.40, 33.00）都在幽暗城法师区；先依游戏的可交付提示。"}, [12]={hint="将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="与悲伤沼泽的神庙任务一起进副本。"}, [13]={npc="部落英雄的灵魂", tgt="部落英雄的灵魂", tag="可选", desc="交回诅咒之地北口，可选钻石水瓶（Diamond Flask）等装备。", star={"钻石水瓶", {"WARRIOR"}}}, [14]={hint="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。", tag="可选", desc="组队从斯通纳德去沉没的神庙，找绿龙摩弗拉斯。"}, [15]={hint="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。", tag="可选", desc="组队从斯通纳德去沉没的神庙，找绿龙摩弗拉斯。"}, [16]={hint="将碧蓝钥匙交给乔拉齐·拉文霍德公爵。", tag="可选", desc="组队从斯通纳德去沉没的神庙，找绿龙摩弗拉斯。"}, [17]={npc="乔拉齐·拉文霍德公爵", tgt="乔拉齐·拉文霍德公爵", tag="可选", desc="从斯通纳德转飞塔伦米尔后到庄园交，可选黑檀面具（Ebon Mask）等装备。", star={"暗色蝠斗篷", {"ROGUE"}}}, [18]={hint="从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。", tag="可选", desc="需组队；若队伍只清龙区，先告知需下到底层解蛇像。"}, [19]={hint="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。", tag="可选", desc="组队从斯通纳德去沉没的神庙，找绿龙摩弗拉斯。"}, [20]={text="留在东部王国。下一站从幽暗城往东到亡灵壁垒。"}}},
    ["04-44"] = {name="西瘟疫之地", nameA="西瘟疫之地 {a:813}", tips={{k="交通", text="要去亡灵壁垒须步行。西侧往提瑞斯法林地或幽暗城，走城外飞艇回奥格瑞玛。"}, {k="取捨", text="值得做：费尔斯通农场的瘟疫锅和包裹在同一处，回城可把 迟到总比不到好、杰雷米亚的忧伤 一起交。"}, {k="取捨", text="之后顺路：本趟完成第一口锅，达尔松之泪的 目标：达尔松之泪 与安多哈尔的通灵学院任务留下一轮。杰雷米亚的好运护符 ／两半合一 后段回西瘟疫才做。"}, {k="提醒", text="未到 55 级，可补费尔斯通农场外围的普通骷髅和食尸鬼（约 38, 56）；避开安多哈尔内的高等精英。", s={{"未到 55 级，可补费尔斯通农场外围的普通骷髅和食尸鬼（约 38, 56）"}, {"避开安多哈尔内的高等精英"}}}}, danger={[1]="安多哈尔中央有 61 级精英『召唤者』阿拉基。标记哨塔时沿城边走，不要穿中央广场。"}, grind={[1]={mob="骷髅剥皮者", note="费尔斯通农场普通亡灵，瘟疫锅路线顺路，农田外比屋群好拉。任务玩家多时在外围移动。"}, [2]={mob="被奴役的食尸鬼", note="同农场普通食尸鬼，能补上骷髅刷新空档。不要追怪进安多哈尔。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}, [2]={npc="迈克尔·加勒特"}, [3]={npc="旅店老板诺曼"}, [4]={npc="旅店老板诺曼"}, [5]={npc="艾林诺尔·拉斯克"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="从幽暗城出城，沿提瑞斯法林地东路到亡灵壁垒（83.13, 68.94）。保留幽暗城的飞行点，方便本段末尾交城内支线。"}, [2]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="接完就在德林顿旁的箱子领瓶中火，与任务提供的天灾军旗都要带上。"}, [3]={hint="到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。", desc="先用瓶中火烧帐篷，再使用军旗。"}, [4]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="先用瓶中火烧帐篷，再使用军旗。"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [6]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [7]={hint="与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。"}, [8]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [9]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [10]={text="从壁垒向东进费尔斯通农场，先收天灾大锅样本，再绕詹妮丝的房子与马厩。"}, [11]={hint="到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。", desc="先确认身上有范蒂丝给的空瓶。"}, [12]={npc="瘟疫之锅", npcObj=true}, [13]={npc="瘟疫之锅", npcObj=true, desc="拿到样本后，在同一口大锅接回程。"}, [14]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [15]={hint="这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。", desc="包裹位于马厩内，靠近后与物件互动。"}, [16]={npc="詹妮丝的包裹", npcObj=true}, [17]={npc="詹妮丝的包裹", npcObj=true, desc="选部落版 迟到总比不到好，返回幽暗城交；本地只取包裹。"}, [18]={text="由费尔斯通农场往东到达尔松之泪。这里先解房屋日记与钥匙，天灾大锅留下一趟。"}, [19]={npc="达尔松夫人的日记", npcObj=true}, [20]={hint="完成任务目标。"}, [21]={npc="达尔松夫人的日记", npcObj=true}, [22]={npc="厕所", npcObj=true, desc="日记读完再找游荡的骷髅。开厕所后农夫会出现。"}, [23]={hint="掉落自：游荡的骷髅", desc="日记读完再找游荡的骷髅。开厕所后农夫会出现。"}, [24]={npc="厕所", npcObj=true, desc="日记读完再找游荡的骷髅。开厕所后农夫会出现。"}, [25]={npc="锁住的柜橱", npcObj=true, desc="先清厕所周围，开柜后可立即交件。"}, [26]={hint="掉落自：农夫达尔松", desc="先清厕所周围，开柜后可立即交件。"}, [27]={npc="锁住的柜橱", npcObj=true, desc="先清厕所周围，开柜后可立即交件。"}, [28]={text="沿安多哈尔外缘逐塔走，再回壁垒。塔门有高等守卫时先等巡逻离开。"}, [29]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。", desc="在门口即可使用火炬，无须进塔打守卫。"}, [30]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [31]={hint="把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [32]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [33]={text="回幽暗城，先在公会登记处附近交城内包裹。"}, [34]={hint="与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。"}, [35]={npc="皇家管理人巴哈乌斯", tgt="皇家管理人巴哈乌斯"}, [36]={npc="皇家管理人巴哈乌斯", tgt="皇家管理人巴哈乌斯"}, [37]={hint="在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。"}, [38]={npc="杰雷米亚·派森", tgt="杰雷米亚·派森"}, [39]={npc="杰雷米亚·派森", tgt="杰雷米亚·派森", desc="先保留半个护符，西瘟疫之地亡灵壁垒到费尔斯通农场交。"}, [40]={npc="哀恸骑士", tag="可选、需游戏内实测", desc="幽暗城交完城内任务后、上飞艇前往西南找他。骑士有多个刷新点。"}, [41]={hint="Speak with the Knight of Mourning to learn more about his unfinished quest.", tag="可选、需游戏内实测", desc="幽暗城交完城内任务后、上飞艇前往西南找他。骑士有多个刷新点。"}, [42]={npc="哀恸骑士", tag="可选、需游戏内实测", desc="幽暗城交完城内任务后、上飞艇前往西南找他。骑士有多个刷新点。"}, [43]={npc="哀恸骑士", tag="可选、需游戏内实测", desc="先听完 The Knight of Mourning；飞艇回奥格瑞玛时可组艾萨拉 Blackmaw Hold。取得圣匣后，等回到提瑞斯法林地再交。", star={"Sword of Mourning", {"PALADIN"}}}, [44]={hint="将灵魂图腾所需的材料交给捕风者巴斯拉。", tag="可选", desc="打瘟疫农场任务时顺带清蜘蛛、熊和秃鹰。"}, [45]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="幽暗城起飞前先飞塔伦米尔找巴斯拉交。"}, [46]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="有神庙队伍就接；下一次东部王国回访可完成。", star={"被迷惑的水之魂", {"SHAMAN"}}}, [47]={text="在幽暗城外的飞艇塔搭往奥格瑞玛的飞艇。"}}},
    ["04-45"] = {name="费伍德森林 南段", nameA="费伍德森林 南段／{a:1997}", short="费伍德森林 南段 +", tips={{k="交通", text="血毒岗哨开飞行点，下站仍由此出发。若途经灰谷碎木岗哨，沿大道绕过联盟城镇的守卫。"}, {k="取捨", text="值得做：南部死木熊怪直接开木喉声望；加德纳尔、南段洛尔和碧火萨特月井可连着跑。"}, {k="取捨", text="之后顺路：净化费伍德 先接，北边拿齐血琥珀。采完后晚点再回南部交，省下立刻折返一趟。"}, {k="提醒", text="未到 55 级时，优先在碎痕谷外圈（约 41, 42）打普通元素，或补木喉声望的死木熊怪。", s={{"未到 55 级时，优先在碎痕谷外圈（约 41, 42）打普通元素，或补木喉声望的死木熊怪"}}}}, danger={[1]="碎痕谷热能元素会在坑边成对刷新。从坡口单拉，别往坑底跨到下一群。"}, grind={[1]={mob="热能野兽", note="碎痕谷外圈的普通元素，和热能击杀任务重叠。入口有任务玩家时从外侧向内轮打。"}, [2]={mob="热能恐兽", note="同一片普通元素点，有较高等的变种，与热能野兽混打。地形窄，留意成对刷新。"}}, supply={[1]={npc="布拉卡尔"}, [2]={npc="奥索巴·狂怒图腾"}, [3]={npc="拜尔"}, [4]={npc="拜尔"}, [5]={npc="旅店老板凯利斯克"}, [6]={npc="旅店老板凯利斯克"}}, steps={[1]={npc="杰斯雷蒙", tgt="杰斯雷蒙", tag="可选", desc="艾萨拉瓦罗莫克接，并在安戈洛环形山马绍尔营地打齐白色暴掠龙爪。"}, [2]={text="从奥格瑞玛飞灰谷碎木岗哨，沿大道西行后从灰谷北路进费伍德森林，先停南端的翡翠圣地。"}, [3]={npc="格拉兹", tgt="格拉兹"}, [4]={npc="梅贝丝·河风", tgt="梅贝丝·河风", desc="血琥珀在费伍德北段；下一站顺路打铁木树人，晚一点回南端交。"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [6]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [7]={hint="格拉兹要你去杀死6个死木战士、6个死木探路者以及6个死木园丁。", desc="完成后木喉熊怪声望上升。若还是敌对，后续到北营地再补。"}, [8]={npc="格拉兹", tgt="格拉兹"}, [9]={npc="格拉兹", tgt="格拉兹", desc="先接，下一站到费伍德最北边交。"}, [10]={text="沿主路往北先经加德纳尔，再到血毒岗哨。"}, [11]={nodeA="{a:1997}", desc="向布拉卡尔开启飞行点。"}, [12]={hint="到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}, [13]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [14]={npc="德雷卡苏", tgt="德雷卡苏"}, [15]={text="沿主路北行一小段到碎痕谷，完成腐蚀调查，再走西侧萨特月井和南端兽人营地回翡翠圣地。"}, [16]={hint="杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。", desc="务必走到任务勘查区，单杀元素不会完成全部目标。"}, [17]={hint="从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。", desc="此处和加德纳尔中央另一口月井是两个不同目标。"}, [18]={hint="杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。", desc="目标在南端营地深处；沿坡道清掉周边怪再拉。"}, [19]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [20]={npc="塔诺恩·红羽", tgt="塔诺恩·红羽"}, [21]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", desc="下趟用空水壶到加德纳尔中央月井装水。"}, [22]={text="回血毒岗哨，交水样与洛尔的爪子；视需要在这里补给。"}, [23]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [24]={npc="德雷卡苏", tgt="德雷卡苏"}, [25]={npc="奥汀克", tgt="奥汀克", tag="可选", desc="奥格瑞玛往费伍德的转场可先飞艾萨拉，交奥汀克。可选魔暴龙眼（Devilsaur Eye）等装备。", star={"魔暴龙眼", {"HUNTER"}}}, [26]={npc="大法师克希雷姆", tgt="大法师克希雷姆", tag="可选", desc="转往费伍德前可先去艾萨拉找克希雷姆交；奖励可选火焰宝石（Fire Ruby）等装备。", star={"火焰宝石", {"MAGE"}}}, [27]={npc="万能的尼比", tgt="万能的尼比", tag="可选"}, [28]={hint="与费伍德森林的伊普斯谈一谈。", tag="可选"}, [29]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [30]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="加德纳尔精华可先拿；月光林地永夜港从奥格瑞玛可先飞艾萨拉，西瘟疫之地亡灵壁垒在东部王国时可飞斯通纳德往诅咒之地。"}, [31]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="若已有训练师版 小鬼的要求，直接交 小鬼的要求 再接 奇怪的材料。"}, [32]={hint="将一块恶魔布交给费伍德森林的伊普斯。", tag="可选", desc="若已有训练师版 小鬼的要求，直接交 小鬼的要求 再接 奇怪的材料。"}, [33]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="若已有训练师版 小鬼的要求，直接交 小鬼的要求 再接 奇怪的材料。"}, [34]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [35]={hint="将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。", tag="可选"}, [36]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [37]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="打算组神庙再接；西瘟疫之地亡灵壁垒到东部王国后可下。", star={"灵魂收割者", {"WARLOCK"}}}, [38]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选", desc="翡翠圣地找格雷塔；可选祝福珠串（Blessed Prayer Beads）等装备。", star={"祝福珠串", {"PRIEST"}}}}},
    ["04-46"] = {name="费伍德森林 木喉要塞", nameA="费伍德森林 {a:1997}至木喉要塞", shortA="费伍德森林 {a:1997} +", tips={{k="交通", text="血毒岗哨补给后沿大道向北。洞内看分岔，走往冬泉谷的出口。"}, {k="取捨", text="值得做：北部铁木森林一起解血琥珀与堕落的力量，最后才刷死木熊怪声望。"}, {k="取捨", text="之后顺路：已打完 净化费伍德 先留物品，往后回翡翠圣地再交。水之魂的帮助 留棘齿城。"}, {k="提醒", text="木喉声望达「冷淡」即可安全走洞。若声望仍是敌对，或未到 56 级，可在北死木村（约 62, 8）补熊怪。", s={{"木喉声望达「冷淡」即可安全走洞"}, {"若声望仍是敌对，或未到 56 级，可在北死木村（约 62, 8）补熊怪"}}}}, danger={[1]="木喉要塞仍对你敌对时，洞内的守卫可能成群加入战斗。先打外面的死木熊怪升到冷淡再穿洞。"}, grind={[1]={mob="死木复仇者", note="北死木村普通熊怪，去木喉要塞前顺打，可补声望及羽毛。营帐间容易连拉，先清外圈。"}, [2]={mob="死木守卫", note="同村靠大道的普通熊怪，遇到声望团可沿路侧挑落单怪。不要打木喉守卫。"}}, supply={[1]={npc="布拉卡尔"}, [2]={npc="奥索巴·狂怒图腾"}, [3]={npc="拜尔"}, [4]={npc="拜尔"}}, steps={[1]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [2]={npc="特鲁尔·法贝恩", tgt="特鲁尔·法贝恩", desc="下站冬泉谷打枭兽，后续回血毒岗哨交。"}, [3]={text="先往南去加德纳尔中央月井，取水后走回翡翠圣地交件。之后才回碧火萨特月井放出小猫。"}, [4]={hint="把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}, [5]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [6]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", desc="留到棘齿城南面的水之先知伊斯伦交。"}, [7]={hint="把温娜的小猫带到堕落的月亮井旁边，把猫放出来，然后把它还给温娜。", desc="放猫后别走太快或飞走；到温娜身边须先点小猫交还，才能交任务。"}, [8]={npc="温娜·哈萨德", tgt="温娜·哈萨德"}, [9]={text="离开血毒岗哨，沿主路北上铁木森林与死木村，最北端在木喉洞口找纳菲恩。"}, [10]={hint="收集15颗血琥珀，把它们交给费伍德森林的梅贝丝·河风。", desc="收齐先保留，下次回南费伍德再向梅贝丝交。"}, [11]={hint="菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。", tag="若先前已接", desc="需已在莫沙彻营地接取；菲拉斯莫沙彻营地回营地交。"}, [12]={hint="沿着路去费伍德森林，和名叫纳菲恩的熊怪谈一谈。他站在木喉要塞的入口处。"}, [13]={npc="纳菲恩", tgt="纳菲恩"}, [14]={npc="纳菲恩", tgt="纳菲恩"}, [15]={hint="格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。", desc="北营地清完再确认声望，仍敌对就加刷死木怪直到冷淡。"}, [16]={npc="纳菲恩", tgt="纳菲恩"}, [17]={npc="纳菲恩", tgt="纳菲恩", desc="从洞内往冬泉谷出口走，出洞找萨尔法。"}, [18]={text="木喉熊怪声望到「冷淡」后进洞，沿冬泉谷出口走。洞内不打木喉熊怪。"}}},
    ["04-47"] = {name="冬泉谷", nameA="冬泉谷 {a:2255}", tips={{k="交通", text="初到永望镇开鸟点并绑炉石。下一站飞菲拉斯莫沙彻营地。若未开飞行点，可先飞千针石林乱风岗，沿大路西行到菲拉斯开点。"}, {k="取捨", text="值得做：冰火温泉的多诺瓦任务先交齐，枭兽沿路清；永望镇雪怪、奇美拉可在同趟做。"}, {k="取捨", text="可跳过：尤西乌斯是精英，冬泉熊怪的活动 须往西折返洞口。有队伍或还缺进度再做。"}, {k="取捨", text="之后顺路：永望镇报告与尼古拉斯公爵的书先放任务栏，东部王国下一轮一起交。"}, {k="提醒", text="还不到 56 级就打永望镇东边的普通雪人（约 64, 40）或东侧寒水村外围熊怪，避开巡逻精英。", s={{"还不到 56 级就打永望镇东边的普通雪人（约 64, 40）或东侧寒水村外围熊怪，避开巡逻精英"}}}}, danger={[1]="永望镇北边有精英碎齿熊尤西乌斯巡逻。单打普通熊时绕开，已组队再做它的任务。", [2]="寒水村内的萨满祭司和巡逻熊怪容易成群。缺经验就沿村外找落单守卫。"}, grind={[1]={mob="冰蓟雪人", note="永望镇东侧的普通雪人，靠补给点且可顺收毛皮。洞口常有同任务玩家，先沿山脚打。"}, [2]={mob="冬泉巢穴守卫", note="寒水村外圈的普通熊怪，补木喉声望与相关掉落。村内施法怪容易连拉，避开精英巡逻。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={hint="穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。", tag="若费伍德森林血毒岗哨与木喉要塞已接"}, [2]={npc="萨尔法", tgt="萨尔法", tag="若费伍德森林血毒岗哨与木喉要塞已接"}, [3]={npc="萨尔法", tgt="萨尔法", tag="可选", desc="可在永望镇东侧的寒水村解。后续还要西返，可等下次回洞口再交。"}, [4]={text="从洞口向南去冰火温泉，先接多诺瓦的熊怪任务，再去西部寒水熊怪营地。"}, [5]={hint="把林克的剑交给冬泉谷的多诺瓦·雪山。", tag="若安戈洛环形山马绍尔营地已接"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="若安戈洛环形山马绍尔营地已接"}, [7]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="菲拉斯莫沙彻营地北菲拉斯取药剂；下次回冰火温泉再交。"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={hint="冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}, [10]={npc="空的火酒瓶", npcObj=true, tag="掉落才接", desc="熊怪会掉空的火酒瓶，捡到后点开；这是月光林地永夜港至冬泉谷霜语峡谷熊怪链的前置；若还没掉，到寒水村外继续打普通熊怪。"}, [11]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [12]={hint="将空的火酒瓶交给冬泉谷的多诺瓦·雪山。", tag="若有火酒瓶"}, [13]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="若有火酒瓶"}, [14]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", desc="留到下一趟北费伍德，找死木营帐中的蒸锅。"}, [15]={text="向东往永望镇，沿路清两类枭兽。"}, [16]={nodeA="{a:2255}", desc="向尤格雷克开启飞行点。"}, [17]={text="将炉石绑定在旅店老板维兹奇处（61.36, 38.83）。"}, [18]={hint="费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。", tag="若费伍德森林血毒岗哨与木喉要塞已接", desc="打完留到回费伍德血毒岗哨再交。"}, [19]={hint="把丁奇的信交给菲诺克。", tag="若燃烧平原烈焰峰与黑石山已接"}, [20]={npc="菲诺克", tgt="菲诺克", tag="若燃烧平原烈焰峰与黑石山已接"}, [21]={npc="菲诺克", tgt="菲诺克", tag="需先完成 菲诺克"}, [22]={npc="乌米", tgt="乌米"}, [23]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通", desc="下一趟到亡灵壁垒交银色黎明军官加鲁什。"}, [24]={npc="格雷戈·格雷斯通", tgt="格雷戈·格雷斯通", desc="留往东瘟疫之地圣光之愿礼拜堂交。"}, [25]={npc="杰希卡·雷德帕斯", tgt="杰希卡·雷德帕斯", desc="与永望镇的报告一起带到东瘟疫，东瘟疫之地圣光之愿礼拜堂在达隆郡交。"}, [26]={npc="斯托姆·影蹄", tgt="斯托姆·影蹄", tag="精英、可选"}, [27]={text="先清永望镇东面的雪人洞穴与周边，再视进度绕北边和东侧。"}, [28]={hint="为永望镇的乌米收集10张厚雪人毛皮。", desc="下一段需要雪人角，晚一趟再接 雪怪计划！。"}, [29]={npc="乌米", tgt="乌米"}, [30]={hint="将8支完整的冰风奇美拉角交给菲诺克。", tag="需先完成 菲诺克"}, [31]={npc="菲诺克", tgt="菲诺克", tag="需先完成 菲诺克"}, [32]={npc="菲诺克", tgt="菲诺克", tag="可选", desc="下次顺路去燃烧平原才回覆丁奇。"}, [33]={hint="永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。", tag="精英、可选", desc="56 级精英，组队再打。"}, [34]={npc="斯托姆·影蹄", tgt="斯托姆·影蹄", tag="精英、可选"}, [35]={hint="萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。", tag="需折返洞口、可选"}, [36]={npc="萨尔法", tgt="萨尔法", tag="需折返洞口、可选"}}},
    ["05-d25"] = {name="黑石塔下层", entrance="灼热峡谷 34.80, 85.30（黑石山外部路标）", pickup="在燃烧平原 烈焰峰先开飞行点，55 级后回烈焰峰找基布雷尔接两件。到冬泉谷 永望镇找基尔拉姆，跨海回东部王国后飞卡加斯向高图斯、贾拉玛弗、雷克斯洛特接任。走灼热峡谷或烈焰峰到黑石山东侧上层阳台入共同传送门；回卡加斯交 高图斯的命令，接 伊崔格的智慧 并保留。", pickupS={{"在燃烧平原 烈焰峰先开飞行点，55 级后回烈焰峰找基布雷尔接两件"}, {"到冬泉谷 永望镇找基尔拉姆，跨海回东部王国后飞卡加斯向高图斯、贾拉玛弗、雷克斯洛特接任"}, {"走灼热峡谷或烈焰峰到黑石山东侧上层阳台入共同传送门"}, {"回卡加斯交 高图斯的命令，接 伊崔格的智慧 并保留"}}, tips={{k="動線", text="下层入口→奥莫克→沃什加斯→斜坡下找比修和装置→沃恩→蛛网区清卵与烟网蛛后→哈雷肯与基兹鲁尔→维姆萨拉克。奥莫克、沃恩与维姆萨拉克的宝石一路收齐。"}, {k="取捨", text="优先三王文件、座狼、卵与比修；队伍已有能开上层的人就可略过印章链。"}, {k="說明", text="开服后下层可进。黑石山外部路标另可用燃烧平原 29.40, 38.30；进山后沿上行路到东侧高台，进门后往右下走。", s={{"开服后下层可进"}, {"黑石山外部路标另可用燃烧平原 29.40, 38.30"}, {"进山后沿上行路到东侧高台，进门后往右下走"}}}}, steps={[1]={npc="基尔拉姆", tgt="基尔拉姆"}, [2]={npc="基布雷尔", tgt="基布雷尔"}, [3]={npc="基布雷尔", tgt="基布雷尔"}, [4]={npc="军官高图斯", tgt="军官高图斯", desc="若 NPC 不直接给接取界面，先交谈取得高图斯的命令，再右键使用。"}, [5]={npc="神射手贾拉玛弗", tgt="神射手贾拉玛弗"}, [6]={npc="雷克斯洛特", tgt="雷克斯洛特"}, [7]={text="黑石塔下层 入口"}, [8]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需游戏内实测", desc="满 57 级才接。上层阳台侧路的裂盾渗透者是伪装的维埃兰，靠近交谈。"}, [9]={hint="到黑石塔去查明比修的下落。", desc="位置：从沃什加斯房沿大斜坡下，在侧台找比修。", spot="从沃什加斯房沿大斜坡下，在侧台找比修"}, [10]={npc="比修", tgt="比修", tag="需游戏内实测", spot="沃什加斯房外大斜坡下，侧台的比修"}, [11]={npc="比修", tgt="比修", tag="需游戏内实测", preText="狡猾的比修"}, [12]={hint="找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。", desc="位置：从比修平台回房中央再往下，搜下层装置。", spot="从比修平台回房中央再往下，搜下层装置"}, [13]={npc="比修", tgt="比修", tag="需游戏内实测", spot="比修所在的侧台"}, [14]={npc="比修", tgt="比修", tag="需游戏内实测", preText="比修的装置"}, [15]={hint="到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。", desc="位置：沿蛛网隧道拾卵，先清卵堆旁的蜘蛛。", spot="沿蛛网隧道拾卵，先清卵堆旁的蜘蛛"}, [16]={hint="到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。", desc="位置：过奥莫克后走通道，找暗影猎手沃什加斯。顺序：先打沃什加斯，再沿其房间斜坡找比修。", spot="过奥莫克后走通道，找暗影猎手沃什加斯"}, [17]={hint="到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。", desc="先告诉队伍留一只幼狼，避免被范围攻击击杀。位置：过蜘蛛区与巨魔岔道，进狼房抓幼狼。", spot="过蜘蛛区与巨魔岔道，进狼房抓幼狼"}, [18]={hint="杀死血斧座狼的领袖，哈雷肯。", desc="位置：蜘蛛区后岔路往右，沿路进左侧狼巢。", spot="蜘蛛区后岔路往右，沿路进左侧狼巢"}, [19]={hint="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。", desc="文件位置会变，遇到前三房先找。文件可能出现在任一首领房间，逐间查看。位置：沿三王线逐房找文件，也查看乌洛克贡品堆。顺序：奥莫克→沃恩→维姆萨拉克。", spot="沿三王线逐房找文件，也查看乌洛克贡品堆"}, [20]={hint="找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。", tag="可选", desc="宝石与印章掉落机率有限，先和队友约定分配；若只打上层，队伍一人持完成品即可。文件可能出现在任一首领房间，逐间查看。位置：三王各拾宝石，沿路小怪另找原始印章。顺序：奥莫克→沃恩→维姆萨拉克。", spot="三王各拾宝石，沿路小怪另找原始印章"}, [21]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需游戏内实测"}, [22]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需游戏内实测", preText="晋升印章"}, [23]={hint="把比修的侦查报告交给卡加斯的雷克斯洛特。"}, [24]={npc="军官高图斯", tgt="军官高图斯"}, [25]={npc="神射手贾拉玛弗", tgt="神射手贾拉玛弗"}, [26]={npc="雷克斯洛特", tgt="雷克斯洛特"}, [27]={npc="基布雷尔", tgt="基布雷尔"}, [28]={npc="基布雷尔", tgt="基布雷尔"}, [29]={npc="基尔拉姆", tgt="基尔拉姆"}, [30]={npc="军官高图斯", tgt="军官高图斯", desc="先保留，飞船或飞艇回到奥格瑞玛时进智慧谷找伊崔格。", preText="高图斯的命令"}, [31]={hint="到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。", tag="可选", desc="精英建议组队；控龙前停手，留足血量。"}, [32]={npc="裂盾渗透者", tgt="裂盾渗透者", tag="可选、需游戏内实测", desc="回黑石塔下层门内找维埃兰。"}}},
    ["04-48"] = {name="菲拉斯（短访）", nameA="菲拉斯 {a:1099}（短访）", tips={{k="交通", text="主要转场为永望镇飞莫沙彻、莫沙彻飞棘齿城。若已安排藏宝海湾交件，可用棘齿城对开的船补交。"}, {k="取捨", text="值得做：菲拉斯 莫沙彻营地与怒痕堡接、费伍德做的 堕落的力量 是回村就能交的任务。"}, {k="取捨", text="可跳过：海岸支线在西侧，定位器没掉就不找；只有想补经验或要去双塔山时才把海岸并入。"}, {k="提醒", text="此站没有必须单独练等的门槛。若差 56 级，先到下一站交件，再把经验差留给后段同等怪区。", s={{"此站没有必须单独练等的门槛"}, {"若差 56 级，先到下一站交件，再把经验差留给后段同等怪区"}}}}, danger={[1]="被遗忘的海岸巨人要先用压缩器缩小再打。等海元素走开后逐只处理。"}, grind={[1]={mob="北泉唤风者", note="若已在北泉交件，可清营地外围的普通鹰身人，顺收北泉任务掉落。怪等偏低，若还差一大截就去冬泉谷。"}, [2]={mob="冰蓟雪人", note="若差 56 级，上一站离开永望镇前优先在这片补。普通雪人集中，外坡比洞口好拉。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="从永望镇飞莫沙彻营地；这一趟先回营地交菲拉斯莫沙彻营地与怒痕堡的费伍德支线，已接视灵药剂再去北边。"}, [2]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", tag="若费伍德森林血毒岗哨与木喉要塞已完成"}, [3]={text="若身上有 视灵药剂，沿菲拉斯大道向西至岔路，再朝双塔山与北边的乌鸦风废墟。"}, [4]={hint="去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。", tag="若冬泉谷永望镇已接", desc="格雷甘交换药剂是 视灵药剂 的对话流程；本趟只取药，别喝，留给冬泉谷多诺瓦交。"}, [5]={text="打算补海岸支线才去被遗忘的海岸。若手上有菲拉斯定位器，可先去深痕谷洞穴接护送，再顺路走到海岸。", tag="可选"}, [6]={npc="OOX-22/FE定位器", npcObj=true, tag="可选", desc="定位器为野怪掉落，已捡到才接。"}, [7]={hint="把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。", tag="可选", desc="定位器为野怪掉落，已捡到才接。"}, [8]={npc="自动导航机器人OOX-22/FE", tgt="自动导航机器人OOX-22/FE", tag="可选", desc="定位器为野怪掉落，已捡到才接。"}, [9]={npc="自动导航机器人OOX-22/FE", tgt="自动导航机器人OOX-22/FE", tag="可选", desc="沿路有伏击。护送后交件在藏宝海湾，贫瘠之地棘齿城若改由藏宝海湾搭船才交。"}, [10]={hint="将OOX-22/FE护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。", tag="可选", desc="沿路有伏击。护送后交件在藏宝海湾，贫瘠之地棘齿城若改由藏宝海湾搭船才交。"}, [11]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [12]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [13]={hint="使用索尔宾的超级压缩器，把菲拉斯的任意巨人缩小到便于对付的体型。从缩小后的巨人身上收集15份微缩残渣，交给菲拉斯被遗忘的海岸码头上的索尔宾·范达瑟。", tag="可选", desc="先缩小再击杀；未缩小的巨人不掉所需物品。"}, [14]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [15]={hint="从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。", tag="可选"}, [16]={npc="索尔宾·范达瑟", tgt="索尔宾·范达瑟", tag="可选"}, [17]={text="回莫沙彻营地飞棘齿城。已完成 拯救OOX-22/FE！ 且想交件时，可由棘齿城搭船往返藏宝海湾；其余直接在棘齿城办交接。"}}},
    ["04-49"] = {name="贫瘠之地（短访）", nameA="贫瘠之地 {a:392}（短访）", tips={{k="交通", text="棘齿城飞奥格瑞玛后，换城外幽暗城方向飞艇。抵达提瑞斯法林地，沿东路到亡灵壁垒。"}, {k="取捨", text="值得做：已完成安戈洛灰烬和车间支线就一起交给莉芙，海岸再接伊斯伦回费伍德的信。"}, {k="取捨", text="可跳过：若身上没有棘齿城可交任务，可由菲拉斯直接飞奥格瑞玛转飞艇。"}, {k="提醒", text="棘齿城的怪等级偏低。未到 56 级可在转飞艇前飞回永望镇打东侧普通雪人（约 64, 40），或到西瘟疫之地亡灵壁垒在费尔斯通农场（约 38, 56）打普通亡灵。", s={{"棘齿城的怪等级偏低"}, {"未到 56 级可在转飞艇前飞回永望镇打东侧普通雪人（约 64, 40），或到西瘟疫之地亡灵壁垒在费尔斯通农场（约 38, 56）打普通亡灵"}}}}, grind={[1]={mob="骷髅巫师", note="棘齿城只办交接。缺 56 级时沿原路搭飞艇，到下一站费尔斯通农场再打。普通骷髅多，从田埂拉，避开血色巡逻。"}}, supply={[1]={npc="布拉高克"}, [2]={npc="旅店老板维尔雷"}, [3]={npc="格拉利克斯"}, [4]={npc="旅店老板维尔雷"}, [5]={npc="加吉克"}, [6]={npc="霍苏斯"}}, steps={[1]={npc="奥格索普·奥布诺提斯", tgt="奥格索普·奥布诺提斯", tag="若走藏宝海湾转船、可选"}, [2]={text="到棘齿城后先交工程任务，再沿岸往南找水之先知伊斯伦。"}, [3]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", tag="若安戈洛环形山马绍尔营地已采满灰烬"}, [4]={hint="到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。", tag="若安戈洛环形山马绍尔营地已接"}, [5]={npc="莉芙·雷兹菲克斯", tgt="莉芙·雷兹菲克斯", tag="若安戈洛环形山马绍尔营地已接"}, [6]={hint="把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。", tag="若费伍德森林血毒岗哨与木喉要塞已接"}, [7]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", tag="若费伍德森林血毒岗哨与木喉要塞已接"}, [8]={npc="水之先知伊斯伦", tgt="水之先知伊斯伦", tag="需先完成 水之魂的帮助", desc="保留净化水。后段回费伍德翡翠圣地再交格雷塔。"}, [9]={text="回棘齿城飞奥格瑞玛，搭城外前往提瑞斯法林地的飞艇。抵达后沿提瑞斯法林地东路前往亡灵壁垒。"}}},
    ["04-50"] = {name="西瘟疫之地", tips={{k="交通", text="第 1 步由飞艇塔往亡灵壁垒。打完盖罗恩农场后沿主路向东去东瘟疫。"}, {k="取捨", text="值得做：瘟疫之锅按接续顺序做，嚎哭鬼屋顺路完成两段野生动物。"}, {k="取捨", text="先别交：返回亡灵壁垒 留西瘟疫之地 亡灵壁垒，瘟疫与你 在东瘟疫之地 圣光之愿礼拜堂完成、回西瘟疫之地 亡灵壁垒交。"}, {k="提醒", text="同为 56-57 级带，接着去东瘟疫之地圣光之愿礼拜堂。壁垒旁接了 才开始累积骸骨碎片。打算自备通灵学院钥匙的角色，交完就接 昂贵的模具，并带两块瑟银锭带去塔纳利斯加基森，再进安戈洛环形山。", s={{"同为 56-57 级带，接着去东瘟疫之地圣光之愿礼拜堂"}, {"壁垒旁接了 才开始累积骸骨碎片"}, {"打算自备通灵学院钥匙的角色，交完就接 昂贵的模具，并带两块瑟银锭带去塔纳利斯加基森，再进安戈洛环形山"}}}}, danger={[1]="达尔松之泪北侧有血色巡逻。收瘟疫锅材料时从田埂拉骷髅，别往北穿营地。"}, grind={[1]={mob="恐惧骸骨", note="达尔松之泪的普通骷髅，跑瘟疫锅可顺收骸骨碎片。北侧会遇到血色巡逻，打外侧。"}, [2]={mob="冰冷的食尸鬼", note="嚎哭鬼屋附近的普通食尸鬼，等级较合适，和下一口锅同路。屋门口密集，从田边开始。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}}, steps={[1]={text="从棘齿城飞奥格瑞玛并转乘飞艇，抵达提瑞斯法林地后，沿幽暗城外的大路往东走到亡灵壁垒。"}, [2]={hint="把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。"}, [3]={npc="银色黎明军官加鲁什", tgt="银色黎明军官加鲁什"}, [4]={npc="米克·莱文", tgt="米克·莱文"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [6]={hint="和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。"}, [7]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [8]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [9]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [10]={hint="到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。", desc="先清锅边的普通亡灵，靠近锅会引出护锅者。"}, [11]={npc="瘟疫之锅", npcObj=true}, [12]={npc="瘟疫之锅", npcObj=true}, [13]={hint="把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [14]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [15]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [16]={hint="到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。", desc="先清锅边的普通亡灵，靠近锅会引出护锅者。"}, [17]={npc="瘟疫之锅", npcObj=true}, [18]={npc="瘟疫之锅", npcObj=true}, [19]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [20]={hint="消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [21]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [22]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [23]={hint="消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}, [24]={npc="穆格雷斯·深水", tgt="穆格雷斯·深水"}, [25]={hint="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。", desc="与两口瘟疫之锅同趟收，回壁垒交样本时一起交。"}, [26]={hint="把嚎哭鬼屋的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [27]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [28]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [29]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [30]={hint="到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。", desc="先清锅边的普通亡灵，靠近锅会引出护锅者。"}, [31]={npc="瘟疫之锅", npcObj=true}, [32]={npc="瘟疫之锅", npcObj=true}, [33]={hint="将巫毒羽毛交给捕风者巴斯拉。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="可从幽暗城飞斯通纳德组队。"}, [34]={npc="捕风者巴斯拉", tgt="捕风者巴斯拉", tag="可选", desc="在奥特兰克交巴斯拉，可选迷恋的水之魂（Enamored Water Spirit）等装备。", star={"被迷惑的水之魂", {"SHAMAN"}}}, [35]={hint="到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。", tag="可选、目标：加什尔 / 祖罗尔 / 加什尔 / 胡库 / 米杉 / 胡库 / 祖罗 / 洛若尔 / 洛若尔", desc="可从幽暗城飞斯通纳德。留费伍德森林铁木森林交伊普斯。"}}},
    ["04-51"] = {name="东瘟疫之地", tips={{k="交通", text="在交 尼古拉斯·瑟伦霍夫公爵 与接 达隆郡的保卫者 后开礼拜堂飞行点；末步飞幽暗城后转飞艇。"}, {k="取捨", text="先别交：瘟疫与你 与 玛莱恩姑妈 回西瘟疫之地 亡灵壁垒交。"}, {k="取捨", text="可跳过：暗翼蝠（Duskwing, Oh How I Hate Thee...，）在东瘟疫，是精英巡逻目标；按视频的取舍略过。"}, {k="取捨", text="可跳过：哈米亚的请求 要在墓穴与祖尔玛夏间来回，遗忘的记忆 点墓土后会引来一群佣兵，赶路可以略过。"}, {k="提醒", text="进度落后可在瘟疫木林外围（约 29, 28）打普通蝙蝠、犬与食尸鬼。要到 57 级可等菲拉斯乱羽高地前补。", s={{"进度落后可在瘟疫木林外围（约 29, 28）打普通蝙蝠、犬与食尸鬼"}, {"要到 57 级可等菲拉斯乱羽高地前补"}}}}, danger={[1]="瘟疫木林靠近斯坦索姆的一侧有高等缝合憎恶和巡逻。采白蚁或找食尸鬼时走外围。"}, grind={[1]={mob="吃人的食尸鬼", note="瘟疫木林外围的普通亡灵。可顺路补居民灵魂相关任务，避开较高等的缝合憎恶及巡逻。"}, [2]={mob="狂怒的瘟疫犬", note="同区道路外的普通瘟疫犬，等级贴近本段、空地较好拉。有人清亡灵时可改沿外圈找狗。"}}, supply={[1]={npc="乔吉亚"}, [2]={npc="杰希卡·查伯斯"}, [3]={npc="工匠威尔海姆"}, [4]={npc="杰希卡·查伯斯"}, [5]={npc="护理者奥林"}}, steps={[1]={text="过西界后沿索多里尔河岸找提里奥，接齐再向南上主路。"}, [2]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [4]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [5]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [6]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [7]={hint="在达隆郡里找到帕米拉·雷德帕斯。"}, [8]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [9]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [10]={hint="找到帕米拉的洋娃娃。", desc="拾取零件时可能出现鬼魂，先清门口。"}, [11]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [12]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [13]={npc="帕米拉·雷德帕斯", tgt="帕米拉·雷德帕斯"}, [14]={hint="到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。", desc="腐质只有约 10 分钟有效期，收齐后当场研磨。"}, [15]={hint="找到卡林·瑞德巴思。"}, [16]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [17]={hint="将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"}, [18]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [19]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [20]={text="确认圣光之愿礼拜堂的部落飞行点已开；首次到访找乔吉亚（70.53, 47.55）。接着沿路北上打瘟疫木林一圈。"}, [21]={hint="在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。", desc="沿瘟疫木林外围找蚁丘，避开斯坦索姆门口的精英。"}, [22]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [23]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [24]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [25]={hint="杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。"}, [26]={hint="释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。", desc="杀完要点刚出现的灵魂，单纯击杀不会累计。"}, [27]={npc="卡林·雷德帕斯", tgt="卡林·雷德帕斯"}, [28]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [29]={npc="纳萨诺斯·凋零者", tgt="纳萨诺斯·凋零者"}, [30]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [31]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [32]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [33]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="要做完提里奥的三个狩猎任务才会出现。"}, [34]={hint="听听提里奥·弗丁要说什么。", desc="要做完提里奥的三个狩猎任务才会出现。"}, [35]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="要做完提里奥的三个狩猎任务才会出现。"}, [36]={text="完成后从礼拜堂飞幽暗城，再搭飞艇去奥格瑞玛。"}}},
    ["05-d27"] = {name="斯坦索姆 亡灵区", entrance="东瘟疫之地 遗失的补给品 约 43.50, 19.40（亡灵区侧门）", pickup="先在东瘟疫之地 圣光之愿礼拜堂找贝蒂娜、莱尼德与护理者奥林，西去恐惧谷找埃根后再进侧门。从正门跑过的队伍可把后续 活跃的探子 留这一趟。", pickupS={{"先在东瘟疫之地 圣光之愿礼拜堂找贝蒂娜、莱尼德与护理者奥林，西去恐惧谷找埃根后再进侧门"}, {"从正门跑过的队伍可把后续 活跃的探子 留这一趟"}}, tips={{k="動線", text="侧门先找小教堂的奥里克斯→打三座通灵塔的安娜丝塔丽、奈鲁布恩坎和苍白的玛勒基，顺查通灵塔资料→屠宰场拉姆斯登→打瑞文戴尔后与奥里克斯交谈。沿路收肉块、开木箱取圣水、解放幽灵居民。"}, {k="取捨", text="肉块、圣水、埃根的灵魂可同趟。只刷一翼可略过需要先拿信仰奖章的奥里克斯线。"}, {k="說明", text="五人队。侧门用城市大门钥匙；第一次可从正门通过城内路线，从巴瑟拉斯取得侧门钥匙。", s={{"五人队"}, {"侧门用城市大门钥匙"}, {"第一次可从正门通过城内路线，从巴瑟拉斯取得侧门钥匙"}}}, {k="提醒", text="五人队。侧门用城市大门钥匙；第一次可从正门通过城内路线，从巴瑟拉斯取得侧门钥匙。", s={{"五人队"}, {"侧门用城市大门钥匙"}, {"第一次可从正门通过城内路线，从巴瑟拉斯取得侧门钥匙"}}}}, steps={[1]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="如果已交，这趟可接 活跃的探子。"}, [2]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="必须先交 血肉不会撒谎；若第一次进本还没开，留下一趟。", preText="血肉不会撒谎"}, [3]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅"}, [4]={npc="护理者奥林", tgt="护理者奥林"}, [5]={hint="找到埃根。你只知道他在斯坦索姆附近。"}, [6]={npc="埃根", tgt="埃根"}, [7]={npc="埃根", tgt="埃根", desc="取得埃根的爆破枪。", preText="永不安息的灵魂"}, [8]={text="斯坦索姆 亡灵区 入口"}, [9]={hint="从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……", desc="位置：侧门入街区，沿途清亡灵并拾取肉块。", spot="侧门入街区，沿途清亡灵并拾取肉块"}, [10]={hint="到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。", desc="位置：三座通灵塔逐座搜，资料在其中一座小箱。顺序：每打倒一位塔门首领就进塔检查。", spot="三座通灵塔逐座搜，资料在其中一座小箱"}, [11]={hint="到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。", desc="位置：沿街查看木制补给箱，清附近怪再开。", spot="沿街查看木制补给箱，清附近怪再开"}, [12]={hint="对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！", desc="位置：沿街找幽灵居民，同一目标连用两次爆破枪。", spot="沿街找幽灵居民，同一目标连用两次爆破枪"}, [13]={npc="奥里克斯", tgt="奥里克斯", tag="需游戏内实测", desc="在血色区玛洛尔的保险箱取得信仰奖章后，去亡灵区入口旁小教堂。"}, [14]={hint="使用／收集：玛洛尔的保险箱", desc="位置：亡灵区侧门进去，找入口旁燃烧小教堂。", spot="亡灵区侧门进去，找入口旁燃烧小教堂"}, [15]={npc="奥里克斯", tgt="奥里克斯", tag="需游戏内实测", spot="亡灵区入口旁的燃烧小教堂"}, [16]={npc="奥里克斯", tgt="奥里克斯", tag="需游戏内实测", desc="先给奖章并接任务，再去打瑞文戴尔男爵。", preText="信仰奖章"}, [17]={hint="完成任务目标。", desc="击败后在同一房间与奥里克斯交谈。位置：清通灵塔后过屠宰场，到瑞文戴尔房找奥里克斯。顺序：击杀后同房找奥里克斯。", spot="清通灵塔后过屠宰场，到瑞文戴尔房找奥里克斯"}, [18]={npc="奥里克斯", tgt="奥里克斯", tag="需游戏内实测", desc="完成时奥里克斯会移到尾王房间；接取仍在亡灵区入口旁的小教堂。", spot="瑞文戴尔房，奥里克斯会移到房内"}, [19]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}, [20]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}, [21]={npc="莱尼德·巴萨罗梅", tgt="莱尼德·巴萨罗梅"}, [22]={npc="埃根", tgt="埃根"}}},
    ["05-d26"] = {name="斯坦索姆 血色区", entrance="东瘟疫之地 遗失的补给品 约 27.10, 10.70（正门传送门）", pickup="先在东瘟疫之地 圣光之愿礼拜堂找公爵和烟鬼。沿瘟疫之地大道往西北，走正门；要做提里奥的画，先在东瘟疫之地 圣光之愿礼拜堂完成狩猎，接续跑南部墓穴、北谷，转去西瘟疫 凯尔达隆找画家，再回东瘟疫。", pickupS={{"先在东瘟疫之地 圣光之愿礼拜堂找公爵和烟鬼"}, {"沿瘟疫之地大道往西北，走正门"}, {"要做提里奥的画，先在东瘟疫之地 圣光之愿礼拜堂完成狩猎，接续跑南部墓穴、北谷，转去西瘟疫 凯尔达隆找画家，再回东瘟疫"}}, tips={{k="動線", text="正门→市场烟草店→进血色堡垒，威利支线可略→档案管理员加尔福特的房间同时取资料与烧档案→需要全清再打巴纳扎尔。"}, {k="取捨", text="烟草和档案任务两件好接；已完成提里奥前半再加爱与家庭。想只跑一趟时先把前置接齐。"}, {k="說明", text="五人队。血色要塞门请带血色十字军钥匙。未满 58 级时先接、到等级再组；可从地下侧门进亡灵区。", s={{"五人队"}, {"血色要塞门请带血色十字军钥匙"}, {"未满 58 级时先接、到等级再组"}, {"可从地下侧门进亡灵区"}}}, {k="提醒", text="五人队。血色要塞门请带血色十字军钥匙。未满 58 级时先接、到等级再组；可从地下侧门进亡灵区。", s={{"五人队"}, {"血色要塞门请带血色十字军钥匙"}, {"未满 58 级时先接、到等级再组"}, {"可从地下侧门进亡灵区"}}}}, steps={[1]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩"}, [2]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵", desc="同趟清档案管理员，记得烧档案。"}, [3]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。同任务也可找提里奥·弗丁领主（53.95, 24.45）。"}, [4]={hint="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。"}, [5]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [6]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。同任务也可找提里奥·弗丁领主（53.95, 24.45）。"}, [7]={hint="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。"}, [8]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [9]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。同任务也可找提里奥·弗丁领主（53.95, 24.45）。"}, [10]={hint="在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。"}, [11]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [12]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。", preText="恶魔之犬、血染的天空、腐肉虫"}, [13]={hint="听听提里奥·弗丁要说什么。"}, [14]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [15]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。", preText="救赎"}, [16]={hint="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。"}, [17]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [18]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。", preText="遗忘的记忆"}, [19]={hint="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。"}, [20]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}, [21]={npc="提里奥·弗丁", tgt="提里奥·弗丁", desc="提里奥的选做长链，已在东瘟疫之地 圣光之愿礼拜堂完成则从下一步开始。", preText="失落的荣耀"}, [22]={hint="到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。"}, [23]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾"}, [24]={npc="画家瑞弗蕾", tgt="画家瑞弗蕾", preText="爱与家庭"}, [25]={text="斯坦索姆 血色区 入口"}, [26]={hint="找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。", desc="位置：正门进市场，开希亚比烟草店的箱子。", spot="正门进市场，开希亚比烟草店的箱子"}, [27]={hint="在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。", desc="血色档案位于档案管理员所在的档案室。位置：进血色堡垒档案室，打加尔福特后烧档案。", spot="进血色堡垒档案室，打加尔福特后烧档案"}, [28]={hint="到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到\"爱与家庭\"这幅画，它被隐藏在另一幅描绘两个月亮的画之后。", desc="双月画就在档案室首领所在的房间。位置：同一间血色档案室，查墙上的双月画。", spot="同一间血色档案室，查墙上的双月画"}, [29]={npc="烟鬼拉鲁恩", tgt="烟鬼拉鲁恩"}, [30]={npc="尼古拉斯·瑟伦霍夫公爵", tgt="尼古拉斯·瑟伦霍夫公爵"}, [31]={npc="提里奥·弗丁", tgt="提里奥·弗丁"}}},
    ["04-52"] = {name="月光林地", tips={{k="交通", text="第 2 步飞雷霆崖，第 7 步飞费伍德并走木喉要塞，在月光林地西南开飞行点，再步行进冬泉谷。"}, {k="取捨", text="值得做：先接 废土 和 净化之匣，希利苏斯南风村能接着做同一区的任务。"}, {k="取捨", text="先别交：神秘的粘液 到冬泉谷 永望镇交；净化之匣 在希利苏斯 塞纳里奥要塞拾取，留月光林地 永夜港交。"}, {k="提醒", text="木喉熊怪若还会主动攻击，先在要塞外打死木熊怪或完成费伍德森林翡翠圣地与血毒岗哨至冬泉谷永望镇的声望任务；通过要塞后可立刻接冬泉谷永望镇。", s={{"木喉熊怪若还会主动攻击，先在要塞外打死木熊怪或完成费伍德森林翡翠圣地与血毒岗哨至冬泉谷永望镇的声望任务"}, {"通过要塞后可立刻接冬泉谷永望镇"}}}}, danger={[1]="若从月光林地走木喉要塞转冬泉谷，先确认木喉声望。敌对时先绕或回费伍德补声望。"}, grind={[1]={mob="死木复仇者", note="永夜港交完可由木喉要塞回费伍德侧入口补。普通死木熊怪密集，还能补木喉声望；避开木喉守卫与帐篷内的连拉。"}, [2]={mob="冬泉巢穴守卫", note="若已穿过要塞，冬泉谷一侧先打沿路普通熊怪。可在多诺瓦附近补少量，主要怪群仍在永望镇以东。"}}, supply={[1]={npc="法斯托恩"}, [2]={npc="梅里"}, [3]={npc="达尔贡"}, [4]={npc="黛欧琳·夏叶"}}, steps={[1]={npc="塞纳里奥使者托尔·黑蹄", tgt="塞纳里奥使者托尔·黑蹄"}, [2]={text="从奥格瑞玛飞雷霆崖，在城下接信差的引导，再往长者高地找大德鲁伊。"}, [3]={npc="雷霆崖信使斯塔德尔", tgt="雷霆崖信使斯塔德尔", desc="此为部落前往永夜港的引导；做过 新的边疆 或 新的边疆 的角色可直接找哈缪尔。"}, [4]={hint="与雷霆崖长者高地的大德鲁伊哈缪尔·符文图腾谈一谈关于议会号召部落成员探索卡利姆多大陆的事情。", desc="此为部落前往永夜港的引导；做过 新的边疆 或 新的边疆 的角色可直接找哈缪尔。"}, [5]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾", desc="此为部落前往永夜港的引导；做过 新的边疆 或 新的边疆 的角色可直接找哈缪尔。"}, [6]={npc="大德鲁伊哈缪尔·符文图腾", tgt="大德鲁伊哈缪尔·符文图腾"}, [7]={text="从雷霆崖飞血毒岗哨，往北绕死木村到 60.20, 5.84 的死木蒸锅，接着走木喉要塞往月光林地岔路。"}, [8]={hint="搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。"}, [9]={npc="死木蒸锅", npcObj=true}, [10]={npc="死木蒸锅", npcObj=true}, [11]={hint="与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。"}, [12]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [13]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [14]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [15]={node="月光林地", desc="往月光林地西南侧，向法斯托恩开启部落飞行点。"}, [16]={hint="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr.", tag="可选、需游戏内实测", desc="55-60 级地城，从艾萨拉北部洞口往内走到副本门。圣匣保留到再访提瑞斯法林地。"}, [17]={text="再穿木喉要塞去冬泉谷。"}}},
    ["04-53"] = {name="冬泉谷", tips={{k="交通", text="第 1 步从木喉要塞出来先停温泉，末步依是否要绕菲拉斯乱羽高地选航线。"}, {k="取捨", text="先别交：墓地相见 在塔纳利斯 加基森解。剧毒之水 到费伍德森林 铁木森林刷物品，回冬泉谷 冰火温泉交。"}, {k="取捨", text="值得做：雪怪计划！ 会沿同一路线跑三张图，接了就先在永望镇用一次。"}, {k="提醒", text="还差 57 级就先在冰蓟岭（约 66, 43）打普通雪人，或在菲拉斯乱羽高地打角鹰兽。", s={{"还差 57 级就先在冰蓟岭（约 66, 43）打普通雪人，或在菲拉斯乱羽高地打角鹰兽"}}}}, danger={[1]="冰蓟岭的洞道窄，57-58 级雪人会在转角连拉。缺经验先打洞口外侧。"}, grind={[1]={mob="冰蓟雪人女王", note="冰蓟岭洞口的普通雪人，任务需要的角也会掉。人多可打外坡，洞内留意连拉。"}, [2]={mob="冰蓟雪人王", note="同一带的高等普通雪人，补到 57 级的经验较合适。队友先清窄道，避免两只同时进战。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={text="出木喉要塞沿路往东，先到温泉找多诺瓦，再进永望镇。"}, [2]={hint="将你的发现报告给多诺瓦·雪山。"}, [3]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [4]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [5]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [7]={npc="乌米", tgt="乌米"}, [8]={hint="为永望镇的乌米收集2支完美的雪人角。", desc="只有洞内成年的女族长、雪人王掉落，低阶雪人留给前段任务。"}, [9]={npc="乌米", tgt="乌米"}, [10]={npc="乌米", tgt="乌米", desc="接完先在永望镇对莱加奇（61.54, 38.61）使用机械雪人，另外两人安戈洛环形山马绍尔营地顺路。"}, [11]={text="选做取蛋或已组好厄运之槌队伍时才飞菲拉斯莫沙彻营地；两项都跳过就从永望镇直飞加基森。"}}},
    ["04-54"] = {name="菲拉斯", tips={{k="交通", text="第 1 步为南下取蛋的停靠点，第 2 步飞加基森。"}, {k="取捨", text="可跳过：超级测蛋器（The Super Egg-O-Matic）的一次性交件，已做过或已达 57 级且想省跑图时，可以直接飞加基森。"}, {k="提醒", text="未到 57 级可在乱羽高地（约 57, 76）打普通角鹰兽，或者冬泉谷永望镇打冰蓟雪人后直接搭机。", s={{"未到 57 级可在乱羽高地（约 57, 76）打普通角鹰兽，或者冬泉谷永望镇打冰蓟雪人后直接搭机"}}}}, grind={[1]={mob="冰蓟雪人女王", note="菲拉斯短访只有角鹰兽蛋支线。缺 57 级可在上一站离开永望镇前补，冰蓟岭雪人等级较高；洞口可能有人抢。"}}, supply={[1]={npc="夏恩"}, [2]={npc="旅店老板格鲁尔"}, [3]={npc="卡温德"}, [4]={npc="旅店老板格鲁尔"}, [5]={npc="卡温德"}, [6]={npc="塔霍斯"}}, steps={[1]={text="从莫沙彻营地沿南路到乱羽高地；点角鹰兽蛋（55.91, 76.03 或 58.62, 75.53），拿 1 颗就回飞行点。", tag="可选"}, [2]={text="取蛋者回莫沙彻营地飞加基森。跳过菲拉斯的角色到加基森直接开始安戈洛环形山马绍尔营地。"}}},
    ["05-d30"] = {name="厄运之槌 北", entrance="菲拉斯 62.50, 24.90（北区传送门）", pickup="在菲拉斯 莫沙彻营地整队再往西；菲拉斯 莫沙彻营地可先准备材料。北区常用任务多在本内，先在东区取得月牙钥匙，或者与有钥匙的队友同行。要交职业书可先从拍卖场备妥对应书。", pickupS={{"在菲拉斯 莫沙彻营地整队再往西"}, {"菲拉斯 莫沙彻营地可先准备材料"}, {"北区常用任务多在本内，先在东区取得月牙钥匙，或者与有钥匙的队友同行"}, {"要交职业书可先从拍卖场备妥对应书"}}, tips={{k="動線", text="一般全清依序走莫尔达、克雷格、芬古斯、诺特旁的陷阱、克罗卡斯和戈多克大王。打贡品则保留沿途守卫，找诺特并处理陷阱，打完大王再回克雷格。职业书可另由入口庭院侧门通图书馆。"}, {k="取捨", text="练级以一趟能打完的队伍优先；只为贡品而刻意等材料时，可先做主线。"}, {k="說明", text="贡品打法尽量保留守卫和克雷格，打倒戈多克大王后再对话。只想打普通全清，先和队伍讲清楚。", s={{"贡品打法尽量保留守卫和克雷格，打倒戈多克大王后再对话"}, {"只想打普通全清，先和队伍讲清楚"}}}, {k="提醒", text="贡品打法尽量保留守卫和克雷格，打倒戈多克大王后再对话。只想打普通全清，先和队伍讲清楚。", s={{"贡品打法尽量保留守卫和克雷格，打倒戈多克大王后再对话"}, {"只想打普通全清，先和队伍讲清楚"}}}}, steps={[1]={text="厄运之槌 北 入口"}, [2]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需游戏内实测", desc="要用的材料是符文布卷 ×4、硬甲皮 ×8、符文线 ×2，加本内食人魔鞣酸 ×1。"}, [3]={hint="把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。", desc="位置：过芬古斯后上层拾鞣酸，再到陷阱旁找诺特。", spot="过芬古斯后上层拾鞣酸，再到陷阱旁找诺特"}, [4]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需游戏内实测", spot="芬古斯后，陷阱旁的诺特"}, [5]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需游戏内实测", desc="有戈多克镣铐钥匙才做；贡品打法保留守卫，掉落机会较少。"}, [6]={hint="掉落自：戈多克蛮兵、戈多克大法师、戈多克领主", desc="位置：过芬古斯庭院，到破损陷阱旁用钥匙救诺特。", spot="过芬古斯庭院，到破损陷阱旁用钥匙救诺特"}, [7]={npc="诺特·希姆加克", tgt="诺特·希姆加克", tag="需游戏内实测", spot="芬古斯庭院的破损陷阱旁，诺特"}, [8]={npc="践踏者克雷格", tgt="践踏者克雷格", tag="需游戏内实测", desc="完成贡品路线取得国王状态后找克雷格。践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。"}, [9]={hint="完成任务目标。", desc="践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。位置：打完大王取得国王身分，原路回前段找克雷格。顺序：贡品跑后回头交谈。", spot="打完大王取得国王身分，原路回前段找克雷格"}, [10]={npc="践踏者克雷格", tgt="践踏者克雷格", tag="需游戏内实测", desc="贡品通关后仍要留在本内交给克雷格。践踏者克雷格在戈多克平民区；取得国王状态后才与他对话。", spot="戈多克平民区的践踏者克雷格"}, [11]={npc="迦罗娜：潜行与诡计研究", npcObj=true, tag="需游戏内实测", desc="职业书从首领／书堆取得或向玩家交易，右键启动后去图书馆。"}, [12]={hint="将这本典籍交给它的主人。", desc="位置：北门进庭院走侧锁门，沿长隧道下到图书馆。", spot="北门进庭院走侧锁门，沿长隧道下到图书馆"}, [13]={npc="博学者基尔达斯", tgt="博学者基尔达斯", tag="需游戏内实测", spot="图书馆里的博学者基尔达斯"}, [14]={npc="防御宝典", npcObj=true, tag="需游戏内实测", desc="职业书从首领／书堆取得或向玩家交易，右键启动后去图书馆。"}, [15]={hint="将这本典籍交给它的主人。", desc="位置：北门进庭院走侧锁门，沿长隧道下到图书馆