    ["05-d29"] = {name="厄运之槌 西", entrance="菲拉斯 60.30, 30.20（庭院西区传送门）", pickup="在菲拉斯 莫沙彻营地找先知科鲁拉克；满 54 级可在菲拉斯 莫沙彻营地先接 精灵的传说。飞莫沙彻后沿大道向西，队内先确认月牙钥匙；没人有就先排东区。", pickupS={{"在菲拉斯 莫沙彻营地找先知科鲁拉克"}, {"满 54 级可在菲拉斯 莫沙彻营地先接 精灵的传说"}, {"飞莫沙彻后沿大道向西，队内先确认月牙钥匙"}, {"没人有就先排东区"}}, tips={{k="動線", text="西门→花园清水晶塔→特迪斯·扭木→上层找古灵接任务并清塔（卡雷迪斯、伊琳娜可选）→牢笼打伊莫塔尔→图书馆打托塞德林→回古灵交接，再返图书馆找宝藏与遗骸。"}, {k="取捨", text="同一趟完成 精灵的传说、伊莫塔尔的疯狂 及 辛德拉的宝藏；材料换附魔与多本长链留装备行程。"}, {k="說明", text="五人队。月牙钥匙可由东区普希林取得。需清五塔才能打伊莫塔尔；图书馆的职业书见北区说明。", s={{"五人队"}, {"月牙钥匙可由东区普希林取得"}, {"需清五塔才能打伊莫塔尔"}, {"图书馆的职业书见北区说明"}}}, {k="提醒", text="五人队。月牙钥匙可由东区普希林取得。需清五塔才能打伊莫塔尔；图书馆的职业书见北区说明。", s={{"五人队"}, {"月牙钥匙可由东区普希林取得"}, {"需清五塔才能打伊莫塔尔"}, {"图书馆的职业书见北区说明"}}}}, steps={[1]={npc="先知科鲁拉克", tgt="先知科鲁拉克", desc="在莫沙彻营地接；图书馆由西区通过，或用北区旁通道。"}, [2]={text="厄运之槌 西 入口"}, [3]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需游戏内实测", desc="进西区上层先与辛德拉古灵对话。"}, [4]={hint="你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。", desc="先清除五座水晶塔。位置：花园及上层清五塔，穿锁门打伊莫塔尔和王子。顺序：五塔→伊莫塔尔→图书馆王子。", spot="花园及上层清五塔，穿锁门打伊莫塔尔和王子"}, [5]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需游戏内实测", spot="图书馆里的辛德拉古灵"}, [6]={npc="辛德拉古灵", tgt="辛德拉古灵", tag="需游戏内实测", desc="交古灵后接，与 伊莫塔尔的疯狂 同一趟。", preText="伊莫塔尔的疯狂"}, [7]={hint="返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！", desc="位置：从伊莫塔尔牢笼穿走廊，找图书馆楼梯下宝箱。", spot="从伊莫塔尔牢笼穿走廊，找图书馆楼梯下宝箱"}, [8]={npc="辛德拉的宝藏", npcObj=true, tag="需游戏内实测", spot="图书馆楼梯下的辛德拉宝箱"}, [9]={hint="到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。", desc="位置：从牢笼穿走廊进图书馆，找靠书架的遗骸。", spot="从牢笼穿走廊进图书馆，找靠书架的遗骸"}, [10]={npc="先知科鲁拉克", tgt="先知科鲁拉克"}}},
    ["05-d28"] = {name="厄运之槌 东", entrance="菲拉斯 64.80, 30.20（竞技场东墙凹处传送门）", pickup="艾萨拉 瓦罗莫克经奥格瑞玛且满 54 级时可向公告员高拉克接 ；在菲拉斯 莫沙彻营地交塔罗并先接 蕾瑟塔蒂丝的网，飞菲拉斯 莫沙彻营地后找拉瑞斯小亭的埃斯托尔迪。净化之匣 可从月光林地接，希利苏斯 塞纳里奥要塞南风村取匣、月光林地 永夜港交后才有 魔藤碎片，可留到晚一趟。", pickupS={{"艾萨拉 瓦罗莫克经奥格瑞玛且满 54 级时可向公告员高拉克接"}, {"在菲拉斯 莫沙彻营地交塔罗并先接 蕾瑟塔蒂丝的网，飞菲拉斯 莫沙彻营地后找拉瑞斯小亭的埃斯托尔迪"}, {"净化之匣 可从月光林地接，希利苏斯 塞纳里奥要塞南风村取匣、月光林地 永夜港交后才有 魔藤碎片，可留到晚一趟"}}, tips={{k="動線", text="主入口先追普希林，到终点再开打→蕾瑟塔蒂丝与海多斯博恩依分支顺路打→萨特祭坛打瑟雷姆·刺蹄→尾王奥兹恩。图书馆另从西区或北区进。"}, {k="取捨", text="东区先拿月牙钥匙，塔罗与普希林两件最顺。魔藤碎片 未解到时不用为了取匣先跨两张图。"}, {k="說明", text="五人队，东门可直接进。别只跳王漏掉普希林。钥匙留着开西、北区。", s={{"五人队，东门可直接进"}, {"别只跳王漏掉普希林"}, {"钥匙留着开西、北区"}}}, {k="提醒", text="五人队，东门可直接进。别只跳王漏掉普希林。钥匙留着开西、北区。", s={{"五人队，东门可直接进"}, {"别只跳王漏掉普希林"}, {"钥匙留着开西、北区"}}}}, steps={[1]={npc="公告员高拉克", tgt="公告员高拉克", desc="市区引导，可直接向塔罗接 蕾瑟塔蒂丝的网。"}, [2]={hint="和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。"}, [3]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄"}, [4]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄", desc="部落版本；莫沙彻营地 是可选引导，可直接接。"}, [5]={npc="埃斯托尔迪", tgt="埃斯托尔迪", desc="莫沙彻营地北面拉瑞斯小亭。"}, [6]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳", desc="主线第52、56、59站已有这条，已交略过。"}, [7]={hint="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"}, [8]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [9]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳", desc="带上净化之匣；若菲拉斯 乱羽高地尚未完成 ，可下次再做。", preText="净化之匣"}, [10]={text="厄运之槌 东 入口"}, [11]={hint="到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。", desc="依次与普希林交谈，追到最后一站。位置：东门先与普希林说话，沿通道反复追到尽头。顺序：沿路多次对话才开打。", spot="东门先与普希林说话，沿通道反复追到尽头"}, [12]={hint="把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。", desc="位置：从花园走上层通道到蕾瑟塔蒂丝的平台。", spot="从花园走上层通道到蕾瑟塔蒂丝的平台。"}, [13]={hint="在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。", desc="魔藤碎片就在奥茨恩附近。位置：沿末段通道到奥兹恩房，打完找碎片并封印。", spot="沿末段通道到奥兹恩房，打完找碎片并封印"}, [14]={npc="博学者莱德罗斯", tgt="博学者莱德罗斯", tag="需游戏内实测", desc="60 级可从图书馆莱德罗斯接，已在西／北区拿到再来东区。"}, [15]={hint="到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。", desc="位置：走东区的下层水道，打水池旁的海多斯博恩。", spot="走东区的下层水道，打水池旁的海多斯博恩"}, [16]={npc="埃斯托尔迪", tgt="埃斯托尔迪"}, [17]={npc="塔罗·刺蹄", tgt="塔罗·刺蹄"}, [18]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [19]={npc="博学者莱德罗斯", tgt="博学者莱德罗斯", tag="需游戏内实测", desc="回图书馆，交后学最高阶造水术。"}}},
    ["04-55"] = {name="安戈洛环形山", tips={{k="交通", text="第 1、11 步经加基森，沿途用机械雪人，末步走西北坡去希利苏斯。"}, {k="取捨", text="先别交：新的泉水 到冬泉谷 冰火温泉交，雪怪计划！ 到永望镇交；林克的记忆 留费伍德森林 铁木森林。"}, {k="取捨", text="可跳过：超级测蛋器 只在捡到蛋且还能交时出发；没捡的不用折返。"}, {k="提醒", text="同为 57-59 级带。要补进度可打火羽山普通元素或北侧猩猩，留意平原巡逻的魔暴龙。", s={{"同为 57-59 级带"}, {"要补进度可打火羽山普通元素或北侧猩猩，留意平原巡逻的魔暴龙"}}}}, danger={[1]="火羽山南侧平原有 54-56 级精英魔暴龙。护送林格前先观察路线，走山腰避开平原。"}, grind={[1]={mob="有生烈焰", note="火羽山的普通元素，等级较高且可顺做火山任务。沿山腰拉，别进入魔暴龙巡逻的平原。"}, [2]={mob="焦油兽王", note="马绍尔营地附近的普通焦油怪，差一点就升级时可从营地出发打几轮。沿池边单拉。"}}, supply={[1]={npc="格莱菲"}, [2]={npc="吉波尔特"}, [3]={npc="奈尔加"}, [4]={npc="奈尔加"}, [5]={npc="旅店老板菲兹格瑞博"}}, steps={[1]={text="先在加基森完成墓园交接。做机械雪人任务的角色也留在镇内，等使用过雪人再走南路。"}, [2]={npc="测蛋器", npcObj=true, tag="可选", desc="用菲拉斯乱羽高地捡的 1 颗蛋；已做过就直接跳过。"}, [3]={hint="使用／收集：角鹰兽的蛋", tag="可选"}, [4]={npc="测蛋器", npcObj=true, tag="可选"}, [5]={hint="在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。", desc="喝下会死亡；先用灵魂完成交谈，再回墓园复活。"}, [6]={npc="加里杨", tgt="加里杨"}, [7]={npc="加里杨", tgt="加里杨"}, [8]={hint="复活，然后寻找加里杨让你去找的那块墓碑。"}, [9]={npc="明显的墓碑", npcObj=true}, [10]={npc="明显的墓碑", npcObj=true}, [11]={text="先对加基森的斯普琳科（51.06, 26.87）使用机械雪人，再沿南路入环形山。"}, [12]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [13]={hint="在安戈洛尔环形山找到东部水晶塔。"}, [14]={hint="使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。", desc="打开托尔瓦的麻袋，先放肉块，再用费洛蒙引出拉克维。"}, [15]={hint="将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。", tag="目标：安戈洛猩猩 / 安戈洛猩猩 / 安戈洛巨猩猩 / 安戈洛大猩猩"}, [16]={hint="在安戈洛尔环形山找到北部水晶塔。"}, [17]={hint="把林克的强化之剑交给安戈洛尔环形山的林克。"}, [18]={npc="林克", tgt="林克"}, [19]={npc="林克", tgt="林克"}, [20]={hint="到马绍尔营地那里的山洞中去找科琳。"}, [21]={npc="科琳", tgt="科琳"}, [22]={npc="科琳", tgt="科琳"}, [23]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [24]={hint="带着乌米的机械雪人去吓唬她的朋友：", desc="前两人沿冬泉谷永望镇及本段转场完成；在这里对奎克希尔使用后留冬泉谷霜语峡谷交。"}, [25]={hint="在安戈洛尔环形山找到西部水晶塔。"}, [26]={npc="克拉兰克", tgt="克拉兰克"}, [27]={hint="安戈洛尔环形山的克拉兰克要你去找到火羽山中温度最高的地方。", desc="有反应才算完成，不用跳进熔岩。"}, [28]={hint="在火羽山找到林格。"}, [29]={npc="林格", tgt="林格"}, [30]={npc="林格", tgt="林格", desc="护送前先清洞口；林格倒下时用斯普拉格的水壶叫醒他。"}, [31]={hint="把林格带回马绍尔营地的斯普拉格·弗劳克身边。"}, [32]={npc="斯普拉格·弗劳克", tgt="斯普拉格·弗劳克"}, [33]={npc="科琳", tgt="科琳"}, [34]={npc="科琳", tgt="科琳"}, [35]={npc="科琳", tgt="科琳"}, [36]={npc="科琳", tgt="科琳"}, [37]={hint="过一会再和科琳说话。"}, [38]={npc="科琳", tgt="科琳"}, [39]={npc="克拉兰克", tgt="克拉兰克"}, [40]={npc="克拉兰克", tgt="克拉兰克"}, [41]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [42]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [43]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [44]={hint="把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。", desc="进洞时先清外层猩猩，尤尔查本身为普通怪。"}, [45]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者"}, [46]={npc="托尔瓦·寻路者", tgt="托尔瓦·寻路者", tag="可选", desc="走东南入口时交托尔瓦；可选皮甲或法杖。", star={"斑白毛皮", {"DRUID"}}}, [47]={text="由安戈洛西北坡进希利苏斯，沿路直上塞纳里奥要塞。"}}},
    ["05-d31"] = {name="塑造者之台", entrance="安戈洛环形山 去辛特兰的旅程 48.10, 6.10（泰坦建筑室外路标；副本传送门精确点?）", pickup="前往月光林地途中，经雷霆崖时可先到莫高雷西北找 Mayena Earthseeker。回安戈洛环形山 马绍尔营地后，沿北边石阶往上找泰坦建筑；95928 以外两件的接取者仍待确认。", pickupS={{"前往月光林地途中，经雷霆崖时可先到莫高雷西北找 Mayena Earthseeker"}, {"回安戈洛环形山 马绍尔营地后，沿北边石阶往上找泰坦建筑"}, {"95928 以外两件的接取者仍待确认"}}, tips={{k="動線", text="入口→泰坦遗迹沿途收四色水晶→在无色水晶旁一起处理水池目标。泰坦龙、Bolt、Vitrix、纳纳雅的完整击杀顺序待核。"}, {k="取捨", text="先接有核对到 NPC 的 Crystalline Elements。若在营地没有其他任务可接，直接跟队进本。"}, {k="說明", text="永恒版新增五人副本。由马绍尔营地北侧上坡，泰坦门前可用安戈洛采集的能量水晶。安戈洛约 48.10, 6.10 为泰坦建筑的外侧入口路标，副本传送门精确点?。", s={{"永恒版新增五人副本"}, {"由马绍尔营地北侧上坡，泰坦门前可用安戈洛采集的能量水晶"}, {"安戈洛约 48.10, 6.10 为泰坦建筑的外侧入口路标，副本传送门精确点?"}}}, {k="提醒", text="永恒版新增五人副本。由马绍尔营地北侧上坡，泰坦门前可用安戈洛采集的能量水晶。安戈洛约 48.10, 6.10 为泰坦建筑的外侧入口路标，副本传送门精确点?。", s={{"永恒版新增五人副本"}, {"由马绍尔营地北侧上坡，泰坦门前可用安戈洛采集的能量水晶"}, {"安戈洛约 48.10, 6.10 为泰坦建筑的外侧入口路标，副本传送门精确点?"}}}}, steps={[1]={npc="玛耶娜·寻地者", tgt="玛耶娜·寻地者", desc="在雷霆崖西侧高原接；接交 NPC 对照永恒版游戏纪录。"}, [2]={npc="化学家弗雷", tgt="化学家弗雷", tag="需游戏内实测"}, [3]={npc="大药剂师法拉尼尔", tgt="大药剂师法拉尼尔", tag="需游戏内实测"}, [4]={text="塑造者之台 入口"}, [5]={hint="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace.", tag="需游戏内实测", desc="位置：由入口沿泰坦遗迹主线，向元素敌人收四色。", spot="由入口沿泰坦遗迹主线，向元素敌人收四色"}, [6]={hint="Gather 8 Seeping Slime Essence in the Shaper's Terrace.", tag="需游戏内实测", desc="位置：在副本内找渗漏软泥怪，确切水池位置待核。", spot="在副本内找渗漏软泥怪，确切水池位置待核"}, [7]={hint="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace.", desc="位置：到无色水晶旁，在晶体周围地面找耗尽碎片。", spot="到无色水晶旁，在晶体周围地面找耗尽碎片"}, [8]={npc="玛耶娜·寻地者"}, [9]={npc="化学家弗雷", tgt="化学家弗雷", tag="需游戏内实测"}, [10]={tag="需游戏内实测"}}},
    ["04-56"] = {name="希利苏斯", tips={{k="交通", text="第 1 步开塞纳里奥要塞飞行点，最后一步转飞艇回东部王国。"}, {k="取捨", text="先别交：净化之匣、档案管理员阿姆伯尔 留到月光林地交。"}, {k="取捨", text="可跳过：诺格的背包 要从要塞再跑一次地图最南端；通缉：死亡弯钩 要杀精英，练级路线可略过。"}, {k="取捨", text="可跳过：视频提及的暗翼蝠 在东瘟疫；希利苏斯这站也略过组队精英。"}, {k="提醒", text="未满 59 级仍可先到西瘟疫之地亡灵壁垒；要补则留在要塞东北（约 55, 29）打普通蝎、蜘蛛或西南暮光教徒（约 38, 44）。", s={{"未满 59 级仍可先到西瘟疫之地亡灵壁垒"}, {"要补则留在要塞东北（约 55, 29）打普通蝎、蜘蛛或西南暮光教徒（约 38, 44）"}}}}, danger={[1]="南风村塔顶会触发异种蝎群。先清塔内和楼梯，把退路留到触发后。"}, grind={[1]={mob="暮光复仇者", note="暮光营地外侧普通教徒，等级正合适、掉暮光装，可顺做教徒任务。会遇到收装玩家，从营边清。"}, [2]={mob="掘泥打击者", note="要塞东北空地的普通怪，等级稍低但密度好，与采任务材料同路。若暮光营地人多可替换。"}}, supply={[1]={npc="鲁克·驯风者"}, [2]={npc="卡兰德拉斯"}, [3]={npc="瓦古斯"}, [4]={npc="卡兰德拉斯"}, [5]={npc="卡兰德拉斯"}, [6]={npc="库尔·锐角"}}, steps={[1]={nodeA="{a:3425}", desc="抵达塞纳里奥要塞后，向鲁克·驯风者开启部落飞行点。"}, [2]={text="可在旅店（51.89, 39.16）绑炉石，跑完勇士之墓后用。"}, [3]={hint="与希利苏斯塞纳里奥要塞的唤风者梅恩·长角谈一谈。"}, [4]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [5]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [6]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [7]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [8]={npc="鲍尔·蛮鬃", tgt="鲍尔·蛮鬃"}, [9]={hint="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你带8个石鞭蝎之刺和8个掠沙蜘蛛的牙齿给他。"}, [10]={hint="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死15只掘泥打击者。"}, [11]={hint="在希利苏斯的勇士之墓附近找莱耶·星击谈谈，把拉比恩的信交给他。"}, [12]={npc="莱耶·星击", tgt="莱耶·星击"}, [13]={npc="莱耶·星击", tgt="莱耶·星击"}, [14]={hint="希利苏斯塞纳里奥要塞的地质学家拉克斯班要你去收集8块暮光石板碎片。"}, [15]={hint="把10片暮光密文信交给塞纳里奥要塞的鲍尔·蛮鬃。"}, [16]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [17]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [18]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [19]={npc="鲍尔·蛮鬃", tgt="鲍尔·蛮鬃"}, [20]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [21]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [22]={npc="地质学家拉克斯班", tgt="地质学家拉克斯班"}, [23]={hint="希利苏斯塞纳里奥要塞的唤风者梅恩·长角要求你去杀死20只掘泥摧毁者。"}, [24]={hint="希利苏斯塞纳里奥要塞的比提克斯·斯巴格要求你给他带去3个石鞭巨钳蝎之刺、3个石鞭掠夺者之刺和3个石行蜘蛛的牙齿。"}, [25]={hint="把复原的石板带给希利苏斯的隐士奥泰尔。"}, [26]={npc="隐士奥泰尔", tgt="隐士奥泰尔"}, [27]={hint="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。"}, [28]={hint="在南风村释放8个被折磨的德鲁伊和8个被折磨的哨兵的灵魂，然后向希利苏斯勇士之墓的莱耶·星击复命。", desc="亡灵死后可能生出异种蝎，先处理再拉下一只。"}, [29]={npc="莱耶·星击", tgt="莱耶·星击"}, [30]={npc="莱耶·星击", tgt="莱耶·星击"}, [31]={hint="爬上南风村的塔，找寻激活异种蝎群的方法。把任何你认为不寻常的东西交给希利苏斯勇士之墓的莱耶·星击。", desc="清塔梯的怪再开物件，塔里视线窄。"}, [32]={npc="莱耶·星击", tgt="莱耶·星击"}, [33]={npc="莱耶·星击", tgt="莱耶·星击"}, [34]={text="回塞纳里奥要塞；若这站已绑炉石，这时可用。"}, [35]={npc="比提克斯·斯巴格", tgt="比提克斯·斯巴格"}, [36]={npc="唤风者梅恩·长角", tgt="唤风者梅恩·长角"}, [37]={text="从要塞飞回奥格瑞玛，在杜隆塔尔转提瑞斯法飞艇。"}}},
    ["04-57"] = {name="西瘟疫之地", tips={{k="交通", text="第 1 步进亡灵壁垒，最后一步从幽暗城外搭飞艇。"}, {k="取捨", text="值得做：费尔斯通和安多哈尔连着做，末段白蚁回程刚好一起交。"}, {k="取捨", text="之后顺路：克罗米其余链要再跑东瘟疫；有专程回去再接。"}, {k="提醒", text="未到 59 级可在安多哈尔东侧外围（约 46, 64）或瘟疫农场打普通亡灵，再转费伍德。", s={{"未到 59 级可在安多哈尔东侧外围（约 46, 64）或瘟疫农场打普通亡灵，再转费伍德"}}}}, danger={[1]="安多哈尔市政厅靠近 61 级精英『召唤者』阿拉基。找达隆郡的历史时从外墙绕进出。"}, grind={[1]={mob="灼热的食尸鬼", note="安多哈尔东缘的普通亡灵，回农场前能连打，请避开城内精英和多怪屋群。"}, [2]={mob="亡鬼幻象", note="盖罗恩农场的普通怨灵，若仍在东边可就近补，等级较高。从农场外围绕，避免房屋内连拉。"}}, supply={[1]={npc="银色黎明军需官哈萨娜"}, [2]={npc="迈克尔·加勒特"}, [3]={npc="旅店老板诺曼"}, [4]={npc="旅店老板诺曼"}, [5]={npc="艾林诺尔·拉斯克"}, [6]={npc="托马斯·莫丹"}, [7]={npc="艾泽基尔·格瑞乌斯"}}, steps={[1]={text="由提瑞斯法飞艇塔往亡灵壁垒，再走费尔斯通农场、安多哈尔与北山伐木场。"}, [2]={hint="把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。"}, [3]={npc="暗影牧师范蒂丝", tgt="暗影牧师范蒂丝"}, [4]={npc="米克·莱文", tgt="米克·莱文"}, [5]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", star={"英勇短剑", {"PALADIN", "MAGE", "WARLOCK"}}}, [6]={hint="完成任务目标。"}, [7]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", star={"英勇短剑", {"PALADIN", "MAGE", "WARLOCK"}}}, [8]={npc="米克·莱文", tgt="米克·莱文"}, [9]={hint="把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"}, [10]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [11]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [12]={hint="在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。", desc="食尸鬼在农场移动，先找农场南侧。"}, [13]={npc="詹妮丝·费尔斯通", tgt="詹妮丝·费尔斯通"}, [14]={hint="与安多哈尔废墟南边的玛莱恩谈一谈。"}, [15]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [16]={npc="玛莱恩·雷德帕斯", tgt="玛莱恩·雷德帕斯"}, [17]={hint="把约瑟夫的结婚戒指交给安多哈尔的克罗米。", desc="安多哈尔市中心有精英巫妖，走外侧到旅店。"}, [18]={npc="克罗米", tgt="克罗米"}, [19]={npc="克罗米", tgt="克罗米"}, [20]={npc="克罗米", tgt="克罗米"}, [21]={hint="把《达隆郡的历史》交给安多哈尔的克罗米。", desc="假书可能引出敌人；看封面并避开市中心精英。"}, [22]={hint="在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。"}, [23]={npc="克罗米", tgt="克罗米"}, [24]={npc="克罗米", tgt="克罗米"}, [25]={npc="克罗米", tgt="克罗米"}, [26]={hint="在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。"}, [27]={npc="克罗米", tgt="克罗米"}, [28]={hint="到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。"}, [29]={npc="白蚁桶", npcObj=true}, [30]={npc="白蚁桶", npcObj=true}, [31]={hint="使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。", desc="桶会引来敌人，开完就撤离。"}, [32]={npc="米克·莱文", tgt="米克·莱文"}, [33]={npc="哀恸骑士", tag="可选、需游戏内实测", desc="回提瑞斯法林地西南找哀恸骑士，完成后可选 Sword of Mourning（台服物品名称?）。", star={"Sword of Mourning", {"PALADIN"}}}, [34]={text="回幽暗城飞艇塔，搭飞艇回奥格瑞玛，再往费伍德。"}}},
    ["05-d32"] = {name="通灵学院", entrance="西瘟疫之地 海中的威胁 约 68.90, 72.80（凯尔达隆地下入口）", pickup="在西瘟疫之地 亡灵壁垒可先接阿莱克西 巴罗夫家族的宝藏 与钥匙前段；圣光之愿礼拜堂接 瘟疫之龙。从亡灵壁垒沿南路上凯尔达隆岛，先找伊娃再进门。若要亲自做钥匙，在亡灵壁垒交骸骨碎片后接模具，去塔纳利斯 加基森与安戈洛环形山 火羽山，最后回亡灵壁垒完成。", pickupS={{"在西瘟疫之地 亡灵壁垒可先接阿莱克西 巴罗夫家族的宝藏 与钥匙前段"}, {"圣光之愿礼拜堂接 瘟疫之龙"}, {"从亡灵壁垒沿南路上凯尔达隆岛，先找伊娃再进门"}, {"若要亲自做钥匙，在亡灵壁垒交骸骨碎片后接模具，去塔纳利斯 加基森与安戈洛环形山 火羽山，最后回亡灵壁垒完成"}}, tips={{k="動線", text="入口桥→第一大厅取地契→召唤厅后取另一份→骨库打血骨傀儡与瘟疫幼龙→莱斯·霜语房取地契→下层六室拿末份并清克拉斯蒂诺夫房→黑暗院长加丁。"}, {k="取捨", text="四张地契、瘟疫幼龙和教授同趟收益高。钥匙只要队伍有人能开门，其他人可省整条材料链。"}, {k="說明", text="五人队。带钥匙者先开外门。教授之后 卡斯迪诺夫的恐惧之袋、传令官基尔图诺斯 要接续刷本，留给有同一队伍的行程。", s={{"五人队"}, {"带钥匙者先开外门"}, {"教授之后 卡斯迪诺夫的恐惧之袋、传令官基尔图诺斯 要接续刷本，留给有同一队伍的行程"}}}, {k="提醒", text="五人队。带钥匙者先开外门。教授之后 卡斯迪诺夫的恐惧之袋、传令官基尔图诺斯 要接续刷本，留给有同一队伍的行程。", s={{"五人队"}, {"带钥匙者先开外门"}, {"教授之后 卡斯迪诺夫的恐惧之袋、传令官基尔图诺斯 要接续刷本，留给有同一队伍的行程"}}}}, steps={[1]={npc="阿莱克斯·巴罗夫", tgt="阿莱克斯·巴罗夫", desc="亡灵壁垒，满 52 级可提前接。"}, [2]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克", desc="在圣光之愿礼拜堂找到贝蒂娜。"}, [3]={npc="艾瓦·萨克霍夫", tgt="艾瓦·萨克霍夫", desc="凯尔达隆门前的伊娃。"}, [4]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="只在需自己制作通灵学院钥匙时跑；西瘟疫之地 亡灵壁垒已做可略。"}, [5]={hint="到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。"}, [6]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [7]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="主线西瘟疫之地 亡灵壁垒已排。", preText="误导血色十字军"}, [8]={hint="使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。"}, [9]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [10]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", desc="西瘟疫之地 亡灵壁垒可先交。", preText="标记哨塔"}, [11]={hint="和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。"}, [12]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [13]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="西瘟疫之地 亡灵壁垒已接或交过时略过这三步；打算自备钥匙就接模具。", preText="通灵学院"}, [14]={hint="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}, [15]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [16]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="安戈洛环形山 马绍尔营地过加基森前先准备两块瑟银锭。", preText="骸骨碎片"}, [17]={hint="把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。"}, [18]={npc="克林科·古德斯迪尔", tgt="克林科·古德斯迪尔"}, [19]={npc="克林科·古德斯迪尔", tgt="克林科·古德斯迪尔", desc="安戈洛环形山 马绍尔营地可与火羽山任务一趟完成。", preText="昂贵的模具"}, [20]={hint="把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。"}, [21]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [22]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯", desc="西瘟疫之地 亡灵壁垒做安多哈尔时有队伍才打。", preText="火羽山"}, [23]={hint="杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。"}, [24]={npc="药剂师迪瑟斯", tgt="药剂师迪瑟斯"}, [25]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿", preText="阿拉基的圣甲虫"}, [26]={hint="完成任务目标。"}, [27]={npc="高级执行官德灵顿", tgt="高级执行官德灵顿"}, [28]={text="通灵学院 入口"}, [29]={hint="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。", desc="位置：依序搜首厅、召唤厅后、霜语房、巴罗夫房。顺序：南海镇→塔伦米尔→布瑞尔→凯尔达隆。", spot="依序搜首厅、召唤厅后、霜语房、巴罗夫房"}, [30]={hint="杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。", desc="位置：过召唤厅后进骨库，在血骨傀儡房杀幼龙。", spot="过召唤厅后进骨库，在血骨傀儡房杀幼龙"}, [31]={hint="在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。", desc="艾瓦与卢森的遗骸在教授房内。位置：进末段六室找克拉斯蒂诺夫，同房焚两份遗骸。顺序：遗骸在同房。", spot="进末段六室找克拉斯蒂诺夫，同房焚两份遗骸"}, [32]={npc="艾瓦·萨克霍夫", tgt="艾瓦·萨克霍夫", desc="伊娃可接下一趟的恐惧之袋；练级首趟可以只交教授。"}, [33]={npc="阿莱克斯·巴罗夫", tgt="阿莱克斯·巴罗夫"}, [34]={npc="贝蒂娜·比格辛克", tgt="贝蒂娜·比格辛克"}}},
    ["04-58"] = {name="费伍德森林", tips={{k="交通", text="第 1 步由灰谷北上，末步走木喉要塞去月光林地。"}, {k="取捨", text="可跳过：最终一击 要为深处三个目标再走一次暗影堡，单人不顺就略过。"}, {k="取捨", text="先别交：剧毒之水 带到冬泉谷 冰火温泉交。"}, {k="提醒", text="未满 60 级可在铁木森林（约 49, 25）打剧毒元素和铁木树人，也可把差额留给冬泉谷。", s={{"未满 60 级可在铁木森林（约 49, 25）打剧毒元素和铁木树人，也可把差额留给冬泉谷"}}}}, danger={[1]="暗影堡的火盆分散在狭窄洞道。先清一段再灭火，撤退时沿原路走。"}, grind={[1]={mob="剧毒之水", note="铁木森林水池边普通元素，能同步收剧毒水滴。等级偏低只补小差额，池边任务玩家多时前往冬泉谷。"}, [2]={mob="曲木撕裂者", note="北路旁普通树人，若水池被占可接着打，靠道路方便继续往木喉要塞。留意营地内施法怪。"}}, supply={[1]={npc="旅店老板凯利斯克"}, [2]={npc="旅店老板凯利斯克"}, [3]={npc="布拉卡尔"}, [4]={npc="奥索巴·狂怒图腾"}, [5]={npc="拜尔"}, [6]={npc="拜尔"}}, steps={[1]={text="由奥格瑞玛飞灰谷碎木岗哨，沿大路向北进费伍德，先到翡翠圣地与附近路边。"}, [2]={npc="梅贝丝·河风", tgt="梅贝丝·河风"}, [3]={hint="把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"}, [4]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [5]={hint="到费伍德森林去找艾瑞丹·蓝风。"}, [6]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [7]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [8]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [9]={hint="使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。", desc="先清通道再深入；洞内坐标可能重叠。"}, [10]={hint="为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。", desc="银爪由狼、熊掉落；铁树之心找铁木树人。"}, [11]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄"}, [12]={npc="艾瑞丹·蓝风", tgt="艾瑞丹·蓝风"}, [13]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选", desc="若有人同行或能稳定单拉，再回暗影堡深处做。"}, [14]={hint="杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的头颅交给费伍德森林的格雷塔·苔蹄。", tag="可选", desc="两名守卫与领主位置近，先清附近巡逻。"}, [15]={npc="格雷塔·苔蹄", tgt="格雷塔·苔蹄", tag="可选"}, [16]={npc="特鲁尔·法贝恩", tgt="特鲁尔·法贝恩"}, [17]={hint="为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。"}, [18]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="可选灵魂收割者（Soul Harvester）等装备。", star={"灵魂收割者", {"WARLOCK"}}}, [19]={hint="费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。", tag="可选", desc="已在第 45、52、57 站转场拿齐，就直接回伊普斯。"}, [20]={npc="伊普斯", tgt="伊普斯", tag="可选"}, [21]={npc="伊普斯", tgt="伊普斯", tag="可选", desc="精英战建议组队。回尼比交任务可解锁召唤地狱火（Inferno）。"}, [22]={hint="在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。", tag="可选", desc="精英战建议组队。回尼比交任务可解锁召唤地狱火（Inferno）。"}, [23]={npc="万能的尼比", tgt="万能的尼比", tag="可选", desc="精英战建议组队。回尼比交任务可解锁召唤地狱火（Inferno）。"}, [24]={text="沿路北上进木喉要塞，走月光林地方向。"}}},
    ["04-59"] = {name="月光林地", tips={{k="交通", text="第 1 步步行到永夜港，末步先按手上任务选温泉或永望镇。"}, {k="取捨", text="值得做：永夜港两位 NPC 的交接在同一座村。"}, {k="取捨", text="之后顺路：魔藤碎片 要进厄运之槌东区，留副本行程。"}, {k="提醒", text="仍在 59-60 级带，做完直接进冬泉谷霜语峡谷。", s={{"仍在 59-60 级带，做完直接进冬泉谷霜语峡谷"}}}}, danger={[1]="从月光林地转冬泉谷时，木喉声望仍敌对的角色不要直接穿洞，先从费伍德侧处理声望。"}, grind={[1]={mob="疯狂的碎齿熊", note="月光林地交件后沿要塞转冬泉谷，到霜语峡谷北口打普通熊。怪等贴近 60，避开谷底精英。"}}, supply={[1]={npc="梅里"}, [2]={npc="达尔贡"}, [3]={npc="黛欧琳·夏叶"}, [4]={npc="法斯托恩"}}, steps={[1]={text="出木喉要塞走大路往永夜港，把希利苏斯带来的两件物品交掉。"}, [2]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [3]={hint="将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。"}, [4]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [5]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [6]={hint="与月光林地永夜港的拉比恩·萨图纳谈一谈。"}, [7]={npc="拉比恩·萨图纳", tgt="拉比恩·萨图纳"}, [8]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [9]={hint="完成任务目标。"}, [10]={npc="阿姆伯尔", tgt="阿姆伯尔"}, [11]={text="带着 新的泉水 或 剧毒之水 时，由月光林地原路穿木喉要塞往冬泉谷，先到温泉。两件都没有且跳过多诺瓦的支线时，才从法斯托恩（32.09, 66.61）飞永望镇。"}}},
    ["04-60"] = {name="冬泉谷", tips={{k="交通", text="第 1 步先到温泉，交完永望镇的雪人后往南，末步在峡谷北口外补怪。"}, {k="取捨", text="值得做：冬泉信使 优先找落单的信使；奇怪的源头 是探索，和视频的补怪点同路。"}, {k="取捨", text="可跳过：冬泉酋长 是精英；单人直接以普通熊怪补等。"}, {k="提醒", text="未满 60 级就照视频在霜语峡谷北侧打熊，打一般的疯狂的裂齿熊（约 57.63, 70.83／66.68, 70.57），避开谷底精英。", s={{"未满 60 级就照视频在霜语峡谷北侧打熊，打一般的疯狂的裂齿熊（约 57.63, 70.83／66.68, 70.57），避开谷底精英"}}}}, danger={[1]="霜语峡谷内有 59-60 级精英霜槌巨人，北口补熊时沿坡单拉，别把怪带进谷底。", [2]="暗语峡谷有 57-60 级精英赫达琳杀戮者。奇怪的源头在北口触发，完成就回道路。"}, grind={[1]={mob="疯狂的碎齿熊", note="霜语峡谷北口西侧的普通熊，近战、能单拉和剥皮。清完往东线轮替，别进谷底精英区。"}, [2]={mob="疯狂的碎齿熊", note="峡谷北口东侧的普通熊，西侧有人或尚未刷新就沿坡转来。沿坡拉回道路，避开谷底精英。"}}, supply={[1]={npc="尤格雷克"}, [2]={npc="旅店老板维兹奇"}, [3]={npc="尼克撒克"}, [4]={npc="旅店老板维兹奇"}, [5]={npc="维撒克"}}, steps={[1]={text="由木喉要塞出来先到温泉找多诺瓦，交安戈洛环形山马绍尔营地、费伍德森林铁木森林带来的任务，再去永望镇和南部山谷。直飞永望镇且跳过温泉任务者从乌米开始。"}, [2]={hint="到冬泉谷去和多诺瓦·雪山谈一谈。"}, [3]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [4]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [5]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [6]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [7]={hint="找到冬泉信使，阻止他们向冬泉村运送物品。", desc="主路信使会成队，单人可找木喉入口或死木蒸锅附近的落单信使。"}, [8]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [9]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选", desc="59 级精英，旁边有其他熊怪，有队友再做。"}, [10]={hint="冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。", tag="可选", desc="先清外圈，战后若拾到信可依需求解后续。"}, [11]={npc="潦草的日志", npcObj=true, tag="可选", desc="打冬泉酋长拾到日志才右键接。"}, [12]={hint="把潦草的日志交给冬泉谷的多诺瓦·雪山。", tag="可选"}, [13]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选"}, [14]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山", tag="可选"}, [15]={npc="乌米", tgt="乌米"}, [16]={hint="根据多诺瓦·雪山的指示行动，然后回到她那里报告。", desc="到峡谷入口即可，避开深处的精英。"}, [17]={npc="多诺瓦·雪山", tgt="多诺瓦·雪山"}, [18]={text="还没到 60 级时留在峡谷北口外，刷普通疯狂的碎齿熊。"}}},
    ["05-d34"] = {name="黑石塔上层", entrance="灼热峡谷 34.80, 85.30（黑石山外部路标）", pickup="满 55 级后从冬泉谷 永望镇飞奥格瑞玛，再搭飞艇到东部王国先做下层 高图斯的命令，回卡加斯高图斯接 伊崔格的智慧。可于贫瘠之地 棘齿城后回奥格瑞玛智慧谷向伊崔格、萨尔交接并留 为部落而战！。57 级后回幽暗城炼金区接 薇薇安·拉格雷和黑暗石板，再飞卡加斯交给薇薇安，接 黑暗石板。下层至少一人完成 晋升印章→晋升印章 带印章开门；已有持章队友可直接打上层。", pickupS={{"满 55 级后从冬泉谷 永望镇飞奥格瑞玛，再搭飞艇到东部王国先做下层 高图斯的命令，回卡加斯高图斯接 伊崔格的智慧"}, {"可于贫瘠之地 棘齿城后回奥格瑞玛智慧谷向伊崔格、萨尔交接并留 为部落而战！"}, {"57 级后回幽暗城炼金区接 薇薇安·拉格雷和黑暗石板，再飞卡加斯交给薇薇安，接 黑暗石板"}, {"下层至少一人完成 晋升印章→晋升印章 带印章开门"}, {"已有持章队友可直接打上层"}}, tips={{k="動線", text="龙塔大厅七符文→烈焰卫士艾博希尔→孵化间取石板→黑手大厅→竞技场打雷德与盖斯→熔炉（比斯巨兽可选）→塔顶王座打达基萨斯并查看身后宝珠。"}, {k="取捨", text="卡加斯和奥格瑞玛先接满；黑手的命令是团队副本传送前置，有需求再做。"}, {k="說明", text="与下层共用外门，进门后向左上去找上层锁门；组队先找可用晋升印章的队友。开服后攻略已有上层实际门序；若遇到跳台地形挡路，走上层外侧步道。", s={{"与下层共用外门，进门后向左上去找上层锁门"}, {"组队先找可用晋升印章的队友"}, {"开服后攻略已有上层实际门序"}, {"若遇到跳台地形挡路，走上层外侧步道"}}}}, steps={[1]={npc="军官高图斯", tgt="军官高图斯", desc="若 NPC 不直接给接取界面，先交谈取得高图斯的命令，再右键使用。"}, [2]={hint="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。", desc="文件位置会变，遇到前三房先找。文件可能出现在任一首领房间，逐间查看。"}, [3]={npc="军官高图斯", tgt="军官高图斯"}, [4]={npc="军官高图斯", tgt="军官高图斯", preText="高图斯的命令"}, [5]={hint="和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。"}, [6]={npc="萨尔", tgt="萨尔"}, [7]={npc="萨尔", tgt="萨尔", preText="伊崔格的智慧"}, [8]={npc="药剂师金格", tgt="药剂师金格", tag="可选", desc="57 级从幽暗城炼金区接。已接到 黑暗石板 可略过转介。"}, [9]={hint="与卡加斯的暗法师薇薇安·拉格雷谈一谈。", tag="可选"}, [10]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", tag="可选"}, [11]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷", desc="薇薇安有提供就直接接。若尚未出现，可从幽暗城的 薇薇安·拉格雷和黑暗石板 导引开始。"}, [12]={npc="黑手的命令", npcObj=true, tag="可选", desc="在黑石塔门外从裂盾军需官拿到信后右键接；有意开黑翼之巢才做。"}, [13]={text="黑石塔上层 入口"}, [14]={hint="去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。", desc="位置：过孵化间上黑手大厅，进竞技场北门触发雷德。顺序：先取孵化间石板再打竞技场。", spot="过孵化间上黑手大厅，进竞技场北门触发雷德"}, [15]={hint="将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。", desc="贴路线避开龙蛋，踩碎会引雏龙。位置：杀烈焰卫士后进孵化间，沿墙看地上的石板。顺序：在第13步竞技场前完成。", spot="杀烈焰卫士后进孵化间，沿墙看地上的石板"}, [16]={hint="真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。", tag="可选", desc="烙印在达基萨斯身后。位置：竞技场南门出，经熔炉往王座，烙印在王后。顺序：击杀达基萨斯后点击身后烙印。", spot="竞技场南门出，经熔炉往王座，烙印在王后"}, [17]={npc="达基萨斯的烙印", npcObj=true, tag="可选、需游戏内实测", spot="达基萨斯王座后方的烙印"}, [18]={npc="萨尔", tgt="萨尔"}, [19]={npc="暗法师薇薇安·拉格雷", tgt="暗法师薇薇安·拉格雷"}}},
    ["05-d33"] = {name="Blackmaw Hold", entrance="冬泉谷 66.60, 84.40", pickup="瓦罗莫克找杰迪加接 Beneath Nordrassil；同站可到奥汀克接 撕裂之爪，刺骨之牙，满 55 级再回艾萨拉找 Ekkal。经贫瘠之地 棘齿城回卡利姆多时先飞雷霆崖到长者高地交杰迪加的信、接 Get to the Roots of It，并往莫高雷找穆伦·地怒。最后飞瓦罗莫克，由艾萨拉地道前往副本；留 Get to the Roots of It、Blackmaw Magic 到下次雷霆崖和莫高雷回程。", pickupS={{"瓦罗莫克找杰迪加接 Beneath Nordrassil"}, {"同站可到奥汀克接 撕裂之爪，刺骨之牙，满 55 级再回艾萨拉找 Ekkal"}, {"经贫瘠之地 棘齿城回卡利姆多时先飞雷霆崖到长者高地交杰迪加的信、接 Get to the Roots of It，并往莫高雷找穆伦·地怒"}, {"最后飞瓦罗莫克，由艾萨拉地道前往副本"}, {"留 Get to the Roots of It、Blackmaw Magic 到下次雷霆崖和莫高雷回程"}}, tips={{k="動線", text="入口熊怪通道沿路收 Blackmaw Pouches→地下根系区收诺达希尔根帽→枯萎之喉与骨鼻的岔路→血鬃长老取仪祭图腾。分岔与打王顺序待核。"}, {k="取捨", text="顺路先准备奥汀克、埃达拉斯废墟任务；部落根帽链在雷霆崖一次办完。"}, {k="說明", text="传送门的坐标落在冬泉谷地图。从艾萨拉 38.70, 33.40 进熊怪地道一路走到门，勿由冬泉谷地表寻找。", s={{"传送门的坐标落在冬泉谷地图"}, {"从艾萨拉 38.70, 33.40 进熊怪地道一路走到门，勿由冬泉谷地表寻找"}}}}, steps={[1]={npc="杰迪加", tgt="杰迪加", tag="需游戏内实测"}, [2]={hint="Speak to Nara Wildmane at Elder Rise in Thunder Bluff.", tag="需游戏内实测"}, [3]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", tag="需游戏内实测"}, [4]={npc="纳拉·蛮鬃", tgt="纳拉·蛮鬃", tag="需游戏内实测", preText="Beneath Nordrassil"}, [5]={npc="奥汀克", tgt="奥汀克"}, [6]={npc="阿拉娜·风暴行者", tgt="Muln Earthfury", desc="莫高雷通往雷霆崖的区域，依莫高雷地图坐标找。"}, [7]={npc="Ekkal", tgt="Ekkal"}, [8]={text="Blackmaw Hold 入口"}, [9]={hint="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff.", tag="需游戏内实测", desc="位置：沿城内通道找地下根系区，在根部采根帽。", spot="沿城内通道找地下根系区，在根部采根帽"}, [10]={hint="将巨熊之爪与不屈者之牙交给艾萨拉的奥汀克。", tag="目标：巨熊枯萎之喉／『不屈者』骨鼻、需游戏内实测", desc="位置：沿熊怪通道找枯萎之喉与骨鼻，分岔待核。", spot="沿熊怪通道找枯萎之喉与骨鼻，分岔待核"}, [11]={hint="Recover a Blackmaw Ritual Totem from Blackmaw Hold.", tag="需游戏内实测", desc="位置：进城后沿首领路线找血鬃长老，取仪祭图腾。", spot="进城后沿首领路线找血鬃长老，取仪祭图腾"}, [12]={hint="掉落自：Blackmaw Berserker、Blackmaw Thrall、Blackmaw Headhunter", desc="位置：进门沿熊怪居住区清腐化黑喉族，留意袋子。", spot="进门沿熊怪居住区清腐化黑喉族，留意袋子"}, [13]={npc="奥汀克", tgt="奥汀克"}, [14]={npc="Ekkal", tgt="Ekkal"}, [15]={npc="纳拉·蛮鬃"}, [16]={npc="阿拉娜·风暴行者", tgt="Muln Earthfury"}}},
  },
  quests = {
    [2] = {n="沙普塔隆的爪子", d="将沙普塔隆的爪子交给灰谷碎木哨岗的塞娜尼·雷心。"},
    [10] = {n="谢申克的救赎", d="寻找初级勘探员谢申克的下落，把他或者他的勘探设备交给加基森的高级勘探员菲兹杜瑟。", objs={"谢申克的勘探设备"}},
    [23] = {n="乌萨苟斯的爪子", d="将乌萨苟斯的爪子交给灰谷碎木哨岗的的塞娜尼·雷心。"},
    [24] = {n="萨杜布拉的头颅", d="将萨杜布拉的头颅交给灰谷碎木哨岗的的塞娜尼·雷心。"},
    [25] = {n="石爪山的困境", d="清除位于碎木哨岗西南和石爪小径正东的密斯特拉湖一带的12个污浊的水元素。\n在密斯特拉湖上的眺望台中侦查联盟的前哨站。\n返回灰谷慰藉之林的碎木哨岗，向马斯托克·维尔西斯报告。", tgo={{"污浊的水元素"}}},
    [27] = {n="必修的课程", d="与月光林地永夜港的德迪利特·星焰谈一谈。"},
    [28] = {n="湖中试炼", d="在月神湖寻找神殿灵珠，把它带到月光林地西北部的雷姆洛斯神殿去。在神殿中使用神殿灵珠，然后与神殿中的塔加里谈话来完成试炼。", objs={"雷姆洛斯神殿"}},
    [30] = {n="海狮试炼", d="寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。\n在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。\n将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。", objs={"雷姆洛斯神殿"}},
    [31] = {n="水栖形态", d="回到雷霆崖，让图拉克·符文图腾看看你的海狮坠饰。"},
    [32] = {n="异种蝎的威胁", d="把报告带给奥格瑞玛的基尔兹宾·鼓眼。"},
    [63] = {n="水之召唤", d="击败堕落的水之魂，把堕落水之魂的护腕和剩余的最纯净的水放在银松森林的圣泉火盆上。", tgo={{"堕落的水之魂"}}},
