    [2283] = {n="搜寻项链", d="在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。", tgo={{"暗炉勘探员", "暗炉恶棍", "暗炉掘地工"}}},
    [2284] = {n="搜寻项链，再来一次", d="在奥达曼里找寻宝石的线索。"},
    [2318] = {n="翻译日记", d="在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"},
    [2338] = {n="翻译日记", d="将项链借给加卡尔。作为交换，他将帮你翻译日记。"},
    [2339] = {n="寻找宝贝", d="从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。\n红宝石被藏在暗影矮人层层设防的地区。\n黄宝石藏在石腭怪活动地区的一个瓮中。\n蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。\n能量源可能在奥达曼的某个最强生物的手中。", tgo={{}, {"格瑞姆洛克"}, {}, {"阿扎达斯"}}, objs={"暗影熔炉地窖", "显眼的石罐"}},
    [2340] = {n="交付宝石", d="把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。"},
    [2341] = {n="项链任务的终结", d="去卡加斯看看加卡尔是否成功了。"},
    [2342] = {n="寻找宝物", d="从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。", objs={"加勒特的宝箱"}},
    [2378] = {n="寻找碎手氏族", d="前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。"},
    [2379] = {n="赞杜沙", d="与暗影裂口的赞杜沙谈一谈。"},
    [2381] = {n="抢劫海盗", d="把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和潜行者工具，你的任务需要使用这两件东西。\n如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！", tgo={{"波利"}}},
    [2382] = {n="棘齿城的维尼克斯", d="到棘齿城去，与卑鄙的维尼克斯谈一谈。"},
    [2383] = {n="简易羊皮纸", d="阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。"},
    [2418] = {n="能量石", d="给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。", tgo={{"暗炉勘探员", "暗炉恶棍", "暗炉掘地工"}, {"暗炉勘探员", "暗炉恶棍", "暗炉掘地工"}}},
    [2458] = {n="卧底密探", d="到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。\n看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。\n注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。"},
    [2460] = {n="碎手军礼", d="对着申苏尔练习碎手军礼。", tgo={{"申苏尔"}}},
    [2478] = {n="基本不可能的任务", d="从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。\n杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。", tgo={{"变异风险投资公司工人"}, {"风险投资公司看守"}, {"风险投资公司巡逻员"}, {"大工头普兹克·加里维克斯"}, {"工头希里克斯"}, {}}, objs={"加里维克斯的保险箱"}},
    [2479] = {n="希诺特的帮助", d="到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。\n要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！"},
    [2480] = {n="希诺特的帮助", d="等待瑟尔格·希诺特完成解药。"},
    [2521] = {n="为库米沙效力", d="在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。\n你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无暇的德莱尼水晶球。\n每找到一颗，你都会得到相应的酬劳。", tgo={{"巨槌食人魔", "巨槌食人魔法师", "巨槌蛮兵"}}},
    [2581] = {n="弯牙土狼的颚骨", d="收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。", tgo={{"饥饿的弯牙土狼", "弯牙土狼", "毁灭"}, {"灰鬃野猪", "地狱野猪", "格朗特"}, {"厚甲毒刺蝎", "掠夺者科拉克"}}},
    [2583] = {n="野猪的活力", d="收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。", tgo={{"灰鬃野猪", "地狱野猪", "格朗特"}, {"厚甲毒刺蝎", "掠夺者科拉克"}, {"红石蜥蜴", "红石晶鳞蜥蜴", "死眼"}}},
    [2585] = {n="决定性的打击", d="收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。", tgo={{"厚甲毒刺蝎", "掠夺者科拉克"}, {"黑色屠戮者", "拾骨者"}, {"灰鬃野猪", "地狱野猪", "格朗特"}}},
    [2601] = {n="石化蜥蜴的大脑", d="收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。", tgo={{"红石蜥蜴", "红石晶鳞蜥蜴", "死眼"}, {"黑色屠戮者", "拾骨者"}}},
    [2603] = {n="秃鹫的活力", d="收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。", tgo={{"黑色屠戮者", "拾骨者"}, {"饥饿的弯牙土狼", "弯牙土狼", "毁灭"}}},
    [2605] = {n="口渴的地精", d="找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。", tgo={{"灌木露水收集者"}}},
    [2606] = {n="好味道", d="马林·诺格弗格让你与加基森的斯普琳科谈一谈。"},
    [2641] = {n="斯普琳科的秘密佐料", d="加基森的斯普琳科要你去给她找到一颗紫色水生菇。", objs={"紫色水生菇"}},
    [2661] = {n="给马林的粉末", d="斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。"},
    [2662] = {n="诺格弗格药剂", d="马林·诺格弗格让你在他制成药剂之后再去找他。"},
    [2741] = {n="超级测蛋器", d="使用／收集：角鹰兽的蛋", objs={"角鹰兽的蛋"}},
    [2766] = {n="寻找OOX-22/FE！", d="把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。"},
    [2767] = {n="拯救OOX-22/FE！", d="将OOX-22/FE护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。"},
    [2768] = {n="探水棒", d="把探水棒交给加基森的首席工程师沙克斯·比格维兹。", tgo={{"布莱中士"}}, star={"石工兄弟会之戒", {"ROGUE", "HUNTER", "DRUID"}}},
    [2770] = {n="加兹瑞拉", d="把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。", tgo={{"加兹瑞拉"}}},
    [2781] = {n="通缉：卡利夫·斯科比斯汀", d="将卡利夫·斯科比斯汀的头颅交给加基森的首席工程师沙克斯·比格维兹。", tgo={{"卡利夫·斯科比斯汀"}}},
    [2822] = {n="质量的保证", d="给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。", tgo={{"深痕雪人", "暴怒的巨型深痕雪人", "暴怒的深痕雪人"}}},
    [2841] = {n="设备之战", d="从诺莫瑞根拿到钻探设备蓝图和瑟玛普拉格的保险箱密码，把它们交给奥格瑞玛的诺格。", tgo={{}, {"麦克尼尔·瑟玛普拉格"}}, objs={"瑟玛普拉格的保险箱"}},
    [2842] = {n="主工程师斯库提", d="和藏宝海湾的斯库提谈一谈。"},
    [2843] = {n="出发！诺莫瑞根！", d="等斯库提调整好地精传送器。", tgo={{"斯库提"}}},
    [2846] = {n="深渊皇冠", d="将深渊皇冠交给尘泥沼泽的塔贝萨。", tgo={{"水占师维蕾萨"}}},
    [2862] = {n="与豺狼人开战", d="将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。", tgo={{"混血木爪豺狼人", "木爪捕兽者", "木爪蛮兵"}}},
    [2863] = {n="突然袭击", d="在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。", tgo={{"木爪突击队员"}}},
    [2865] = {n="圣甲虫的壳", d="给加基森的特兰雷克带去5个完整的圣甲虫壳。", tgo={{"圣甲虫"}}},
    [2873] = {n="斯杜雷的货物", d="将斯杜雷的货物交给热砂港的斯杜雷。", objs={"被偷走的货物"}},
    [2874] = {n="给马克基雷的货物", d="将斯杜雷的瓶子交给藏宝海湾的\"海狼\"马克基雷。"},
