    [2975] = {n="菲拉斯的食人魔", d="莫沙彻营地的洛卡·奥赫要你杀掉10个戈杜尼食人魔、10个戈杜尼食人魔法师和5个戈杜尼蛮兵。", tgo={{"戈杜尼食人魔"}, {"戈杜尼食人魔法师"}, {"戈杜尼蛮兵"}}},
    [2976] = {n="可怕的发现", d="将一箱恐怖图腾之角交给奥格瑞玛的贝尔戈洛姆·石槌。"},
    [2978] = {n="戈杜尼卷轴", d="将戈杜尼卷轴交给莫沙彻营地的洛克·奥汉。"},
