    [3001] = {n="寻找斯坦哈德", d="在棘齿城找到斯坦哈德·法尔杉。"},
    [3002] = {n="戈杜尼宝珠", d="将戈杜尼宝珠交给奥格瑞玛暗木小屋里的尤塞尔奈。"},
    [3042] = {n="巨魔调和剂", d="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。", tgo={{"沙怒暗影法师", "沙怒饮血者", "沙怒巫医"}}},
    [3062] = {n="黑暗之心", d="莫沙彻营地的塔罗·刺蹄要你给他拿去艾丹娜·邪爪的黑心。", tgo={{"艾丹娜·邪爪"}}},
